	private void FixVillageIdentityInfo(DataContext context)
	{
		HashSet<int> chars = DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId).GetMembers().GetMembers(0);
		List<int> wrongSettlementCharIds = new List<int>();
		foreach (int charId in chars)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			OrganizationInfo orgInfo = character.GetOrganizationInfo();
			if (orgInfo.Grade == 0 && !orgInfo.Principal)
			{
				orgInfo.Principal = true;
				character.SetOrganizationInfo(orgInfo, context);
				Logger.Warn($"Fixing character {character}'s wrong principal value when join taiwu by stone house");
			}
			if (orgInfo.OrgTemplateId == 20)
			{
				wrongSettlementCharIds.Add(charId);
			}
		}
		int i = 0;
		for (int max = wrongSettlementCharIds.Count; i < max; i++)
		{
			int charId2 = wrongSettlementCharIds[i];
			GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId2);
			OrganizationInfo orgInfo2 = character2.GetOrganizationInfo();
			orgInfo2.OrgTemplateId = 16;
			orgInfo2.Grade = 0;
			orgInfo2.SettlementId = _taiwuVillageSettlementId;
			character2.SetOrganizationInfo(orgInfo2, context);
			Events.RaiseXiangshuInfectionFeatureChanged(context, character2, 211);
			Logger.Warn($"Fixing character {character2}'s wrong settlement id as taiwu villiager");
		}
	}

	private void FixVillageWorkData(DataContext context)
	{
		Location location = GetTaiwuVillageLocation();
		foreach (KeyValuePair<int, VillagerWorkData> pair in _villagerWork)
		{
			VillagerWorkData workData = pair.Value;
			if (VillagerWorkType.IsWorkOnMap(workData.WorkType))
			{
				Location workLocation = new Location(workData.AreaId, workData.BlockId);
				DomainManager.Extra.AddLocationMark(context, workLocation);
			}
			if (pair.Value.WorkType < 10 && pair.Value.AreaId == location.AreaId && pair.Value.BlockId == location.BlockId)
			{
				BuildingBlockKey buildingBlockKey = new BuildingBlockKey(pair.Value.AreaId, pair.Value.BlockId, pair.Value.BuildingBlockIndex);
				BuildingBlockData blockData = DomainManager.Building.GetElement_BuildingBlocks(buildingBlockKey);
				if (blockData.TemplateId == 0)
				{
					Logger.Warn($"Fixing character {pair.Key}'s wrong  villager work data");
					RemoveVillagerWork(context, pair.Key);
				}
			}
		}
		ExtraDomain extraDomain = DomainManager.Extra;
		CharacterDomain characterDomain = DomainManager.Character;
		VillagerRoleRecords records = extraDomain.GetVillagerRoleRecordsData();
		HashSet<int> idSetCurrentVillager = new HashSet<int>(extraDomain.GetVillagerRoleCharacters());
		foreach (int charId in idSetCurrentVillager)
		{
			VillagerRoleBase role = null;
			if (!records.History.Any((VillagerRoleRecordElement r) => r.CharacterId == charId) && characterDomain.TryGetElement_Objects(charId, out var character) && (role = extraDomain.GetVillagerRole(charId)) != null)
			{
				VillagerRoleRecordElement record = new VillagerRoleRecordElement
				{
					CharacterId = charId,
					CharacterTemplateId = character.GetTemplateId(),
					RoleTemplateId = role.RoleTemplateId,
					Personalities = character.GetPersonalities(),
					LifeSkillAttainments = character.GetLifeSkillAttainments(),
					Avatar = character.GenerateAvatarRelatedData(),
					Date = DomainManager.World.GetCurrDate()
				};
				CharacterDomain.GetNameRelatedData(character, ref record.Name);
				records.History.Add(record);
			}
		}
		extraDomain.SetVillagerRoleRecordsData(context, records);
	}

	private void FixUnlockedWorkingVillagersData(DataContext context)
	{
		List<int> villagers = DomainManager.Extra.GetUnlockedWorkingVillagers();
		for (int i = villagers.Count - 1; i >= 0; i--)
		{
			if (!_villagerWork.ContainsKey(villagers[i]))
			{
				Logger.Warn($"Fixing character {villagers[i]}'s wrong unlocked working villagers data");
				villagers.RemoveAt(i);
			}
		}
		DomainManager.Extra.SetUnlockedWorkingVillagers(villagers, context);
	}

	private void FixAbnormalTaiwuData(DataContext context)
	{
		RemoveTaiwuInvalidFeatures(context);
		TryRemoveReferenceSkillAtLockedSlot(context);
		RemoveTaiwuFromPrison(context);
	}

	private void RemoveTaiwuFromPrison(DataContext context)
	{
		sbyte prisonerSect = DomainManager.Organization.GetPrisonerSect(_taiwuCharId);
		if (prisonerSect >= 0)
		{
			Settlement settlement = DomainManager.Organization.GetSettlementByOrgTemplateId(prisonerSect);
			if (settlement is Sect { Prison: var prison } sect)
			{
				prison.OfflineRemovePrisoner(_taiwuCharId);
				DomainManager.Organization.UnregisterSectPrisoner(_taiwuCharId);
				DomainManager.Organization.SetSettlementPrison(context, settlement.GetId(), prison);
				AdaptableLog.Warning($"Fixing taiwu in prison: {_taiwuChar} removed from {sect}.");
			}
		}
	}

	private void FixAbnormalEquipmentPlan(DataContext context)
	{
		if (!DomainManager.World.IsCurrWorldBeforeVersion(0, 0, 68))
		{
			return;
		}
		ItemKey defaultItemKey = default(ItemKey);
		bool isModified = false;
		for (int i = 0; i < _equipmentsPlans.Length; i++)
		{
			EquipmentPlan equipmentPlan = _equipmentsPlans[i];
			for (int j = 0; j < equipmentPlan.Slots.Length; j++)
			{
				if (equipmentPlan.Slots[j].Equals(defaultItemKey))
				{
					equipmentPlan.Slots[j] = ItemKey.Invalid;
					isModified = true;
				}
			}
			if (isModified)
			{
				SetElement_EquipmentsPlans(i, equipmentPlan, context);
				Logger.Warn($"Fixing abnormal equipment plan {i}.");
			}
		}
	}

	private void FixAbnormalGroupData(DataContext context)
	{
		OrganizationInfo taiwuOrgInfo = _taiwuChar.GetOrganizationInfo();
		OrganizationInfo expectedGroupOrgInfo = new OrganizationInfo(taiwuOrgInfo.OrgTemplateId, 0, principal: true, taiwuOrgInfo.SettlementId);
		OrganizationItem expectedOrgCfg = Config.Organization.Instance[expectedGroupOrgInfo.OrgTemplateId];
		OrganizationMemberItem expectedOrgMemberCfg = OrganizationDomain.GetOrgMemberConfig(expectedGroupOrgInfo);
		foreach (int groupCharId in _groupCharIds.GetCollection())
		{
			GameData.Domains.Character.Character groupChar = DomainManager.Character.GetElement_Objects(groupCharId);
			if (groupChar.IsActiveExternalRelationState(188uL))
			{
				groupChar.DeactivateExternalRelationState(context, 188uL);
			}
			if (DomainManager.Character.TryGetElement_CrossAreaMoveInfos(groupCharId, out var _))
			{
				DomainManager.Character.RemoveCrossAreaTravelInfo(context, groupCharId);
				Logger.Warn($"Removing unexpectedly traveling taiwu group member {groupChar}");
			}
			OrganizationInfo orgInfo = groupChar.GetOrganizationInfo();
			if (orgInfo.OrgTemplateId != taiwuOrgInfo.OrgTemplateId)
			{
				(string surname, string givenName) realName = CharacterDomain.GetRealName(groupChar);
				string surname = realName.surname;
				string givenName = realName.givenName;
				OrganizationMemberItem orgMemberCfg = OrganizationDomain.GetOrgMemberConfig(orgInfo);
				OrganizationItem orgCfg = Config.Organization.Instance[orgInfo.OrgTemplateId];
				if (DomainManager.Organization.TryGetSettlementCharacter(groupCharId, out var settlementChar) && settlementChar.GetSettlementId() != expectedGroupOrgInfo.SettlementId)
				{
					DomainManager.Organization.ChangeOrganization(context, groupChar, expectedGroupOrgInfo);
				}
				Logger.Warn($"Fixing abnormal taiwu group char {surname}{givenName}({groupCharId}) organization: {orgCfg.Name}{orgMemberCfg.GradeName} => {expectedOrgCfg.Name}{expectedOrgMemberCfg.GradeName}");
			}
		}
	}

	private void RemoveTaiwuInvalidFeatures(DataContext context)
	{
		List<short> featureIds = _taiwuChar.GetFeatureIds();
		for (sbyte combatSkillType = 0; combatSkillType < 14; combatSkillType++)
		{
			CombatSkillTypeItem combatSkillTypeCfg = Config.CombatSkillType.Instance[combatSkillType];
			if (featureIds.Remove(combatSkillTypeCfg.LegendaryBookFeature))
			{
				Logger.Warn("Removing taiwu's invalid feature " + CharacterFeature.Instance[combatSkillTypeCfg.LegendaryBookFeature].Name);
			}
		}
		_taiwuChar.SetFeatureIds(featureIds, context);
	}

	private void FixNotLearnedSkills(DataContext context)
	{
		HashSet<short> notLearnedLifeSkills = _notLearnLifeSkillReadingProgress.Keys.ToHashSet();
		HashSet<short> learnedLifeSkills = _lifeSkills.Keys.ToHashSet();
		notLearnedLifeSkills.IntersectWith(learnedLifeSkills);
		List<GameData.Domains.Character.LifeSkillItem> taiwuLifeSkills = _taiwuChar.GetLearnedLifeSkills();
		if (notLearnedLifeSkills.Count > 0)
		{
			foreach (short templateId in notLearnedLifeSkills)
			{
				Logger.Warn("Fixing life skill exists in both not learned and learned skills: " + LifeSkill.Instance[templateId].Name);
				TaiwuLifeSkill notLearnedLifeSkill = GetElement_NotLearnLifeSkillReadingProgress(templateId);
				TaiwuLifeSkill learnedLifeSkill = GetElement_LifeSkills(templateId);
				for (byte pageId = 0; pageId < 5; pageId++)
				{
					OfflineAddReadingProgress(learnedLifeSkill, pageId, notLearnedLifeSkill.GetBookPageReadingProgress(pageId));
				}
				RemoveElement_NotLearnLifeSkillReadingProgress(templateId, context);
				SetElement_LifeSkills(templateId, learnedLifeSkill, context);
			}
		}
		for (int i = 0; i < taiwuLifeSkills.Count; i++)
		{
			GameData.Domains.Character.LifeSkillItem skillItem = taiwuLifeSkills[i];
			if (!_lifeSkills.ContainsKey(skillItem.SkillTemplateId))
			{
				RegisterLifeSkill(context, skillItem);
				Logger.Warn("Fixing unregistered life skill " + LifeSkill.Instance[skillItem.SkillTemplateId].Name);
			}
		}
		bool lifeSkillChanged = false;
		foreach (KeyValuePair<short, TaiwuLifeSkill> lifeSkill2 in _lifeSkills)
		{
			lifeSkill2.Deconstruct(out var key, out var value);
			short templateId2 = key;
			TaiwuLifeSkill lifeSkill = value;
			int index = _taiwuChar.FindLearnedLifeSkillIndex(templateId2);
			if (index >= 0)
			{
				continue;
			}
			Config.LifeSkillItem lifeSkillCfg = LifeSkill.Instance[templateId2];
			LifeSkillTypeItem skillTypeCfg = Config.LifeSkillType.Instance[lifeSkillCfg.Type];
			GameData.Domains.Character.LifeSkillItem lifeSkillItem = new GameData.Domains.Character.LifeSkillItem(templateId2);
			for (byte pageId2 = 0; pageId2 < 5; pageId2++)
			{
				if (lifeSkill.GetBookPageReadingProgress(pageId2) >= 100)
				{
					lifeSkillItem.SetPageRead(pageId2);
				}
			}
			taiwuLifeSkills.Add(lifeSkillItem);
			lifeSkillChanged = true;
			Logger.Warn($"Fixing lifeSkill {lifeSkillCfg.Name} ({skillTypeCfg.Name}) exists only in taiwu data, not in char data");
		}
		if (lifeSkillChanged)
		{
			_taiwuChar.SetLearnedLifeSkills(taiwuLifeSkills, context);
		}
		HashSet<short> notLearnedCombatSkills = _notLearnCombatSkillReadingProgress.Keys.ToHashSet();
		HashSet<short> learnedCombatSkills = _combatSkills.Keys.ToHashSet();
		notLearnedCombatSkills.IntersectWith(learnedCombatSkills);
		if (notLearnedCombatSkills.Count <= 0)
		{
			return;
		}
		foreach (short templateId3 in notLearnedCombatSkills)
		{
			Logger.Warn("Fixing combat skill exists in both not learned and learned skills: " + Config.CombatSkill.Instance[templateId3].Name);
			TaiwuCombatSkill notLearnedCombatSkill = GetElement_NotLearnCombatSkillReadingProgress(templateId3);
			TaiwuCombatSkill learnedCombatSkill = GetElement_CombatSkills(templateId3);
			for (byte internalIndex = 0; internalIndex < 15; internalIndex++)
			{
				OfflineAddReadingProgress(learnedCombatSkill, internalIndex, notLearnedCombatSkill.GetBookPageReadingProgress(internalIndex));
			}
			RemoveElement_NotLearnCombatSkillReadingProgress(templateId3, context);
			SetElement_CombatSkills(templateId3, learnedCombatSkill, context);
		}
	}

	private void FixHiddenEquipSkills(DataContext context)
	{
		bool changed = false;
		short[] equipSkills = _taiwuChar.GetEquippedCombatSkills();
		for (sbyte index = GameData.Domains.Character.CombatSkillHelper.SlotEndIndexes[^1]; index < equipSkills.Length; index++)
		{
			if (equipSkills[index] >= 0)
			{
				equipSkills[index] = -1;
				changed = true;
			}
		}
		if (changed)
		{
			_taiwuChar.SetEquippedCombatSkills(equipSkills, context);
			AdaptableLog.Warning("Hidden equip skills removed");
		}
	}

	private bool FixWarehouseModifiedItem(DataContext context, ItemKey key, out ItemKey baseKey)
	{
		baseKey = DomainManager.Item.GetBaseItem(key).GetItemKey();
		if (!key.Equals(baseKey))
		{
			int amount = DomainManager.Taiwu.GetWarehouseItemCount(key);
			DomainManager.Taiwu.WarehouseRemove(context, key, amount);
			DomainManager.Taiwu.WarehouseAdd(context, baseKey, amount);
			return true;
		}
		return false;
	}

	private void FixWarehouseNontransferableItems(DataContext context, ItemKey key)
	{
		ItemBase baseItem = DomainManager.Item.GetBaseItem(key);
		if (!baseItem.GetTransferable())
		{
			int amount = DomainManager.Taiwu.GetWarehouseItemCount(key);
			DomainManager.Taiwu.WarehouseRemove(context, key, amount);
			_taiwuChar.AddInventoryItem(context, key, amount);
		}
	}

	private bool FixWarehouseExtraGoodsItems(DataContext context, ItemKey key, out ItemKey result)
	{
		result = ItemKey.Invalid;
		if (ModificationStateHelper.IsActive(key.ModificationState, 8))
		{
			DomainManager.Taiwu.WarehouseRemove(context, key, 1, deleteItem: true);
			result = DomainManager.Item.CreateItem(context, key.ItemType, key.TemplateId);
			DomainManager.Taiwu.WarehouseAdd(context, result, 1);
			return true;
		}
		return false;
	}

	private bool FixWarehouseSectAccessoryItems(DataContext context, ItemKey key, out ItemKey result)
	{
		result = ItemKey.Invalid;
		ItemBase resultItem;
		bool removed = DomainManager.Item.RemoveRefinedEffectsAndReturnMaterial(context, key, null, out resultItem);
		if (removed)
		{
			result = resultItem.GetItemKey();
			DomainManager.Taiwu.WarehouseRemove(context, key, 1);
			DomainManager.Taiwu.WarehouseAdd(context, result, 1);
		}
		return removed;
	}

	private void FixWarehouse(DataContext context)
	{
		bool versionNeedRepairSectAccessory = DomainManager.Item.VersionNeedRepairSectAccessory;
		HashSet<ItemKey> currItems = ObjectPool<HashSet<ItemKey>>.Instance.Get();
		currItems.Clear();
		List<ItemKey> warehouseList = DomainManager.Taiwu.GetWarehouseAllItemKey();
		for (int i = 0; i < warehouseList.Count; i++)
		{
			ItemKey key = warehouseList[i];
			if (DomainManager.Item.ItemExists(key))
			{
				if (FixWarehouseModifiedItem(context, key, out var result))
				{
					key = result;
				}
				if (FixWarehouseExtraGoodsItems(context, key, out result))
				{
					key = result;
				}
				if (versionNeedRepairSectAccessory && FixWarehouseSectAccessoryItems(context, key, out result))
				{
					key = result;
				}
				FixWarehouseNontransferableItems(context, key);
				if (!ItemTemplateHelper.IsStackable(key.ItemType, key.TemplateId))
				{
					int amount = DomainManager.Taiwu.GetWarehouseItemCount(key);
					if (amount > 1)
					{
						currItems.Add(key);
					}
				}
			}
			else
			{
				_warehouse.Items.Remove(key);
				Logger.Warn($"Removing non-existing warehouse item {key}.");
			}
		}
		if (currItems.Count > 0)
		{
			foreach (ItemKey currItem in currItems)
			{
				_warehouse.Items[currItem] = 1;
				Logger.Warn($"Fixing unstackable warehouse item {currItem}.");
			}
			currItems.Clear();
		}
		ObjectPool<HashSet<ItemKey>>.Instance.Return(currItems);
	}

	private void FixAllTreasuries(DataContext context)
	{
		if (FixTreasury(context, _treasury))
		{
			SetTreasury(_treasury, context);
			Logger.Warn("Taiwu Village treasury fixed.");
		}
		List<Settlement> settlements = new List<Settlement>();
		DomainManager.Organization.GetAllSettlements(settlements);
		foreach (Settlement settlement in settlements)
		{
			if (!DomainManager.Extra.TryGetElement_SettlementLayeredTreasuries(settlement.GetId(), out var treasuries))
			{
				continue;
			}
			SettlementTreasury[] settlementTreasuries = treasuries.SettlementTreasuries;
			foreach (SettlementTreasury treasury in settlementTreasuries)
			{
				if (FixTreasury(context, treasury))
				{
					Logger.Warn($"{settlement} treasury fixed.");
				}
			}
		}
	}

	private static bool FixTreasury(DataContext context, SettlementTreasury treasury)
	{
		if (treasury == null || treasury.Inventory == null)
		{
			return false;
		}
		bool modified = false;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		Inventory taiwuInventory = taiwuChar.GetInventory();
		List<ItemKey> treasuryItems = treasury.Inventory.Items.Keys.ToList();
		for (int i = 0; i < treasuryItems.Count; i++)
		{
			ItemKey key = treasuryItems[i];
			if (!DomainManager.Item.ItemExists(key))
			{
				treasury.Inventory.Items.Remove(key);
				Logger.Warn($"Removing non-existing treasury item {key}.");
				modified = true;
			}
			else if (taiwuInventory.Items.ContainsKey(key) && !ItemTemplateHelper.IsPureStackable(key))
			{
				treasury.Inventory.Items.Remove(key);
				Logger.Warn($"Removing duplicate treasury item {key} which is already in {taiwuChar}.");
				modified = true;
			}
		}
		return modified;
	}

