	private void FixFiveLoongDlcClothing(DataContext context)
	{
		if (!DlcManager.IsDlcInstalled(2764950uL))
		{
			return;
		}
		bool[] alreadyHave = new bool[5];
		ItemKey[] equipment = _taiwuChar.GetEquipment();
		for (int i = equipment.Length - 1; i >= 0; i--)
		{
			ItemKey key = equipment[i];
			if (key.ItemType == 3)
			{
				short templateId = key.TemplateId;
				if (templateId >= 75 && templateId <= 79)
				{
					int index = key.TemplateId - 75;
					if (!alreadyHave[index])
					{
						alreadyHave[index] = true;
					}
				}
			}
		}
		List<ItemKey> inventoryList = _taiwuChar.GetInventory().Items.Keys.ToList();
		for (int i2 = inventoryList.Count - 1; i2 >= 0; i2--)
		{
			ItemKey key2 = inventoryList[i2];
			if (key2.ItemType == 3)
			{
				short templateId = key2.TemplateId;
				if (templateId >= 75 && templateId <= 79)
				{
					int index2 = key2.TemplateId - 75;
					if (!alreadyHave[index2])
					{
						alreadyHave[index2] = true;
					}
					else
					{
						_taiwuChar.RemoveInventoryItem(context, key2, 1, deleteItem: true);
						Logger.Warn($"Fixing taiwu repeated fiveLoongCloth, templateId: {key2.TemplateId}");
					}
				}
			}
		}
	}

	private void FixSkillBookReadingProgress(DataContext context)
	{
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = _taiwuChar.GetLearnedLifeSkills();
		List<short> learnedCombatSkills = _taiwuChar.GetLearnedCombatSkills();
		foreach (GameData.Domains.Character.LifeSkillItem lifeSkillItem in learnedLifeSkills)
		{
			if (TryGetTaiwuLifeSkill(lifeSkillItem.SkillTemplateId, out var taiwuLifeSkill))
			{
				FixLifeSkillBookReadingProgress(lifeSkillItem, taiwuLifeSkill);
			}
		}
		foreach (short templateId in learnedCombatSkills)
		{
			if (TryGetElement_CombatSkills(templateId, out var taiwuCombatSkill))
			{
				FixCombatSkillBookReadingProgress(templateId, taiwuCombatSkill);
			}
		}
		void FixCombatSkillBookReadingProgress(short skillTemplateId, TaiwuCombatSkill taiwuCombatSkill2)
		{
			if (DomainManager.CombatSkill.TryGetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillTemplateId), out var skillItem))
			{
				bool isChange = false;
				for (byte combatSkillBookInternalIndex = 0; combatSkillBookInternalIndex < 15; combatSkillBookInternalIndex++)
				{
					sbyte readingProgress = taiwuCombatSkill2.GetBookPageReadingProgress(combatSkillBookInternalIndex);
					if (readingProgress < 100 && CombatSkillStateHelper.IsPageRead(skillItem.GetReadingState(), combatSkillBookInternalIndex))
					{
						taiwuCombatSkill2.SetBookPageReadingProgress(combatSkillBookInternalIndex, 100);
						isChange = true;
					}
				}
				if (isChange)
				{
					SetTaiwuCombatSkill(context, skillTemplateId, taiwuCombatSkill2);
					Logger.Warn("Fixing taiwu Wrong SkillBookReadingProgress, SkillName: " + Config.CombatSkill.Instance[skillTemplateId].Name);
				}
			}
		}
		void FixLifeSkillBookReadingProgress(GameData.Domains.Character.LifeSkillItem lifeSkillItem2, TaiwuLifeSkill taiwuLifeSkill2)
		{
			short skillTemplateId = lifeSkillItem2.SkillTemplateId;
			bool isChange = false;
			for (byte pageId = 0; pageId < 5; pageId++)
			{
				sbyte readingProgress = taiwuLifeSkill2.GetBookPageReadingProgress(pageId);
				if (readingProgress < 100 && lifeSkillItem2.IsPageRead(pageId))
				{
					taiwuLifeSkill2.SetBookPageReadingProgress(pageId, 100);
					isChange = true;
				}
			}
			if (isChange)
			{
				DomainManager.Taiwu.SetTaiwuLifeSkill(context, skillTemplateId, taiwuLifeSkill2);
				Logger.Warn("Fixing taiwu Wrong SkillBookReadingProgress, SkillName: " + LifeSkill.Instance[skillTemplateId].Name);
			}
		}
	}

	private void FixSkillBookReadingState(DataContext context)
	{
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = _taiwuChar.GetLearnedLifeSkills();
		List<LifeSkillStateModify> lifeSkillModifyList = new List<LifeSkillStateModify>();
		for (int i = 0; i < learnedLifeSkills.Count; i++)
		{
			GameData.Domains.Character.LifeSkillItem lifeSkillItem = learnedLifeSkills[i];
			if (TryGetTaiwuLifeSkill(lifeSkillItem.SkillTemplateId, out var taiwuLifeSkill))
			{
				FixLifeSkillBookReadingState(lifeSkillItem, taiwuLifeSkill, i, lifeSkillModifyList);
			}
		}
		bool lifeSkillStateModified = lifeSkillModifyList.Count > 0;
		foreach (LifeSkillStateModify modify in lifeSkillModifyList)
		{
			GameData.Domains.Character.LifeSkillItem lifeSkillItem2 = learnedLifeSkills[modify.Index];
			lifeSkillItem2.ReadingState = (byte)(lifeSkillItem2.ReadingState | (1 << modify.ReadPageIndex));
			learnedLifeSkills[modify.Index] = lifeSkillItem2;
		}
		if (lifeSkillStateModified)
		{
			_taiwuChar.SetLearnedLifeSkills(learnedLifeSkills, context);
		}
		static void FixLifeSkillBookReadingState(GameData.Domains.Character.LifeSkillItem lifeSkillItem3, TaiwuLifeSkill taiwuLifeSkill2, int index, List<LifeSkillStateModify> lifeSkillStateModifies)
		{
			for (byte pageId = 0; pageId < 5; pageId++)
			{
				sbyte readingProgress = taiwuLifeSkill2.GetBookPageReadingProgress(pageId);
				if (readingProgress == 100 && !lifeSkillItem3.IsPageRead(pageId))
				{
					lifeSkillStateModifies.Add(new LifeSkillStateModify
					{
						Index = index,
						ReadPageIndex = pageId
					});
				}
			}
		}
	}

