	private void RegisterUpdateMusicBonus()
	{
		DataUid musicUid = new DataUid(19, 68, ulong.MaxValue);
		DataUid isEnabledUid = new DataUid(19, 69, ulong.MaxValue);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(musicUid, "UpdateMusicBonus", UpdateMusicBonus);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(isEnabledUid, "UpdateMusicBonus", UpdateMusicBonus);
	}

	private void UpdateMusicBonus(DataContext context, DataUid uid)
	{
		short musicId = DomainManager.Extra.GetSectXuannvPlayerMusicId();
		bool isEnabled = DomainManager.Extra.GetSectXuannvPlayerIsEnabled();
		if (musicId < 0 || !isEnabled)
		{
			HashSet<int> taiwuGroupCharIds = _groupCharIds.GetCollection();
			foreach (int charId in taiwuGroupCharIds)
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
				character.RemoveFeatureGroup(context, 262);
			}
			{
				foreach (int charId2 in _taiwuSpecialGroup)
				{
					GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId2);
					character2.RemoveFeatureGroup(context, 262);
				}
				return;
			}
		}
		short featureId = Music.Instance[musicId].TemporaryFeature;
		HashSet<int> taiwuGroupCharIds2 = _groupCharIds.GetCollection();
		foreach (int charId3 in taiwuGroupCharIds2)
		{
			GameData.Domains.Character.Character character3 = DomainManager.Character.GetElement_Objects(charId3);
			character3.AddFeature(context, featureId, removeMutexFeature: true);
		}
		foreach (int charId4 in _taiwuSpecialGroup)
		{
			GameData.Domains.Character.Character character4 = DomainManager.Character.GetElement_Objects(charId4);
			character4.AddFeature(context, featureId, removeMutexFeature: true);
		}
	}

