	[DomainMethod]
	public void AddHideSkeletonEquipSlot(DataContext context, sbyte slotType)
	{
		int equipPlanId = GetCurrEquipmentPlanId();
		if (!_hideSkeletonEquipSlots.ContainsKey(equipPlanId))
		{
			AddElement_HideSkeletonEquipSlots(equipPlanId, SByteList.Create(), context);
		}
		SByteList slotList = _hideSkeletonEquipSlots[equipPlanId];
		if (!slotList.Items.Contains(slotType))
		{
			slotList.Items.Add(slotType);
			SetElement_HideSkeletonEquipSlots(equipPlanId, slotList, context);
		}
	}

	[DomainMethod]
	public void RemoveHideSkeletonEquipSlot(DataContext context, sbyte slotType)
	{
		int equipPlanId = GetCurrEquipmentPlanId();
		if (_hideSkeletonEquipSlots.TryGetValue(equipPlanId, out var slotList) && slotList.Items.Contains(slotType))
		{
			slotList.Items.Remove(slotType);
			if (slotList.Items.Count > 0)
			{
				SetElement_HideSkeletonEquipSlots(equipPlanId, slotList, context);
			}
			else
			{
