	private int CalcBuildingSpaceLimit()
	{
		int maxSpace = GetTaiwuVillageBaseSpace();
		if (_prosperousConstruction)
		{
			maxSpace += 30;
		}
		maxSpace += GetBuildingSpaceExtraAdd();
		Location taiwuLocation = GetTaiwuVillageLocation();
		return maxSpace + DomainManager.Building.GetBuildingBlockEffect(taiwuLocation, EBuildingScaleEffect.BuildingSpaceBonus);
	}

	private int GetTaiwuVillageBaseSpace()
	{
		int maxSpace = 0;
		BuildingScaleItem config = BuildingScale.Instance[(short)107];
		bool challenge = DomainManager.World.IsChallengeModeEnabled(EChallengeModeImplement.BuildingAreaLimit);
		List<Location> taiwuBuildingList = DomainManager.Building.GetTaiwuBuildingAreas();
		Location taiwuLocation = GetTaiwuVillageLocation();
		for (int i = 0; i < taiwuBuildingList.Count; i++)
		{
			Location location = taiwuBuildingList[i];
			if (location.AreaId != taiwuLocation.AreaId || location.BlockId != taiwuLocation.BlockId)
			{
				continue;
			}
			BuildingAreaData areaData = DomainManager.Building.GetElement_BuildingAreas(location);
			for (short index = 0; index < areaData.Width * areaData.Width; index++)
			{
				BuildingBlockKey blockKey = new BuildingBlockKey(location.AreaId, location.BlockId, index);
				BuildingBlockData blockData = DomainManager.Building.GetElement_BuildingBlocks(blockKey);
				if (blockData.TemplateId == 44 && blockData.CanUse())
				{
					int level = blockData.CalcUnlockedLevelCount() - 1;
					int normalLevelEffect = config.LevelEffect.GetOrLast(level);
					if (challenge)
					{
						normalLevelEffect -= level;
					}
					maxSpace += normalLevelEffect;
				}
			}
		}
		if (challenge)
		{
			maxSpace -= GlobalConfig.Instance.ChallengeTaiwuVillageBaseSpaceReduce;
		}
		return maxSpace;
	}

	public bool TriggerBuildingSpaceGuiding()
	{
		int curr = CalcBuildingSpaceCurr();
		int limit = CalcBuildingSpaceLimit();
		return (float)curr / (float)limit >= 0.8f;
	}

	[SingleValueDependency(9, new ushort[] { 2 })]
	[SingleValueCollectionDependency(9, new ushort[] { 1 })]
	private int CalcBuildingSpaceCurr()
	{
		int currentSpace = 0;
		List<Location> taiwuBuildingList = DomainManager.Building.GetTaiwuBuildingAreas();
		Location taiwuLocation = GetTaiwuVillageLocation();
		for (int i = 0; i < taiwuBuildingList.Count; i++)
		{
			Location location = taiwuBuildingList[i];
			if (location.AreaId != taiwuLocation.AreaId || location.BlockId != taiwuLocation.BlockId)
			{
				continue;
			}
			BuildingAreaData areaData = DomainManager.Building.GetElement_BuildingAreas(location);
			for (short index = 0; index < areaData.Width * areaData.Width; index++)
			{
				BuildingBlockKey blockKey = new BuildingBlockKey(location.AreaId, location.BlockId, index);
				BuildingBlockData blockData = DomainManager.Building.GetElement_BuildingBlocks(blockKey);
				if (blockData.TemplateId >= 0 && (BuildingBlock.Instance[blockData.TemplateId].Type == EBuildingBlockType.Building || BuildingBlock.Instance[blockData.TemplateId].Type == EBuildingBlockType.MainBuilding))
				{
					currentSpace += BuildingBlock.Instance[blockData.TemplateId].Width;
				}
			}
		}
		return currentSpace;
	}

