	[ObjectCollectionDependency(4, 0, new ushort[] { 34 }, Condition = InfluenceCondition.CharIsTaiwu)]
	[ObjectCollectionDependency(4, 0, new ushort[] { 96, 97, 55 }, Condition = InfluenceCondition.CharIsTaiwuWorker)]
	private void CalcResourceChange(int[] value)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(10))
		{
			for (sbyte resourceType = 0; resourceType < 8; resourceType++)
			{
				value[resourceType] = 0;
			}
			return;
		}
		CalcResourceChangeBeforeExpand(value);
		for (sbyte i = 0; i < value.Length; i++)
		{
			value[i] += DomainManager.Extra.CalcResourceChangeByJiaoPool(i);
		}
		value[7] += DomainManager.Taiwu.GetVillagerRoleHeadTotalAuthorityCost();
		value[7] += DomainManager.Organization.CalcApprovingRateEffectAuthorityGain();
		if (SharedMethods.NeedCostMoreResource)
		{
			ResourceInts cost = GetTotalVillagerMaintenance();
			for (int index = 0; index < 8; index++)
			{
				value[index] -= cost[index];
			}
		}
	}

	public void CalcResourceChangeBeforeExpand(int[] value)
	{
		CalcResourceBlockIncomeEffectValues(ref value);
		foreach (KeyValuePair<int, VillagerWorkData> item in _villagerWork)
		{
			VillagerWorkData workData = item.Value;
			if (workData.WorkType == 10 && CanWork(workData.CharacterId))
			{
				int addResource = workData.GetCollectResourceIncome();
				value[workData.ResourceType] += addResource;
			}
		}
		List<Location> taiwuBuildingList = DomainManager.Building.GetTaiwuBuildingAreas();
		for (int i = 0; i < taiwuBuildingList.Count; i++)
		{
			Location location = taiwuBuildingList[i];
			BuildingAreaData areaData = DomainManager.Building.GetElement_BuildingAreas(location);
			for (short index = 0; index < areaData.Width * areaData.Width; index++)
			{
				BuildingBlockKey blockKey = new BuildingBlockKey(location.AreaId, location.BlockId, index);
				BuildingBlockData blockData = DomainManager.Building.GetElement_BuildingBlocks(blockKey);
				if (blockData.RootBlockIndex < 0)
				{
					BuildingBlockItem configData = BuildingBlock.Instance[blockData.TemplateId];
					if (configData.IsCollectResourceBuilding)
					{
						sbyte resourceType = DomainManager.Building.GetCollectBuildingResourceType(blockKey);
						sbyte getResourceType = (sbyte)((resourceType < 6) ? resourceType : 5);
						value[getResourceType] += DomainManager.Building.CalcResourceOutputCount(blockKey, getResourceType);
					}
					if (blockData.NeedMaintenanceCost())
					{
						int[] maintenanceCost = GameData.Domains.Building.SharedMethods.GetFinalMaintenanceCost(configData);
						for (int j = 0; j < maintenanceCost.Length; j++)
						{
							value[j] -= maintenanceCost[j];
						}
					}
					if (blockData.TemplateId == 45 && blockData.CanUse())
					{
						value[7] += DomainManager.Building.CalculateGainAuthorityByShrinePerMonth(blockKey);
					}
					if (blockData.Durability == 0 && blockData.CalcUnlockedLevelCount() == 1 && configData.DestoryType == 1)
					{
						value[7] -= configData.MaxDurability;
					}
				}
			}
		}
		if (DomainManager.World.GetCurrMonthInYear() == GlobalConfig.Instance.CricketActiveStartMonth - 1)
		{
			value[7] += BuildingDomain.GetCricketAuthorityGain();
		}
	}

	public void CalcResourceBlockIncomeEffectValues(ref int[] value)
	{
		Location taiwuLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		ResourceInts resourcesChange = DomainManager.Building.CalcResourceBlockIncomeEffects(taiwuLocation).resourcesChange;
		DomainManager.Building.FinalizeResourceBlockIncomeEffectValues(ref resourcesChange, isTaiwu: true);
		for (int i = 0; i < value.Length; i++)
		{
			value[i] += resourcesChange.Get(i);
		}
	}

