	[ObjectCollectionDependency(4, 0, new ushort[] { 26 }, Condition = InfluenceCondition.CharIsInTaiwuGroup)]
	private Injuries CalcTaiwuGroupWorstInjuries()
	{
		HashSet<int> ids = DomainManager.Taiwu.GetGroupCharIds().GetCollection();
		Injuries res = default(Injuries);
		res.Initialize();
		foreach (int id in ids)
		{
			Injuries injuries = DomainManager.Character.GetElement_Objects(id).GetInjuries();
			for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
			{
				var (outer, inner) = injuries.Get(bodyPart);
				if (res.Get(bodyPart, isInnerInjury: true) < inner)
				{
					res.Set(bodyPart, isInnerInjury: true, inner);
				}
				if (res.Get(bodyPart, isInnerInjury: false) < outer)
				{
					res.Set(bodyPart, isInnerInjury: false, outer);
				}
			}
		}
		return res;
	}

