	public void FindWarehouseItems(Predicate<ItemBase> predicate, List<(ItemKey itemKey, int amount)> items)
	{
		foreach (KeyValuePair<ItemKey, int> item2 in _warehouse.Items)
		{
			item2.Deconstruct(out var key, out var value);
			ItemKey itemKey = key;
			int amount = value;
			ItemBase item = DomainManager.Item.GetBaseItem(itemKey);
			if (predicate(item))
			{
				items.Add((itemKey, amount));
			}
		}
	}

