	public void LoseOverloadWarehouseItems(DataContext context)
	{
		List<MapBlockData> neighborList = ObjectPool<List<MapBlockData>>.Instance.Get();
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
		int currDate = DomainManager.World.GetCurrDate();
		TaiwuVillageStoragesRecordCollection taiwuVillageStoragesRecordCollection = DomainManager.Taiwu.GetTaiwuVillageStoragesRecordCollection();
		bool addSecretInformation = false;
		ItemKey secretInfoParamItemKey = ItemKey.Invalid;
		Location taiwuVillageLocation = GetTaiwuVillageLocation();
		int reduceHappiness = 0;
		int troughCurrLoad = DomainManager.Taiwu.CalcTroughCurrLoad();
		int troughMaxLoad = GetTroughMaxLoad();
		if (troughCurrLoad > troughMaxLoad)
		{
			LoseOverloadItems(ItemSourceType.Trough, DomainManager.Taiwu.TroughItems, troughCurrLoad - troughMaxLoad);
		}
		int overloadedWeight = GetWarehouseCurrLoad() - GetWarehouseMaxLoad();
		if (overloadedWeight <= 0)
		{
			Clean();
			return;
		}
		ItemSourceType[] taiwuVillageStorages = TaiwuVillageStorages;
		foreach (ItemSourceType sourceType in taiwuVillageStorages)
		{
			IReadOnlyDictionary<ItemKey, int> items = GetItems(sourceType);
			LoseOverloadItems(sourceType, items, overloadedWeight);
			overloadedWeight = GetWarehouseCurrLoad() - GetWarehouseMaxLoad();
			if (overloadedWeight <= 0)
			{
				break;
			}
		}
		CommitTaiwuVillageStoragesRecordCollection(context);
		if (addSecretInformation)
		{
			SecretInformationCollection secretInformationCollection = DomainManager.Information.GetSecretInformationCollection();
			int secretInfoOffset = secretInformationCollection.AddLoseOverloadingItem(_taiwuCharId, (ulong)secretInfoParamItemKey, taiwuVillageLocation);
			DomainManager.Information.AddSecretInformationWithNecessity(context, secretInfoOffset, withInitialDistribute: true, necessarily: false, null);
		}
		if (reduceHappiness > 0)
		{
			_taiwuChar.ChangeHappiness(context, -reduceHappiness);
		}
		instantNotifications.AddHappinessDecreased(_taiwuCharId);
		Clean();
		void Clean()
		{
			ObjectPool<List<MapBlockData>>.Instance.Return(neighborList);
		}
		void LoseOverloadItems(ItemSourceType itemSourceType, IReadOnlyDictionary<ItemKey, int> oriItems, int toLoseWeight)
		{
			List<(ItemBase, int)> itemsToBeLost = context.AdvanceMonthRelatedData.ItemsWithAmount.Occupy();
			CharacterDomain.GetLostItemsDueToOverload(context, toLoseWeight, oriItems, itemsToBeLost);
			DomainManager.Map.GetNeighborBlocks(taiwuVillageLocation.AreaId, taiwuVillageLocation.BlockId, neighborList, 3);
			int j = 0;
			for (int count = itemsToBeLost.Count; j < count; j++)
			{
				(ItemBase, int) tuple = itemsToBeLost[j];
				ItemBase item = tuple.Item1;
				int amount = tuple.Item2;
				ItemKey itemKey = item.GetItemKey();
				monthlyNotifications.AddLoseItemCausedByWarehouseFull(itemKey.ItemType, itemKey.TemplateId);
				taiwuVillageStoragesRecordCollection.AddLoseOverloadWarehouseItems(currDate, GetTaiwuVillageStorageType(itemSourceType), itemKey.ItemType, itemKey.TemplateId);
				RemoveItem(context, itemKey, amount, itemSourceType, deleteItem: false);
				MapBlockData block = neighborList[context.Random.Next(neighborList.Count)];
				DomainManager.Map.AddBlockItem(context, block, itemKey, amount);
				reduceHappiness += item.GetHappinessChange() * amount;
				if (!addSecretInformation && ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId) >= 6)
				{
					addSecretInformation = true;
					if (!secretInfoParamItemKey.IsValid() || ItemTemplateHelper.GetBaseValue(secretInfoParamItemKey.ItemType, secretInfoParamItemKey.TemplateId) < ItemTemplateHelper.GetBaseValue(itemKey.ItemType, itemKey.TemplateId))
					{
						secretInfoParamItemKey = itemKey;
					}
				}
			}
			context.AdvanceMonthRelatedData.ItemsWithAmount.Release(ref itemsToBeLost);
		}
	}

