	[DomainMethod]
	public ResourceInts GetTotalVillagerMaintenance()
	{
		ResourceInts paid = new ResourceInts(default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int));
		if (SharedMethods.NeedCostMoreResource)
		{
			foreach (var item in from villager in DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId).GetMembers().Select(GetVillagerMaintenance)
				where villager.character != null && villager.character.GetId() != _taiwuCharId
				select villager)
			{
				ResourceInts resources = item.resources;
				paid.Add(ref resources);
			}
		}
		return paid;
	}

	public void CostResources(DataContext context)
	{
		MonthlyNotificationCollection monthlyNotification = DomainManager.World.GetMonthlyNotificationCollection();
		ResourceInts paid = new ResourceInts(default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int));
		ResourceInts totalResources = GetTotalResources();
		foreach (var villager in from tuple in DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId).GetMembers().Select(GetVillagerMaintenance)
			where tuple.character != null && tuple.character.GetId() != _taiwuCharId
			orderby tuple.resources.GetValueSum() descending
			select tuple)
		{
			ResourceInts resources = villager.resources;
			resources.Add(ref paid);
			if (totalResources.CheckIsMeet(ref resources))
			{
				paid = resources;
				continue;
			}
			monthlyNotification.AddCostResourceNotEnough(villager.character.GetId());
			CharacterDomain character = DomainManager.Character;
			GameData.Domains.Character.Character item = villager.character;
			GameData.Domains.Character.Character taiwuChar = _taiwuChar;
			ResourceInts item2 = villager.resources;
			character.ChangeFavorabilityOptional(context, item, taiwuChar, (int)Math.Clamp((float)item2.GetValueSum() * (0f - GlobalConfig.Instance.ChallengeCostResourceFavorFactor), -2.1474836E+09f, 0f), 5);
			if (DomainManager.Character.GetFavorability(villager.character.GetId(), _taiwuChar.GetId()) < GlobalConfig.Instance.ChallengeCostResourceLeaveVillageThreshold)
			{
				VillagerLeaveTaiwuVillage(context, villager.character);
				monthlyNotification.AddCostResourceNotEnoughResult(villager.character.GetId());
			}
		}
		ResourceInts taiwuResources = _taiwuChar.GetResources();
		SettlementTreasury treasury = GetTaiwuTreasury();
		bool treasuryUpdated = false;
		for (sbyte type = 0; type < 8; type++)
		{
			int toLoseAmount = paid[type];
			if (LoseResource(type, ref taiwuResources, ref toLoseAmount))
			{
				_taiwuChar.SetResources(ref taiwuResources, context);
			}
			if (LoseResource(type, ref treasury.Resources, ref toLoseAmount, TaiwuVillageStorageType.Treasury))
			{
				treasuryUpdated = true;
			}
		}
		if (treasuryUpdated)
		{
			SetTaiwuTreasury(context, treasury);
		}
		static bool LoseResource(sbyte resourceType, ref ResourceInts reference2, ref int reference, TaiwuVillageStorageType storageType = TaiwuVillageStorageType.Count)
		{
			if (reference <= 0)
			{
				return false;
			}
			int loseAmount = Math.Min(reference2[resourceType], reference);
			if (loseAmount > 0)
			{
				reference2[resourceType] -= loseAmount;
				reference -= loseAmount;
			}
			return true;
		}
	}

	public static (GameData.Domains.Character.Character character, ResourceInts resources) GetVillagerMaintenance(int characterId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(characterId, out var character) || character.GetPhysiologicalAge() < 16 || character.GetCreatingType() != 1)
		{
			return (character: null, resources: new ResourceInts(default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int)));
		}
		return (character: character, resources: SharedMethods.GetChallengeModeCostResource(character.GetLifeSkillAttainments(), character.GetCombatSkillAttainments()));
	}

	public void LoseOverloadResources(DataContext context)
	{
		MonthlyNotificationCollection monthlyNotification = DomainManager.World.GetMonthlyNotificationCollection();
		int maxAmount = DomainManager.Taiwu.GetMaterialResourceMaxCount();
		int currDate = DomainManager.World.GetCurrDate();
		Location location = _taiwuChar.GetLocation();
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		TaiwuVillageStoragesRecordCollection taiwuVillageStoragesRecordCollection = DomainManager.Taiwu.GetTaiwuVillageStoragesRecordCollection();
		ResourceInts totalResources = GetTotalResources();
		ResourceInts taiwuResources = _taiwuChar.GetResources();
		SettlementTreasury treasury = GetTaiwuTreasury();
		bool treasuryUpdated = false;
		for (sbyte type = 0; type < 6; type++)
		{
			int currTotalAmount = totalResources[type];
			if (currTotalAmount > maxAmount)
			{
				int lostAmount = currTotalAmount - maxAmount;
				int toLoseAmount = lostAmount;
				if (LoseResource(type, ref taiwuResources, ref toLoseAmount))
				{
					_taiwuChar.SetResources(ref taiwuResources, context);
				}
				if (LoseResource(type, ref treasury.Resources, ref toLoseAmount, TaiwuVillageStorageType.Treasury))
				{
					treasuryUpdated = true;
				}
				if (treasuryUpdated)
				{
					CommitTaiwuVillageStoragesRecordCollection(context);
				}
				if (DomainManager.Taiwu._prevMonthResourceCollection[type] != maxAmount)
				{
					monthlyNotification.AddLoseResourceCausedByInventoryFull(_taiwuCharId, type);
					lifeRecordCollection.AddLoseOverloadingResource(_taiwuCharId, currDate, location, type, lostAmount);
				}
			}
		}
		if (treasuryUpdated)
		{
			SetTaiwuTreasury(context, treasury);
		}
		bool LoseResource(sbyte resourceType, ref ResourceInts resources, ref int reference, TaiwuVillageStorageType storageType = TaiwuVillageStorageType.Count)
		{
			if (reference <= 0)
			{
				return false;
			}
			int loseAmount = Math.Min(resources[resourceType], reference);
			if (loseAmount > 0)
			{
				resources[resourceType] -= loseAmount;
				reference -= loseAmount;
				if (storageType != TaiwuVillageStorageType.Count)
				{
					taiwuVillageStoragesRecordCollection.AddLoseOverloadResources(currDate, storageType, resourceType, loseAmount);
				}
			}
			return true;
		}
	}

