	public (int attainmentEffect, bool upgradeMakeItem, bool hasBuilding) GetTaiwuCraftBuildingEffect(sbyte lifeSkillType)
	{
		Location taiwuVillageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
		short buildingBlockTemplateId = -1;
		BuildingBlock.Instance.Iterate(delegate(BuildingBlockItem b)
		{
			if (b.CanMakeItem && b.RequireLifeSkillType == lifeSkillType)
			{
				buildingBlockTemplateId = b.TemplateId;
				return false;
			}
			return true;
		});
		BuildingBlockData buildingBlockData = DomainManager.Taiwu.GetTaiwuBuildingBlockData(buildingBlockTemplateId);
		if (buildingBlockData != null)
		{
			BuildingBlockKey buildingBlockKey = new BuildingBlockKey(taiwuVillageLocation.AreaId, taiwuVillageLocation.BlockId, buildingBlockData.BlockIndex);
			(int, bool) result = DomainManager.Building.GetBuildingEffectForMake(buildingBlockKey, lifeSkillType);
			return (attainmentEffect: result.Item1, upgradeMakeItem: result.Item2, hasBuilding: true);
		}
		return (attainmentEffect: 0, upgradeMakeItem: false, hasBuilding: false);
	}

