	[DomainMethod]
	public int GetItemCount(sbyte itemType, short itemTemplateId)
	{
		int count = 0;
		ItemKey[] equipment = _taiwuChar.GetEquipment();
		ItemKey[] array = equipment;
		for (int i = 0; i < array.Length; i++)
		{
			ItemKey itemKey = array[i];
			if (itemKey.ItemType == itemType && itemKey.TemplateId == itemTemplateId)
			{
				count++;
			}
		}
		count += _taiwuChar.GetInventory().GetInventoryItemCount(itemType, itemTemplateId);
		ItemSourceType[] taiwuVillageStorages = TaiwuVillageStorages;
		foreach (ItemSourceType sourceType in taiwuVillageStorages)
		{
			IReadOnlyDictionary<ItemKey, int> items = GetItems(sourceType);
			foreach (KeyValuePair<ItemKey, int> pair in items)
			{
				if (pair.Key.ItemType == itemType && pair.Key.TemplateId == itemTemplateId)
				{
					count += pair.Value;
				}
			}
		}
		return count;
	}

	[DomainMethod]
	public static int GetStrategyRoomLevel()
	{
		int level = 0;
		List<Location> taiwuBuildingList = DomainManager.Building.GetTaiwuBuildingAreas();
		for (int i = 0; i < taiwuBuildingList.Count; i++)
		{
			Location location = taiwuBuildingList[i];
			BuildingAreaData areaData = DomainManager.Building.GetElement_BuildingAreas(location);
			for (short index = 0; index < areaData.Width * areaData.Width; index++)
			{
				BuildingBlockKey blockKey = new BuildingBlockKey(location.AreaId, location.BlockId, index);
				BuildingBlockData blockData = DomainManager.Building.GetElement_BuildingBlocks(blockKey);
				if (blockData.TemplateId == 98 && blockData.CanUse())
				{
					return blockData.CalcUnlockedLevelCount();
				}
			}
		}
		return level;
	}

