		return Config.Clothing.Instance[templateId].DisplayId;
	}

	[DomainMethod]
	public unsafe void SelectCombatSkillAttainmentPanelPlan(DataContext context, sbyte combatSkillType, sbyte planId)
	{
		SaveCombatSkillAttainmentPanelPlan(context, combatSkillType, _currCombatSkillAttainmentPanelPlanIds[combatSkillType]);
		_currCombatSkillAttainmentPanelPlanIds[combatSkillType] = planId;
		SetCurrCombatSkillAttainmentPanelPlanIds(_currCombatSkillAttainmentPanelPlanIds, context);
		short[] panels = _taiwuChar.GetCombatSkillAttainmentPanels();
		int panelSize = 126;
		fixed (short* pPlans = _combatSkillAttainmentPanelPlans)
		{
			short* pCurrPlan = pPlans + panelSize * planId + combatSkillType * 9;
			CombatSkillAttainmentPanelsHelper.SetPanel(panels, combatSkillType, pCurrPlan);
		}
		for (sbyte grade = 0; grade < 9; grade++)
		{
			short combatSkillTemplateId = CombatSkillAttainmentPanelsHelper.Get(panels, combatSkillType, grade);
			CombatSkillKey combatSkillKey = new CombatSkillKey(_taiwuCharId, combatSkillTemplateId);
			if (!DomainManager.CombatSkill.TryGetElement_CombatSkills(combatSkillKey, out var combatSkill) || !combatSkill.CanBreakout())
			{
				CombatSkillAttainmentPanelsHelper.Set(panels, combatSkillType, grade, -1);
			}
		}
		QuickFillCombatSkillAttainmentPanel(context, combatSkillType);
	}

	private unsafe void SaveCombatSkillAttainmentPanelPlan(DataContext context, sbyte combatSkillType, sbyte planId)
	{
		short[] panels = _taiwuChar.GetCombatSkillAttainmentPanels();
		int panelSize = 126;
		fixed (short* pPlans = _combatSkillAttainmentPanelPlans)
		{
			short* pCurrPlan = pPlans + panelSize * planId + combatSkillType * 9;
			CombatSkillAttainmentPanelsHelper.GetPanel(panels, combatSkillType, pCurrPlan);
		}
		SetCombatSkillAttainmentPanelPlans(_combatSkillAttainmentPanelPlans, context);
	}

	private bool QuickFillCombatSkillAttainmentPanel(DataContext context, sbyte combatSkillType)
	{
		Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> learnedCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(_taiwuCharId);
		List<KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill>> viableSkills = learnedCombatSkills.Where((KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> pair) => Config.CombatSkill.Instance[pair.Key].Type == combatSkillType && pair.Value.CanBreakout()).ToList();
		short[] taiwuPanel = _taiwuChar.GetCombatSkillAttainmentPanels();
		bool changed = false;
		for (sbyte grade = 0; grade < 9; grade++)
		{
			if (CombatSkillAttainmentPanelsHelper.Get(taiwuPanel, combatSkillType, grade) == -1)
			{
				foreach (KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> item in viableSkills)
				{
					short templateId = item.Key;
					if (Config.CombatSkill.Instance[templateId].Grade != grade)
					{
						continue;
					}
					CombatSkillAttainmentPanelsHelper.Set(taiwuPanel, combatSkillType, grade, templateId);
					changed = true;
					break;
				}
			}
		}
		_taiwuChar.SetCombatSkillAttainmentPanels(taiwuPanel, context);
		return changed;
	}

