	[DomainMethod]
	public bool MasteredSkillWillChangePlan(short skillTemplateId)
	{
		CombatSkillEquipment combatSkillEquipment = _taiwuChar.GetCombatSkillEquipment();
		CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
		if (!combatSkillEquipment.IsCombatSkillEquipped(skillTemplateId))
		{
			return false;
		}
		Span<sbyte> gridCounts = stackalloc sbyte[5];
		sbyte totalGenericGrid = _taiwuChar.GetCombatSkillSlotCounts(gridCounts);
		Span<sbyte> costCounts = stackalloc sbyte[4];
		for (sbyte equipType = 1; equipType < 5; equipType++)
		{
			costCounts[equipType - 1] = CharacterDomain.GetCombatSkillsCostedGrid(_taiwuCharId, combatSkillEquipment, equipType);
		}
		Span<sbyte> specificGrids = stackalloc sbyte[4];
		GameData.Domains.CombatSkill.CombatSkill skill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillTemplateId));
		skill.GetSpecificGridCount(specificGrids);
		for (sbyte equipType2 = 1; equipType2 < 5; equipType2++)
		{
			sbyte totalGrid = gridCounts[equipType2];
			sbyte costedGrid = costCounts[equipType2 - 1];
			sbyte specificGrid = specificGrids[equipType2 - 1];
			if (totalGrid - specificGrid < costedGrid)
			{
				return true;
			}
		}
		byte[] genericGridAllocation = plan.GenericGridAllocation;
		int costedGenericGrid = genericGridAllocation.Sum();
		sbyte specificGenericGrid = skill.GetGenericGridCount();
		return totalGenericGrid - specificGenericGrid < costedGenericGrid;
	}

	[Obsolete]
	public unsafe void ClearExceedCombatSkills(DataContext context)
	{
		if (!DomainManager.Character.IsCharacterAlive(_taiwuCharId))
		{
			return;
		}
		CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
		sbyte* pGridCounts = stackalloc sbyte[5];
		Span<sbyte> gridCounts = new Span<sbyte>(pGridCounts, 5);
		int totalGenericGrid = _taiwuChar.GetCombatSkillSlotCounts(gridCounts);
		if (_taiwuChar.ClearExceededCombatSkills(context, 0, gridCounts[0]))
		{
			totalGenericGrid = _taiwuChar.GetCombatSkillSlotCounts(gridCounts);
		}
		for (int i = 0; i < plan.GenericGridAllocation.Length; i++)
		{
			byte allocatedGenericGridCount = plan.GenericGridAllocation[i];
			if (totalGenericGrid >= allocatedGenericGridCount)
			{
				totalGenericGrid -= allocatedGenericGridCount;
				continue;
			}
			allocatedGenericGridCount = (byte)totalGenericGrid;
			plan.GenericGridAllocation[i] = allocatedGenericGridCount;
			totalGenericGrid = 0;
		}
		for (sbyte equipType = 1; equipType < 5; equipType++)
		{
			_taiwuChar.ClearExceededCombatSkills(context, equipType);
		}
		SetElement_CombatSkillPlans(_currCombatSkillPlanId, plan, context);
	}

	[DomainMethod]
	public void AllocateGenericGrid(DataContext context, sbyte equipType)
	{
		if (equipType < 1)
		{
			throw new ArgumentException($"Invalid generic grid type:{equipType}");
		}
		Span<sbyte> gridCounts = stackalloc sbyte[5];
		sbyte genericSlotCount = _taiwuChar.GetCombatSkillSlotCounts(gridCounts);
		CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
		int index = equipType - 1;
		int cost = GameData.Domains.Character.CombatSkillHelper.GetGenericAllocationNextCost(equipType, plan.GenericGridAllocation[index]);
		int remaining = _taiwuChar.ApplyGenericCombatSkillSlotAllocations(gridCounts, genericSlotCount);
		if (cost > remaining)
		{
			throw new InvalidOperationException("No more available generic grid");
		}
		plan.GenericGridAllocation[index]++;
		SetElement_CombatSkillPlans(_currCombatSkillPlanId, plan, context);
	}

	[DomainMethod]
	public void DeallocateGenericGrid(DataContext context, sbyte equipType)
	{
		if (equipType < 1)
		{
			throw new Exception($"Invalid generic grid type:{equipType}");
		}
		CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
		if (plan.GenericGridAllocation[equipType - 1] == 0)
		{
			throw new Exception($"No generic grid allocated in type:{equipType}");
		}
		plan.GenericGridAllocation[equipType - 1]--;
		SetElement_CombatSkillPlans(_currCombatSkillPlanId, plan, context);
	}

	[DomainMethod]
	public void UpdateCombatSkillPlan(DataContext context, int index)
	{
		CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
		if (_currCombatSkillPlanId != index)
		{
			plan.Record(_taiwuChar);
			SetElement_CombatSkillPlans(_currCombatSkillPlanId, plan, context);
			SetCurrCombatSkillPlanId(index, context);
			plan = _combatSkillPlans[_currCombatSkillPlanId];
		}
		DomainManager.Extra.UpdateTaiwuMasteredCombatSkillsByPlan(context);
		DomainManager.Character.ApplyCombatSkillPlan(context, _taiwuChar, plan);
		SetElement_CombatSkillPlans(_currCombatSkillPlanId, plan, context);
	}

	[DomainMethod]
	public void CopyCombatSkillPlan(DataContext context)
	{
		byte planCount = DomainManager.Extra.GetUnlockedCombatSkillPlanCount();
		if (planCount != 9)
		{
			DomainManager.Extra.SetUnlockedCombatSkillPlanCount((byte)(planCount + 1), context);
			CombatSkillPlan curr = _combatSkillPlans[_currCombatSkillPlanId];
			curr.Record(_taiwuChar);
			SetElement_CombatSkillPlans(_currCombatSkillPlanId, curr, context);
			CombatSkillPlan plan = _combatSkillPlans[planCount];
			plan.Assign(curr);
			SetElement_CombatSkillPlans(planCount, plan, context);
			DomainManager.Extra.CopyTaiwuCombatSkillsPlan(context, _currCombatSkillPlanId, planCount);
			UpdateCombatSkillPlan(context, planCount);
		}
	}

	[DomainMethod]
	public void AppendCombatSkillPlan(DataContext context)
	{
		byte planCount = DomainManager.Extra.GetUnlockedCombatSkillPlanCount();
		if (planCount != 9)
		{
			DomainManager.Extra.SetUnlockedCombatSkillPlanCount((byte)(planCount + 1), context);
			CombatSkillPlan plan = _combatSkillPlans[planCount];
			plan.Reset();
			SetElement_CombatSkillPlans(planCount, plan, context);
			UpdateCombatSkillPlan(context, planCount);
		}
	}

	[DomainMethod]
	public void ClearCombatSkillPlan(DataContext context)
	{
		DomainManager.Character.UnequipAllCombatSkills(context, _taiwuCharId);
	}

	[DomainMethod]
	public void DeleteCombatSkillPlan(DataContext context)
	{
		byte planCount = DomainManager.Extra.GetUnlockedCombatSkillPlanCount();
		if (planCount != 1)
		{
			DomainManager.Extra.SetUnlockedCombatSkillPlanCount((byte)(planCount - 1), context);
			CombatSkillPlan plan = _combatSkillPlans[_currCombatSkillPlanId];
			plan.Reset();
			for (int i = _currCombatSkillPlanId; i < planCount - 1; i++)
			{
				SetElement_CombatSkillPlans(i, _combatSkillPlans[i + 1], context);
			}
			SetElement_CombatSkillPlans(planCount - 1, plan, context);
			DomainManager.Extra.DeleteTaiwuCombatSkillsPlan(context, _currCombatSkillPlanId);
			if (_currCombatSkillPlanId != planCount - 1)
			{
				UpdateCombatSkillPlan(context, _currCombatSkillPlanId);
				return;
			}
			ClearCombatSkillPlan(context);
			UpdateCombatSkillPlan(context, _currCombatSkillPlanId - 1);
		}
	}

	public void RegisterCombatSkill(DataContext context, GameData.Domains.CombatSkill.CombatSkill skill)
	{
		short skillTemplateId = skill.GetId().SkillTemplateId;
		ushort readingState = skill.GetReadingState();
		if (_notLearnCombatSkillReadingProgress.TryGetValue(skillTemplateId, out var notLearnedCombatSkill))
		{
			notLearnedCombatSkill.ApplyBookPageReadingProgress(readingState);
			RemoveElement_NotLearnCombatSkillReadingProgress(skillTemplateId, context);
			AddElement_CombatSkills(skillTemplateId, notLearnedCombatSkill, context);
		}
		else if (!_combatSkills.ContainsKey(skillTemplateId))
		{
			TaiwuCombatSkill taiwuCombatSkill = new TaiwuCombatSkill(readingState);
			AddElement_CombatSkills(skillTemplateId, taiwuCombatSkill, context);
		}
		else
		{
			AdaptableLog.Warning("Combat skill " + Config.CombatSkill.Instance[skillTemplateId].Name + " is already learned.", appendWarningMessage: true);
		}
		RecordLifeSummary(context, 46);
	}

