	public bool IsCombatSkillInPlans(short combatSkillTemplateId)
	{
		if (Enumerable.Contains(GetTaiwu().GetEquippedCombatSkills(), combatSkillTemplateId))
		{
			return true;
		}
		CombatSkillPlan[] combatSkillPlans = _combatSkillPlans;
		foreach (CombatSkillPlan plan in combatSkillPlans)
		{
			if (Enumerable.Contains(plan.AgilitySkillList, combatSkillTemplateId) || Enumerable.Contains(plan.AssistanceSkillList, combatSkillTemplateId) || Enumerable.Contains(plan.AttackSkillList, combatSkillTemplateId) || Enumerable.Contains(plan.DefenseSkillList, combatSkillTemplateId) || Enumerable.Contains(plan.NeigongList, combatSkillTemplateId))
			{
				return true;
			}
		}
		return false;
	}

