	[DomainMethod]
	public void SetLuohanBreak(DataContext context, short combatSkillId, sbyte luohanId, sbyte behaviorType)
	{
		if (luohanId < 0)
		{
			RemoveElement_LuohanBreak(combatSkillId, context);
		}
		else if (_luohanBreak.ContainsKey(combatSkillId))
		{
			SetElement_LuohanBreak(combatSkillId, luohanId, context);
		}
		else
		{
			AddElement_LuohanBreak(combatSkillId, luohanId, context);
		}
		SkillBreakPlate plate;
		if (luohanId >= 0)
		{
			GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills((charId: _taiwuCharId, skillId: combatSkillId));
			ushort state = combatSkill.GetActivationState();
			for (byte i = 0; i < 5; i++)
			{
				state = CombatSkillStateHelper.SetPageInactive(state, i);
			}
			state = CombatSkillStateHelper.SetPageActive(state, (byte)behaviorType);
			combatSkill.SetActivationState(state, context);
			DomainManager.Taiwu.RecordLifeSummary(context, 51);
		}
		else if (_combatSkillBreakPlates.TryGetValue(combatSkillId, out plate) && plate != null)
		{
			ChangeCurrBreakPlate(context, combatSkillId, plate);
		}
		else
		{
			GameData.Domains.CombatSkill.CombatSkill combatSkill2 = DomainManager.CombatSkill.GetElement_CombatSkills((charId: _taiwuCharId, skillId: combatSkillId));
			ushort state2 = combatSkill2.GetActivationState();
			for (byte i2 = 0; i2 < 5; i2++)
			{
				state2 = CombatSkillStateHelper.SetPageInactive(state2, i2);
			}
			combatSkill2.SetActivationState(state2, context);
		}
	}

