	[DomainMethod]
	public void ChangeCombatSkillBreakPlate(DataContext context, short skillId, sbyte index)
	{
		CombatSkillBreakPreset preset;
		bool isAdd = !_combatSkillBreakPresets.TryGetValue(skillId, out preset);
		if (preset == null)
		{
			preset = new CombatSkillBreakPreset();
		}
		if (preset.CurrentIndex == index)
		{
			return;
		}
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		GameData.Domains.CombatSkill.CombatSkill skill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(taiwuCharId, skillId));
		TaiwuCombatSkill taiwuSkill = DomainManager.Taiwu.GetElement_CombatSkills(skillId);
		CombatSkillBreakSnapshot snapshot = new CombatSkillBreakSnapshot
		{
			BreakPlate = _combatSkillBreakPlates.GetOrDefault(skillId),
			LastClearTime = taiwuSkill.LastClearBreakPlateTime,
			LastForceBreakoutStepsCount = skill.GetForcedBreakoutStepsCount(),
			LuohanId = _luohanBreak.GetValueOrDefault<short, sbyte>(skillId, -1),
			LuohanState = skill.GetActivationState(),
			DefaultState = skill.GetActivationState()
		};
		CombatSkillBreakPreset combatSkillBreakPreset = preset;
		if (combatSkillBreakPreset.Presets == null)
		{
			combatSkillBreakPreset.Presets = new List<CombatSkillBreakSnapshot>();
		}
		preset.Presets.SetOrAdd(preset.CurrentIndex, snapshot);
		preset.CurrentIndex = index;
		if (isAdd)
		{
			AddElement_CombatSkillBreakPresets(skillId, preset, context);
		}
		else
		{
			SetElement_CombatSkillBreakPresets(skillId, preset, context);
		}
		CombatSkillBreakSnapshot newSnapshot = preset.Presets.GetOrDefault(index) ?? new CombatSkillBreakSnapshot();
		ChangeCurrBreakPlate(context, skillId, newSnapshot);
		if (newSnapshot.LuohanId >= 0)
		{
			sbyte outline = CombatSkillStateHelper.GetActiveOutlinePageType(newSnapshot.LuohanState);
			skill.SetActivationState(newSnapshot.LuohanState, context);
			SetLuohanBreak(context, skillId, newSnapshot.LuohanId, (sbyte)((outline >= 0) ? outline : 2));
			return;
		}
		SetLuohanBreak(context, skillId, -1, -1);
		SkillBreakPlate breakPlate = newSnapshot.BreakPlate;
		if (breakPlate == null || !breakPlate.Success)
		{
			skill.SetActivationState(newSnapshot.DefaultState, context);
		}
	}

	[DomainMethod]
	public SkillBreakPlate EnterSkillBreakPlate(DataContext context, short skillId, ushort selectedPages)
	{
		if (!DomainManager.CombatSkill.TryGetElement_CombatSkills((charId: _taiwuCharId, skillId: skillId), out var skill))
		{
			throw new Exception($"Skill {skillId} not learned");
		}
		if (!skill.CanBreakout())
		{
			throw new Exception($"Skill {skillId} cannot break out");
		}
		if (CombatSkillStateHelper.GetActiveOutlinePageType(selectedPages) == -1 || CombatSkillStateHelper.GetReadNormalPagesCount(selectedPages) != 5)
		{
			throw new Exception($"Skill {skillId} selected break out page {selectedPages} not correct");
		}
		CombatSkillItem skillConfig = Config.CombatSkill.Instance[skillId];
		if (!_combatSkillBreakPlates.TryGetValue(skillId, out var plate))
		{
			SkillBreakPlateItem config = skillConfig.SkillBreakPlate;
			if (DomainManager.TutorialChapter.InGuiding && skillId == 716)
			{
				config = Config.SkillBreakPlate.Instance[(sbyte)9];
			}
			(int succeedCount, int failCount) clearedSkillPlateStepInfo = DomainManager.Extra.GetClearedSkillPlateStepInfo(skillId);
			int lastSuccess = clearedSkillPlateStepInfo.succeedCount;
			int lastFailed = clearedSkillPlateStepInfo.failCount;
			plate = new SkillBreakPlate(context.Random, config, selectedPages, lastSuccess, lastFailed);
			DomainManager.Extra.RemoveClearedSkillPlateStepInfo(context, skillId);
		}
		plate.StepBase = _taiwuChar.GetSkillBreakoutAvailableStepsCount(skillId);
		plate.LegendaryBookState = DomainManager.Extra.GetLegendaryBookState(skillConfig.Type);
		plate.BaseSuccessRate = CalcTaiwuBreakBaseSuccessRate(skillConfig);
		SetOrAddSkillBreakPlate(context, skillId, plate);
		if (!CombatSkillStateHelper.IsBrokenOut(skill.GetActivationState()))
		{
			TransferNextBreakoutBonusToSkill(context, skillId);
		}
		return plate;
	}

	private void TransferNextBreakoutBonusToSkill(DataContext context, short skillId)
	{
		CombatSkillKey genericKey = new CombatSkillKey(_taiwuCharId, -1);
		CombatSkillKey skillKey = new CombatSkillKey(_taiwuCharId, skillId);
		if (_nextBreakoutStepBaseBonus.TryGetValue(genericKey, out var stepBonus))
		{
			RemoveElement_NextBreakoutStepBaseBonus(genericKey, context);
			if (_nextBreakoutStepBaseBonus.ContainsKey(skillKey))
			{
				SetElement_NextBreakoutStepBaseBonus(skillKey, _nextBreakoutStepBaseBonus[skillKey] + stepBonus, context);
			}
			else
			{
				AddElement_NextBreakoutStepBaseBonus(skillKey, stepBonus, context);
			}
		}
		if (_nextBreakoutSuccessRateBonus.TryGetValue(genericKey, out var rateBonus))
		{
			RemoveElement_NextBreakoutSuccessRateBonus(genericKey, context);
			if (_nextBreakoutSuccessRateBonus.ContainsKey(skillKey))
			{
				SetElement_NextBreakoutSuccessRateBonus(skillKey, _nextBreakoutSuccessRateBonus[skillKey] + rateBonus, context);
			}
			else
			{
				AddElement_NextBreakoutSuccessRateBonus(skillKey, rateBonus, context);
			}
		}
	}

	private void ReturnNextBreakoutBonusToGeneric(DataContext context, short skillId)
	{
		CombatSkillKey genericKey = new CombatSkillKey(_taiwuCharId, -1);
		CombatSkillKey skillKey = new CombatSkillKey(_taiwuCharId, skillId);
		if (_nextBreakoutStepBaseBonus.TryGetValue(skillKey, out var stepBonus))
		{
			RemoveElement_NextBreakoutStepBaseBonus(skillKey, context);
			if (_nextBreakoutStepBaseBonus.ContainsKey(genericKey))
			{
				SetElement_NextBreakoutStepBaseBonus(genericKey, _nextBreakoutStepBaseBonus[genericKey] + stepBonus, context);
			}
			else
			{
				AddElement_NextBreakoutStepBaseBonus(genericKey, stepBonus, context);
			}
		}
		if (_nextBreakoutSuccessRateBonus.TryGetValue(skillKey, out var rateBonus))
		{
			RemoveElement_NextBreakoutSuccessRateBonus(skillKey, context);
			if (_nextBreakoutSuccessRateBonus.ContainsKey(genericKey))
			{
				SetElement_NextBreakoutSuccessRateBonus(genericKey, _nextBreakoutSuccessRateBonus[genericKey] + rateBonus, context);
			}
			else
			{
				AddElement_NextBreakoutSuccessRateBonus(genericKey, rateBonus, context);
			}
		}
	}

	[DomainMethod]
	public CharacterMenuSkillBreakData GetEnterSkillBreakPlateInfo(DataContext context, short skillId)
	{
		CombatSkillItem configData = Config.CombatSkill.Instance[skillId];
		SkillGradeDataItem skillGradeCfg = SkillGradeData.Instance[configData.Grade];
		int requireQualification = skillGradeCfg.PracticeQualificationRequirement;
		short currQualification = _taiwuChar.GetCombatSkillQualification(configData.Type);
		bool isCombatSkillQualification = true;
		sbyte lifeSkillType;
		short lifeSkillQualification = SharedMethods.GetQualificationWithSectApprovalBonus(configData.SectId, currQualification, _taiwuChar.GetLifeSkillQualifications(), out lifeSkillType);
		LifeSkillTypeItem lifeSkillConfig = null;
		if (lifeSkillQualification > currQualification)
		{
			currQualification = lifeSkillQualification;
			isCombatSkillQualification = false;
			lifeSkillConfig = Config.LifeSkillType.Instance[lifeSkillType];
		}
		CharacterMenuSkillBreakData data = new CharacterMenuSkillBreakData
		{
			WudangUpgradeInteractionUnlocked = DomainManager.Organization.GetSectFunctionStatus(4, SectFunctionStatuses.SectFunctionStatusType.UpgradedInteractionUnlocked),
			BaseCostExp = GetBreakBaseCostExp(skillId),
			RequireQualification = requireQualification,
			CurrQualification = currQualification,
			IsCombatSkillQualification = isCombatSkillQualification
		};
		data.SkillDisplayDataSimple = DomainManager.CombatSkill.GetCombatSkillDisplayDataCharacterMenuListItem(skillId, GetTaiwu().GetId(), GetTaiwu());
		return data;
	}

