	[DomainMethod]
	public void ClearBreakPlate(DataContext context, short skillId, bool fromGmCmd = false)
	{
		int successCount = 0;
		int failedCount = 0;
		if (_combatSkillBreakPlates.TryGetValue(skillId, out var plate))
		{
			RemoveElement_CombatSkillBreakPlates(skillId, context);
			successCount = plate.SuccessCount;
			failedCount = plate.FailedCount;
		}
		DomainManager.Extra.AddClearedSkillPlateStepInfo(context, skillId, successCount, failedCount);
		if (_taiwuChar.GetLoopingNeigong() == skillId)
		{
			_taiwuChar.SetLoopingNeigong(-1, context);
		}
		if (DomainManager.CombatSkill.TryGetElement_CombatSkills((charId: _taiwuCharId, skillId: skillId), out var skill))
		{
			ushort state = skill.GetActivationState();
			for (byte i = 0; i < 5; i++)
			{
				state = CombatSkillStateHelper.SetPageInactive(state, i);
			}
			skill.SetActivationState(state, context);
		}
		CharacterDomain.TryRemoveCombatSkillFromAttainmentPanel(context, _taiwuChar, skillId);
		if (TryGetElement_CombatSkills(skillId, out var taiwuSkill))
		{
			if (!fromGmCmd)
			{
				taiwuSkill.LastClearBreakPlateTime = DomainManager.World.GetCurrDate();
			}
			taiwuSkill.FullPowerCastTimes = 0;
			SetElement_CombatSkills(skillId, taiwuSkill, context);
		}
		if (_taiwuChar.IsCombatSkillEquipped(skillId))
		{
			DomainManager.SpecialEffect.Remove(context, _taiwuCharId, skillId, 2);
		}
		ReturnNextBreakoutBonusToGeneric(context, skillId);
	}

	[DomainMethod]
	public SkillBreakPlate SelectSkillBreakGrid(DataContext context, short skillId, SkillBreakPlateIndex index)
	{
		SkillBreakPlate plate = _combatSkillBreakPlates[skillId];
		int baseCostExp = GetBreakBaseCostExp(skillId);
		int costExp = plate.CalcCostExp(baseCostExp, index);
		if (_taiwuChar.GetExp() < costExp)
		{
			return null;
		}
		if (!plate.SelectBreak(context.Random, index, out var selectInGoneMad))
		{
			return null;
		}
		_taiwuChar.ChangeExp(context, -costExp);
		CombatSkillItem config = Config.CombatSkill.Instance[skillId];
		if (plate.Success)
		{
			FinishBreak(context, skillId, plate);
			AchievementManager.RequestSetStat(context, 8, 1);
		}
		if (plate.State != ESkillBreakPlateState.NotFinished)
		{
			DomainManager.Taiwu.RecordLifeSummary(context, 51);
		}
		SkillBreakGridTypeItem gridConfig = SkillBreakGridType.Instance[plate.GetGridAt(index).TemplateId];
		if (gridConfig.HealthCost != 0)
		{
			_taiwuChar.ChangeHealth(context, -gridConfig.HealthCost);
		}
		if (selectInGoneMad)
		{
			AchievementManager.RequestSetStat(context, 9, 1);
		}
		bool goneMadInAllBreak = DomainManager.SpecialEffect.ModifyData(_taiwuCharId, skillId, 266, dataValue: false);
		if (selectInGoneMad || goneMadInAllBreak)
		{
			Injuries injuries = _taiwuChar.GetInjuries();
			short disorderOfQi = 0;
			int overflowInjuryValue = GameData.Domains.Character.CombatSkillHelper.CalcForceBreakoutInjuriesAndDisorderOfQi(context.Random, config, ref injuries, ref disorderOfQi);
			_taiwuChar.SetInjuries(injuries, context);
			_taiwuChar.ChangeDisorderOfQiRandomRecovery(context, disorderOfQi);
			int costHealth = -(overflowInjuryValue * GlobalConfig.Instance.ReduceHealthPerFatalDamageMark[1]);
			costHealth += DisorderLevelOfQi.GetDisorderLevelOfQiConfig(_taiwuChar.GetDisorderOfQi()).BreakCostHealth;
			_taiwuChar.ChangeHealth(context, costHealth);
		}
		SetOrAddSkillBreakPlate(context, skillId, plate);
		return plate;
	}

	[DomainMethod]
	public SkillBreakPlate SwapSkillBreakGrid(DataContext context, short skillId, SkillBreakPlateIndex indexA, SkillBreakPlateIndex indexB)
	{
		if (!_combatSkillBreakPlates.TryGetValue(skillId, out var plate))
		{
			return null;
		}
		GameData.Domains.CombatSkill.CombatSkill skillData = DomainManager.CombatSkill.GetElement_CombatSkills((charId: _taiwuCharId, skillId: skillId));
		if (CombatSkillStateHelper.IsBrokenOut(skillData.GetActivationState()))
		{
			return null;
		}
		int costExp = (GlobalConfig.Instance.SwapSkillBreakCostExp + plate.SwapCount) * GetBreakBaseCostExp(skillId);
		int haveExp = _taiwuChar.GetExp();
		if (haveExp < costExp)
		{
			return null;
		}
		if (!plate.SwapGrid(indexA, indexB))
		{
			return null;
		}
		_taiwuChar.ChangeExp(context, -costExp);
		SetOrAddSkillBreakPlate(context, skillId, plate);
		return plate;
	}

	[DomainMethod]
	public int GetBreakBaseCostExp(short skillId)
	{
		CombatSkillItem skillConfig = Config.CombatSkill.Instance[skillId];
		sbyte templateId = skillConfig.Grade;
		if (DomainManager.TutorialChapter.InGuiding)
		{
			templateId = 0;
		}
		return Config.SkillBreakPlate.Instance[templateId].CostExp;
	}

	[DomainMethod]
	public List<SkillBreakPlateBonus> GetAvailableRelationBonuses(short skillId)
	{
		HashSet<RelationKey> usingAdoreCharIds = new HashSet<RelationKey>();
		HashSet<RelationKey> usingEnemyCharIds = new HashSet<RelationKey>();
		HashSet<RelationKey> usingFamilyAndFriendCharIds = new HashSet<RelationKey>();
		foreach (SkillBreakPlate plate in GetConflictRelationSkillBreakPlates(skillId))
		{
			foreach (SkillBreakPlateBonus bonus in plate.GetBonusesWithoutCheck())
			{
				if (bonus.RelationType == 16384)
				{
					usingAdoreCharIds.Add(bonus.RelationKey);
				}
				if (bonus.RelationType == 32768)
				{
					usingEnemyCharIds.Add(bonus.RelationKey);
				}
				if (bonus.Type == ESkillBreakPlateBonusType.Friend)
				{
					usingFamilyAndFriendCharIds.Add(bonus.RelationKey);
				}
			}
		}
		List<SkillBreakPlateBonus> result = new List<SkillBreakPlateBonus>();
		RelatedCharacters relatedCharacters = DomainManager.Character.GetRelatedCharacters(_taiwuCharId);
		foreach (int charId in relatedCharacters.Adored.GetCollection())
		{
			if (DomainManager.Character.IsCharacterAlive(charId))
			{
				SkillBreakPlateBonus bonus2 = SkillBreakPlateBonusHelper.CreateRelation(charId, _taiwuCharId, 16384);
				if (!bonus2.ShouldBeRemoved() && !usingAdoreCharIds.Contains(bonus2.RelationKey))
				{
					result.Add(bonus2);
				}
			}
		}
		foreach (int charId2 in relatedCharacters.Enemies.GetCollection())
		{
			if (DomainManager.Character.IsCharacterAlive(charId2))
			{
				SkillBreakPlateBonus bonus3 = SkillBreakPlateBonusHelper.CreateRelation(charId2, _taiwuCharId, 32768);
				if (!bonus3.ShouldBeRemoved() && !usingEnemyCharIds.Contains(bonus3.RelationKey))
				{
					result.Add(bonus3);
				}
			}
		}
		HashSet<int> familyAndFriendCharIds = ObjectPool<HashSet<int>>.Instance.Get();
		familyAndFriendCharIds.Clear();
		relatedCharacters.GetAllTwoWayRelatedCharIds(familyAndFriendCharIds);
		foreach (int charId3 in familyAndFriendCharIds)
		{
			if (DomainManager.Character.IsCharacterAlive(charId3))
			{
				SkillBreakPlateBonus bonus4 = SkillBreakPlateBonusHelper.CreateFriend(charId3, _taiwuCharId, skillId);
				if (!bonus4.ShouldBeRemoved() && !usingFamilyAndFriendCharIds.Contains(bonus4.RelationKey))
				{
					result.Add(bonus4);
				}
			}
		}
		ObjectPool<HashSet<int>>.Instance.Return(familyAndFriendCharIds);
		return result;
	}

	public IEnumerable<SkillBreakPlate> GetConflictRelationSkillBreakPlates(short skillId)
	{
		foreach (SkillBreakPlate value in _combatSkillBreakPlates.Values)
		{
			yield return value;
		}
		foreach (CombatSkillBreakPreset preset in _combatSkillBreakPresets.Values)
		{
			List<CombatSkillBreakSnapshot> presets = preset.Presets;
			if (presets == null || presets.Count <= 0)
			{
				continue;
			}
			foreach (CombatSkillBreakSnapshot snapshot in preset.Presets)
			{
				if (snapshot?.BreakPlate != null)
				{
					yield return snapshot.BreakPlate;
				}
			}
		}
	}

	[DomainMethod]
	public SkillBreakBonusSelectDisplayData GetSkillBreakBonusSelectDisplayData(DataContext context, short skillId, int selectedCharId)
	{
		SkillBreakBonusSelectDisplayData bonusSelectDisplayData = new SkillBreakBonusSelectDisplayData();
		bonusSelectDisplayData.CanTransferItemToWarehouse = DomainManager.Taiwu.CanTransferItemToWarehouse(context);
		bonusSelectDisplayData.CombatSkillDisplayData = DomainManager.CombatSkill.GetCombatSkillDisplayDataOnce(_taiwuCharId, skillId);
		bonusSelectDisplayData.ExpBonusItemList = new List<SkillBreakBonusSelectableItem>();
		IReadOnlyList<int> levels = SkillBreakPlateConstants.ExpLevelValues;
		for (int i = 0; i < levels.Count; i++)
		{
			int expLevel = levels.Count - i - 1;
			SkillBreakPlateBonus bonusData = SkillBreakPlateBonus.CreateExp(expLevel);
			SkillBreakBonusSelectableItem item = new SkillBreakBonusSelectableItem
			{
				BonusItemType = 0,
				BonusData = bonusData
			};
			bonusSelectDisplayData.ExpBonusItemList.Add(item);
		}
		for (ItemSourceType sourceType = ItemSourceType.Inventory; sourceType <= ItemSourceType.Treasury; sourceType++)
		{
			List<SkillBreakBonusSelectableItem> bonusList = bonusSelectDisplayData.GetBonusItemList(sourceType);
			IReadOnlyDictionary<ItemKey, int> itemDict = GetItems(sourceType);
			foreach (var (itemKey2, amount) in itemDict)
			{
				if (!SkillBreakPlateConstants.IsBonusItem(itemKey2.ItemType, itemKey2.TemplateId))
				{
					continue;
				}
				EBonusItemType type;
				if (IsLifeSkillBook(itemKey2))
				{
					type = EBonusItemType.Book;
				}
				else if (IsMedicine(itemKey2))
				{
					type = EBonusItemType.Medicine;
				}
				else if (IsMaterial(itemKey2))
				{
					type = EBonusItemType.Material;
				}
				else if (IsFood(itemKey2))
				{
					type = EBonusItemType.Food;
				}
				else
				{
					if (!IsBloodDew(itemKey2))
					{
						continue;
					}
					type = EBonusItemType.BloodDew;
				}
				SkillBreakPlateBonus bonusData2 = SkillBreakPlateBonus.CreateItem(itemKey2.ItemType, itemKey2.TemplateId);
				if (bonusData2.IsMatch(skillId))
				{
					ItemBase itemBase = DomainManager.Item.GetBaseItem(itemKey2);
					ItemDisplayData itemData = DomainManager.Item.GetItemDisplayData(itemBase, amount, _taiwuCharId, (sbyte)sourceType);
					SkillBreakBonusSelectableItem selectableItem = new SkillBreakBonusSelectableItem
					{
						BonusItemType = (sbyte)type,
						BonusData = bonusData2,
						ItemDisplayData = itemData
					};
					bonusList.Add(selectableItem);
				}
			}
		}
		List<SkillBreakPlateBonus> characterBonusList = GetAvailableRelationBonuses(skillId);
		bonusSelectDisplayData.CharacterBonusItemList = new List<SkillBreakBonusSelectableItem>();
		foreach (SkillBreakPlateBonus bonus in characterBonusList)
		{
			if (bonus.IsMatch(skillId))
			{
				bonusSelectDisplayData.CharacterBonusItemList.Add(new SkillBreakBonusSelectableItem
				{
					BonusItemType = 1,
					BonusData = bonus,
					CharacterDisplayData = DomainManager.Character.GetCharacterDisplayData(bonus.RelationCharId)
				});
			}
		}
		List<int> charIdList = characterBonusList.Select((SkillBreakPlateBonus b) => b.RelationCharId).ToList();
		if (selectedCharId >= 0 && !charIdList.Contains(selectedCharId))
		{
			charIdList.Add(selectedCharId);
		}
		bonusSelectDisplayData.SelectedCharacterDisplayData = ((selectedCharId >= 0) ? DomainManager.Character.GetCharacterDisplayData(selectedCharId) : null);
		return bonusSelectDisplayData;
	}

