	private static bool IsLifeSkillBook(ItemKey itemKey)
	{
		if (itemKey.ItemType != 10)
		{
			return false;
		}
		SkillBookItem skillBookConfig = Config.SkillBook.Instance[itemKey.TemplateId];
		return skillBookConfig.ItemSubType == 1000;
	}

	private static bool IsFood(ItemKey itemKey)
	{
		sbyte itemType = itemKey.ItemType;
		if (itemType == 7 || itemType == 9)
		{
			return true;
		}
		return false;
	}

	private static bool IsMedicine(ItemKey itemKey)
	{
		return itemKey.ItemType == 8;
	}

	private static bool IsMaterial(ItemKey itemKey)
	{
		return itemKey.ItemType == 5;
	}

	private static bool IsBloodDew(ItemKey itemKey)
	{
		short templateId = itemKey.TemplateId;
		bool flag = itemKey.ItemType == 12;
		bool flag2 = flag;
		if (flag2)
		{
			bool flag3 = (uint)(templateId - 9) <= 8u;
			flag2 = flag3;
		}
		return flag2;
	}

