	public byte CalcTaiwuBreakBaseSuccessRate(CombatSkillItem skillConfig, CombatSkillBreakSuccessRateDisplayData displayData = null, bool applyCommandBonus = true)
	{
		int baseSuccessRate = 30 + (9 - skillConfig.Grade) * 5;
		if (displayData != null)
		{
			displayData.BaseBaseSuccessRate = (byte)baseSuccessRate;
		}
		if (skillConfig.SectId != 0)
		{
			short settlementId = DomainManager.Organization.GetSettlementIdByOrgTemplateId(skillConfig.SectId);
			Sect sect = DomainManager.Organization.GetElement_Sects(settlementId);
			short approvingRate = sect.CalcApprovingRate();
			if (approvingRate >= 500)
			{
				baseSuccessRate += 10;
				if (displayData != null)
				{
					displayData.OrganizationBonus = 10;
				}
			}
		}
		int attributesBonus = Math.Min(_taiwuChar.GetMaxMainAttributes()[5] / 10, 30);
		baseSuccessRate += attributesBonus;
		if (displayData != null)
		{
			displayData.AttributesBonus = (byte)attributesBonus;
		}
		sbyte consummateLevel = _taiwuChar.GetEffectiveConsummateLevel();
		int consummateLevelBonus = ConsummateLevel.Instance[consummateLevel].AddBreakSuccessRate;
		baseSuccessRate += consummateLevelBonus;
		if (displayData != null)
		{
			displayData.ConsummateLevelBonus = (byte)consummateLevelBonus;
		}
		Location location = _taiwuChar.GetLocation();
		int buildingEffect = DomainManager.Building.GetBuildingBlockEffect(location, EBuildingScaleEffect.BreakOutSuccessRate, skillConfig.Type);
		if (buildingEffect != 0)
		{
			byte buildingBonus = (byte)((buildingEffect - 100) * baseSuccessRate / 100);
			baseSuccessRate *= (CValuePercentBonus)buildingEffect;
			if (displayData != null)
			{
				displayData.BuildingBonus = buildingBonus;
			}
		}
		byte difficulty = DomainManager.World.GetBreakoutDifficulty();
		short difficultyAdjust = WorldCreation.Instance[(byte)3].InfluenceFactors[difficulty];
		baseSuccessRate += difficultyAdjust;
		if (displayData != null)
		{
			displayData.DifficultyBonus = (byte)difficultyAdjust;
		}
		if (applyCommandBonus)
		{
			CombatSkillKey key = new CombatSkillKey(_taiwuCharId, -1);
			if (_nextBreakoutSuccessRateBonus.TryGetValue(key, out var successRateBonus))
			{
				baseSuccessRate += successRateBonus;
			}
		}
		byte finalSuccessRate = (byte)Math.Clamp(baseSuccessRate, 0, 100);
		if (displayData != null)
		{
			displayData.BaseSuccessRate = finalSuccessRate;
		}
		return finalSuccessRate;
	}

	private unsafe void FinishBreak(DataContext context, short skillTemplateId, SkillBreakPlate plate)
	{
		GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills((charId: _taiwuCharId, skillId: skillTemplateId));
		combatSkill.SetActivationState(plate.SelectedPages, context);
		int forceBreakoutSteps = plate.StepCostedGoneMad;
		if (forceBreakoutSteps < 0)
		{
			forceBreakoutSteps = 0;
		}
		combatSkill.SetForcedBreakoutStepsCount((sbyte)forceBreakoutSteps, context);
		CombatSkillItem configData = Config.CombatSkill.Instance[skillTemplateId];
		short[] attainmentPanels = _taiwuChar.GetCombatSkillAttainmentPanels();
		short* attainmentSkillList = stackalloc short[9];
		CombatSkillAttainmentPanelsHelper.GetPanel(attainmentPanels, configData.Type, attainmentSkillList);
		if (attainmentSkillList[configData.Grade] < 0)
		{
			CombatSkillAttainmentPanelsHelper.Set(attainmentPanels, configData.Type, configData.Grade, skillTemplateId);
			_taiwuChar.SetCombatSkillAttainmentPanels(attainmentPanels, context);
		}
		if (_taiwuChar.IsCombatSkillEquipped(skillTemplateId))
		{
			DomainManager.SpecialEffect.UpdateEquippedSkillEffect(context, _taiwuChar);
		}
		CombatSkillKey key = new CombatSkillKey(_taiwuCharId, skillTemplateId);
		if (_nextBreakoutStepBaseBonus.ContainsKey(key))
		{
			RemoveElement_NextBreakoutStepBaseBonus(key, context);
		}
		if (_nextBreakoutSuccessRateBonus.ContainsKey(key))
		{
			RemoveElement_NextBreakoutSuccessRateBonus(key, context);
		}
		AddLegacyPoint(context, 24);
	}

