	private void ChangeCurrBreakPlate(DataContext context, short skillId, SkillBreakPlate plate)
	{
		GameData.Domains.CombatSkill.CombatSkill skill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillId));
		ChangeCurrBreakPlateBasic(context, skillId, plate);
		ushort oldActivationState = skill.GetActivationState();
		ushort newActivationState = (ushort)((plate != null && plate.Success) ? plate.SelectedPages : 0);
		skill.SetActivationState(newActivationState, context);
		if (CombatSkillStateHelper.IsBrokenOut(oldActivationState) && !CombatSkillStateHelper.IsBrokenOut(newActivationState))
		{
			if (_taiwuChar.GetLoopingNeigong() == skillId)
			{
				_taiwuChar.SetLoopingNeigong(-1, context);
			}
			if (!skill.CanBreakout())
			{
				CharacterDomain.TryRemoveCombatSkillFromAttainmentPanel(context, _taiwuChar, skillId);
			}
		}
		if (skill.Template.EquipType == 0)
		{
			_taiwuChar.UpdateAllocatedGenericGrids(context);
		}
		if (_taiwuChar.IsCombatSkillEquipped(skillId) && _taiwuChar.GetCombatSkillCanAffect(skillId))
		{
			if (CombatSkillStateHelper.IsBrokenOut(oldActivationState))
			{
				DomainManager.SpecialEffect.Remove(context, _taiwuCharId, skillId, 2);
			}
			if (CombatSkillStateHelper.IsBrokenOut(newActivationState))
			{
				DomainManager.SpecialEffect.Add(context, _taiwuCharId, skillId, 2, -1);
			}
		}
	}

