	public bool AddItem(DataContext context, ItemKey itemKey, int amount, ItemSourceType itemSourceType, bool offLine = false, EItemAutoOperationSource source = EItemAutoOperationSource.Other)
	{
		switch (itemSourceType)
		{
		case ItemSourceType.Equipment:
		case ItemSourceType.Inventory:
			return _taiwuChar.AddInventoryItem(context, itemKey, amount, offLine, source);
		case ItemSourceType.Warehouse:
			DomainManager.Taiwu.WarehouseAdd(context, itemKey, amount);
			break;
		case ItemSourceType.Treasury:
			DomainManager.Taiwu.StoreItemInTreasury(context, itemKey, amount);
			break;
		case ItemSourceType.Trough:
			DomainManager.Taiwu.TroughAdd(context, itemKey, amount);
			break;
		case ItemSourceType.Stock:
			DomainManager.Taiwu.AddStockItem(context, itemKey, amount);
			break;
		default:
			throw new ArgumentOutOfRangeException("itemSourceType", itemSourceType, null);
		}
		return true;
	}

	public void AddItem(DataContext context, List<ItemKey> keyList, ItemSourceType itemSourceType)
	{
		Tester.Assert(keyList != null);
		Tester.Assert(keyList.Count > 0);
		foreach (ItemKey key in keyList)
		{
			AddItem(context, key, 1, itemSourceType, offLine: true);
		}
		CommitOfflineOperation(context, itemSourceType);
	}

	public void AddItem(DataContext context, Inventory inventory, ItemSourceType itemSourceType)
