	public void RemoveTaiwuItemFromTaiwuStorage(DataContext context, ItemKey itemKey, int count, bool deleteItem)
	{
		if (itemKey.IsValid())
		{
			if (DomainManager.Taiwu.GetItems(ItemSourceType.Inventory).TryGetValue(itemKey, out var amount))
			{
				DomainManager.Taiwu.RemoveItem(context, itemKey, count, 1, deleteItem && amount == count);
			}
			else if (DomainManager.Taiwu.GetItems(ItemSourceType.Warehouse).TryGetValue(itemKey, out amount))
			{
				DomainManager.Taiwu.RemoveItem(context, itemKey, count, 2, deleteItem && amount == count);
			}
			else if (DomainManager.Taiwu.GetItems(ItemSourceType.Treasury).TryGetValue(itemKey, out amount))
			{
				DomainManager.Taiwu.RemoveItem(context, itemKey, count, 3, deleteItem && amount == count);
			}
		}
	}

	public int GetTaiwuItemCountFromSources(sbyte itemType, short itemTemplateId, IList<ItemSourceType> itemSourceTypes)
	{
		if (itemSourceTypes == null)
		{
			return 0;
		}
		int count = 0;
		foreach (ItemSourceType itemSourceType in itemSourceTypes)
		{
			IReadOnlyDictionary<ItemKey, int> items = DomainManager.Taiwu.GetItems(itemSourceType);
			foreach (KeyValuePair<ItemKey, int> pair in items)
			{
				bool isLocked = DomainManager.Taiwu.IsItemLocked(pair.Key);
				if (pair.Key.ItemType == itemType && pair.Key.TemplateId == itemTemplateId && !isLocked)
				{
					count += pair.Value;
				}
			}
		}
		return count;
	}

	public bool RemoveTaiwuItemFromSources(DataContext context, sbyte itemType, short itemTemplateId, int count, IList<ItemSourceType> itemSourceTypes, bool deleteItem)
	{
		if (itemSourceTypes == null)
		{
			return false;
		}
		int totalCount = 0;
		List<(ItemKey, int, ItemSourceType)> itemList = new List<(ItemKey, int, ItemSourceType)>();
		foreach (ItemSourceType itemSourceType in itemSourceTypes)
		{
			IReadOnlyDictionary<ItemKey, int> items = DomainManager.Taiwu.GetItems(itemSourceType);
			foreach (KeyValuePair<ItemKey, int> pair in items)
			{
				if (pair.Key.ItemType == itemType && pair.Key.TemplateId == itemTemplateId)
				{
					totalCount += pair.Value;
					itemList.Add((pair.Key, pair.Value, itemSourceType));
				}
			}
		}
		if (totalCount < count)
		{
			return false;
		}
		foreach (var (key, haveCount, itemSourceType2) in itemList)
		{
			if (count <= 0)
			{
				break;
			}
			int removeCount = Math.Min(count, haveCount);
			DomainManager.Taiwu.RemoveItem(context, key, removeCount, itemSourceType2, deleteItem);
			count -= removeCount;
		}
		return true;
	}

