	[DomainMethod]
	public List<ItemDisplayData> ChoosyGetMaterial(DataContext context, sbyte resourceType, int count)
	{
		if (count == 0)
		{
			return null;
		}
		_taiwuChar.ChangeResource(context, resourceType, -count * GlobalConfig.Instance.ChoosyResourceBaseCost);
		Inventory inventory = new Inventory();
		List<short> materialIdList = new List<short>();
		List<ChoosyItem> choosyConfigList = new List<ChoosyItem>();
		LifeSkillShorts lifeSkillAttainments = DomainManager.Taiwu.GetTaiwu().GetLifeSkillAttainments();
		if (resourceType == 5)
		{
			choosyConfigList.AddRange(Choosy.Instance.Where(delegate(ChoosyItem c)
			{
				sbyte lifeSkillType2 = c.LifeSkillType;
				return (uint)(lifeSkillType2 - 8) <= 1u;
			}));
		}
		else
		{
			ResourceTypeItem resourceConfig = Config.ResourceType.Instance[resourceType];
			sbyte lifeSkillType = resourceConfig.LifeSkillType;
			choosyConfigList.AddRange(Choosy.Instance.Where((ChoosyItem c) => c.LifeSkillType == lifeSkillType));
		}
		for (int i = 0; i < count; i++)
		{
			int gradeIndex = 0;
			ChoosyItem choosyConfig = choosyConfigList.GetRandom(context.Random);
			short lifeSkillAttainment = lifeSkillAttainments[choosyConfig.LifeSkillType];
			DomainManager.Extra.ChoosyRemainUpgradeRateDict.TryGetValue(choosyConfig.TemplateId, out var remainRate);
			DomainManager.Extra.ChoosyRemainUpgradeCountDict.TryGetValue(choosyConfig.TemplateId, out var remainCount);
			int upgradeRate = Math.Min(choosyConfig.MaxUpgradeRate, choosyConfig.BaseUpgradeRate + remainRate);
			int maxCount = Math.Min(choosyConfig.MaxUpgradeCount, choosyConfig.BaseUpgradeCount + remainCount) / 10000;
			int usedCount = 0;
			bool success = false;
			while (usedCount < maxCount)
			{
				usedCount++;
				int random = context.Random.Next(10000);
				if (random > 10000 - upgradeRate)
				{
					gradeIndex++;
					if (gradeIndex >= choosyConfig.GradeList.Count - 1)
					{
						success = true;
						break;
					}
				}
			}
			if (success)
			{
				remainRate = 0;
				remainCount = 0;
			}
			else
			{
				remainRate += choosyConfig.UpgradeRateAttainmentBonus * lifeSkillAttainment / choosyConfig.AttainmentRate;
				remainRate = Math.Min(remainRate, choosyConfig.MaxUpgradeRate - choosyConfig.BaseUpgradeRate);
				remainCount += choosyConfig.UpgradeCountAttainmentBonus * lifeSkillAttainment / choosyConfig.AttainmentRate;
				remainCount = Math.Min(remainCount, choosyConfig.MaxUpgradeCount - choosyConfig.BaseUpgradeCount);
			}
			if (gradeIndex == choosyConfig.GradeList.Count - 2)
			{
				remainRate /= 2;
			}
			DomainManager.Extra.ChoosyRemainUpgradeRateDict[choosyConfig.TemplateId] = remainRate;
			DomainManager.Extra.ChoosyRemainUpgradeCountDict[choosyConfig.TemplateId] = remainCount;
			short grade = choosyConfig.GradeList[gradeIndex];
			materialIdList.Clear();
			for (int id = 0; id < Config.Material.Instance.Count; id++)
			{
				if (id < 278 || id > 339)
				{
					MaterialItem materialItem = Config.Material.Instance[id];
					if (materialItem.ResourceType == resourceType && materialItem.Grade == grade && materialItem.DropRate > 0)
					{
						materialIdList.Add(materialItem.TemplateId);
					}
				}
			}
			if (materialIdList.Count > 0)
			{
				short targetId = materialIdList.GetRandom(context.Random);
				ItemKey itemKey = DomainManager.Item.CreateItem(context, 5, targetId);
				inventory.OfflineAdd(itemKey, 1);
				_taiwuChar.AddInventoryItem(context, itemKey, 1, offLine: true);
			}
		}
		short key;
		int value;
		foreach (KeyValuePair<short, int> item in DomainManager.Extra.ChoosyRemainUpgradeRateDict)
		{
			item.Deconstruct(out key, out value);
			short key2 = key;
			int value2 = value;
			DomainManager.Extra.SetChoosyRemainUpgradeRate(key2, value2, context);
		}
		foreach (KeyValuePair<short, int> item2 in DomainManager.Extra.ChoosyRemainUpgradeCountDict)
		{
			item2.Deconstruct(out key, out value);
			short key3 = key;
			int value3 = value;
			DomainManager.Extra.SetChoosyRemainUpgradeCount(key3, value3, context);
		}
		_taiwuChar.SetInventory(_taiwuChar.GetInventory(), context);
		List<ItemDisplayData> resultList = DomainManager.Item.GetItemDisplayDataListOptionalFromInventory(inventory, _taiwuCharId, 1);
		int craftSeniority = 0;
		int doctorSeniority = 0;
		foreach (ItemDisplayData itemDisplayData in resultList)
		{
			sbyte skillType = ItemTemplateHelper.GetResourceType(itemDisplayData.Key.ItemType, itemDisplayData.Key.TemplateId);
			if ((uint)(skillType - 1) <= 3u)
			{
				MaterialItem config = Config.Material.Instance[itemDisplayData.Key.TemplateId];
				int key4 = ((config.RefiningEffect < 0) ? 21 : 22);
				int seniority = ProfessionFormulaImpl.Calculate(key4, (int)itemDisplayData.Value);
				craftSeniority += seniority;
			}
			else if (skillType == 5)
			{
				int seniority2 = ProfessionFormulaImpl.Calculate(90, (int)itemDisplayData.Value);
				doctorSeniority += seniority2;
			}
		}
		DomainManager.Extra.ChangeProfessionSeniority(context, 2, craftSeniority);
		DomainManager.Extra.ChangeProfessionSeniority(context, 13, doctorSeniority);
		return resultList;
	}

	public void AddChoosyRemainUpgradeData(DataContext context)
	{
		LifeSkillShorts lifeSkillAttainments = DomainManager.Taiwu.GetTaiwu().GetLifeSkillAttainments();
		for (sbyte id = 0; id < Choosy.Instance.Count; id++)
		{
			ChoosyItem choosyConfig = Choosy.Instance[id];
			DomainManager.Extra.TryGetChoosyRemainUpgradeCount(id, out var upgradeCount);
			DomainManager.Extra.TryGetChoosyRemainUpgradeRate(id, out var upgradeRate);
			short lifeSkillAttainment = lifeSkillAttainments[choosyConfig.LifeSkillType];
			int maxAddCount = choosyConfig.UpgradeCountAttainmentBonus * lifeSkillAttainment / choosyConfig.AttainmentRate;
			int maxAddRate = choosyConfig.UpgradeRateAttainmentBonus * lifeSkillAttainment / choosyConfig.AttainmentRate;
			int randomAddCount = ((maxAddCount > 0) ? context.Random.Next(maxAddCount) : 0);
			int randomAddRate = ((maxAddRate > 0) ? context.Random.Next(maxAddRate) : 0);
			int finalAddCount = Math.Min(choosyConfig.MaxUpgradeCount, upgradeCount + randomAddCount);
			int finalAddRate = Math.Min(choosyConfig.MaxUpgradeRate, upgradeRate + randomAddRate);
			DomainManager.Extra.SetChoosyRemainUpgradeCount(id, finalAddCount, context);
			DomainManager.Extra.SetChoosyRemainUpgradeRate(id, finalAddRate, context);
		}
	}

