	[DomainMethod]
	public void SetCricketPlan(DataContext context, int index, ItemKey cricket, int cricketIndex)
	{
		CricketPresetItem preset = _cricketPreset.Presets.GetOrDefault(index);
		if (preset?.CricketIds?.GetOrDefault(cricketIndex, -1) != cricket.Id)
		{
			for (int i = _cricketPreset.Presets.Count; i <= index; i++)
			{
				_cricketPreset.AddPreset();
			}
			if (preset == null)
			{
				preset = _cricketPreset.Presets[index];
			}
			CricketPresetItem cricketPresetItem = preset;
			if (cricketPresetItem.CricketIds == null)
			{
				cricketPresetItem.CricketIds = new List<int>();
			}
			preset.CricketIds.SetOrAdd(cricketIndex, cricket.Id, -1);
			if (cricket == ItemKey.Invalid && preset.PolymorphCharIds != null && cricketIndex < preset.PolymorphCharIds.Count)
			{
				preset.PolymorphCharIds[cricketIndex] = -1;
			}
			SetCricketPreset(_cricketPreset, context);
		}
	}

