	[DomainMethod]
	public bool PutMaterialToCricketRoom(DataContext context, List<ItemKeyAndCount> keys, ItemSourceType sourceType)
	{
		if (keys == null || keys.Count <= 0)
		{
			return false;
		}
		ItemKey itemKey;
		int count;
		foreach (ItemKeyAndCount key3 in keys)
		{
			key3.Deconstruct(out itemKey, out count);
			ItemKey key = itemKey;
			if (key.ItemType != 12)
			{
				return false;
			}
			MiscItem config = Config.Misc.Instance[key.TemplateId];
			bool flag;
			if (config != null)
			{
				EMiscResourceMaterialType resourceMaterialType = config.ResourceMaterialType;
				if ((uint)resourceMaterialType <= 1u)
				{
					flag = true;
					goto IL_0089;
				}
			}
			flag = false;
			goto IL_0089;
			IL_0089:
			if (!flag)
			{
				return false;
			}
		}
		foreach (ItemKeyAndCount key4 in keys)
		{
			key4.Deconstruct(out itemKey, out count);
			ItemKey key2 = itemKey;
			int count2 = count;
			RemoveItem(context, key2, count2, sourceType, deleteItem: false);
			CricketRoomData cricketRoomData = _cricketRoomData;
			if (cricketRoomData.MaterialCounts == null)
			{
				cricketRoomData.MaterialCounts = new Dictionary<short, int>();
			}
			int existCount = _cricketRoomData.MaterialCounts.GetOrDefault(key2.TemplateId);
			_cricketRoomData.MaterialCounts[key2.TemplateId] = existCount + count2;
		}
		_cricketRoomData.UpdateEnabledStatus();
		SetCricketRoomData(_cricketRoomData, context);
		return true;
	}

	[DomainMethod]
	public bool TakeMaterialFromCricketRoom(DataContext context, List<ItemKeyAndCount> keys, ItemSourceType sourceType)
	{
		if (keys != null && keys.Count > 0)
		{
			Dictionary<short, int> materialCounts = _cricketRoomData.MaterialCounts;
			if (materialCounts != null && materialCounts.Count > 0)
			{
				ItemKey itemKey;
				int count;
				foreach (ItemKeyAndCount key3 in keys)
				{
					key3.Deconstruct(out itemKey, out count);
					ItemKey key = itemKey;
					int count2 = count;
					if (key.ItemType != 12)
					{
						return false;
					}
					if (!_cricketRoomData.MaterialCounts.TryGetValue(key.TemplateId, out var existCount))
					{
						return false;
					}
					if (existCount < count2)
					{
						return false;
					}
				}
				foreach (ItemKeyAndCount key4 in keys)
				{
					key4.Deconstruct(out itemKey, out count);
					ItemKey key2 = itemKey;
					int count3 = count;
					ItemKey trulyKey = DomainManager.Item.CreateMisc(context, key2.TemplateId);
					AddItem(context, trulyKey, count3, sourceType);
					_cricketRoomData.MaterialCounts[key2.TemplateId] -= count3;
					if (_cricketRoomData.MaterialCounts[key2.TemplateId] == 0)
					{
						_cricketRoomData.MaterialCounts.Remove(key2.TemplateId);
					}
				}
				SetCricketRoomData(_cricketRoomData, context);
				return true;
			}
		}
		return false;
	}

	[DomainMethod]
	public ItemDisplayData CricketRoomPolymorphReturn(DataContext context, int charId)
	{
		if (!_cricketRoomData.EnabledPolymorphReturn)
