		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			return null;
		}
		ItemKey cricketKey = CricketPolymorphReturn(context, character);
		if (!cricketKey.IsValid())
		{
			return null;
		}
		GameData.Domains.Item.Cricket cricket = DomainManager.Item.GetElement_Crickets(cricketKey.Id);
		AddLifeRecordCricketPolymorphReturn(charId, cricket);
		CricketPolymorphReturnToVoid(context, character);
		_taiwuChar.AddInventoryItem(context, cricketKey, 1);
		return DomainManager.Item.GetItemDisplayData(cricketKey, charId);
	}

	[DomainMethod]
	public Location CricketRoomWishingCricket(DataContext context, short wishingCricketId)
	{
		if (!_cricketRoomData.EnabledMakingWish)
		{
			return Location.Invalid;
		}
		if (_cricketLuckPoint < GlobalConfig.Instance.CricketWishingCostLuckPoint)
		{
			return Location.Invalid;
		}
		CricketPartsItem template = CricketParts.Instance[wishingCricketId];
		if (template == null || template.Type != ECricketPartsType.King)
		{
			return Location.Invalid;
		}
		MapBlockData block = DomainManager.Map.SelectBlockInTaiwuVillageInfluenceRange(context.Random, AllowCricketPrefer) ?? DomainManager.Map.SelectBlockInTaiwuVillageInfluenceRange(context.Random, AllowCricket);
		if (block == null)
		{
			return Location.Invalid;
		}
		SetCricketLuckPoint(_cricketLuckPoint - GlobalConfig.Instance.CricketWishingCostLuckPoint, context);
		DomainManager.Extra.CreateExtraCricketMapUnit(context, block.GetLocation(), GlobalConfig.Instance.CricketWishingDuration, showAsRegular: false, wishingCricketId);
		return block.GetLocation();
	}

	[DomainMethod]
	public void CricketWishingCricketReturnLuckPoint(DataContext context)
	{
		SetCricketLuckPoint(_cricketLuckPoint + GlobalConfig.Instance.CricketWishingReturnLuckPoint, context);
	}

	private bool AllowCricket(MapBlockData block)
	{
		if (DomainManager.Map.LocationHasCricket(null, block.GetLocation()))
		{
			return false;
		}
		return CricketPlaceDataHelper.BlockAllowCricket(block);
	}

	private bool AllowCricketPrefer(MapBlockData block)
	{
		if (!AllowCricket(block))
		{
			return false;
		}
		HashSet<int> fixedCharacterSet = block.FixedCharacterSet;
		if (fixedCharacterSet != null && fixedCharacterSet.Count > 0)
		{
			return false;
		}
		Location location = block.GetLocation();
		if (DomainManager.Merchant.IsCaravanAtBlock(location))
		{
			return false;
		}
		AdventureCacheData cache = DomainManager.Adventure.GetAdventureCache();
		return !cache.QueryAnyAdventureOrMajorEvent(location);
	}

