	[DomainMethod]
	public bool FeedingCricket(DataContext context, ItemKey targetKey, List<ItemKeyAndCount> keys, ItemSourceType sourceType)
	{
		if (targetKey.ItemType != 11 || !DomainManager.Item.TryGetElement_Crickets(targetKey.Id, out var target))
		{
			return false;
		}
		if (keys == null || keys.Count <= 0)
		{
			return false;
		}
		ItemKey itemKey;
		int count;
		foreach (ItemKeyAndCount key3 in keys)
		{
			key3.Deconstruct(out itemKey, out count);
			ItemKey key = itemKey;
			if (key.ItemType == 12)
			{
				short templateId = key.TemplateId;
				if (templateId >= 9 && templateId <= 17)
				{
					continue;
				}
			}
			return false;
		}
		foreach (ItemKeyAndCount key4 in keys)
		{
			key4.Deconstruct(out itemKey, out count);
			ItemKey key2 = itemKey;
			int count2 = count;
			RemoveItem(context, key2, count2, sourceType, deleteItem: false);
			sbyte grade = key2.GetConfig().Grade;
			int addValue = GlobalConfig.Instance.CricketBloodDewAddSpirit[grade];
			target.AddSpirit(context, addValue * count2);
		}
		return true;
	}

