		{
			foreach (short templateId in crossArchiveGameData.OwnedClothingSet.Keys)
			{
				RecordOwnedClothing(context, templateId);
			}
		}
		SetCricketPreset(_cricketPreset, context);
		if (crossArchiveGameData.TaiwuPropertyPermanentBonuses != null)
		{
			foreach (var (type, dreamBackBonus) in crossArchiveGameData.TaiwuPropertyPermanentBonuses)
			{
				if (_taiwuPropertyPermanentBonuses.TryGetValue(type, out var bonus))
				{
					bonus.AddValue = Math.Max(bonus.AddValue, dreamBackBonus.AddValue);
					bonus.AddPercent = Math.Max(bonus.AddPercent, dreamBackBonus.AddPercent);
					SetElement_TaiwuPropertyPermanentBonuses(type, bonus, context);
				}
				else
				{
					AddElement_TaiwuPropertyPermanentBonuses(type, dreamBackBonus, context);
				}
			}
		}
		if (crossArchiveGameData.SelectedUniqueLegacies != null)
		{
			SetSelectedUniqueLegacies(crossArchiveGameData.SelectedUniqueLegacies, context);
		}
	}

	public void UnpackCrossArchiveGameData_Building(DataContext context, CrossArchiveGameData crossArchiveGameData)
	{
		_taiwuChar.ChangeResources(context, ref crossArchiveGameData.TaiwuResources);
		UnpackBuildingItems(context, crossArchiveGameData, ref crossArchiveGameData.WarehouseItems, ItemSourceType.Warehouse);
		UnpackBuildingItems(context, crossArchiveGameData, ref crossArchiveGameData.TreasuryItems, ItemSourceType.Treasury);
