				{
					item.Deconstruct(out var key, out value);
					int id = key;
					sbyte value2 = value;
					SetWeaponInnerRatiosById(context, crossArchiveGameData.UnpackedItems.TryGetValue(id, out var realId) ? realId.Id : id, value2);
				}
			}
			if (crossArchiveGameData.WeaponInnerRatiosByTemplateId != null)
			{
				foreach (KeyValuePair<short, sbyte> item2 in crossArchiveGameData.WeaponInnerRatiosByTemplateId)
				{
					item2.Deconstruct(out var key2, out value);
					short id2 = key2;
					sbyte value3 = value;
					SetWeaponInnerRatiosByTemplateId(context, id2, value3);
				}
			}
		}
		crossArchiveGameData.WeaponInnerRatiosById = null;
		crossArchiveGameData.WeaponInnerRatiosByTemplateId = null;
		crossArchiveGameData.EquipmentsPlans = null;
	}

	public void UnpackCrossArchiveGameData_LifeSkills(DataContext context, CrossArchiveGameData crossArchiveGameData)
