		for (int i = 0; i < _currLifeSkillAttainmentPanelPlanIndex.Length; i++)
		{
			SetElement_CurrLifeSkillAttainmentPanelPlanIndex(i, crossArchiveGameData.CurrLifeSkillAttainmentPanelPlanIndex[i], context);
		}
		crossArchiveGameData.TaiwuLifeSkills = null;
		crossArchiveGameData.NotLearnedLifeSkills = null;
		crossArchiveGameData.CurrLifeSkillAttainmentPanelPlanIndex = null;
		bool CombineDreamBackTaiwuLifeSkill(short num, TaiwuLifeSkill dreamBackLifeSkill3)
		{
			if (_lifeSkills.TryGetValue(num, out var lifeSkill))
			{
				CombineTaiwuLifeSkillData(lifeSkill, dreamBackLifeSkill3);
				SetElement_LifeSkills(num, lifeSkill, context);
				return true;
			}
			if (_notLearnLifeSkillReadingProgress.TryGetValue(num, out var notLearnedLifeSkill))
			{
				CombineTaiwuLifeSkillData(notLearnedLifeSkill, dreamBackLifeSkill3);
				RemoveElement_NotLearnCombatSkillReadingProgress(num, context);
				AddElement_LifeSkills(num, notLearnedLifeSkill, context);
				return true;
			}
			return false;
		}
		static void CombineTaiwuLifeSkillData(TaiwuLifeSkill taiwuLifeSkill, TaiwuLifeSkill taiwuLifeSkill2)
		{
			sbyte[] readingProgress = taiwuLifeSkill.GetAllBookPageReadingProgress();
			sbyte[] dreamBackReadingProgress = taiwuLifeSkill2.GetAllBookPageReadingProgress();
			for (byte index = 0; index < readingProgress.Length; index++)
			{
				sbyte progress = Math.Max(readingProgress[index], dreamBackReadingProgress[index]);
				taiwuLifeSkill.SetBookPageReadingProgress(index, progress);
			}
		}
	}

	public void UnpackCrossArchiveGameData_CombatSkills(DataContext context, CrossArchiveGameData crossArchiveGameData, bool overwriteEquipments)
	{
		int currDate = DomainManager.World.GetCurrDate();
		int dateDiff = currDate - DomainManager.Extra.GetFinalDateBeforeDreamBack();
		Dictionary<short, TaiwuCombatSkill> dreamBackCombatSkills = crossArchiveGameData.TaiwuCombatSkills;
		short key;
		TaiwuCombatSkill value;
		if (dreamBackCombatSkills != null)
		{
			foreach (KeyValuePair<short, TaiwuCombatSkill> item in dreamBackCombatSkills)
			{
				item.Deconstruct(out key, out value);
				short skillId = key;
				TaiwuCombatSkill dreamBackCombatSkill = value;
				if (dreamBackCombatSkill.LastClearBreakPlateTime >= 0)
				{
					dreamBackCombatSkill.LastClearBreakPlateTime += dateDiff;
				}
				if (!CombineDreamBackTaiwuCombatSkill(skillId, dreamBackCombatSkill))
				{
					AddElement_CombatSkills(skillId, dreamBackCombatSkill, context);
				}
			}
		}
		Dictionary<short, TaiwuCombatSkill> dreamBackNotLearnedCombatSkills = crossArchiveGameData.NotLearnedCombatSkills;
		if (dreamBackNotLearnedCombatSkills != null)
		{
			foreach (KeyValuePair<short, TaiwuCombatSkill> item2 in dreamBackNotLearnedCombatSkills)
			{
				item2.Deconstruct(out key, out value);
				short skillId2 = key;
				TaiwuCombatSkill dreamBackCombatSkill2 = value;
				if (!CombineDreamBackTaiwuCombatSkill(skillId2, dreamBackCombatSkill2))
				{
					AddElement_NotLearnCombatSkillReadingProgress(skillId2, dreamBackCombatSkill2, context);
				}
			}
		}
		HashSet<short> skillIds = new HashSet<short>();
		if (crossArchiveGameData.CombatSkillBreakPlates != null)
		{
			foreach (short skillId3 in crossArchiveGameData.CombatSkillBreakPlates.Keys)
			{
				skillIds.Add(skillId3);
			}
		}
		if (crossArchiveGameData.CombatSkillBreakPresets != null)
		{
			foreach (short skillId4 in crossArchiveGameData.CombatSkillBreakPresets.Keys)
			{
				skillIds.Add(skillId4);
			}
		}
		Dictionary<short, SkillBreakPlate> conflictPlates = new Dictionary<short, SkillBreakPlate>();
		Dictionary<short, CombatSkillBreakPreset> conflictPresets = new Dictionary<short, CombatSkillBreakPreset>();
		foreach (short skillId5 in skillIds)
		{
			SkillBreakPlate crossPlate = crossArchiveGameData.CombatSkillBreakPlates?.GetOrDefault(skillId5);
			if (crossPlate != null && !crossPlate.Success)
			{
				crossPlate = null;
			}
			CombatSkillBreakPreset crossPreset = crossArchiveGameData.CombatSkillBreakPresets?.GetOrDefault(skillId5);
			if (crossPreset != null && !crossPreset.AnySuccess)
			{
				crossPreset = null;
			}
			if (crossPlate == null && crossPreset == null)
			{
				continue;
			}
			if (crossPreset != null)
			{
				foreach (CombatSkillBreakSnapshot snapshot in crossPreset.Presets)
				{
					if (snapshot != null)
					{
						snapshot.LastClearTime += dateDiff;
					}
				}
			}
			if ((_combatSkillBreakPlates.TryGetValue(skillId5, out var plate) && plate.Success) || (_combatSkillBreakPresets.TryGetValue(skillId5, out var preset) && preset.AnySuccess))
			{
				if (crossPlate != null)
				{
					conflictPlates[skillId5] = crossPlate;
				}
				if (crossPreset != null)
				{
					conflictPresets[skillId5] = crossPreset;
				}
				continue;
			}
			if (crossPlate != null)
			{
				if (_combatSkillBreakPlates.ContainsKey(skillId5))
				{
					SetElement_CombatSkillBreakPlates(skillId5, crossPlate, context);
				}
				else
				{
					AddElement_CombatSkillBreakPlates(skillId5, crossPlate, context);
				}
			}
			if (crossPreset != null)
			{
				if (_combatSkillBreakPresets.ContainsKey(skillId5))
				{
					SetElement_CombatSkillBreakPresets(skillId5, crossPreset, context);
				}
				else
				{
					AddElement_CombatSkillBreakPresets(skillId5, crossPreset, context);
				}
			}
		}
		crossArchiveGameData.CombatSkillBreakPlates = conflictPlates;
		crossArchiveGameData.CombatSkillBreakPresets = conflictPresets;
		if (overwriteEquipments)
		{
			short[] equippedCombatSkills = _taiwuChar.GetEquippedCombatSkills();
			short[] dreamBackEquippedCombatSkills = crossArchiveGameData.TaiwuChar.GetEquippedCombatSkills();
			Array.Copy(dreamBackEquippedCombatSkills, equippedCombatSkills, equippedCombatSkills.Length);
			_taiwuChar.SetEquippedCombatSkills(equippedCombatSkills, context);
			if (crossArchiveGameData.ExternalEquippedCombatSkills != null)
			{
				DomainManager.Extra.SetCharacterEquippedCombatSkills(context, _taiwuCharId, crossArchiveGameData.ExternalEquippedCombatSkills);
			}
			SetCurrCombatSkillPlanId(crossArchiveGameData.CurrCombatSkillPlanId, context);
			for (int i = 0; i < _combatSkillPlans.Length; i++)
			{
				SetElement_CombatSkillPlans(i, crossArchiveGameData.CombatSkillPlans[i], context);
			}
			short[] dreamBackPanel = crossArchiveGameData.TaiwuChar.GetCombatSkillAttainmentPanels();
			short[] panel = _taiwuChar.GetCombatSkillAttainmentPanels();
			dreamBackPanel.CopyTo(panel, 0);
			_taiwuChar.SetCombatSkillAttainmentPanels(panel, context);
			SetCombatSkillAttainmentPanelPlans(crossArchiveGameData.CombatSkillAttainmentPanelPlans, context);
			SetCurrCombatSkillAttainmentPanelPlanIds(crossArchiveGameData.CurrCombatSkillAttainmentPanelPlanIds, context);
		}
		_taiwuChar.SetCurrNeili(_taiwuChar.GetMaxNeili(), context);
		crossArchiveGameData.CombatSkillPlans = null;
		crossArchiveGameData.CombatSkillAttainmentPanelPlans = null;
		crossArchiveGameData.CurrCombatSkillAttainmentPanelPlanIds = null;
		bool CombineDreamBackTaiwuCombatSkill(short num, TaiwuCombatSkill dreamBackCombatSkill3)
		{
			if (_combatSkills.TryGetValue(num, out var combatSkill))
			{
				CombineTaiwuCombatSkillData(combatSkill, dreamBackCombatSkill3);
				SetElement_CombatSkills(num, combatSkill, context);
				return true;
			}
			if (_notLearnCombatSkillReadingProgress.TryGetValue(num, out var notLearnedCombatSkill))
			{
				CombineTaiwuCombatSkillData(notLearnedCombatSkill, dreamBackCombatSkill3);
				RemoveElement_NotLearnCombatSkillReadingProgress(num, context);
				AddElement_CombatSkills(num, notLearnedCombatSkill, context);
				return true;
			}
			return false;
		}
		static void CombineTaiwuCombatSkillData(TaiwuCombatSkill taiwuCombatSkill, TaiwuCombatSkill taiwuCombatSkill2)
		{
			taiwuCombatSkill.FullPowerCastTimes = Math.Max(taiwuCombatSkill.FullPowerCastTimes, taiwuCombatSkill2.FullPowerCastTimes);
			taiwuCombatSkill.LastClearBreakPlateTime = Math.Max(taiwuCombatSkill.LastClearBreakPlateTime, taiwuCombatSkill2.LastClearBreakPlateTime);
			sbyte[] readingProgress = taiwuCombatSkill.GetAllBookPageReadingProgress();
			sbyte[] dreamBackReadingProgress = taiwuCombatSkill2.GetAllBookPageReadingProgress();
			for (byte internalIndex = 0; internalIndex < readingProgress.Length; internalIndex++)
			{
				sbyte progress = Math.Max(readingProgress[internalIndex], dreamBackReadingProgress[internalIndex]);
				taiwuCombatSkill.SetBookPageReadingProgress(internalIndex, progress);
			}
		}
	}

	[DomainMethod]
	public int GetIsTaiwuFirstByLuck(DataContext context, int npcId)
	{
		int taiwuLuck = 0;
		int npcLuck = 0;
		foreach (int id in GetGroupCharIds().GetCollection())
		{
			taiwuLuck += DomainManager.Character.GetElement_Objects(id).GetPersonality(5);
		}
		GameData.Domains.Character.Character opponent = DomainManager.Character.GetElement_Objects(npcId);
		int leaderId = opponent.GetLeaderId();
		if (leaderId == _taiwuCharId)
		{
			npcLuck = taiwuLuck;
		}
		else if (leaderId >= 0)
		{
			foreach (int charId in DomainManager.Character.GetGroup(leaderId).GetCollection())
			{
				npcLuck += DomainManager.Character.GetElement_Objects(charId).GetPersonality(5);
			}
		}
		else
		{
			npcLuck += opponent.GetPersonality(5);
		}
		int prob = 50 + taiwuLuck - npcLuck;
		return context.Random.CheckPercentProb(prob) ? 1 : (-1);
	}

	[DomainMethod]
	public DebateGame DebateGameInitialize(DataContext context, sbyte type, bool isTaiwuFirst, int npcId, List<int> spectatorIds)
	{
		GameData.Domains.Character.Character taiwu = GetTaiwu();
		GameData.Domains.Character.Character npc = DomainManager.Character.GetElement_Objects(npcId);
		List<short> taiwuCards = taiwu.GetUnlockedDebateStrategyList();
		List<short> npcCards = npc.GetUnlockedDebateStrategyList();
		List<sbyte> taiwuCardTypes = DebateGameGetTaiwuSelectedCardTypes();
		List<sbyte> npcCardTypes = DomainManager.Extra.DebateGameGetPlayerSelectedStrategyCardTypes(npcId);
		int taiwuBases = taiwu.GetLifeSkillAttainment(type) * context.Random.Next(DebateConstants.AttainmentToBasesPercent[0], DebateConstants.AttainmentToBasesPercent[1]) / 100;
		int npcBases = npc.GetLifeSkillAttainment(type) * context.Random.Next(DebateConstants.AttainmentToBasesPercent[0], DebateConstants.AttainmentToBasesPercent[1]) / 100;
		for (int i = taiwuCards.Count - 1; i >= 0; i--)
		{
			if (!taiwuCardTypes.Contains(DebateStrategy.Instance[taiwuCards[i]].LifeSkillType))
			{
				taiwuCards.RemoveAt(i);
			}
		}
		for (int i2 = npcCards.Count - 1; i2 >= 0; i2--)
		{
			if (!npcCardTypes.Contains(DebateStrategy.Instance[npcCards[i2]].LifeSkillType))
			{
				npcCards.RemoveAt(i2);
			}
		}
		DebatePlayer playerLeft = new DebatePlayer(taiwu.GetId(), DebateConstants.MaxPressure, taiwuBases, taiwuCards);
		DebatePlayer playerRight = new DebatePlayer(npc.GetId(), DebateConstants.MaxPressure, npcBases, npcCards);
		Dictionary<IntPair, DebateNode> debateGrid = new Dictionary<IntPair, DebateNode>();
		for (int y = 0; y < DebateConstants.DebateLineCount; y++)
		{
			for (int x = 0; x < DebateConstants.DebateLineNodeCount; x++)
			{
				debateGrid[new IntPair(x, y)] = new DebateNode(x, y);
			}
		}
		_pawnId = 0;
		_nodeEffectId = 0;
		_activatedStrategyId = 0;
		_debateRevealedPawnCount = (taiwu: 0, npc: 0);
		if (spectatorIds != null)
		{
			foreach (int spectatorId in spectatorIds)
			{
				GameData.Domains.Character.Character spectator = DomainManager.Character.GetElement_Objects(spectatorId);
				if (spectator.GetCreatingType() == 1)
				{
					if (npc.GetCreatingType() == 1)
					{
						DomainManager.Character.TryCreateRelation(context, spectatorId, _debateNpcId);
					}
					DomainManager.Character.TryCreateRelation(context, spectatorId, _taiwuCharId);
				}
				_debateSpectatorCooldownMap[spectatorId] = 0;
			}
		}
		Debate = new DebateGame(type, isTaiwuFirst, playerLeft, playerRight, spectatorIds ?? new List<int>(), debateGrid, isTaiwuAi: false);
		DebateGameInitializeAi(context, npc);
		DebateGameInitializeStrategyActions();
		return Debate;
	}

	[DomainMethod]
	public List<int> DebateGamePickSpectators(DataContext context, sbyte lifeSkillType, int npcId, bool isTaiwu, List<int> spectatorIds)
	{
		_debateLifeSkillType = lifeSkillType;
		_debateNpcId = npcId;
		_debateNpc = DomainManager.Character.GetElement_Objects(_debateNpcId);
		List<int> result = new List<int>();
		List<int> sorted = new List<int>();
		HashSet<int> opponentGroupCharIds = new HashSet<int>();
		GameData.Domains.Character.Character opponent = DomainManager.Character.GetElement_Objects(npcId);
		if (opponent.GetCreatingType() != 1)
		{
			if (!isTaiwu)
			{
				CharacterItem config = Config.Character.Instance[opponent.GetTemplateId()];
				if (config.MinionGroupId >= 0)
				{
					MinionGroupItem minionGroup = MinionGroup.Instance[config.MinionGroupId];
					foreach (short templateId in minionGroup.Minions)
					{
						int id = DomainManager.Character.CreateNonIntelligentCharacter(context, templateId);
						result.Add(id);
						_debateNpcSpectators.Add(id);
					}
				}
				return result;
			}
		}
		else
		{
			int leaderId = opponent.GetLeaderId();
			if (leaderId >= 0 && leaderId != _taiwuCharId)
			{
				foreach (int charId in DomainManager.Character.GetGroup(leaderId).GetCollection())
				{
					opponentGroupCharIds.Add(charId);
				}
			}
		}
		Location location = GetTaiwu().GetLocation();
		if (location.IsValid())
		{
			CalcTaiwuDebateSpectators(location, sorted);
		}
		else if (!isTaiwu)
		{
			foreach (int charId2 in opponentGroupCharIds)
			{
				sorted.Add(charId2);
			}
		}
		if (isTaiwu)
		{
			foreach (int id2 in GetGroupCharIds().GetCollection())
			{
				sorted.Add(id2);
			}
		}
		for (int index = sorted.Count - 1; index >= 0; index--)
		{
			int charId3 = sorted[index];
			if (charId3 == _debateNpcId || charId3 == _taiwuCharId || !DomainManager.Character.TryGetElement_Objects(charId3, out var character) || character.GetAgeGroup() == 0 || character.GetFeatureIds().Contains(211) || character.GetLegendaryBookOwnerState() == 3 || (isTaiwu && opponentGroupCharIds.Contains(charId3)))
			{
				sorted.RemoveAt(index);
			}
		}
		if (spectatorIds != null)
		{
			foreach (int spectatorId in spectatorIds)
			{
				sorted.Remove(spectatorId);
			}
		}
		if (isTaiwu)
		{
			sorted.Sort(DebateGameCompareSpectatorByAttainment);
		}
		else
		{
			switch (_debateNpc.GetBehaviorType())
			{
			case 0:
			case 1:
				sorted.Sort(DebateGameCompareSpectatorByNpcImpression);
				break;
			case 3:
			case 4:
				sorted.Sort(DebateGameCompareSpectatorByTaiwuImpression);
				break;
			default:
				sorted.Sort(DebateGameCompareSpectatorByMixedImpression);
				break;
			}
		}
		int count = (isTaiwu ? sorted.Count : Math.Min(3, sorted.Count));
		for (int i = 0; i < count; i++)
		{
			result.Add(sorted[0]);
			sorted.RemoveAt(0);
		}
		if (!isTaiwu)
		{
			foreach (int id3 in result)
			{
				_debateNpcSpectators.Add(id3);
			}
		}
		return result;
	}

	[DomainMethod]
	public DebateGame DebateGameNextState(DataContext context)
	{
		Debate.DebateOperations.Clear();
		switch (Debate.State)
		{
		case 0:
			if (Debate.IsTaiwuFirst)
			{
				DebateGameTryApplyComment(context, isTaiwu: true, 0);
				DebateGameTryApplyComment(context, isTaiwu: true, 8);
			}
			else
			{
				DebateGameTryApplyComment(context, isTaiwu: false, 0);
				DebateGameTryApplyComment(context, isTaiwu: false, 8);
			}
			break;
		case 1:
			if (Debate.IsTaiwuFirst)
			{
				DebateGameTryApplyComment(context, isTaiwu: false, 0);
				DebateGameTryApplyComment(context, isTaiwu: false, 8);
			}
			else
			{
				DebateGameTryApplyComment(context, isTaiwu: true, 0);
				DebateGameTryApplyComment(context, isTaiwu: true, 8);
			}
			break;
		}
		Debate.State = (sbyte)((Debate.State + 1) % 3);
		_debateCardUsedCount = 0;
		_debateBeatPawnCount = (taiwu: 0, npc: 0);
		if (Debate.State == 0)
		{
			Debate.IsTaiwuAiProcessedInRound = false;
			Debate.Round++;
			DebateGameUpdateNodeEffects(context);
			if (Debate.Round > 0)
			{
				DebateGameUpdatePlayerStrategyCard(context, isTaiwu: true);
				DebateGameUpdatePlayerStrategyCard(context, isTaiwu: false);
			}
			if (Debate.Round > 1)
			{
				DebateGameRecoverResources(context, isTaiwu: true);
				DebateGameRecoverResources(context, isTaiwu: false);
				DebateGameRemoveDeadPawns();
			}
			DebateGameUpdateRoundStartStrategyEffect(context);
			if (Debate.Round > DebateConstants.PressureAutoIncreaseRound)
			{
				DebateGameChangePlayerPressure(context, (left: DebateConstants.PressureAutoIncreaseValue, right: DebateConstants.PressureAutoIncreaseValue));
			}
			if (Debate.Round >= DebateConstants.MaxRound && !Debate.IsGameOver)
			{
				DebateGameTryProcessEnd();
			}
		}
		if (!Debate.IsGameOver)
		{
			DebateGameProcessState(context);
		}
		return Debate;
	}

	[DomainMethod]
	public DebateGame DebateGameMakeMove(DataContext context, IntPair coordinate, bool isTaiwu, sbyte grade, bool countAsMakeMove = true)
	{
		Tester.Assert(Debate.DebateGrid[coordinate].PawnId < 0);
		if (isTaiwu && !Debate.IsTaiwuAi && countAsMakeMove)
		{
			Debate.DebateOperations.Clear();
		}
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(isTaiwu);
		int cost = Debate.GetPawnGradeToBase(player.MaxBases, grade);
		DebateGameChangePlayerBases(player, -cost, isTaiwu: false, -1);
		bool makeMoveFailed = DebateGameCheckPressure(context, isTaiwu, 7);
		DebateGameAddPawn(context, coordinate, isTaiwu, grade, 0, makeMoveFailed);
		if (countAsMakeMove)
		{
			DebateGameTryApplyNoCountAsMakeMove(coordinate, isTaiwu, makeMoveFailed);
		}
		if (makeMoveFailed)
		{
			DebateGameApplyPressureEffect(isTaiwu, 7, player.Pressure, -1);
		}
		return Debate;
	}

	[DomainMethod]
	public DebateGame DebateGameSetTaiwuAi(DataContext context, bool isAi)
	{
		Debate.DebateOperations.Clear();
		Debate.IsTaiwuAi = isAi;
		if (isAi && Debate.GetIsTaiwuTurn())
		{
			DebateGameTaiwuTurn(context);
		}
		return Debate;
	}

	[DomainMethod]
	public void DebateGameSetTaiwuSelectedCardTypes(DataContext context, List<sbyte> types)
	{
		int res = 0;
		if (types != null)
		{
			foreach (sbyte type in types)
			{
				res |= 1 << (int)type;
			}
		}
		DomainManager.Extra.SetTaiwuSelectedDebateCardType(res, context);
	}

	[DomainMethod]
	public List<sbyte> DebateGameGetTaiwuSelectedCardTypes()
	{
		int bit = DomainManager.Extra.GetTaiwuSelectedDebateCardType();
		List<sbyte> res = new List<sbyte>();
		if (bit <= 0)
		{
			return res;
		}
		for (sbyte i = 0; i < 16; i++)
		{
			if ((bit & (1 << (int)i)) != 0)
			{
				res.Add(i);
			}
		}
		return res;
	}

	[DomainMethod]
	public DebateGame DebateGameRemoveCards(bool isTaiwu, List<int> removingCards)
	{
		if (isTaiwu && !Debate.IsTaiwuAi)
		{
			Debate.DebateOperations.Clear();
		}
		removingCards.Sort();
		for (int i = removingCards.Count - 1; i >= 0; i--)
		{
			int index = removingCards[i];
			DebateGameRemovePlayerCanUseCard(isTaiwu, Debate.GetStrategyCardLocation(isTaiwu, 7), index);
		}
		if (removingCards.Count > 0)
		{
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 4, new int[1] { removingCards.Count }));
		}
		return Debate;
	}

	[DomainMethod]
	public DebateGame DebateGameResetCards(DataContext context, bool isTaiwu, bool isManul)
	{
		if (isTaiwu && isManul)
		{
			Debate.DebateOperations.Clear();
		}
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(isTaiwu);
		int pressure = player.Pressure;
		bool end = DebateGameSetPlayerPressure(context, player, player.Pressure + GlobalConfig.Instance.DebateResetCardsPressureDelta);
		Debate.DebateOperations.Add(new DebateOperation(22, isTaiwu, player.UsedCards));
		player.OwnedCards.AddRange(player.UsedCards);
		player.UsedCards.Clear();
		Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 5, new int[1] { player.Pressure - pressure }));
		if (end)
		{
			DebateGameTryProcessEnd();
		}
		return Debate;
	}

	[DomainMethod]
	public bool DebateGameTryForceWin(DataContext context)
	{
		int taiwuVal = Math.Max(1, _taiwuChar.GetLifeSkillAttainment(Debate.LifeSkillType) * (100 + Debate.PlayerLeft.GamePoint * DebateConstants.SurrenderAttainmentFactor) / 100);
		int npcVal = Math.Max(1, _debateNpc.GetLifeSkillAttainment(Debate.LifeSkillType) * (100 + Debate.PlayerRight.GamePoint * DebateConstants.SurrenderAttainmentFactor) / 100);
		int percent = taiwuVal * GlobalConfig.Instance.DebateSurrenderFactor / npcVal + Math.Max(1, Debate.PlayerRight.Pressure) - DebateConstants.SurrenderBehaviorFactor[_debateNpc.GetBehaviorType()];
		return context.Random.CheckPercentProb(percent);
	}

	[DomainMethod]
	public bool DebateGameTryForceWinInCombatBegin(DataContext context, sbyte lifeSkillType)
	{
		int taiwuVal = Math.Max(1, _taiwuChar.GetLifeSkillAttainment(lifeSkillType) * (100 + GlobalConfig.Instance.DebateMaxGamePoint * DebateConstants.SurrenderAttainmentFactor) / 100);
		int npcVal = Math.Max(1, _debateNpc.GetLifeSkillAttainment(lifeSkillType) * (100 + GlobalConfig.Instance.DebateMaxGamePoint * DebateConstants.SurrenderAttainmentFactor) / 100);
		int percent = taiwuVal * GlobalConfig.Instance.DebateSurrenderFactor / npcVal + Math.Max(1, 0) - DebateConstants.SurrenderBehaviorFactor[_debateNpc.GetBehaviorType()];
		return context.Random.CheckPercentProb(percent);
	}

	[DomainMethod]
	public DebateResult DebateGameOver(DataContext context, bool isTaiwuWin, bool isSurrender)
	{
		DebateResult result = new DebateResult();
		sbyte taiwuConsummateLevel = _taiwuChar.GetConsummateLevel();
		sbyte npcConsummateLevel = _debateNpc.GetConsummateLevel();
		short taiwuAttainment = _taiwuChar.GetLifeSkillAttainment(_debateLifeSkillType);
		short npcAttainment = _debateNpc.GetLifeSkillAttainment(_debateLifeSkillType);
		bool npcShouldCount = _debateNpc.GetCreatingType() == 1;
		sbyte taiwuHappiness = _taiwuChar.GetHappiness();
		sbyte npcHappiness = _debateNpc.GetHappiness();
		result.IsTaiwuWin = isTaiwuWin;
		if (isTaiwuWin)
		{
			DebateGameApplyDebateEvaluation(context, 0, isWin: true, result);
			DomainManager.Taiwu.RecordLifeSummary(context, 39);
			AchievementManager.RequestSetStat(context, 5, 1);
			DomainManager.Taiwu.AddLegacyPoint(context, 18);
			int percent = ((taiwuAttainment != 0) ? (npcAttainment * 100 / taiwuAttainment) : 0);
			if (percent <= DebateConstants.BullyPercent)
			{
				DebateGameApplyDebateEvaluation(context, 2, isWin: true, result);
			}
			else if (percent >= DebateConstants.OverComePercent)
			{
				DebateGameApplyDebateEvaluation(context, 3, isWin: true, result);
			}
		}
		else
		{
			DebateGameApplyDebateEvaluation(context, 1, isWin: false, result);
			if (isSurrender)
			{
				DebateGameApplyDebateEvaluation(context, 4, isWin: false, result);
			}
		}
		if (Debate != null)
		{
			foreach (int spectatorId in Debate.Spectators)
			{
				result.Favorability[spectatorId] = new IntPair(DebateGameGetSpectatorFavor(spectatorId, _taiwuCharId), 0);
			}
		}
		result.AddHappiness(_taiwuCharId, result.HappinessDelta);
		result.AddHappiness(_debateNpcId, -result.HappinessDelta);
		if (Debate != null)
		{
			foreach (int spectatorId2 in Debate.Spectators)
			{
				GameData.Domains.Character.Character spectator = DomainManager.Character.GetElement_Objects(spectatorId2);
				if (spectator.GetCreatingType() == 1)
				{
					if (_debateNpcSpectators.Contains(spectatorId2))
					{
						spectator.ChangeHappiness(context, -result.HappinessDelta);
					}
					else
					{
						spectator.ChangeHappiness(context, result.HappinessDelta);
					}
				}
			}
		}
		if (Debate != null)
		{
			foreach (GameData.Domains.Taiwu.Debate.DebateComment comment in Debate.Comments)
			{
				if (comment.PlayerId == _taiwuCharId || npcShouldCount)
				{
					DebateGameApplyComment(context, comment, result);
				}
			}
		}
		if (result.Happiness.ContainsKey(_taiwuCharId))
		{
			_taiwuChar.ChangeHappiness(context, result.GetHappiness(_taiwuCharId));
		}
		if (result.Happiness.ContainsKey(_debateNpcId) && _debateNpc.GetCreatingType() == 1)
		{
			_debateNpc.ChangeHappiness(context, result.GetHappiness(_debateNpcId));
		}
		result.IsTaiwuWin = isTaiwuWin;
		result.Happiness[_taiwuCharId] = new IntPair(taiwuHappiness, _taiwuChar.GetHappiness());
		result.Happiness[_debateNpcId] = new IntPair(npcHappiness, _debateNpc.GetHappiness());
		if (Debate != null)
		{
			foreach (int spectatorId3 in Debate.Spectators)
			{
				result.Favorability[spectatorId3] = new IntPair(result.Favorability[spectatorId3].First, DebateGameGetSpectatorFavor(spectatorId3, _taiwuCharId));
			}
		}
		int expIndex = Math.Clamp(npcConsummateLevel, 0, GlobalConfig.Instance.CombatGetExpBase.Length - 1);
		int exp = GlobalConfig.Instance.CombatGetExpBase[expIndex];
		exp += result.ExpA;
		exp = exp * result.ExpB / 100;
		exp = exp * (100 + result.ExpCMax + result.ExpCMin) / 100;
		result.Exp = new IntPair(_taiwuChar.GetExp(), exp);
		_taiwuChar.ChangeExp(context, exp);
		int authorityIndex = Math.Clamp(npcConsummateLevel, 0, GlobalConfig.Instance.CombatGetAuthorityBase.Length - 1);
		int authority = GlobalConfig.Instance.CombatGetAuthorityBase[authorityIndex];
		authority += result.AuthorityA;
		authority = authority * result.AuthorityB / 100;
		authority = authority * (100 + result.AuthorityCMax + result.AuthorityCMin) / 100;
		result.Authority = new IntPair(_taiwuChar.GetResource(7), authority);
		_taiwuChar.ChangeResource(context, 7, authority);
		sbyte readInLifeSkillCombatCount = DomainManager.Extra.GetReadInLifeSkillCombatCount();
		ItemKey currBook = GetCurReadingBook();
		SkillBookItem bookCfg = Config.SkillBook.Instance[currBook.TemplateId];
		int chanceReading = 40 + (npcConsummateLevel - taiwuConsummateLevel) * 10;
		chanceReading += result.ReadRate;
		if (readInLifeSkillCombatCount > 0 && currBook.IsValid() && GetTotalReadingProgress(currBook.Id) < 100 && bookCfg.LifeSkillTemplateId >= 0 && context.Random.CheckPercentProb(chanceReading))
		{
			result.ShowReadingEvent = true;
			DomainManager.Extra.SetReadInLifeSkillCombatCount((sbyte)(readInLifeSkillCombatCount - 1), context);
			result.ShowReadingEvent2 = UpdateReadingProgressInCombat(context);
			if (result.ShowReadingEvent2)
			{
				DomainManager.Extra.AddReadingEventBookId(context, currBook.Id);
			}
		}
		sbyte loopInLifeSkillCombatCount = DomainManager.Extra.GetLoopInLifeSkillCombatCount();
		short loopingNeigongTemplateId = _taiwuChar.GetLoopingNeigong();
		CombatSkillKey skillKey = new CombatSkillKey(_taiwuChar.GetId(), loopingNeigongTemplateId);
		int chanceLooping = 40 + (npcConsummateLevel - taiwuConsummateLevel) * 10;
		chanceLooping += result.LoopRate;
		if (loopInLifeSkillCombatCount > 0 && loopingNeigongTemplateId >= 0 && DomainManager.CombatSkill.TryGetElement_CombatSkills(skillKey, out var _) && context.Random.CheckPercentProb(chanceLooping))
		{
			DomainManager.Extra.SetLoopInLifeSkillCombatCount((sbyte)(loopInLifeSkillCombatCount - 1), context);
			ApplyNeigongLoopingImprovementOnce(context);
			result.ShowLoopingEvent = true;
			result.ShowLoopingEvent2 = TryAddLoopingEvent(context, chanceLooping);
			InstantNotificationCollection instantCollection = DomainManager.World.GetInstantNotificationCollection();
			instantCollection.AddQiArtInLifeSkillCombatNoChance(loopingNeigongTemplateId);
		}
		if (isTaiwuWin)
		{
			switch (_debateLifeSkillType)
			{
			case 13:
			{
				ProfessionFormulaItem formula3 = ProfessionFormula.Instance[82];
				int addSeniority3 = formula3.Calculate(npcAttainment);
				DomainManager.Extra.ChangeProfessionSeniority(context, 12, addSeniority3);
				break;
			}
			case 12:
			{
				ProfessionFormulaItem formula2 = ProfessionFormula.Instance[95];
				int addSeniority2 = formula2.Calculate(npcAttainment);
				DomainManager.Extra.ChangeProfessionSeniority(context, 14, addSeniority2);
				break;
			}
			default:
			{
				ProfessionFormulaItem formula = ProfessionFormula.Instance[31];
				int addSeniority = formula.Calculate(npcAttainment);
				DomainManager.Extra.ChangeProfessionSeniority(context, 4, addSeniority);
				break;
			}
			}
		}
		if (isTaiwuWin && DomainManager.Character.TryGetElement_Objects(_debateNpcId, out var target))
		{
			short randomEnemyId = Config.Character.Instance[target.GetTemplateId()].RandomEnemyId;
			if (randomEnemyId >= 0)
			{
				Location location = _taiwuChar.GetLocation();
				if (!location.IsValid())
				{
					location = _taiwuChar.GetValidLocation();
				}
				int prev = DomainManager.Extra.GetAreaSpiritualDebt(location.AreaId);
				List<int> enemyTeam = DomainManager.Character.GetNonIntelligentNpcCombatTeam(context, target);
				int areaSpiritualDebt = 0;
				foreach (int charId in enemyTeam)
				{
					short randomId = Config.Character.Instance[DomainManager.Character.GetElement_Objects(charId).GetTemplateId()].RandomEnemyId;
					if (randomId >= 0)
					{
						areaSpiritualDebt += RandomEnemy.Instance[randomId].SpiritualDebt;
					}
				}
				DomainManager.Extra.ChangeAreaSpiritualDebt(context, location.AreaId, areaSpiritualDebt);
				int curr = DomainManager.Extra.GetAreaSpiritualDebt(location.AreaId);
				if (curr != prev)
				{
					result.AreaSpiritualDebt = new IntPair(prev, curr - prev);
				}
			}
		}
		foreach (int charId2 in result.Happiness.Keys)
		{
			result.CharacterDisplayDataMap[charId2] = DomainManager.Character.GetCharacterDisplayData(charId2);
		}
		foreach (int charId3 in result.Favorability.Keys)
		{
			result.CharacterDisplayDataMap[charId3] = DomainManager.Character.GetCharacterDisplayData(charId3);
		}
		_debateStrategyActions = null;
		_debateAiTaiwu = null;
		_debateAiNpc = null;
		Debate = null;
		_debateSpectatorCooldownMap.Clear();
		_debateNpcSpectators.Clear();
		DomainManager.TaiwuEvent.RecordCombatResult(isTaiwuWin);
		DomainManager.Global.InvokeGuidingTrigger(context, 322);
		return result;
	}

	private void DebateGameProcessState(DataContext context)
	{
		DebateGameUpdateCanMakeMoveNode();
		DebateGameUpdatePlayerMakeMoveCount();
		switch (Debate.State)
		{
		case 0:
			if (Debate.IsTaiwuFirst)
			{
				DebateGameTaiwuTurn(context);
			}
			else
			{
				DebateGameNpcTurn(context);
			}
			break;
		case 1:
			if (Debate.IsTaiwuFirst)
			{
				DebateGameNpcTurn(context);
			}
			else
			{
				DebateGameTaiwuTurn(context);
			}
			break;
		case 2:
			DebateGamePawnTurn(context);
			break;
		}
	}

	private void DebateGameTaiwuTurn(DataContext context)
	{
		if (Debate.IsTaiwuAi && !Debate.IsTaiwuAiProcessedInRound)
		{
			DebateGameStartAiOperation(context, isTaiwu: true);
		}
	}

	private void DebateGameNpcTurn(DataContext context)
	{
		DebateGameStartAiOperation(context, isTaiwu: false);
	}

	private void DebateGamePawnTurn(DataContext context)
	{
		_debateVisitedPawns.Clear();
		for (int i = 0; i < DebateConstants.DebateLineCount; i++)
		{
			DebateGameProcessLine(context, i);
		}
	}

	private void DebateGameRecoverResources(DataContext context, bool isTaiwu)
	{
		DebatePlayer player = (isTaiwu ? Debate.PlayerLeft : Debate.PlayerRight);
		bool noBasesRecover = DebateGameCheckPressure(context, isTaiwu, 5);
		bool noStrategyRecover = DebateGameCheckPressure(context, isTaiwu, 4);
		int strategyRecover = DebateConstants.StrategyPointRecover;
		int basesRecover = DebateConstants.BasesRecoverPercent;
		if (noStrategyRecover)
		{
			DebateGameApplyPressureEffect(isTaiwu, 4, player.Pressure, -1);
			strategyRecover = strategyRecover * DebateConstants.PressureStrategyRecoverPercent / 100;
		}
		if (noBasesRecover)
		{
			DebateGameApplyPressureEffect(isTaiwu, 5, player.Pressure, -1);
			basesRecover = basesRecover * DebateConstants.PressureBasesRecoverPercent / 100;
		}
		Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 0, new int[4] { strategyRecover, 0, basesRecover, 0 }));
		DebateGameChangePlayerStrategyPoint(player, strategyRecover);
		DebateGameChangePlayerBases(player, player.MaxBases * basesRecover / 100, isTaiwu: false, -1);
	}

	private void DebateGameRemoveDeadPawns()
	{
		List<int> toRemoveList = ObjectPool<List<int>>.Instance.Get();
		toRemoveList.Clear();
		foreach (var (id, pawn2) in Debate.Pawns)
		{
			if (!pawn2.IsAlive)
			{
				toRemoveList.Add(id);
			}
		}
		foreach (int id2 in toRemoveList)
		{
			DebateGameRemovePawn(id2);
		}
		ObjectPool<List<int>>.Instance.Return(toRemoveList);
	}

	private void DebateGameUpdateNodeEffects(DataContext context)
	{
		foreach (DebateNode node in Debate.DebateGrid.Values)
		{
			if (node.EffectState.TemplateId >= 0)
			{
				node.EffectState.Duration--;
				if (node.EffectState.Duration <= 0)
				{
					DebateGameRemoveNodeEffect(node);
				}
			}
		}
		foreach (int spectatorId in Debate.Spectators)
		{
			if (_debateSpectatorCooldownMap[spectatorId] > 0)
			{
				_debateSpectatorCooldownMap[spectatorId]--;
			}
			else
			{
				if (!context.Random.CheckPercentProb(DebateConstants.AddNodeEffectProb))
				{
					continue;
				}
				sbyte behaviorType = DomainManager.Character.GetElement_Objects(spectatorId).GetBehaviorType();
				foreach (DebateNodeEffectItem config in (IEnumerable<DebateNodeEffectItem>)DebateNodeEffect.Instance)
				{
					if (config.BehaviorType == behaviorType && DebateGameTryAddNodeEffect(context, config.TemplateId, spectatorId))
					{
						break;
					}
				}
			}
		}
		foreach (DebateNode node2 in Debate.DebateGrid.Values)
		{
			if (node2.EffectState.TemplateId >= 0 && node2.PawnId >= 0)
			{
				DebateGameTryApplyNodeEffect(context, node2.Coordinate, EDebateNodeEffectRemoveType.Instant);
			}
		}
	}

	private void DebateGameUpdateRoundStartStrategyEffect(DataContext context)
	{
		foreach (var (pawnId, pawn2) in Debate.Pawns)
		{
			if (pawn2.IsAlive)
			{
				DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, EDebateStrategyTriggerType.RoundStart);
			}
		}
	}

	private void DebateGameUpdatePlayerStrategyCard(DataContext context, bool isTaiwu)
	{
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(isTaiwu);
		Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, -1, null));
		int addCount = Math.Min(player.OwnedCards.Count, Math.Min(GlobalConfig.Instance.DebateMaxShuffleCard, GlobalConfig.Instance.DebateMaxCanUseCards - player.CanUseCards.Count));
		if (addCount > 0)
		{
			CollectionUtils.Shuffle(context.Random, player.OwnedCards);
			for (int i = 0; i < addCount; i++)
			{
				DebateGameAddPlayerCanUseCard(isTaiwu, Debate.GetStrategyCardLocation(isTaiwu, 6), 0);
			}
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 3, new int[1] { addCount }));
		}
	}

	private void DebateGameUpdateCanMakeMoveNode()
	{
		for (int y = 0; y < DebateConstants.DebateLineCount; y++)
		{
			for (int x = 0; x < DebateConstants.DebateLineNodeCount; x++)
			{
				IntPair coordinate = new IntPair(x, y);
				Debate.DebateGrid[coordinate].TaiwuCanMakeMove = Debate.GetNodeCanMakeMove(coordinate, isTaiwu: true);
				Debate.DebateGrid[coordinate].NpcCanMakeMove = Debate.GetNodeCanMakeMove(coordinate, isTaiwu: false);
			}
		}
	}

	private void DebateGameUpdatePlayerMakeMoveCount()
	{
		Debate.PlayerLeft.MakeMoveCount = 0;
		Debate.PlayerRight.MakeMoveCount = 0;
	}

	private void DebateGameTryProcessEnd()
	{
		if (Debate.Round >= DebateConstants.MaxRound)
		{
			Debate.IsTaiwuWin = ((Debate.PlayerLeft.GamePoint == Debate.PlayerRight.GamePoint) ? Debate.IsTaiwuFirst : (Debate.PlayerLeft.GamePoint > Debate.PlayerRight.GamePoint));
			Debate.IsGameOver = true;
		}
		else if (Debate.PlayerLeft.GamePoint <= 0)
		{
			Debate.IsTaiwuWin = Debate.PlayerRight.GamePoint <= 0 && Debate.IsTaiwuFirst;
			Debate.IsGameOver = true;
		}
		else if (Debate.PlayerRight.GamePoint <= 0)
		{
			Debate.IsTaiwuWin = true;
			Debate.IsGameOver = true;
		}
	}

	private void DebateGameExecutePawnConflict(DataContext context, int taiwuPawnId, int npcPawnId, bool isTaiwuPawnTurn)
	{
		int pawnLeftBases = Debate.GetPawnBases(taiwuPawnId, npcPawnId);
		int pawnRightBases = Debate.GetPawnBases(npcPawnId, taiwuPawnId);
		bool isTaiwuWin = pawnLeftBases > pawnRightBases || (pawnLeftBases == pawnRightBases && isTaiwuPawnTurn);
		int result = ((!isTaiwuWin) ? 1 : 0);
		bool loserPawnIsZero = (isTaiwuWin ? Debate.Pawns[npcPawnId].IsZero : Debate.Pawns[taiwuPawnId].IsZero);
		bool loserPawnCurrentIsZero = (isTaiwuWin ? (pawnRightBases == 0) : (pawnLeftBases == 0));
		DebateGameRevealPawnBasesAndStrategy(context, taiwuPawnId);
		DebateGameRevealPawnBasesAndStrategy(context, npcPawnId);
		if (Debate.TryGetPawnStrategyEffectId(taiwuPawnId, 6, isCastedByTaiwu: true, out var strategyId))
		{
			DebateGameAddStrategyRecord(isTaiwu: true, 28, new List<short> { Debate.ActivatedStrategies[strategyId].TemplateId }, null, null);
		}
		if (Debate.TryGetPawnStrategyEffectId(npcPawnId, 6, isCastedByTaiwu: false, out strategyId))
		{
			DebateGameAddStrategyRecord(isTaiwu: false, 28, new List<short> { Debate.ActivatedStrategies[strategyId].TemplateId }, null, null);
		}
		IntPair bases = new IntPair(pawnLeftBases, pawnRightBases);
		Debate.DebateOperations.Add(new DebateOperation(0, taiwuPawnId, npcPawnId, result, bases, Debate.PlayerLeft, Debate.PlayerRight));
		DebateGameProcessPawnConflictResult(context, npcPawnId, pawnLeftBases, !isTaiwuWin);
		DebateGameProcessPawnConflictResult(context, taiwuPawnId, pawnRightBases, isTaiwuWin);
		DebateGameChangePlayerPressure(context, (!isTaiwuWin) ? ((loserPawnIsZero && loserPawnCurrentIsZero) ? (left: 0, right: DebateConstants.PressureDeltaInConflict) : (left: DebateConstants.PressureDeltaInConflict, right: 0)) : ((loserPawnIsZero && loserPawnCurrentIsZero) ? (left: DebateConstants.PressureDeltaInConflict, right: 0) : (left: 0, right: DebateConstants.PressureDeltaInConflict)));
		DomainManager.Global.InvokeGuidingTrigger(context, 328);
	}

	private void DebateGameRevealPawnBasesAndStrategy(DataContext context, int pawnId)
	{
		Pawn pawn = Debate.Pawns[pawnId];
		DebateGameSetPawnRevealed(context, pawnId);
		int[] strategies = pawn.Strategies;
		foreach (int strategyId in strategies)
		{
			if (strategyId >= 0)
			{
				Debate.ActivatedStrategies[strategyId].IsRevealed = true;
			}
		}
	}

	private void DebateGameProcessPawnConflictResult(DataContext context, int pawnId, int otherPawnBases, bool isWin)
	{
		_oneTimeStrategyActionList.Clear();
		Pawn pawn = Debate.Pawns[pawnId];
		DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, (!isWin) ? EDebateStrategyTriggerType.ConflictLose : EDebateStrategyTriggerType.ConflictWin);
		if (!isWin)
		{
			DebateGameSetPawnDead(context, pawnId, 0);
		}
		if (pawn.IsAlive && !pawn.IsImmuneDebuff && !pawn.IsImmuneRemove)
		{
			DebateGameSetPawnBases(pawnId, pawn.Bases - otherPawnBases);
		}
		foreach (Action oneTimeStrategyAction in _oneTimeStrategyActionList)
		{
			oneTimeStrategyAction?.Invoke();
		}
	}

	private void DebateGameProcessLine(DataContext context, int y)
	{
		bool isTaiwuFirst = y % 2 == 0 && Debate.IsTaiwuFirst;
		bool isTaiwuPawnTurn = isTaiwuFirst;
		bool[] isDone = new bool[2];
		while (!isDone[0] || !isDone[1])
		{
			int ptr = ((!isTaiwuPawnTurn) ? 1 : 0);
			int direction = ((!isTaiwuPawnTurn) ? 1 : (-1));
			int pawnId = -1;
			int startPos = (isTaiwuPawnTurn ? (DebateConstants.DebateLineNodeCount - 1) : 0);
			if (isDone[ptr])
			{
				isTaiwuPawnTurn = !isTaiwuPawnTurn;
				continue;
			}
			for (int x = startPos; Debate.GetCoordinateValid(x); x += direction)
			{
				pawnId = Debate.DebateGrid[new IntPair(x, y)].PawnId;
				if (pawnId >= 0 && Debate.Pawns[pawnId].IsOwnedByTaiwu == isTaiwuPawnTurn && !_debateVisitedPawns.Contains(pawnId))
				{
					break;
				}
				pawnId = -1;
			}
			if (pawnId < 0)
			{
				isDone[ptr] = true;
				isTaiwuPawnTurn = !isTaiwuPawnTurn;
				continue;
			}
			Pawn pawn = Debate.Pawns[pawnId];
			IntPair coordinate = Debate.GetPawnTargetPosition(pawnId);
			if (!Debate.GetCoordinateValid(coordinate))
			{
				continue;
			}
			DebateGameTryApplyPawnMoveMore(pawnId);
			DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, EDebateStrategyTriggerType.PawnActing);
			if (Debate.GetPawnIsHalt(pawnId))
			{
				if (Debate.TryGetPawnStrategyEffectId(pawnId, 34, !pawn.IsOwnedByTaiwu, out var strategyId))
				{
					DebateGameAddStrategyRecord(pawn.IsOwnedByTaiwu, 62, new List<short> { Debate.ActivatedStrategies[strategyId].TemplateId }, null, null);
				}
				isTaiwuPawnTurn = !isTaiwuPawnTurn;
				continue;
			}
			int otherId = Debate.DebateGrid[coordinate].PawnId;
			if (otherId < 0)
			{
				DebateGamePawnMoveForward(context, pawnId);
				if (_debateVisitedPawns.Contains(pawnId))
				{
					DebateGameTryApplyPawnMoveMore(pawnId);
				}
				if (_debateVisitedPawns.Contains(pawnId))
				{
					isTaiwuPawnTurn = !isTaiwuPawnTurn;
				}
				continue;
			}
			if (Debate.Pawns[pawnId].IsOwnedByTaiwu == Debate.Pawns[otherId].IsOwnedByTaiwu)
			{
				if (_debateVisitedPawns.Contains(pawnId))
				{
					isTaiwuPawnTurn = !isTaiwuPawnTurn;
				}
				continue;
			}
			int taiwuPawnId = (isTaiwuPawnTurn ? pawnId : otherId);
			int npcPawnId = (isTaiwuPawnTurn ? otherId : pawnId);
			DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, EDebateStrategyTriggerType.ConflictStart);
			DebateGameApplyPawnStrategyEffectByTriggerType(context, otherId, EDebateStrategyTriggerType.ConflictStart);
			if (pawn.IsSwitchLocation || Debate.Pawns[otherId].IsSwitchLocation)
			{
				IntPair taiwuCoordinate = Debate.Pawns[taiwuPawnId].Coordinate;
				IntPair npcCoordinate = Debate.Pawns[npcPawnId].Coordinate;
				DebateGameSetPawnCoordinate(context, taiwuPawnId, npcCoordinate);
				DebateGameSetPawnCoordinate(context, npcPawnId, taiwuCoordinate);
			}
			else
			{
				DebateGameExecutePawnConflict(context, taiwuPawnId, npcPawnId, isTaiwuPawnTurn);
				if (Debate.Pawns[pawnId].IsAlive && Debate.GetNodeCanTeleportPawn(Debate.GetPawnTargetPosition(pawnId)))
				{
					DebateGamePawnMoveForward(context, pawnId);
				}
			}
			if (_debateVisitedPawns.Contains(pawnId))
			{
				DebateGameTryApplyPawnMoveMore(pawnId);
			}
			if (_debateVisitedPawns.Contains(pawnId))
			{
				isTaiwuPawnTurn = !isTaiwuPawnTurn;
			}
		}
	}

	private void DebateGamePawnMoveForward(DataContext context, int pawnId)
	{
		IntPair coordinate = Debate.GetPawnTargetPosition(pawnId);
		if (Debate.DebateGrid[coordinate].PawnId < 0)
		{
			DebateGameSetPawnCoordinate(context, pawnId, coordinate);
		}
		DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, EDebateStrategyTriggerType.PawnForward);
	}

	private void DebateGameApplyPawnDamage(DataContext context, int pawnId)
	{
		Pawn pawn = Debate.Pawns[pawnId];
		if (pawn.Damaged)
		{
			return;
		}
		DebateGameApplyPawnStrategyEffectByTriggerType(context, pawnId, EDebateStrategyTriggerType.PawnDamage);
		DebatePlayer loser = Debate.GetPlayerByPlayerIsTaiwu(!pawn.IsOwnedByTaiwu);
		DebatePlayer winner = Debate.GetPlayerByPlayerIsTaiwu(pawn.IsOwnedByTaiwu);
		if (pawn.NodeDamage > 0)
		{
			DebateGameChangePlayerGamePoint(context, loser, -pawn.NodeDamage, needPlay: true, !pawn.IsOwnedByTaiwu, 4);
		}
		DebateGameChangePlayerGamePoint(context, loser, -DebateConstants.PawnDamageToGamePoint, needPlay: false, !pawn.IsOwnedByTaiwu, -1);
		Debate.DebateOperations.Add(new DebateOperation(4, !pawn.IsOwnedByTaiwu, pawnId, pawn.Coordinate, Debate.PlayerLeft, Debate.PlayerRight));
		Debate.DebateOperations.Add(new DebateOperation(20, !pawn.IsOwnedByTaiwu, 2, new int[4]
		{
			0,
			0,
			DebateConstants.PawnDamageToGamePoint,
			0
		}));
		foreach (PawnDamageInfo damageInfo in pawn.DamageList)
		{
			if (!damageInfo.IsToSelf && !damageInfo.IsStrategyDamage)
			{
				DebateGameChangePlayerGamePoint(context, loser, -damageInfo.Damage, needPlay: true, damageInfo.IsTaiwuCasted, -1);
			}
		}
		int damageToOpponent = DebateConstants.PawnDamageToGamePoint + pawn.DamageToOpponent;
		DebateGameChangePlayerGamePoint(context, winner, damageToOpponent * pawn.ChangeSelfGamePointByDamagePercent / 100, needPlay: true, pawn.ChangeSelfGamePointByDamagePercentIsCastedByTaiwu, -1);
		foreach (PawnDamageInfo damageInfo2 in pawn.DamageList)
		{
			if (!damageInfo2.IsToSelf && damageInfo2.IsStrategyDamage)
			{
				DebateGameChangePlayerGamePoint(context, loser, -damageInfo2.Damage, needPlay: true, damageInfo2.IsTaiwuCasted, -1);
			}
		}
		foreach (PawnDamageInfo damageInfo3 in pawn.DamageList)
		{
			if (damageInfo3.IsToSelf)
			{
				DebateGameChangePlayerGamePoint(context, winner, -damageInfo3.Damage, needPlay: true, damageInfo3.IsTaiwuCasted, -1);
			}
		}
		_debateAiTaiwu.UpdateLineWeightByDamage(pawn.IsOwnedByTaiwu, pawn.Coordinate.Second);
		_debateAiNpc.UpdateLineWeightByDamage(!pawn.IsOwnedByTaiwu, pawn.Coordinate.Second);
		DebateGameSetPawnDead(context, pawnId, 1);
		pawn.Damaged = true;
	}

	private int DebateGameGetSpectatorFavor(int spectatorId, int playerId)
	{
		RelatedCharacter relation;
		return DomainManager.Character.TryGetRelation(spectatorId, playerId, out relation) ? relation.Favorability : 0;
	}

	private void DebateGameApplyDebateEvaluation(DataContext context, short templateId, bool isWin, DebateResult result)
	{
		DebateEvaluationItem config = DebateEvaluation.Instance[templateId];
		result.ExpA += config.ExpA;
		result.ExpB += config.ExpB;
		result.AuthorityA += config.AuthorityA;
		result.AuthorityB += config.AuthorityB;
		result.FavorIncreaseB += config.FavorIncreaseB;
		result.FavorDecreaseB += config.FavorDecreaseB;
		result.ReadRate += config.ReadRate;
		result.LoopRate += config.LoopRate;
		result.HappinessDelta += config.HappinessDelta;
		result.Evaluations.Add(templateId);
		if (config.ExpC > result.ExpCMax)
		{
			result.ExpCMax = config.ExpC;
		}
		else if (config.ExpC < result.ExpCMin)
		{
			result.ExpCMin = config.ExpC;
		}
		if (config.AuthorityC > result.AuthorityCMax)
		{
			result.AuthorityCMax = config.AuthorityC;
		}
		else if (config.AuthorityC < result.AuthorityCMin)
		{
			result.AuthorityCMin = config.AuthorityC;
		}
		if (config.FavorIncreaseC > result.FavorIncreaseCMax)
		{
			result.FavorIncreaseCMax = config.FavorIncreaseC;
		}
		else if (config.FavorIncreaseC < result.FavorIncreaseCMin)
		{
			result.FavorIncreaseCMin = config.FavorIncreaseC;
		}
		if (config.FavorDecreaseC > result.FavorDecreaseCMax)
		{
			result.FavorDecreaseCMax = config.FavorDecreaseC;
		}
		else if (config.FavorDecreaseC < result.FavorDecreaseCMin)
		{
			result.FavorDecreaseCMin = config.FavorDecreaseC;
		}
		if (config.FameAction >= 0)
		{
			_taiwuChar.RecordFameAction(context, config.FameAction, -1, 1);
		}
		foreach (LegacyPointReference data in config.AddLegacyPoint)
		{
			int value = (isWin ? data.WinPercent : data.FailPercent);
			if (value > 0)
			{
				DomainManager.Taiwu.AddLegacyPoint(context, data.TemplateId, value);
			}
		}
	}

	private void DebateGameApplyComment(DataContext context, GameData.Domains.Taiwu.Debate.DebateComment comment, DebateResult result)
	{
		bool isTaiwu = comment.PlayerId == _taiwuCharId;
		GameData.Domains.Character.Character character = (isTaiwu ? _taiwuChar : _debateNpc);
		DebateCommentItem config = Config.DebateComment.Instance[comment.TemplateId];
		int delta = config.Favor;
		Dictionary<short, int> counts = (isTaiwu ? result.TaiwuComments : result.NpcComments);
		if (counts.TryGetValue(comment.TemplateId, out var count))
		{
			if (count >= DebateConstants.CommentStackLimit)
			{
				return;
			}
			counts[comment.TemplateId]++;
		}
		else
		{
			counts[comment.TemplateId] = 1;
		}
		result.AddHappiness(comment.PlayerId, config.Happiness[character.GetBehaviorType()]);
		GameData.Domains.Character.Character spectator = DomainManager.Character.GetElement_Objects(comment.SpectatorId);
		if (spectator.GetCreatingType() != 1)
		{
			return;
		}
		delta += result.FavorA;
		if (delta != 0)
		{
			if (delta > 0)
			{
				delta = delta * result.FavorIncreaseB / 100;
				delta = delta * (100 + result.FavorIncreaseCMax + result.FavorIncreaseCMin) / 100;
			}
			else
			{
				delta = delta * result.FavorDecreaseB / 100;
				delta = delta * (100 + result.FavorDecreaseCMax + result.FavorDecreaseCMin) / 100;
			}
			DomainManager.Character.ChangeFavorabilityOptional(context, spectator, character, delta, -1);
		}
	}

	private void DebateGameTryApplyComment(DataContext context, bool isTaiwu, short templateId)
	{
		int playerId = Debate.GetPlayerByPlayerIsTaiwu(isTaiwu).Id;
		DebateCommentItem config = Config.DebateComment.Instance[templateId];
		if (1 == 0)
		{
		}
		bool flag = templateId switch
		{
			0 => DebateGameComment0(isTaiwu, config.CheckValue), 
			2 => DebateGameComment1(isTaiwu, config.CheckValue), 
			4 => DebateGameComment2(isTaiwu, config.CheckValue), 
			6 => DebateGameComment3(isTaiwu, config.CheckValue), 
			8 => DebateGameComment4(isTaiwu, config.CheckValue), 
			_ => throw new ArgumentOutOfRangeException("templateId", templateId, null), 
		};
		if (1 == 0)
		{
		}
		if (!flag)
		{
			return;
		}
		foreach (int charId in Debate.Spectators)
		{
			sbyte behaviorType = DomainManager.Character.GetElement_Objects(charId).GetBehaviorType();
			int favor = DebateGameGetSpectatorFavor(charId, playerId);
			int positivePercent = ((!isTaiwu) ? (_debateNpcSpectators.Contains(charId) ? DebateConstants.SameSideCommentProb : DebateConstants.OtherSideCommentProb) : (_debateNpcSpectators.Contains(charId) ? DebateConstants.OtherSideCommentProb : DebateConstants.SameSideCommentProb));
			bool isPositive = context.Random.CheckPercentProb(positivePercent + favor / DebateConstants.CommentDivider);
			if (behaviorType != config.BehaviorType)
			{
				config = Config.DebateComment.Instance[config.Negation];
				if (behaviorType != config.BehaviorType)
				{
					continue;
				}
			}
			if (context.Random.CheckPercentProb(DebateConstants.CommentProb) && config.IsPositive == isPositive)
			{
				Debate.Comments.Add(new GameData.Domains.Taiwu.Debate.DebateComment(charId, playerId, config.TemplateId));
				Debate.DebateOperations.Add(new DebateOperation(5, isTaiwu, new IntPair(charId, playerId), config.TemplateId, Debate.PlayerLeft, Debate.PlayerRight));
				Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 6, new int[3] { charId, playerId, config.TemplateId }));
			}
		}
	}

	private bool DebateGameComment0(bool isTaiwu, int value)
	{
		return _debateCardUsedCount == value;
	}

	private bool DebateGameComment1(bool isTaiwu, int value)
	{
		bool isTaiwuMeet = _debateRevealedPawnCount.taiwu == value;
		bool isNpcMeet = _debateRevealedPawnCount.npc == value;
		bool check = (isTaiwu ? isTaiwuMeet : isNpcMeet);
		if (isTaiwu && isTaiwuMeet)
		{
			_debateRevealedPawnCount.taiwu = 0;
		}
		if (!isTaiwu && isNpcMeet)
		{
			_debateRevealedPawnCount.npc = 0;
		}
		return check;
	}

	private bool DebateGameComment2(bool isTaiwu, int value)
	{
		return Debate.GetPawnCount(isTaiwu) >= value;
	}

	private bool DebateGameComment3(bool isTaiwu, int value)
	{
		return isTaiwu ? (_debateBeatPawnCount.taiwu >= value) : (_debateBeatPawnCount.npc >= value);
	}

	private bool DebateGameComment4(bool isTaiwu, int value)
	{
		return _debateCardUsedCount != 0 && (isTaiwu ? (Debate.PlayerLeft.CanUseCards.Count == value) : (Debate.PlayerRight.CanUseCards.Count == value));
	}

	private int DebateGameCompareSpectatorByNpcImpression(int a, int b)
	{
		int impressionA = DebateGameGetSpectatorFavor(a, _debateNpcId);
		int impressionB = DebateGameGetSpectatorFavor(b, _debateNpcId);
		return (impressionA == impressionB) ? (-DomainManager.Character.GetElement_Objects(a).GetLifeSkillAttainment(_debateLifeSkillType).CompareTo(DomainManager.Character.GetElement_Objects(b).GetLifeSkillAttainment(_debateLifeSkillType))) : (-impressionA.CompareTo(impressionB));
	}

	private int DebateGameCompareSpectatorByTaiwuImpression(int a, int b)
	{
		int impressionA = DebateGameGetSpectatorFavor(a, _taiwuCharId);
		int impressionB = DebateGameGetSpectatorFavor(b, _taiwuCharId);
		return (impressionA == impressionB) ? (-DomainManager.Character.GetElement_Objects(a).GetLifeSkillAttainment(_debateLifeSkillType).CompareTo(DomainManager.Character.GetElement_Objects(b).GetLifeSkillAttainment(_debateLifeSkillType))) : impressionA.CompareTo(impressionB);
	}

	private int DebateGameCompareSpectatorByMixedImpression(int a, int b)
	{
		int impressionNpcA = DebateGameGetSpectatorFavor(a, _debateNpcId);
		int impressionTaiwuA = DebateGameGetSpectatorFavor(a, _taiwuCharId);
		int impressionA = Math.Max(-impressionTaiwuA, impressionNpcA);
		int impressionNpcB = DebateGameGetSpectatorFavor(b, _debateNpcId);
		int impressionTaiwuB = DebateGameGetSpectatorFavor(b, _taiwuCharId);
		int impressionB = Math.Max(-impressionTaiwuB, impressionNpcB);
		return (impressionA == impressionB) ? (-DomainManager.Character.GetElement_Objects(a).GetLifeSkillAttainment(_debateLifeSkillType).CompareTo(DomainManager.Character.GetElement_Objects(b).GetLifeSkillAttainment(_debateLifeSkillType))) : (-impressionA.CompareTo(impressionB));
	}

	private int DebateGameCompareSpectatorByAttainment(int a, int b)
	{
		return -DomainManager.Character.GetElement_Objects(a).GetLifeSkillAttainment(_debateLifeSkillType).CompareTo(DomainManager.Character.GetElement_Objects(b).GetLifeSkillAttainment(_debateLifeSkillType));
	}

