			5 => DebateConstants.ReduceBasesRecoverProb[pressureType], 
			6 => DebateConstants.UseStrategyFailedProb[pressureType], 
			7 => DebateConstants.MakeMoveFailedProb[pressureType], 
			_ => 0, 
		};
		if (1 == 0)
		{
		}
