	private void DebateGameTryApplyNodeEffect(DataContext context, IntPair coordinate, EDebateNodeEffectRemoveType type)
	{
		if (!Debate.GetCoordinateValid(coordinate))
		{
			return;
		}
		DebateNode node = Debate.DebateGrid[coordinate];
		if (node.PawnId < 0)
		{
			return;
		}
		Pawn pawn = Debate.Pawns[node.PawnId];
		pawn.ResetNodeValue();
		DebateNodeEffectState nodeEffect = node.EffectState;
		if (nodeEffect.TemplateId < 0)
		{
			return;
		}
		DebateNodeEffectItem config = DebateNodeEffect.Instance[nodeEffect.TemplateId];
		int value = 0;
		if (1 == 0)
		{
		}
		List<IntPair> list = type switch
		{
			EDebateNodeEffectRemoveType.Instant => config.InstantEffectList, 
			EDebateNodeEffectRemoveType.Trigger => config.TriggerEffectList, 
			_ => throw new ArgumentOutOfRangeException("type", type, null), 
		};
		if (1 == 0)
		{
		}
		List<IntPair> effectList = list;
		if (!DebateGameCheckNodeEffect(effectList, pawn))
		{
			return;
		}
		DebateOperation operation = new DebateOperation(19, nodeEffect, node.Coordinate, pawn.IsOwnedByTaiwu);
		Debate.DebateOperations.Add(operation);
		if (config.RemoveType.Contains(type))
		{
			DebateGameRemoveNodeEffect(node);
		}
		foreach (IntPair effect in effectList)
		{
			if (_debateStrategyActions.TryGetValue(effect.First, out var action))
			{
				value = effect.Second;
				DebateStrategyActionParams param = new DebateStrategyActionParams
				{
					Context = context,
					PawnId = node.PawnId,
					Value = effect.Second,
					NodeEffect = nodeEffect,
					Coordinate = node.Coordinate,
					IsCastedByTaiwu = pawn.IsOwnedByTaiwu
				};
				action(param);
			}
		}
		if (config.DebateRecord >= 0)
		{
			int[] param2 = DebateGameGetDebateNodeRecordParameters(config.DebateRecord, nodeEffect, value);
			Debate.DebateOperations.Add(new DebateOperation(20, pawn.IsOwnedByTaiwu, config.DebateRecord, param2));
		}
	}

	private bool DebateGameCheckNodeEffect(List<IntPair> effectList, Pawn pawn)
	{
		if (effectList.Count == 0)
		{
			return false;
		}
		foreach (IntPair effect in effectList)
		{
			if (effect.First == 43 && !Debate.GetPawnCanDamage(pawn.IsOwnedByTaiwu, pawn.Coordinate.First))
			{
				return false;
			}
		}
		return true;
	}

	private void DebateGameTryApplyPawnMoveMore(int pawnId)
	{
		Pawn pawn = Debate.Pawns[pawnId];
		if (pawn.IsAlive)
		{
			if (Debate.GetNodeIsContainingEffect(pawn.Coordinate, 44))
			{
				int[] param = DebateGameGetDebateNodeRecordParameters(8, Debate.DebateGrid[pawn.Coordinate].EffectState, 1);
				_debateVisitedPawns.Remove(pawnId);
				DebateGameRemoveNodeEffect(Debate.DebateGrid[pawn.Coordinate]);
				Debate.DebateOperations.Add(new DebateOperation(20, pawn.IsOwnedByTaiwu, 8, param));
			}
			else
			{
				_debateVisitedPawns.Add(pawnId);
			}
		}
	}

	private void DebateGameTryApplyNoCountAsMakeMove(IntPair coordinate, bool isTaiwu, bool makeMoveFailed)
	{
		if (Debate.GetNodeIsContainingEffect(coordinate, 41))
		{
			DebateNode node = Debate.DebateGrid[coordinate];
			DebateNodeEffectState effect = node.EffectState;
			int[] param = DebateGameGetDebateNodeRecordParameters(10, effect, 1);
			Debate.DebateOperations.Add(new DebateOperation(19, effect, node.Coordinate, isTaiwu));
			DebateGameRemoveNodeEffect(Debate.DebateGrid[coordinate]);
			if (!makeMoveFailed)
			{
				Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 10, param));
			}
		}
		else
		{
			DebateGameChangePlayerMakeMoveCount(Debate.GetPlayerByPlayerIsTaiwu(isTaiwu), 1);
			if (!makeMoveFailed)
			{
				Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 1, new int[2] { 1, 0 }));
			}
		}
	}

	private int[] DebateGameGetDebateNodeRecordParameters(short templateId, DebateNodeEffectState effect, int value)
	{
		DebateRecordItem config = DebateRecord.Instance[templateId];
		int[] res = new int[config.Parameters.Length];
		for (int i = 0; i < config.Parameters.Length; i++)
		{
			int[] array = res;
			int num = i;
			EDebateRecordParamType eDebateRecordParamType = config.Parameters[i];
			if (1 == 0)
			{
			}
			int num2 = eDebateRecordParamType switch
			{
				EDebateRecordParamType.IntValue => value, 
				EDebateRecordParamType.NodeEffect => effect.Id, 
				EDebateRecordParamType.Spectator => effect.CasterId, 
				EDebateRecordParamType.Character => effect.IsHelpTaiwu ? _debateNpcId : _taiwuCharId, 
				_ => 0, 
			};
			if (1 == 0)
			{
			}
			array[num] = num2;
		}
		return res;
	}

	private bool DebateGameGetSpectatorHelpTaiwu(DataContext context, int spectatorId, bool isTaiwu)
	{
		bool isSpectatorTaiwuSide = !_debateNpcSpectators.Contains(spectatorId);
		int favor = DebateGameGetSpectatorFavor(spectatorId, Debate.GetPlayerByPlayerIsTaiwu(isTaiwu).Id);
		int prob = DebateConstants.SpectatorHelpSameSideBase + favor / DebateConstants.SpectatorHelpSameSideDivider;
		return context.Random.CheckPercentProb(prob) == isSpectatorTaiwuSide;
	}

	private bool DebateGameTryAddNodeEffect(DataContext context, short templateId, int spectatorId)
	{
		bool isSpectatorTaiwuSide = !_debateNpcSpectators.Contains(spectatorId);
		bool isHelpTaiwu = DebateGameGetSpectatorHelpTaiwu(context, spectatorId, isSpectatorTaiwuSide);
		bool rebelResult = context.Random.CheckPercentProb(DebateConstants.SpectatorHelpSameSideBase);
		if (1 == 0)
		{
		}
		List<DebateNode> list = templateId switch
		{
			0 => DebateGameGetAvailableNodeJust(isHelpTaiwu), 
			1 => DebateGameGetAvailableNodeKind(isHelpTaiwu), 
			2 => DebateGameGetAvailableNodeEven(isHelpTaiwu), 
			3 => DebateGameGetAvailableNodeRebel(rebelResult), 
			4 => DebateGameGetAvailableNodeEgoistic(isHelpTaiwu), 
			_ => null, 
		};
		if (1 == 0)
		{
		}
		List<DebateNode> list2 = list;
		if (list2 == null)
		{
			return false;
		}
		CollectionUtils.Shuffle(context.Random, list2);
		DebateGameAddNodeEffect(list2[0], templateId, spectatorId, isHelpTaiwu);
		return true;
	}

	private List<DebateNode> DebateGameGetAvailableNodeJust(bool isTaiwuSide)
	{
		List<DebateNode> res = null;
		int startNode = Debate.GetStartCoordinate(!isTaiwuSide);
		foreach (DebateNode node in Debate.DebateGrid.Values)
		{
			if (node.Coordinate.First != startNode && node.PawnId >= 0 && Debate.Pawns[node.PawnId].IsOwnedByTaiwu != isTaiwuSide && !Debate.Pawns[node.PawnId].IsRevealed && node.EffectState.TemplateId < 0)
			{
				if (res == null)
				{
					res = new List<DebateNode>();
