	[DomainMethod]
	public BriberyData GetAiBriberyDataOnPrepareLifeSkillCombat(DataContext context, int charId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		int prob = 0;
		switch (character.GetBehaviorType())
		{
		case 2:
			prob = 10;
			break;
		case 3:
			prob = 13;
			break;
		case 4:
			prob = 16;
			break;
		}
		if (DomainManager.Character.GetAiActionRateAdjust(charId, 11, -1) != 0)
		{
			prob = 0;
		}
		if (_forceAiBribery)
		{
			prob = 100;
		}
		if (_forceBanBribery)
		{
			prob = 0;
		}
		if (context.Random.CheckPercentProb(prob))
		{
			bool useSecretInformation = false;
			switch (character.GetBehaviorType())
			{
			case 1:
				useSecretInformation = context.Random.CheckPercentProb(70);
				break;
			case 2:
				useSecretInformation = context.Random.CheckPercentProb(50);
				break;
			case 3:
				useSecretInformation = context.Random.CheckPercentProb(80);
				break;
			case 4:
				useSecretInformation = context.Random.CheckPercentProb(40);
				break;
			}
			if (useSecretInformation)
			{
				SecretInformationDisplayPackage secretInformation = DomainManager.Taiwu.PickLifeSkillCombatCharacterUseSecretInformation(context, charId);
				if (secretInformation != null && secretInformation.SecretInformationDisplayDataList.Count > 0)
				{
					BriberyData ret = new BriberyData();
					ret.SecretInformationDisplayPackage = secretInformation;
					return ret;
				}
			}
			ItemDisplayData item = DomainManager.Taiwu.PickLifeSkillCombatCharacterUseItem(context, charId);
			if (item != null)
			{
				BriberyData ret2 = new BriberyData();
				ret2.ItemDisplayData = item;
				return ret2;
			}
		}
		return null;
	}

	public SecretInformationDisplayPackage PickLifeSkillCombatCharacterUseSecretInformation(DataContext context, int characterId)
	{
		sbyte behaviorType = DomainManager.Character.GetElement_Objects(characterId).GetBehaviorType();
		if (behaviorType == 0)
		{
			return null;
		}
		SecretInformationDisplayPackage source = DomainManager.Information.GetSecretInformationDisplayPackageFromCharacter(characterId);
		Dictionary<SecretInformationId, int> level = new Dictionary<SecretInformationId, int>();
		switch (behaviorType)
		{
		case 1:
			source.SecretInformationDisplayDataList.RemoveAll(delegate(SecretInformationDisplayData d)
			{
				SecretInformationItem secretInformationItem = SecretInformation.Instance[d.SecretInformationTemplateId];
				return secretInformationItem.ValueType != ESecretInformationValueType.Positive && secretInformationItem.ValueType != ESecretInformationValueType.Normal;
			});
			foreach (SecretInformationDisplayData data3 in source.SecretInformationDisplayDataList)
			{
				SecretInformationItem config3 = SecretInformation.Instance[data3.SecretInformationTemplateId];
				level[data3.SecretInformationId] = 3;
				data3.ParametersPack.ExtractSecretParameters(config3, delegate(int _, int charId)
				{
					short highestScoreRelation = DomainManager.Information.GetHighestScoreRelation(charId);
					if (highestScoreRelation == short.MaxValue)
					{
						level[data3.SecretInformationId] = 1;
					}
					else if (highestScoreRelation >= 0 && highestScoreRelation != 5)
					{
						level[data3.SecretInformationId] = 0;
					}
				});
			}
			break;
		case 2:
			foreach (SecretInformationDisplayData data2 in source.SecretInformationDisplayDataList)
			{
				SecretInformationItem config2 = SecretInformation.Instance[data2.SecretInformationTemplateId];
				level[data2.SecretInformationId] = 3;
				data2.ParametersPack.ExtractSecretParameters(config2, delegate(int _, int charId)
				{
					short highestScoreRelation = DomainManager.Information.GetHighestScoreRelation(charId);
					if (highestScoreRelation >= 0 && highestScoreRelation != short.MaxValue && highestScoreRelation != 5)
					{
						level[data2.SecretInformationId] = 0;
					}
				});
			}
			break;
		case 3:
			source.SecretInformationDisplayDataList.RemoveAll(delegate(SecretInformationDisplayData d)
			{
				SecretInformationItem secretInformationItem = SecretInformation.Instance[d.SecretInformationTemplateId];
				return secretInformationItem.ValueType != ESecretInformationValueType.Negative && secretInformationItem.ValueType != ESecretInformationValueType.Normal;
			});
			foreach (SecretInformationDisplayData data4 in source.SecretInformationDisplayDataList)
			{
				SecretInformationItem config4 = SecretInformation.Instance[data4.SecretInformationTemplateId];
				level[data4.SecretInformationId] = 3;
				data4.ParametersPack.ExtractSecretParameters(config4, delegate(int _, int charId)
				{
					short highestScoreRelation = DomainManager.Information.GetHighestScoreRelation(charId);
					if (highestScoreRelation == short.MaxValue)
					{
						level[data4.SecretInformationId] = 1;
					}
					else if (highestScoreRelation >= 0 && highestScoreRelation != 5)
					{
						level[data4.SecretInformationId] = 0;
					}
				});
			}
			break;
		case 4:
			source.SecretInformationDisplayDataList.RemoveAll(delegate(SecretInformationDisplayData d)
			{
				SecretInformationItem secretInformationItem = SecretInformation.Instance[d.SecretInformationTemplateId];
				return secretInformationItem.ValueType != ESecretInformationValueType.Negative && secretInformationItem.ValueType != ESecretInformationValueType.Positive;
			});
			foreach (SecretInformationDisplayData data in source.SecretInformationDisplayDataList)
			{
				SecretInformationItem config = SecretInformation.Instance[data.SecretInformationTemplateId];
				level[data.SecretInformationId] = 3;
				data.ParametersPack.ExtractSecretParameters(config, delegate(int _, int charId)
				{
					short highestScoreRelation = DomainManager.Information.GetHighestScoreRelation(charId);
					if (highestScoreRelation == short.MaxValue)
					{
						level[data.SecretInformationId] = 1;
					}
					else if (highestScoreRelation >= 0 && highestScoreRelation != 5)
					{
						level[data.SecretInformationId] = 0;
					}
				});
			}
			break;
		}
		source.SecretInformationDisplayDataList.RemoveAll((SecretInformationDisplayData d) => level[d.SecretInformationId] >= 3);
		source.SecretInformationDisplayDataList.Sort((SecretInformationDisplayData a, SecretInformationDisplayData b) => level[a.SecretInformationId].CompareTo(level[b.SecretInformationId]));
		while (source.SecretInformationDisplayDataList.Count > 0)
		{
			source.SecretInformationDisplayDataList.RemoveAt(source.SecretInformationDisplayDataList.Count - 1);
		}
		return source;
	}

	public ItemDisplayData PickLifeSkillCombatCharacterUseItem(DataContext context, int characterId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(characterId);
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		OrganizationItem orgConfig = Config.Organization.Instance[character.GetOrganizationInfo().OrgTemplateId];
		if (orgConfig.IsSect)
		{
			int totalItemTypeWeight = orgConfig.LifeSkillCombatBriberyItemTypeWeight.Sum((LifeSkillCombatBriberyItemTypeWeight t) => t.Weight);
			int totalItemSubTypeWeight = orgConfig.LifeSkillCombatBriberyItemSubTypeWeight.Sum((LifeSkillCombatBriberyItemSubTypeWeight t) => t.Weight);
			if (totalItemTypeWeight + totalItemSubTypeWeight == 0)
			{
				return null;
			}
		}
		sbyte behaviorType = character.GetBehaviorType();
		sbyte b = behaviorType;
		if ((uint)(b - 2) <= 2u)
		{
			List<ItemDisplayData> items = DomainManager.Character.GetAllInventoryItems(characterId);
			sbyte taiwuLevel = taiwuChar.GetConsummateLevel();
			sbyte charLevel = character.GetConsummateLevel();
			sbyte charGrade = character.GetOrganizationInfo().Grade;
			int minGrade;
			int maxGrade;
			if (taiwuLevel >= charLevel)
			{
				minGrade = Math.Clamp(charGrade - 2, 0, 8);
				maxGrade = Math.Clamp(charGrade, 0, 8);
			}
			else
			{
				minGrade = Math.Clamp(taiwuLevel / 2 - 2, 0, 8);
				maxGrade = Math.Clamp(taiwuLevel / 2, 0, 8);
			}
			items.RemoveAll(delegate(ItemDisplayData itemDisplayData)
			{
				Inventory allInventoryFromPool = itemDisplayData.GetAllInventoryFromPool();
				foreach (KeyValuePair<ItemKey, int> item in allInventoryFromPool.Items)
				{
					item.Deconstruct(out var key, out var _);
					ItemKey itemKey = key;
					sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
					if (grade < minGrade || grade > maxGrade)
					{
						return true;
					}
				}
				ItemDisplayData.ReturnInventoryToPool(allInventoryFromPool);
				return false;
			});
			ItemDisplayData picked = null;
			if (orgConfig.IsSect)
			{
				Dictionary<int, (short, int, List<ItemDisplayData>)> itemTypeDict = orgConfig.LifeSkillCombatBriberyItemTypeWeight.Where((LifeSkillCombatBriberyItemTypeWeight p) => p.Weight > 0).ToDictionary((Func<LifeSkillCombatBriberyItemTypeWeight, int>)((LifeSkillCombatBriberyItemTypeWeight p) => p.ItemType), (Func<LifeSkillCombatBriberyItemTypeWeight, (short, int, List<ItemDisplayData>)>)((LifeSkillCombatBriberyItemTypeWeight p) => (Weight: p.Weight, 0, new List<ItemDisplayData>())));
				Dictionary<int, (short, int, List<ItemDisplayData>)> itemSubTypeDict = orgConfig.LifeSkillCombatBriberyItemSubTypeWeight.Where((LifeSkillCombatBriberyItemSubTypeWeight p) => p.Weight > 0).ToDictionary((Func<LifeSkillCombatBriberyItemSubTypeWeight, int>)((LifeSkillCombatBriberyItemSubTypeWeight p) => p.ItemSubType), (Func<LifeSkillCombatBriberyItemSubTypeWeight, (short, int, List<ItemDisplayData>)>)((LifeSkillCombatBriberyItemSubTypeWeight p) => (Weight: p.Weight, 0, new List<ItemDisplayData>())));
				foreach (ItemDisplayData itemData in items)
				{
					sbyte itemType = itemData.RealKey.ItemType;
					if (itemTypeDict.TryGetValue(itemType, out var itemTypeTuple))
					{
						itemTypeTuple.Item3.Add(itemData);
						continue;
					}
					short itemSubType = ItemTemplateHelper.GetItemSubType(itemType, itemData.RealKey.TemplateId);
					if (itemSubTypeDict.TryGetValue(itemSubType, out var itemSubTypeTuple))
					{
						itemSubTypeTuple.Item3.Add(itemData);
					}
				}
				HandleBriberyWeightDict(itemTypeDict);
				HandleBriberyWeightDict(itemSubTypeDict);
				int totalItemTypeWeight2 = itemTypeDict.Sum<KeyValuePair<int, (short, int, List<ItemDisplayData>)>>((KeyValuePair<int, (short Weight, int, List<ItemDisplayData>)> p) => p.Value.Weight);
				int totalItemSubTypeWeight2 = itemSubTypeDict.Sum<KeyValuePair<int, (short, int, List<ItemDisplayData>)>>((KeyValuePair<int, (short Weight, int, List<ItemDisplayData>)> p) => p.Value.Weight);
				int totalWeight = totalItemTypeWeight2 + totalItemSubTypeWeight2;
				if (totalWeight > 0)
				{
					int random = context.Random.Next(totalWeight);
					if (random < totalItemTypeWeight2)
					{
						random = context.Random.Next(totalItemTypeWeight2);
						picked = itemTypeDict.Values.Where<(short, int, List<ItemDisplayData>)>(((short Weight, int, List<ItemDisplayData>) p) => p.Item2 > random).MinBy<(short, int, List<ItemDisplayData>), int>(((short Weight, int, List<ItemDisplayData>) p) => p.Item2).Item3.GetRandom(context.Random);
					}
					else
					{
						random = context.Random.Next(totalItemSubTypeWeight2);
						picked = itemSubTypeDict.Values.Where<(short, int, List<ItemDisplayData>)>(((short Weight, int, List<ItemDisplayData>) p) => p.Item2 > random).MinBy<(short, int, List<ItemDisplayData>), int>(((short Weight, int, List<ItemDisplayData>) p) => p.Item2).Item3.GetRandom(context.Random);
					}
				}
			}
			else
			{
				picked = items.GetRandom(context.Random);
			}
			return picked;
		}
		return null;
	}

	private void HandleBriberyWeightDict(Dictionary<int, (short weight, int curWeight, List<ItemDisplayData> list)> dict)
	{
		foreach (int key in dict.Keys)
		{
			List<ItemDisplayData> item = dict[key].list;
			if (item == null || item.Count <= 0)
			{
				dict.Remove(key);
			}
		}
		int curWeight = 0;
		foreach (int key2 in dict.Keys)
		{
			(short, int, List<ItemDisplayData>) tuple = dict[key2];
			curWeight = (tuple.Item2 = curWeight + tuple.Item1);
			dict[key2] = tuple;
		}
	}

	private bool DebateGameSetPlayerPressure(DataContext context, DebatePlayer player, int value)
	{
		(int pressure, int gamePoint) gamePointAndPressureDelta = Debate.GetGamePointAndPressureDelta(player, value);
		int pressure = gamePointAndPressureDelta.pressure;
		int gamePointDelta = gamePointAndPressureDelta.gamePoint;
		player.Pressure = pressure;
		player.HighestPressure = Math.Max(player.Pressure, player.HighestPressure);
		if (pressure > 0)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 313);
		}
		if (gamePointDelta < 0)
		{
			bool isTaiwu = player.Id == Debate.PlayerLeft.Id;
			player.GamePoint = Math.Max(0, player.GamePoint + gamePointDelta);
			Debate.DebateOperations.Add(new DebateOperation(9, isTaiwu, Debate.PlayerLeft, Debate.PlayerRight, -1));
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, 13, new int[4]
			{
				0,
				pressure,
				Math.Abs(gamePointDelta),
				0
			}));
		}
		return player.GamePoint == 0;
	}

	private void DebateGameChangePlayerMakeMoveCount(DebatePlayer player, int delta)
	{
		player.MakeMoveCount += delta;
	}

	private void DebateGameChangePlayerPressure(DataContext context, (int left, int right) delta)
	{
		bool playerLeftDead = false;
		bool playerRightDead = false;
		if (delta.left != 0)
		{
			playerLeftDead = DebateGameSetPlayerPressure(context, Debate.PlayerLeft, Debate.PlayerLeft.Pressure + delta.left);
		}
		if (delta.right != 0)
		{
			playerRightDead = DebateGameSetPlayerPressure(context, Debate.PlayerRight, Debate.PlayerRight.Pressure + delta.right);
		}
		if (playerLeftDead || playerRightDead)
		{
			DebateGameTryProcessEnd();
		}
	}

	private void DebateGameChangePlayerGamePoint(DataContext context, DebatePlayer player, int delta, bool needPlay = true, bool isTaiwuCasted = false, short nodeEffectTemplateId = -1)
	{
		if (delta == 0)
		{
			return;
		}
		if (delta < 0)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 156);
		}
		int newGamePoint = Math.Min(DebateConstants.MaxGamePoint, player.GamePoint + delta);
		if (player.GamePoint != newGamePoint)
		{
			player.GamePoint = newGamePoint;
			if (needPlay)
			{
				Debate.DebateOperations.Add(new DebateOperation(11, isTaiwuCasted, Debate.PlayerLeft, Debate.PlayerRight, nodeEffectTemplateId));
			}
			DebateGameTryProcessEnd();
		}
	}

	private void DebateGameAddPawn(DataContext context, IntPair coordinate, bool isOwnedByTaiwu, sbyte grade, int value = 0, bool isFailed = false)
	{
		if (isFailed)
		{
			Debate.DebateOperations.Add(new DebateOperation(2, isOwnedByTaiwu, -1, coordinate, Debate.PlayerLeft, Debate.PlayerRight, 0, isFailed: true));
			return;
		}
		int bases = Debate.GetPawnInitialBases(isOwnedByTaiwu, grade, value);
		Pawn pawn = new Pawn(_pawnId, coordinate, isOwnedByTaiwu, bases);
		Debate.DebateGrid[coordinate].PawnId = pawn.Id;
		Debate.DebateOperations.Add(new DebateOperation(2, isOwnedByTaiwu, pawn.Id, coordinate, Debate.PlayerLeft, Debate.PlayerRight, pawn.Bases, isFailed: false));
		Debate.Pawns[_pawnId] = pawn;
		_pawnId++;
		DebateGameTryApplyComment(context, pawn.IsOwnedByTaiwu, 4);
		DebateGameTryApplyNodeEffect(context, coordinate, EDebateNodeEffectRemoveType.Instant);
	}

	private void DebateGameRemovePawn(int id)
	{
		Pawn pawn = Debate.Pawns[id];
		if (Debate.DebateGrid[pawn.Coordinate].PawnId == id)
		{
			Debate.DebateGrid[pawn.Coordinate].PawnId = -1;
		}
		int[] strategies = pawn.Strategies;
		foreach (int strategyId in strategies)
		{
			if (strategyId >= 0)
			{
				DebateGameRemoveStrategy(strategyId, pawn.IsOwnedByTaiwu);
			}
		}
		Debate.Pawns.Remove(id);
	}

	private void DebateGameSetPawnBases(int id, int value)
	{
		Debate.Pawns[id].Bases = Math.Max(0, value);
		Debate.DebateOperations.Add(new DebateOperation(10, id, value, Debate.PlayerLeft, Debate.PlayerRight));
	}

	private void DebateGameSetPawnDead(DataContext context, int id, int cause, bool isTaiwu = false)
	{
		Pawn pawn = Debate.Pawns[id];
		if (pawn.IsHalfImmuneRemove && Debate.TryGetEmptyNode(pawn.IsOwnedByTaiwu, out var coordinates))
		{
			CollectionUtils.Shuffle(context.Random, coordinates);
			DebateGameSetPawnCoordinate(context, id, coordinates[0], isImmuneRemove: true);
			DebateGameSetPawnBases(id, pawn.Bases / 2);
			return;
		}
		if (pawn.IsImmuneRemove)
		{
			IntPair coordinate = Debate.GetStartCoordinate(pawn.IsOwnedByTaiwu, pawn.Coordinate.Second);
			if (Debate.DebateGrid[coordinate].PawnId < 0 || Debate.DebateGrid[coordinate].PawnId == pawn.Id)
			{
				DebateGameSetPawnCoordinate(context, id, coordinate, isImmuneRemove: true);
				return;
			}
		}
		if (Debate.DebateGrid[Debate.Pawns[id].Coordinate].PawnId == id)
		{
			Debate.DebateGrid[Debate.Pawns[id].Coordinate].PawnId = -1;
		}
		Debate.Pawns[id].IsAlive = false;
		Debate.DebateOperations.Add(new DebateOperation(3, id, cause, Debate.PlayerLeft, Debate.PlayerRight, isTaiwu));
		if (cause != 3)
		{
			DebateGameApplyPawnStrategyEffectByTriggerType(context, id, EDebateStrategyTriggerType.PawnDead);
		}
		if (1 == 0)
		{
		}
		bool flag = cause switch
		{
			0 => true, 
			2 => pawn.IsOwnedByTaiwu != isTaiwu, 
			_ => false, 
		};
		if (1 == 0)
		{
		}
		if (flag)
		{
			if (pawn.IsOwnedByTaiwu)
			{
				_debateBeatPawnCount.npc++;
			}
			else
			{
				_debateBeatPawnCount.taiwu++;
			}
			DebateGameTryApplyComment(context, !pawn.IsOwnedByTaiwu, 6);
		}
	}

	private void DebateGameSetPawnRevealed(DataContext context, int id)
	{
		Pawn pawn = Debate.Pawns[id];
		if (pawn.IsRevealed)
		{
			return;
		}
		pawn.IsRevealed = true;
		if (pawn.Bases <= 0)
		{
			if (pawn.IsOwnedByTaiwu)
			{
				_debateRevealedPawnCount.taiwu++;
			}
			else
			{
				_debateRevealedPawnCount.npc++;
			}
		}
		DebateGameTryApplyComment(context, pawn.IsOwnedByTaiwu, 2);
	}

	private void DebateGameSetPawnCoordinate(DataContext context, int id, IntPair coordinate, bool isImmuneRemove = false)
	{
		Pawn pawn = Debate.Pawns[id];
		if (Debate.GetCoordinateValid(pawn.Coordinate) && Debate.DebateGrid[pawn.Coordinate].PawnId == id)
		{
			Debate.DebateGrid[pawn.Coordinate].PawnId = -1;
		}
		pawn.Coordinate = coordinate;
		Debate.DebateGrid[coordinate].PawnId = id;
		Debate.DebateOperations.Add(new DebateOperation(1, id, coordinate, Debate.PlayerLeft, Debate.PlayerRight, isImmuneRemove));
		DebateGameTryApplyNodeEffect(context, coordinate, EDebateNodeEffectRemoveType.Trigger);
		if (Debate.GetPawnCanDamage(pawn.IsOwnedByTaiwu, pawn.Coordinate.First))
		{
			DebateGameApplyPawnDamage(context, id);
		}
	}

	private void DebateGameAddNodeEffect(DebateNode node, short templateId, int casterId, bool isHelpTaiwu)
	{
		DebateNodeEffectItem config = DebateNodeEffect.Instance[templateId];
		node.EffectState = new DebateNodeEffectState(_nodeEffectId, templateId, casterId, config.Duration, isHelpTaiwu);
		_debateSpectatorCooldownMap[casterId] = config.Cooldown;
		Debate.NodeEffects[_nodeEffectId] = node.EffectState;
		_nodeEffectId++;
		Debate.DebateOperations.Add(new DebateOperation(15, node.EffectState, node.Coordinate));
	}

	private void DebateGameRemoveNodeEffect(DebateNode node)
	{
		DebateOperation operation = new DebateOperation(16, node.EffectState, node.Coordinate);
		Debate.DebateOperations.Add(operation);
		node.EffectState = DebateNodeEffectState.Invalid;
	}

	private void DebateGameChangePlayerBases(DebatePlayer player, int delta, bool isTaiwu = false, short nodeEffectTemplateId = -1)
	{
		player.Bases = Math.Clamp(player.Bases + delta, 0, player.MaxBases);
		DebateOperation operation = new DebateOperation(21, isTaiwu, Debate.PlayerLeft, Debate.PlayerRight, nodeEffectTemplateId);
		Debate.DebateOperations.Add(operation);
	}

	private void DebateGameChangePlayerStrategyPoint(DebatePlayer player, int delta)
	{
		player.StrategyPoint = Math.Clamp(player.StrategyPoint + delta, 0, DebateConstants.MaxStrategyPoint);
	}

	private void DebateGameAddStrategy(int pawnId, short templateId, bool isCastedByTaiwu)
	{
		Tester.Assert(Debate.GetPawnStrategyCount(pawnId) < DebateConstants.PawnStrategyLimit);
		ActivatedStrategy strategy = new ActivatedStrategy(_activatedStrategyId, pawnId, templateId, isCastedByTaiwu);
		Pawn pawn = Debate.Pawns[pawnId];
		if (Debate.GetNodeIsContainingEffect(pawn.Coordinate, 32))
		{
			strategy.IsRevealed = true;
		}
		for (int i = 0; i < pawn.Strategies.Length; i++)
		{
			if (pawn.Strategies[i] < 0)
			{
				pawn.Strategies[i] = strategy.Id;
				Debate.DebateOperations.Add(new DebateOperation(6, strategy.PawnId, i, Debate.PlayerLeft, Debate.PlayerRight));
				break;
			}
		}
		Debate.ActivatedStrategies.Add(strategy.Id, strategy);
		_activatedStrategyId++;
	}

	private void DebateGameRemoveStrategy(int id, bool isCastedByTaiwu)
	{
		ActivatedStrategy strategy = Debate.ActivatedStrategies[id];
		Pawn pawn = Debate.Pawns[strategy.PawnId];
		for (int i = 0; i < pawn.Strategies.Length; i++)
		{
			if (pawn.Strategies[i] == strategy.Id)
			{
				pawn.Strategies[i] = -1;
				Debate.DebateOperations.Add(new DebateOperation(13, strategy.PawnId, i, Debate.PlayerLeft, Debate.PlayerRight, isCastedByTaiwu));
			}
		}
		Debate.ActivatedStrategies.Remove(id);
	}

	private void DebateGameChangePawnStrategy(int pawnId, int strategyId, int index, bool changeOwner)
	{
		if (strategyId >= 0)
		{
			ActivatedStrategy strategy = Debate.ActivatedStrategies[strategyId];
			if (changeOwner)
			{
				strategy.IsCastedByTaiwu = !strategy.IsCastedByTaiwu;
			}
			strategy.PawnId = pawnId;
		}
		Debate.Pawns[pawnId].Strategies[index] = strategyId;
	}

	private void DebateGameAddPlayerCanUseCard(bool isTaiwu, int source, int index)
	{
		List<short> sourceList = Debate.GetStrategyCardCollection(isTaiwu, source);
		short card = sourceList[index];
		sourceList.RemoveAt(index);
		int destination = (isTaiwu ? 2 : 5);
		List<short> destinationList = Debate.GetStrategyCardCollection(isTaiwu, destination);
		destinationList.Add(card);
		Debate.DebateOperations.Add(new DebateOperation(8, source, destination, destinationList.Count - 1, card, Debate.PlayerLeft, Debate.PlayerRight));
	}

	private void DebateGameRemovePlayerCanUseCard(bool isTaiwu, int destination, int index, int offset = 0, bool playAnim = true)
	{
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(isTaiwu);
		List<short> collection = Debate.GetStrategyCardCollection(isTaiwu, destination);
		int source = (isTaiwu ? 2 : 5);
		short card = player.CanUseCards[index + offset];
		player.CanUseCards.RemoveAt(index + offset);
		collection.Add(card);
		if (playAnim)
		{
			Debate.DebateOperations.Add(new DebateOperation(8, source, destination, index, card, Debate.PlayerLeft, Debate.PlayerRight));
		}
	}

	[DomainMethod]
	public LifeSkillCombatBeginDisplayData GetLifeSkillCombatBeginDisplayData(DataContext context, int enemyCharId)
	{
		GameData.Domains.Character.Character taiwu = GetTaiwu();
		GameData.Domains.Character.Character enemyChar = DomainManager.Character.GetElement_Objects(enemyCharId);
		List<int> result = new List<int>(16);
		sbyte i;
		for (i = 0; i < 16; i++)
		{
			List<Config.LifeSkillItem> unlockedSkills = (from s in taiwu.GetLearnedLifeSkills()
				where LifeSkill.Instance[s.SkillTemplateId].Type == i && s.IsAllPagesRead()
				select LifeSkill.Instance[s.SkillTemplateId]).ToList();
			int unlockedCount = 0;
			if (unlockedSkills.Exists(delegate(Config.LifeSkillItem s)
			{
				sbyte grade = s.Grade;
				return grade >= 0 && grade <= 2;
			}))
			{
				unlockedCount |= 1;
			}
			if (unlockedSkills.Exists(delegate(Config.LifeSkillItem s)
			{
				sbyte grade = s.Grade;
				return grade >= 3 && grade <= 5;
			}))
			{
				unlockedCount |= 2;
			}
			if (unlockedSkills.Exists(delegate(Config.LifeSkillItem s)
			{
				sbyte grade = s.Grade;
				return grade >= 6 && grade <= 8;
			}))
			{
				unlockedCount |= 4;
			}
			result.Add(unlockedCount);
		}
		return new LifeSkillCombatBeginDisplayData
		{
			SelfAttainments = taiwu.GetLifeSkillAttainments(),
			EnemyAttainments = enemyChar.GetLifeSkillAttainments(),
			LoopingNeigongId = taiwu.GetLoopingNeigong(),
			CurReadingBook = _curReadingBook,
			CurReadingBookProgress = (sbyte)(_curReadingBook.IsValid() ? GetTotalReadingProgress(_curReadingBook.Id) : 0),
			TotalReadInLifeSkillCombatCount = 1,
			ReadInLifeSkillCombatCount = DomainManager.Extra.GetReadInLifeSkillCombatCount(),
			ReadInCombatCount = DomainManager.Taiwu.GetReadInCombatCount(),
			TotalLoopInLifeSkillCombatCount = 1,
			LoopInLifeSkillCombatCount = DomainManager.Extra.GetLoopInLifeSkillCombatCount(),
			LoopInCombatCount = DomainManager.Extra.GetLoopInCombatCount(),
			UnlockedCountList = result
		};
	}

