	private static void CalcTaiwuDebateSpectators(Location location, List<int> sorted)
	{
		AdventureTaiwu taiwu = DomainManager.Adventure.GetAdventureTaiwu();
		if (taiwu.InAdventure)
		{
			AdventureBlockIndex index = taiwu.Index;
			AdventureRuntime adventure = taiwu.Adventure;
			{
				foreach (AdventureElement element in adventure.GetAllElements())
				{
					if (element.Index.XyEquals(index) && element.CharacterId >= 0)
					{
						sorted.Add(element.CharacterId);
					}
				}
				return;
			}
		}
		int range = DebateConstants.SpectatorPickRange;
		List<MapBlockData> blocks = new List<MapBlockData>();
		DomainManager.Map.GetRealNeighborBlocks(location.AreaId, location.BlockId, blocks, range, includeCenter: true);
		foreach (MapBlockData blockData in blocks)
		{
			if (blockData.CharacterSet == null || blockData.CharacterSet.Count == 0)
			{
				continue;
			}
			foreach (int charId in blockData.CharacterSet)
			{
				sorted.Add(charId);
			}
		}
	}

