	[DomainMethod]
	public DebateGame DebateGameCastStrategy(DataContext context, int index, bool isCastedByTaiwu, List<StrategyTarget> strategyTargets)
	{
		if (isCastedByTaiwu && !Debate.IsTaiwuAi)
		{
			Debate.DebateOperations.Clear();
		}
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(isCastedByTaiwu);
		short templateId = player.CanUseCards[index];
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		int extraCost = 0;
		bool castFailed = DebateGameCheckPressure(context, isCastedByTaiwu, 6);
		Debate.DebateOperations.Add(new DebateOperation(14, isCastedByTaiwu, templateId, Debate.PlayerLeft, Debate.PlayerRight, strategyTargets, castFailed));
		int dest = Debate.GetStrategyCardLocation(isCastedByTaiwu, 7);
		DebateGameRemovePlayerCanUseCard(isCastedByTaiwu, dest, index, 0, !castFailed);
		if (!castFailed)
		{
			if (!isCastedByTaiwu)
			{
				Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu: false, 18, new int[1] { templateId }));
			}
			else
			{
				DomainManager.Taiwu.RecordLifeSummary(context, 40);
			}
			extraCost = ((config.TriggerType != EDebateStrategyTriggerType.Instant) ? (extraCost + DebateGameAddPawnStrategy(isCastedByTaiwu, templateId, strategyTargets)) : (extraCost + DebateGameApplyInstantStrategyEffect(context, index, isCastedByTaiwu, templateId, strategyTargets)));
		}
		DebateGameChangePlayerStrategyPoint(player, -(config.UsedCost + extraCost));
		DebateGameUpdateCanMakeMoveNode();
		if (castFailed)
		{
			DebateGameApplyPressureEffect(isCastedByTaiwu, 6, player.Pressure, templateId);
		}
		_debateCardUsedCount++;
		return Debate;
	}

	private int[] DebateGameGetStrategyRecordParameters(short templateId, List<short> strategyTemplateIds, List<int> pawnIds, List<int> values)
	{
		DebateRecordItem config = DebateRecord.Instance[templateId];
		int[] res = new int[config.Parameters.Length];
		int pawnIdPtr = 0;
		int strategyPtr = 0;
		int valuePtr = 0;
		for (int i = 0; i < config.Parameters.Length; i++)
		{
			int[] array = res;
			int num = i;
			EDebateRecordParamType eDebateRecordParamType = config.Parameters[i];
			if (1 == 0)
			{
			}
			int num2 = eDebateRecordParamType switch
			{
				EDebateRecordParamType.IntValue => Math.Abs(values[valuePtr++]), 
				EDebateRecordParamType.Strategy => strategyTemplateIds[strategyPtr++], 
				EDebateRecordParamType.Pawn => pawnIds[pawnIdPtr++], 
				EDebateRecordParamType.PawnCount => pawnIds.Count, 
				_ => 0, 
			};
			if (1 == 0)
			{
			}
			array[num] = num2;
		}
		return res;
	}

	private void DebateGameAddStrategyRecord(bool isTaiwu, short recordTemplateId, List<short> strategyTemplateIds, List<int> pawnIds, List<int> values)
	{
		Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu, recordTemplateId, DebateGameGetStrategyRecordParameters(recordTemplateId, strategyTemplateIds, pawnIds, values)));
	}

	private bool DebateGameCheckDebateRecord(bool isCastedByTaiwu, short templateId, out bool isPawnCount)
	{
		isPawnCount = false;
		if (!isCastedByTaiwu || templateId < 0)
		{
			return false;
		}
		DebateRecordItem config = DebateRecord.Instance[templateId];
		EDebateRecordParamType[] parameters = config.Parameters;
		foreach (EDebateRecordParamType param in parameters)
		{
			if (param == EDebateRecordParamType.PawnCount)
			{
				isPawnCount = true;
				break;
			}
		}
		return true;
	}

	private void DebateGameDecodeStrategyEffectTargets(List<StrategyTarget> strategyTargets, out List<int> pawnIds, out List<int> cards, out List<IntPair> coordinates, out List<sbyte> pawnGrades)
	{
		pawnIds = null;
		cards = null;
		coordinates = null;
		pawnGrades = null;
		if (strategyTargets == null)
		{
			return;
		}
		foreach (StrategyTarget target in strategyTargets)
		{
			switch (target.Type)
			{
			case EDebateStrategyTargetObjectType.Pawn:
				if (pawnIds == null)
				{
					pawnIds = new List<int>();
				}
				foreach (ulong data3 in target.List)
				{
					pawnIds.Add((int)data3);
				}
				break;
			case EDebateStrategyTargetObjectType.Node:
				if (coordinates == null)
				{
					coordinates = new List<IntPair>();
				}
				foreach (ulong data2 in target.List)
				{
					coordinates.Add((IntPair)data2);
				}
				break;
			case EDebateStrategyTargetObjectType.PawnGrade:
				if (pawnGrades == null)
				{
					pawnGrades = new List<sbyte>();
				}
				foreach (ulong data4 in target.List)
				{
					pawnGrades.Add((sbyte)data4);
				}
				break;
			case EDebateStrategyTargetObjectType.StrategyCard:
				if (cards == null)
				{
					cards = new List<int>();
				}
				foreach (ulong data in target.List)
				{
					int value = (int)data;
					cards.Add(value);
				}
				break;
			}
		}
	}

	private void DebateGameApplyNoTargetInstantStrategyEffect(DataContext context, bool isCastedByTaiwu, short templateId)
	{
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		foreach (IntPair effect in config.EffectList)
		{
			if (!_debateStrategyActions.TryGetValue(effect.First, out var action))
			{
				throw new Exception("Instant Debate Strategy has no effect: " + config.Name);
			}
			DebateStrategyActionParams param = new DebateStrategyActionParams
			{
				Context = context,
				IsCastedByTaiwu = isCastedByTaiwu,
				StrategyTemplateId = templateId,
				Value = effect.Second
			};
			action(param);
		}
	}

	private void DebateGameApplySingleTargetInstantStrategyEffect(DataContext context, int index, bool isCastedByTaiwu, short templateId, List<StrategyTarget> strategyTargets)
	{
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		DebateGameDecodeStrategyEffectTargets(strategyTargets, out var pawnIds, out var cards, out var _, out var _);
		Tester.Assert(pawnIds != null || cards != null);
		Tester.Assert(pawnIds == null || cards == null);
		if (pawnIds != null && DebateGameCheckDebateRecord(isCastedByTaiwu, config.DebateRecord, out var isPawnCount))
		{
			if (isPawnCount)
			{
				List<int> selfPawnIds = null;
				List<int> opponentPawnIds = null;
				foreach (int pawnId in pawnIds)
				{
					if (Debate.Pawns[pawnId].IsOwnedByTaiwu)
					{
						if (selfPawnIds == null)
						{
							selfPawnIds = new List<int>();
						}
						selfPawnIds.Add(pawnId);
					}
					else
					{
						if (opponentPawnIds == null)
						{
							opponentPawnIds = new List<int>();
						}
						opponentPawnIds.Add(pawnId);
					}
				}
				if (selfPawnIds != null)
				{
					DebateGameAddStrategyRecord(isTaiwu: true, config.DebateRecord, new List<short> { config.TemplateId }, selfPawnIds, new List<int> { config.EffectList[0].Second });
				}
				if (opponentPawnIds != null)
				{
					DebateGameAddStrategyRecord(isTaiwu: true, config.DebateRecord, new List<short> { config.TemplateId }, opponentPawnIds, new List<int> { config.EffectList[0].Second });
				}
			}
			else if (config.DebateRecord == 19)
			{
				Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu: true, 19, new int[1] { templateId }));
			}
			else
			{
				foreach (int pawnId2 in pawnIds)
				{
					DebateGameAddStrategyRecord(isTaiwu: true, config.DebateRecord, new List<short> { config.TemplateId }, new List<int> { pawnId2 }, new List<int> { config.EffectList[0].Second });
				}
			}
		}
		foreach (IntPair effect in config.EffectList)
		{
			if (!_debateStrategyActions.TryGetValue(effect.First, out var action))
			{
				throw new Exception("Instant Debate Strategy has no effect: " + config.Name);
			}
			DebateStrategyActionParams param = new DebateStrategyActionParams
			{
				Context = context,
				IsCastedByTaiwu = isCastedByTaiwu,
				UsingCard = index,
				StrategyTemplateId = templateId,
				Value = effect.Second
			};
			if (pawnIds != null)
			{
				foreach (int pawnId3 in pawnIds)
				{
					param.PawnId = pawnId3;
					action(param);
				}
			}
			else
			{
				if (cards == null)
				{
					continue;
				}
				cards.Sort();
				cards.Reverse();
				foreach (int card in cards)
				{
					param.Card = card;
					action(param);
				}
			}
		}
	}

	private void DebateGameApplyMultipleTargetInstantStrategyEffect(DataContext context, bool isCastedByTaiwu, short templateId, List<StrategyTarget> strategyTargets)
	{
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		Tester.Assert(config.EffectList.Count == 1);
		IntPair effect = config.EffectList[0];
		if (!_debateStrategyActions.TryGetValue(effect.First, out var action))
		{
			throw new Exception("Instant Debate Strategy has no effect: " + config.Name);
		}
		DebateGameDecodeStrategyEffectTargets(strategyTargets, out var pawnIds, out var _, out var coordinates, out var pawnGrades);
		DebateStrategyActionParams param = new DebateStrategyActionParams
		{
			Context = context,
			IsCastedByTaiwu = isCastedByTaiwu,
			StrategyTemplateId = templateId,
			Value = effect.Second
		};
		switch (effect.First)
		{
		case 1:
			param.Grade = pawnGrades[0];
			param.Coordinate = coordinates[0];
			action(param);
			pawnIds = new List<int> { Debate.DebateGrid[coordinates[0]].PawnId };
			break;
		case 2:
		case 36:
		case 39:
			param.PawnId = pawnIds[0];
			param.PawnId2 = pawnIds[1];
			action(param);
			break;
		case 3:
			param.PawnId = pawnIds[0];
			param.Coordinate = coordinates[0];
			action(param);
			break;
		}
		if (isCastedByTaiwu && config.DebateRecord >= 0)
		{
			DebateGameAddStrategyRecord(isTaiwu: true, config.DebateRecord, new List<short> { config.TemplateId }, pawnIds, new List<int> { config.EffectList[0].Second });
		}
	}

	public int DebateGameApplyInstantStrategyEffect(DataContext context, int index, bool isCastedByTaiwu, short templateId, List<StrategyTarget> strategyTargets)
	{
		int cost = 0;
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		if (config.EffectList == null || config.EffectList.Count == 0)
		{
			return cost;
		}
		if (config.TargetList == null || config.TargetList.Count == 0)
		{
			DebateGameApplyNoTargetInstantStrategyEffect(context, isCastedByTaiwu, templateId);
		}
		else
		{
			if (config.TargetList.Count == 1)
			{
				DebateGameApplySingleTargetInstantStrategyEffect(context, index, isCastedByTaiwu, templateId, strategyTargets);
			}
			else
			{
				DebateGameApplyMultipleTargetInstantStrategyEffect(context, isCastedByTaiwu, templateId, strategyTargets);
			}
			foreach (StrategyTarget target in strategyTargets)
			{
				if (target.Type != EDebateStrategyTargetObjectType.Pawn)
				{
					continue;
				}
				foreach (ulong data in target.List)
				{
					int pawnId = (int)data;
					List<DebateGame.EffectItem> list = new List<DebateGame.EffectItem>();
					if (Debate.TryGetPawnStrategyEffectValue(pawnId, 28, out var value, list))
					{
						cost += value;
						DebateGameAddStrategyRecord(isCastedByTaiwu, 55, new List<short>
						{
							list[0].StrategyTemplateId,
							templateId
						}, new List<int> { pawnId }, new List<int> { value });
					}
				}
			}
		}
		return cost;
	}

	private int DebateGameAddPawnStrategy(bool isCastedByTaiwu, short templateId, List<StrategyTarget> strategyTargets)
	{
		int extraCost = 0;
		DebateStrategyItem config = DebateStrategy.Instance[templateId];
		foreach (StrategyTarget target in strategyTargets)
		{
			Tester.Assert(target.Type == EDebateStrategyTargetObjectType.Pawn);
			Tester.Assert(target.List.Count != 0);
			foreach (ulong data in target.List)
			{
				int pawnId = (int)data;
				List<DebateGame.EffectItem> list = new List<DebateGame.EffectItem>();
				if (Debate.TryGetPawnStrategyEffectValue(pawnId, 28, out var value, list))
				{
					extraCost += value;
					DebateGameAddStrategyRecord(isCastedByTaiwu, 55, new List<short>
					{
						list[0].StrategyTemplateId,
						templateId
					}, new List<int> { pawnId }, new List<int> { value });
				}
			}
		}
		foreach (StrategyTarget target2 in strategyTargets)
		{
			foreach (ulong data2 in target2.List)
			{
				int pawnId2 = (int)data2;
				if (isCastedByTaiwu && config.TriggerType == EDebateStrategyTriggerType.Invalid && config.DebateRecord >= 0)
				{
					DebateGameAddStrategyRecord(isTaiwu: true, config.DebateRecord, new List<short> { config.TemplateId }, new List<int> { pawnId2 }, new List<int> { config.EffectList[0].Second });
				}
				DebateGameAddStrategy(pawnId2, templateId, isCastedByTaiwu);
			}
		}
		if (isCastedByTaiwu && config.TriggerType != EDebateStrategyTriggerType.Invalid)
		{
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu: true, 19, new int[1] { templateId }));
		}
		return extraCost;
	}

	private void DebateGameApplyPawnStrategyEffectByTriggerType(DataContext context, int pawnId, EDebateStrategyTriggerType type)
	{
		Pawn pawn = Debate.Pawns[pawnId];
		pawn.ResetStrategyValue();
		int[] strategies = pawn.Strategies;
		foreach (int strategyId in strategies)
		{
			if (strategyId >= 0 && Debate.ActivatedStrategies.TryGetValue(strategyId, out var strategy) && strategy.GetTriggerType() == type)
			{
				DebateGameApplyTriggeredStrategyEffect(context, strategy);
			}
		}
	}

	private void DebateGameApplyTriggeredStrategyEffect(DataContext context, ActivatedStrategy strategy)
	{
		DebateStrategyItem config = strategy.GetConfig();
		int index = -1;
		Pawn pawn = Debate.Pawns[strategy.PawnId];
		int[] strategies = pawn.Strategies;
		for (int i = 0; i < strategies.Length; i++)
		{
			if (strategies[i] == index)
			{
				index = i;
				break;
			}
		}
		Debate.DebateOperations.Add(new DebateOperation(7, strategy.PawnId, strategy.Id, Debate.PlayerLeft, Debate.PlayerRight));
		if (config.EffectList != null && config.EffectList.Count != 0)
		{
			foreach (IntPair effect in config.EffectList)
			{
				if (_debateStrategyActions.TryGetValue(effect.First, out var action))
				{
					DebateStrategyActionParams param = new DebateStrategyActionParams
					{
						Context = context,
						IsCastedByTaiwu = strategy.IsCastedByTaiwu,
						StrategyTemplateId = strategy.TemplateId,
						PawnId = strategy.PawnId,
						Value = effect.Second
					};
					action(param);
				}
			}
			if (config.DebateRecord >= 0)
			{
				DebateGameAddStrategyRecord(pawn.IsOwnedByTaiwu, config.DebateRecord, new List<short> { config.TemplateId }, new List<int> { strategy.PawnId }, new List<int> { config.EffectList[0].Second });
			}
		}
		if (config.IsOneTime)
		{
			_oneTimeStrategyActionList.Add(Action);
		}
		void Action()
		{
			Debate.DebateOperations.Add(new DebateOperation(12, strategy.PawnId, index, Debate.PlayerLeft, Debate.PlayerRight));
			DebateGameRemoveStrategy(strategy.Id, pawn.IsOwnedByTaiwu);
		}
	}

