	private void DebateGameApplyDrawCardInOwned(DebateStrategyActionParams param)
	{
		int selfCount = 0;
		int opponentCount = 0;
		for (int i = 0; i < param.Value; i++)
		{
			bool isTaiwu = !param.IsCastedByTaiwu;
			List<int> collection;
			int location = Debate.TryGetStrategyCardIndexCollection(ref isTaiwu, 6, out collection);
			if (location == -1)
			{
				continue;
			}
			DebateGameAddPlayerCanUseCard(param.IsCastedByTaiwu, location, collection[(collection.Count != 1) ? param.Context.Random.Next(collection.Count) : 0]);
			if (param.IsCastedByTaiwu)
			{
				if (isTaiwu)
				{
					selfCount++;
				}
				else
				{
					opponentCount++;
				}
			}
		}
		if (selfCount > 0)
		{
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu: true, DebateStrategy.Instance[param.StrategyTemplateId].DebateRecord, new int[3] { param.StrategyTemplateId, 0, selfCount }));
		}
		if (opponentCount > 0)
		{
			Debate.DebateOperations.Add(new DebateOperation(20, isTaiwu: true, DebateStrategy.Instance[param.StrategyTemplateId].DebateRecord, new int[3] { param.StrategyTemplateId, 1, opponentCount }));
		}
	}

