	private void DebateGameApplySplitPawn(DebateStrategyActionParams param)
	{
		Pawn pawn = Debate.Pawns[param.PawnId];
		int bases = Debate.GetPawnBases(param.PawnId);
		if (!pawn.IsAlive)
		{
			return;
		}
		List<IntPair> coordinates = new List<IntPair>();
		if (!Debate.TryGetEmptyNode(pawn.IsOwnedByTaiwu, coordinates) && Debate.DebateGrid[pawn.Coordinate].IsVantage != pawn.IsOwnedByTaiwu)
		{
			return;
		}
		DebateGameSetPawnDead(param.Context, param.PawnId, 2, param.IsCastedByTaiwu);
		Debate.TryGetEmptyNode(pawn.IsOwnedByTaiwu, coordinates);
		int count = Math.Min(coordinates.Count, param.Value);
		bases /= count;
		for (int i = 0; i < count; i++)
		{
			if (!Debate.TryGetEmptyNode(pawn.IsOwnedByTaiwu, coordinates))
			{
				break;
			}
			CollectionUtils.Shuffle(param.Context.Random, coordinates);
			DebateGameAddPawn(param.Context, coordinates[0], pawn.IsOwnedByTaiwu, 0, bases);
		}
	}

