	{
		DebatePlayer player = Debate.GetPlayerByPlayerIsTaiwu(param.IsCastedByTaiwu);
		int offset = ((param.Card > param.UsingCard) ? (-1) : 0);
		short card = player.CanUseCards[param.Card + offset];
		sbyte cost = DebateStrategy.Instance[card].UsedCost;
		DebateGameChangePlayerStrategyPoint(player, cost);
		DebateGameRemovePlayerCanUseCard(param.IsCastedByTaiwu, Debate.GetStrategyCardLocation(param.IsCastedByTaiwu, 7), param.Card, offset);
