	private void DebateGameApplyExchangeStrategy(DebateStrategyActionParams param)
	{
		Pawn pawn1 = Debate.Pawns[param.PawnId];
		Pawn pawn2 = Debate.Pawns[param.PawnId2];
		bool changeOwner = pawn1.IsOwnedByTaiwu != pawn2.IsOwnedByTaiwu;
		for (int i = 0; i < DebateConstants.PawnStrategyLimit; i++)
		{
			int strategyId1 = pawn1.Strategies[i];
			int strategyId2 = pawn2.Strategies[i];
			if ((strategyId1 < 0 || !Debate.ActivatedStrategies[strategyId1].GetIsInertia()) && (strategyId2 < 0 || !Debate.ActivatedStrategies[strategyId2].GetIsInertia()))
			{
				if (strategyId1 >= 0)
				{
					Debate.DebateOperations.Add(new DebateOperation(13, pawn1.Id, i, Debate.PlayerLeft, Debate.PlayerRight, param.IsCastedByTaiwu));
				}
				if (strategyId2 >= 0)
				{
					Debate.DebateOperations.Add(new DebateOperation(13, pawn2.Id, i, Debate.PlayerLeft, Debate.PlayerRight, param.IsCastedByTaiwu));
				}
			}
		}
		for (int j = 0; j < DebateConstants.PawnStrategyLimit; j++)
		{
			int strategyId3 = pawn1.Strategies[j];
			int strategyId4 = pawn2.Strategies[j];
			if ((strategyId3 < 0 || !Debate.ActivatedStrategies[strategyId3].GetIsInertia()) && (strategyId4 < 0 || !Debate.ActivatedStrategies[strategyId4].GetIsInertia()))
			{
				if (strategyId4 >= 0)
				{
					Debate.DebateOperations.Add(new DebateOperation(6, pawn1.Id, j, Debate.PlayerLeft, Debate.PlayerRight));
				}
				if (strategyId3 >= 0)
				{
					Debate.DebateOperations.Add(new DebateOperation(6, pawn2.Id, j, Debate.PlayerLeft, Debate.PlayerRight));
				}
			}
		}
		for (int k = 0; k < DebateConstants.PawnStrategyLimit; k++)
		{
			int strategyId5 = pawn1.Strategies[k];
			int strategyId6 = pawn2.Strategies[k];
			if ((strategyId5 < 0 || !Debate.ActivatedStrategies[strategyId5].GetIsInertia()) && (strategyId6 < 0 || !Debate.ActivatedStrategies[strategyId6].GetIsInertia()))
			{
				DebateGameChangePawnStrategy(param.PawnId, strategyId6, k, changeOwner);
				DebateGameChangePawnStrategy(param.PawnId2, strategyId5, k, changeOwner);
			}
		}
	}

	private void DebateGameApplyTeleportToBottom(DebateStrategyActionParams param)
	{
		Pawn pawn = Debate.Pawns[param.PawnId];
		if (!pawn.IsAlive || !Debate.GetCoordinateValid(pawn.Coordinate))
		{
			return;
		}
		int spectatorId = param.NodeEffect.CasterId;
		bool isHelpTaiwu = DebateGameGetSpectatorHelpTaiwu(param.Context, spectatorId, pawn.IsOwnedByTaiwu);
		int direction = ((!isHelpTaiwu) ? 1 : (-1));
		int targetX = Debate.GetStartCoordinate(!isHelpTaiwu) + direction;
		int targetY = -1;
		for (int y = 0; y < DebateConstants.DebateLineCount; y++)
		{
			if (Debate.DebateGrid[new IntPair(targetX, y)].PawnId < 0 && (targetY < 0 || !param.Context.Random.NextBool()))
			{
				targetY = y;
			}
		}
		IntPair coordinate = new IntPair(targetX, targetY);
		if (Debate.GetCoordinateValid(coordinate))
		{
			DebateGameSetPawnCoordinate(param.Context, pawn.Id, coordinate);
		}
	}

	private void DebateGameApplyDamageMoreByNode(DebateStrategyActionParams param)
	{
		Debate.Pawns[param.PawnId].NodeDamage = param.Value;
	}

