	private List<ItemDisplayData> GetResourcesItems(ResourceInts resources, ItemSourceType itemSourceType)
	{
		List<ItemDisplayData> resourceItemList = new List<ItemDisplayData>();
		for (int type = 0; type < 8; type++)
		{
			int amount = resources[type];
			if (amount > 0)
			{
				short templateId = Convert.ToInt16(type);
				ItemKey itemKey = new ItemKey(12, 0, templateId, 0);
				ItemDisplayData itemData = new ItemDisplayData
				{
					Key = itemKey,
					Amount = amount,
					ItemSourceType = (sbyte)itemSourceType
				};
				resourceItemList.Add(itemData);
			}
		}
		return resourceItemList;
	}

	[DomainMethod]
	public (ItemSourceType itemSourceType, List<ItemDisplayData> list) GetAllItems(ItemSourceType itemSourceType, bool includeResources = false)
	{
		if (itemSourceType == ItemSourceType.Resources)
		{
			List<ItemDisplayData> resourcesItemDataList = GetResourcesItems(GetTaiwu().GetResources(), ItemSourceType.Resources);
			return (itemSourceType: itemSourceType, list: resourcesItemDataList);
		}
		List<ItemDisplayData> list = CharacterDomain.GetItemDisplayData(GetTaiwuCharId(), GetItems(itemSourceType), itemSourceType);
		if (includeResources)
		{
			ResourceInts resources = GetTaiwuVillageResources(itemSourceType);
			List<ItemDisplayData> resourcesItemDataList2 = GetResourcesItems(resources, itemSourceType);
			list.AddRange(resourcesItemDataList2);
		}
		return (itemSourceType: itemSourceType, list: list);
	}

