	[DomainMethod]
	public TaiwuResourceDisplayData RequestTaiwuResourceDisplayData()
	{
		int workingAdultCount = 0;
		int assignedAdultCount = 0;
		int workingChildCount = 0;
		int assignedChildCount = 0;
		foreach (int charId in from key in DomainManager.Organization.GetElement_CivilianSettlements(_taiwuVillageSettlementId).GetMembers()
			where _villagerWork.ContainsKey(key)
			select key)
		{
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			(bool, bool) tuple = (character.GetPhysiologicalAge() < 16, _villagerWork[charId].WorkType < 10);
			(bool, bool) tuple2 = tuple;
			if (tuple2.Item1)
			{
				if (tuple2.Item2)
				{
					workingChildCount++;
				}
				else
				{
					assignedChildCount++;
				}
			}
			else if (tuple2.Item2)
			{
				workingAdultCount++;
			}
			else
			{
				assignedAdultCount++;
			}
		}
		short areaId = GetTaiwu()?.GetLocation().AreaId ?? (-1);
		ResourceInts resourceTotal = new ResourceInts(default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int), default(int));
		resourceTotal.Add(ref GetTaiwu().GetResources());
		resourceTotal.Add(ref GetTaiwuTreasury().Resources);
		return new TaiwuResourceDisplayData
		{
			Resources = resourceTotal.ToArray(),
			ResourcesDelta = GetResourceChange(),
			Villager = GetTotalVillagerCount(),
			IdleVillager = GetAvailableVillagerCount(),
			AreaId = areaId,
			Debt = DomainManager.Extra.GetAreaSpiritualDebt(areaId),
			Exp = (GetTaiwu()?.GetExp() ?? 0),
			TaiwuPopulationTipsAdult = GetTotalAdultVillagerCount(),
			TaiwuPopulationTipsAdultWorking = workingAdultCount,
			TaiwuPopulationTipsAdultAssign = assignedAdultCount,
			TaiwuPopulationTipsChildWorking = workingChildCount,
			TaiwuPopulationTipsInJail = DomainManager.Extra.GetStoneRoomCharList().Count
		};
	}

