	[DomainMethod]
	public void SwitchEquipmentPlan(DataContext context, int planId)
	{
		EquipmentPlan oriPlan = _equipmentsPlans[_currEquipmentPlanId];
		oriPlan.Record(_taiwuChar);
		SetElement_EquipmentsPlans(_currEquipmentPlanId, oriPlan, context);
		EquipmentPlan currPlan = _equipmentsPlans[planId];
		currPlan.Apply(context, _taiwuChar, skipInvalid: false);
		currPlan.Record(_taiwuChar);
		SetElement_EquipmentsPlans(planId, currPlan, context);
		SetCurrEquipmentPlanId(planId, context);
	}

	public bool CheckItemIsInEquipmentPlan(ItemKey itemKey)
	{
		int planIndex;
		int slotIndex;
		return FindItemInEquipmentPlan(itemKey, out planIndex, out slotIndex);
	}

	public bool FindItemInEquipmentPlan(ItemKey itemKey, out int planIndex, out int slotIndex)
	{
		planIndex = -1;
		slotIndex = -1;
		if (!ItemType.IsEquipmentItemType(itemKey.ItemType))
		{
			return false;
		}
		for (int i = 0; i < _equipmentsPlans.Length; i++)
		{
			if (i == _currEquipmentPlanId)
			{
				continue;
			}
			EquipmentPlan plan = _equipmentsPlans[i];
			for (int j = 0; j < plan.Slots.Length; j++)
			{
				ItemKey key = plan.Slots[j];
				if (key.Equals(itemKey))
				{
					planIndex = i;
					slotIndex = j;
					return true;
				}
			}
		}
		return false;
	}

	public void SetEquipmentPlan(DataContext context, ItemKey itemKey, int planIndex, int slotIndex)
	{
		if (_equipmentsPlans.CheckIndex(planIndex))
		{
			EquipmentPlan plan = GetElement_EquipmentsPlans(planIndex);
			if (plan.Slots.CheckIndex(slotIndex))
			{
				plan.Slots[slotIndex] = itemKey;
				SetElement_EquipmentsPlans(planIndex, plan, context);
			}
		}
	}

	public void ReCalcAllEquipment(DataContext context)
	{
		ItemKey[] equipmentArray = _taiwuChar.GetEquipment();
		ItemKey[] array = equipmentArray;
		for (int i = 0; i < array.Length; i++)
		{
			ItemKey equipment = array[i];
			if (equipment.IsValid())
			{
				UpdateEquipment(equipment);
			}
		}
		_taiwuChar.SetEquipment(equipmentArray, context);
		Inventory inventory = _taiwuChar.GetInventory();
		if (UpdateEquipmentsInDictionary(inventory.Items))
		{
			_taiwuChar.SetInventory(inventory, context);
		}
		if (UpdateEquipmentsInDictionary(_warehouse.Items))
		{
			SetWarehouse(_warehouse, context);
		}
		bool UpdateEquipment(ItemKey itemKey)
		{
			if (ItemTemplateHelper.IsRefinable(itemKey.ItemType, itemKey.TemplateId) && ModificationStateHelper.IsActive(itemKey.ModificationState, 2))
			{
				EquipmentBase baseEquipment = DomainManager.Item.GetBaseEquipment(itemKey);
				baseEquipment.SetModificationState(baseEquipment.GetModificationState(), context);
				return true;
			}
			return false;
		}
		bool UpdateEquipmentsInDictionary(Dictionary<ItemKey, int> items)
		{
			bool elementModified = false;
			foreach (var (itemKey2, amount) in items)
			{
				if (UpdateEquipment(itemKey2))
				{
					elementModified = true;
				}
			}
			return elementModified;
		}
	}

