			{
				SupplyLevel = settlement.GetSupplyLevel(),
				DebtOrSupport = (Config.Organization.Instance[settlement.GetOrgTemplateId()].IsSect ? settlement.CalcApprovingRate() : DomainManager.Extra.GetAreaSpiritualDebt(settlement.GetLocation().AreaId)),
				Treasuries = new List<SettlementTreasury>()
			};
			AddTreasuryData(0, out data.TreasuryData.SettlementTreasuryDisplayDataListLow, out data.TreasuryData.SettlementGuardDisplayDataListLow);
			AddTreasuryData(1, out data.TreasuryData.SettlementTreasuryDisplayDataListMid, out data.TreasuryData.SettlementGuardDisplayDataListMid);
			AddTreasuryData(2, out data.TreasuryData.SettlementTreasuryDisplayDataListHigh, out data.TreasuryData.SettlementGuardDisplayDataListHigh);
			break;
		}
		case EExchangeType.Shop:
			throw new Exception("EExchangeType.Shop returns ShopDisplayData, which cannot be used here.");
		case EExchangeType.Warehouse:
		{
			InitTaiwuLoad(data.Exchange = new Exchange(exchangeType, targetId, null), GetTaiwu());
			data.Exchange.TargetCurLoad = DomainManager.Taiwu.CalcTroughCurrLoad();
			data.Exchange.TargetMaxLoad = DomainManager.Taiwu.CalcTroughMaxLoad();
			IEnumerable<ItemDisplayData> enumerable = data?.TaiwuInventoryItemDisplayDataList;
			IEnumerable<ItemDisplayData> first = enumerable ?? Enumerable.Empty<ItemDisplayData>();
			enumerable = data?.TaiwuStockItemDisplayDataList;
			IEnumerable<ItemDisplayData> first2 = first.Concat(enumerable ?? Enumerable.Empty<ItemDisplayData>());
			enumerable = data?.TaiwuTreasuryItemDisplayDataList;
			IEnumerable<ItemDisplayData> first3 = first2.Concat(enumerable ?? Enumerable.Empty<ItemDisplayData>());
			enumerable = data?.TaiwuTroughItemDisplayDataList;
			IEnumerable<ItemDisplayData> first4 = first3.Concat(enumerable ?? Enumerable.Empty<ItemDisplayData>());
			enumerable = data?.TaiwuWarehouseItemDisplayDataList;
			foreach (ItemDisplayData item in first4.Concat(enumerable ?? Enumerable.Empty<ItemDisplayData>()))
			{
				item.Value = data.Exchange.CalcBaseValue(item);
			}
			break;
		}
		default:
			throw new ArgumentOutOfRangeException("exchangeType", exchangeType, null);
		}
		data.Exchange.TaiwuCharId = _taiwuCharId;
		return data;
	}

	[DomainMethod]
	public ShopDisplayData GetShopDisplayData(DataContext context, OpenShopEventArguments arg)
	{
		bool cap3Enabled = DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(63);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		ShopDisplayData data = new ShopDisplayData
		{
			TaiwuInventoryItemDisplayDataList = DomainManager.Character.GetAllItems(taiwuCharId, includeResource: false, includeEquipment: true),
			TaiwuWarehouseItemDisplayDataList = GetAllWarehouseItems(context),
			TaiwuTreasuryItemDisplayDataList = GetAllItems(ItemSourceType.Treasury).list,
			TaiwuStockItemDisplayDataList = GetAllItems(ItemSourceType.Stock).list,
			CanTransferItemToWarehouse = CanTransferItemToWarehouse(context),
			TaiwuDisplayData = DomainManager.Character.GetCharacterDisplayData(taiwuCharId)
		};
		GameData.Domains.Character.Character taiwuChar = GetTaiwu();
		data.Exchange = new ShopExchange
		{
			TradeArguments = new MerchantTradeArguments
			{
				TradeMoneySources = new Dictionary<ItemKey, long>(),
				BuyMoney = 0L,
				SoldMoney = 0L,
				ItemChangeList = new List<ItemSourceChange>(),
				OpenShopEventArguments = arg
			},
			ExtraGoodsData = DomainManager.Extra.GetMerchantExtraGoods(arg.Id),
			MerchantCharData = ((arg != null && !arg.IsCaravan && !arg.IsFromBuilding && !arg.IsSpecialBuilding && !arg.IsSettlementTreasury) ? DomainManager.Character.GetCharacterDisplayData(arg.Id) : null),
			TaiwuCharId = _taiwuCharId
		};
		InitTaiwuLoad(data.Exchange, taiwuChar);
		if (arg.IsCaravan)
		{
			ProcessMerchantData(DomainManager.Merchant.GetCaravanMerchantData(context, data.Exchange.CharId = arg.Id));
		}
		else if (arg.IsFromBuilding)
		{
			data.Exchange.CharId = GameData.Domains.Merchant.SharedMethods.GetBuildingMerchantCaravanId(arg.BuildingMerchantType, arg.IsHeadBuildingMerchant);
			ProcessMerchantData(DomainManager.Merchant.GetBuildingMerchantData(context, arg.BuildingMerchantType, arg.IsHeadBuildingMerchant));
		}
		else if (arg.IsSpecialBuilding)
		{
			data.Exchange.CharId = GameData.Domains.Merchant.SharedMethods.GetBuildingMerchantCaravanId(arg.BuildingMerchantType, arg.IsHeadBuildingMerchant);
			ProcessMerchantData(DomainManager.Merchant.GetSectStorySpecialMerchantData(context).MerchantData);
		}
		else
		{
			ProcessMerchantData(DomainManager.Merchant.GetMerchantData(context, data.Exchange.CharId = arg.Id));
			data.Exchange.MerchantCharData = DomainManager.Character.GetCharacterDisplayData(arg.Id);
		}
		MarkSellPrice(data.TaiwuInventoryItemDisplayDataList);
		MarkSource(data.TaiwuWarehouseItemDisplayDataList, ItemSourceType.Warehouse);
		MarkSource(data.TaiwuTreasuryItemDisplayDataList, ItemSourceType.Treasury);
		bool isDebtShop = data.Exchange.MerchantData.MerchantTemplateId == 53;
		data.Exchange.TaiwuValueBase = (isDebtShop ? DomainManager.Extra.GetAreaSpiritualDebt(taiwuChar.GetLocation().AreaId) : taiwuChar.GetResource(6));
		data.Exchange.TargetValueBase = ((!isDebtShop) ? data.Exchange.MerchantData.Money : 0);
		data.Exchange.MerchantOverFavorData = (data.Exchange.TradeArguments.OverFavorData = DomainManager.Extra.GetMerchantOverFavorData(data.Exchange.MerchantData.MerchantType));
		return data;
		List<ItemDisplayData> GetItemList(Inventory inventory)
		{
			return (from item in DomainManager.Item.GetItemDisplayDataListOptionalFromInventory(inventory, -1, -1)?.Select(delegate(ItemDisplayData item)
				{
					item.ExtraGoodsType = (sbyte)(ModificationStateHelper.IsActive(DomainManager.Item.GetBaseItem(item.Key).GetModificationState(), 8) ? ((sbyte)DomainManager.Extra.GetExtraGoodsType(item.Key)) : 0);
					return item;
				})
				where cap3Enabled || item.ExtraGoodsType != 2
				select item).ToList() ?? new List<ItemDisplayData>();
		}
		void MarkSellPrice(IReadOnlyList<ItemDisplayData> source)
		{
			foreach (ItemDisplayData item in source)
			{
				item.Value = data.Exchange.GetItemPrice(item, isBuy: false);
			}
		}
		void MarkSource(IReadOnlyList<ItemDisplayData> source, ItemSourceType sourceType, int seasonTemplateId = int.MinValue)
		{
			foreach (ItemDisplayData item in source)
			{
				item.ItemSourceType = (sbyte)sourceType;
				if (seasonTemplateId != int.MinValue)
				{
					item.SpecialArg = seasonTemplateId;
				}
			}
			if (sourceType == ItemSourceType.BuyBack)
			{
				foreach (ItemDisplayData item2 in source)
				{
					item2.Value = data.Exchange.TradeArguments.MerchantBuyBackData.BuyInPrice[item2.Key];
				}
				return;
			}
			foreach (ItemDisplayData item3 in source)
			{
				item3.Value = data.Exchange.GetItemPrice(item3, ShopExchange.IsShopItem(sourceType));
			}
		}
		void ProcessMerchantData(MerchantData merchantData)
		{
			sbyte season = TimeKit.GetCurrSeason();
			data.Exchange.TradeArguments.MerchantData = merchantData;
			MarkSource(data.TargetItemDisplayData0 = GetItemList(merchantData.GoodsList0), ItemSourceType.Shop0, season);
			MarkSource(data.TargetItemDisplayData1 = GetItemList(merchantData.GoodsList1), ItemSourceType.Shop1, season);
			MarkSource(data.TargetItemDisplayData2 = GetItemList(merchantData.GoodsList2), ItemSourceType.Shop2, season);
			MarkSource(data.TargetItemDisplayData3 = GetItemList(merchantData.GoodsList3), ItemSourceType.Shop3, season);
			MarkSource(data.TargetItemDisplayData4 = GetItemList(merchantData.GoodsList4), ItemSourceType.Shop4, season);
			MarkSource(data.TargetItemDisplayData5 = GetItemList(merchantData.GoodsList5), ItemSourceType.Shop5, season);
			MarkSource(data.TargetItemDisplayData6 = GetItemList(merchantData.GoodsList6), ItemSourceType.Shop6, season);
			MarkSource(data.BuyBackDisplayData = GetItemList((data.Exchange.TradeArguments.MerchantBuyBackData = DomainManager.Merchant.GetMerchantBuyBackData(arg))?.BuyInGoodsList), ItemSourceType.BuyBack);
			long value = default(long);
			foreach (ItemDisplayData item in data.BuyBackDisplayData)
			{
				if (data.Exchange.TradeArguments.MerchantBuyBackData?.BuyInPrice?.TryGetValue(item.Key, out value) == true)
				{
					item.Value = value;
				}
			}
			int[] merchantFavorabilities = DomainManager.Merchant.GetMerchantFavorability();
			data.Exchange.CumulativeMoney = (merchantFavorabilities.CheckIndex(merchantData.MerchantType) ? merchantFavorabilities[merchantData.MerchantType] : 0);
			WriteTaiwuProperties(data.TargetItemDisplayData0);
			WriteTaiwuProperties(data.TargetItemDisplayData1);
			WriteTaiwuProperties(data.TargetItemDisplayData2);
			WriteTaiwuProperties(data.TargetItemDisplayData3);
			WriteTaiwuProperties(data.TargetItemDisplayData4);
			WriteTaiwuProperties(data.TargetItemDisplayData5);
			WriteTaiwuProperties(data.TargetItemDisplayData6);
			WriteTaiwuProperties(data.BuyBackDisplayData);
		}
	}

	[DomainMethod]
	public void ConfirmExchange(DataContext context, Exchange exchange)
	{
		exchange.PrepareConfirmExchange();
		switch (exchange.EExchangeTypeEnum)
		{
		case EExchangeType.Person:
			ConfirmPersonExchange(context, exchange);
			break;
		case EExchangeType.BookSect:
		case EExchangeType.BookPriv:
			ConfirmBookExchange(context, exchange);
			break;
		case EExchangeType.Settlement:
			ConfirmSettlementExchange(context, exchange);
			break;
		case EExchangeType.Shop:
			throw new Exception("Shop cannot be submitted directly");
		case EExchangeType.Warehouse:
			ConfirmWarehouseExchange(context, exchange);
			break;
		default:
			throw new ArgumentOutOfRangeException();
		}
	}

	[DomainMethod]
	public void ConfirmShopExchange(DataContext context, ShopExchange exchange)
	{
		exchange.PrepareConfirmExchange();
		if (exchange.IsGift)
		{
			DomainManager.Merchant.ChangeMerchantCumulativeMoney(context, exchange.MerchantData.MerchantType, (int)Math.Min(2147483647L, exchange.BuyMoney));
			exchange.RefreshGiftDebt();
			DomainManager.Extra.SetMerchantOverFavorData(context, exchange.MerchantData.MerchantType, exchange.TradeArguments.OverFavorData);
			foreach (ExchangeItem exchanged in exchange.ExchangeItemList)
			{
				foreach (var (key, value) in exchanged.Inventory.Items)
				{
					DomainManager.Taiwu.RemoveItem(context, key, value, exchanged.Content.ItemSourceType, deleteItem: true);
				}
			}
			exchange.Clear();
		}
		else
		{
			exchange.Deal();
			DomainManager.Merchant.SettleTrade(context, exchange.TradeArguments);
		}
	}

	private void ConfirmPersonExchange(DataContext context, Exchange exchange)
	{
		ExchangeAdvantage advantageSummary = exchange.AdvantageSummary;
		if (advantageSummary != null && advantageSummary.DebtUsed > 0)
		{
			DomainManager.Extra.ChangeAreaSpiritualDebt(context, (short)exchange.AdvantageSummary.TradeAreaId, -exchange.AdvantageSummary.DebtUsed, getProfessionSeniority: false);
		}
		ExchangeAdvantage advantageSummary2 = exchange.AdvantageSummary;
		if (advantageSummary2 != null && advantageSummary2.SecretId >= 0)
		{
			EventHelper.CostSecretInformationUsedCount(_taiwuCharId, exchange.AdvantageSummary.SecretId);
		}
		GameData.Domains.Character.Character targetChar = DomainManager.Character.GetElement_Objects(exchange.CharId);
		foreach (ExchangeItem exchangeItem in exchange.ExchangeItemList)
		{
			switch (exchangeItem.TypeEnum)
			{
			case ExchangeItem.EExchangeItemType.Item:
				if (exchangeItem.Count > 0)
				{
					if (exchangeItem.ItemData.IsResource)
					{
						sbyte resourceType = exchangeItem.ItemData.ResourceType;
						targetChar.ChangeResource(context, resourceType, -exchangeItem.Count);
						DomainManager.Taiwu.AddResource(context, (exchange.ToItemSourceTypeEnum == ItemSourceType.Treasury) ? ItemSourceType.Treasury : ItemSourceType.Resources, resourceType, exchangeItem.Count);
					}
					else
					{
						targetChar.RemoveInventoryItem(context, exchangeItem.Inventory, deleteItem: false);
						DomainManager.Taiwu.AddItem(context, exchangeItem.Inventory, exchangeItem.ItemData.ItemSourceTypeEnum);
					}
				}
				else if (exchangeItem.Count < 0)
				{
					if (exchangeItem.ItemData.IsResource)
					{
						sbyte resourceType2 = exchangeItem.ItemData.ResourceType;
						targetChar.ChangeResource(context, resourceType2, -exchangeItem.Count);
						DomainManager.Taiwu.RemoveResource(context, exchangeItem.ItemData.ItemSourceTypeEnum, resourceType2, -exchangeItem.Count);
					}
					else
					{
						DomainManager.Taiwu.RemoveItem(context, exchangeItem.Inventory, exchangeItem.ItemData.ItemSourceTypeEnum, deleteItem: false);
						targetChar.AddInventoryItem(context, exchangeItem.Inventory);
					}
				}
				break;
			case ExchangeItem.EExchangeItemType.Kidnap:
				if (exchangeItem.Count > 0)
				{
					KidnappedCharacterList kidnappedCharacterList = DomainManager.Character.GetKidnappedCharacters(exchange.CharId);
					KidnappedCharacter kidnappedCharacter = kidnappedCharacterList.GetCollection().Find((KidnappedCharacter k) => k.CharId == exchangeItem.KidnapCharDisplayData.CharacterId);
					DomainManager.Character.TransferKidnappedCharacter(context, _taiwuCharId, exchange.CharId, kidnappedCharacter);
				}
				else if (exchangeItem.Count < 0)
				{
					KidnappedCharacterList kidnappedCharacterList2 = DomainManager.Character.GetKidnappedCharacters(_taiwuCharId);
					KidnappedCharacter kidnappedCharacter2 = kidnappedCharacterList2.GetCollection().Find((KidnappedCharacter k) => k.CharId == exchangeItem.KidnapCharDisplayData.CharacterId);
					DomainManager.Character.TransferKidnappedCharacter(context, exchange.CharId, _taiwuCharId, kidnappedCharacter2);
				}
				break;
			default:
				throw new ArgumentOutOfRangeException();
			}
		}
	}

	public void ConfirmBookExchange(DataContext context, Exchange exchange)
	{
		long diff = exchange.TotalValue;
		foreach (ItemDisplayData item in exchange.TargetContentItemList)
		{
			item.ItemSourceType = exchange.ToItemSourceType;
		}
		DomainManager.Merchant.ExchangeBook(context, exchange.CharId, exchange.TargetContentItemList, exchange.TaiwuContentItemList, (int)Math.Clamp(exchange.TaiwuValueBase - exchange.TotalValue, 0L, exchange.TaiwuValueBase + exchange.TargetValueBase), (int)Math.Clamp(exchange.TargetValueBase + exchange.TotalValue, 0L, 2147483647L));
	}

	public void ConfirmSettlementExchange(DataContext context, Exchange exchange)
	{
		List<ExchangeItem> exchangeItemList = exchange.ExchangeItemList;
		if (exchangeItemList == null || exchangeItemList.Count <= 0)
		{
			DomainManager.TaiwuEvent.SetListenerEventActionIntArg("ShopActionComplete", "OperationResult", 0);
			return;
		}
		long taiwuTotalValueWithAdvantage = exchange.TaiwuTotalValueWithAdvantage;
		long targetTotalValueWithAdvantage = exchange.TargetTotalValueWithAdvantage;
		if (taiwuTotalValueWithAdvantage >= targetTotalValueWithAdvantage && targetTotalValueWithAdvantage > 0)
		{
			ExecuteSettlementExchange(context, exchange);
			ClearSettlementExchange();
			return;
		}
		OrganizationDomain.ESettlementTreasuryOperationResult result = ((exchange.TaiwuContentList.Count > 0 && exchange.TargetContentList.Count == 0) ? OrganizationDomain.ESettlementTreasuryOperationResult.Store : OrganizationDomain.ESettlementTreasuryOperationResult.Steal);
		SettlementExchange = exchange;
		Dictionary<ItemSourceType, ItemSourceChange> itemChangeDict = new Dictionary<ItemSourceType, ItemSourceChange>
		{
			{
				ItemSourceType.Resources,
				new ItemSourceChange(ItemSourceType.Resources)
			},
			{
				ItemSourceType.Inventory,
				new ItemSourceChange(ItemSourceType.Inventory)
			},
			{
				ItemSourceType.Warehouse,
				new ItemSourceChange(ItemSourceType.Warehouse)
			},
			{
				ItemSourceType.Treasury,
				new ItemSourceChange(ItemSourceType.Treasury)
			},
			{
				ItemSourceType.Equipment,
				new ItemSourceChange(ItemSourceType.Equipment)
			},
			{
				ItemSourceType.Stock,
				new ItemSourceChange(ItemSourceType.Stock)
			}
		};
		foreach (ExchangeItem exchangeItem in exchange.ExchangeItemList)
		{
			if (exchangeItem.TypeEnum != ExchangeItem.EExchangeItemType.Item)
			{
				continue;
			}
			ItemKey key;
			int value;
			if (exchangeItem.Count > 0)
			{
				ItemSourceChange change = itemChangeDict[ItemSourceType.Inventory];
				if (exchangeItem.ItemData.IsResource)
				{
					change.AddItem(exchangeItem.ItemData.RealKey, exchangeItem.ItemData.Amount);
					continue;
				}
				foreach (KeyValuePair<ItemKey, int> item in exchangeItem.Inventory.Items)
				{
					item.Deconstruct(out key, out value);
					ItemKey key2 = key;
					int value2 = value;
					change.AddItem(key2, value2);
				}
			}
			else
			{
				if (exchangeItem.Count >= 0)
				{
					continue;
				}
				ItemSourceChange change2 = itemChangeDict[exchangeItem.ItemData.ItemSourceTypeEnum];
				if (exchangeItem.ItemData.IsResource)
				{
					change2.RemoveItem(exchangeItem.ItemData.RealKey, exchangeItem.ItemData.Amount);
					continue;
				}
				foreach (KeyValuePair<ItemKey, int> item2 in exchangeItem.Inventory.Items)
				{
					item2.Deconstruct(out key, out value);
					ItemKey key3 = key;
					int value3 = value;
					change2.RemoveItem(key3, value3);
				}
			}
		}
		DomainManager.Organization.ConfirmSettlementTreasuryOperation(context, 0, itemChangeDict.Values.ToList(), exchange.TotalValueWithAdvantage, result);
	}

	public void SettlementExchangeCost(DataContext context, Exchange exchange)
	{
		if (exchange != null)
		{
			ExchangeAdvantage advantageSummary = exchange.AdvantageSummary;
			if (advantageSummary != null && advantageSummary.DebtUsed > 0)
			{
				DomainManager.Extra.ChangeAreaSpiritualDebt(context, (short)exchange.AdvantageSummary.TradeAreaId, -exchange.AdvantageSummary.DebtUsed, getProfessionSeniority: false);
			}
			ExchangeAdvantage advantageSummary2 = exchange.AdvantageSummary;
			if (advantageSummary2 != null && advantageSummary2.ApprovingCharId >= 0 && DomainManager.Organization.TryGetSettlementCharacter(exchange.AdvantageSummary.ApprovingCharId, out var settlementChar))
			{
				settlementChar.SetApprovedTaiwu(context, approve: false);
			}
		}
	}

	private void ExecuteSettlementExchange(DataContext context, Exchange exchange)
	{
		SettlementExchangeCost(context, exchange);
		sbyte currentTreasuryLayer = exchange.LayerIndex;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		foreach (ExchangeItem exchangeItem in exchange.ExchangeItemList)
		{
			ItemKey key;
			int value;
			if (exchangeItem.Count > 0)
			{
				if (exchangeItem.ItemData.IsResource)
				{
					sbyte resourceType = exchangeItem.ItemData.ResourceType;
					DomainManager.Organization.TakeResourceFromTreasury(context, exchange.AdvantageSummary.NpcOrganization.SettlementId, taiwuChar, resourceType, exchangeItem.Count, (sbyte)(exchangeItem.ItemData.ItemSourceType - 10));
					DomainManager.Taiwu.AddResource(context, (exchange.ToItemSourceTypeEnum == ItemSourceType.Treasury) ? ItemSourceType.Treasury : ItemSourceType.Resources, resourceType, exchangeItem.Count);
					continue;
				}
				foreach (KeyValuePair<ItemKey, int> item in exchangeItem.Inventory.Items)
				{
					item.Deconstruct(out key, out value);
					ItemKey itemKey = key;
					int count = value;
					DomainManager.Organization.TakeItemFromTreasury(context, exchange.AdvantageSummary.NpcOrganization.SettlementId, taiwuChar, itemKey, count);
				}
				DomainManager.Taiwu.AddItem(context, exchangeItem.Inventory, exchange.ToItemSourceTypeEnum);
			}
			else
			{
				if (exchangeItem.Count >= 0)
				{
					continue;
				}
				if (exchangeItem.ItemData.IsResource)
				{
					sbyte resourceType2 = exchangeItem.ItemData.ResourceType;
					if (exchangeItem.ItemData.ItemSourceTypeEnum != ItemSourceType.Treasury)
					{
						DomainManager.Taiwu.RemoveResource(context, exchangeItem.ItemData.ItemSourceTypeEnum, resourceType2, -exchangeItem.Count);
					}
					else
					{
						DomainManager.Organization.TakeResourceFromTreasury(context, taiwuChar.GetOrganizationInfo().SettlementId, taiwuChar, resourceType2, -exchangeItem.Count, -1);
					}
					DomainManager.Organization.StoreResourceInTreasury(context, exchange.AdvantageSummary.NpcOrganization.SettlementId, taiwuChar, resourceType2, -exchangeItem.Count, currentTreasuryLayer);
					continue;
				}
				DomainManager.Taiwu.RemoveItem(context, exchangeItem.Inventory, exchangeItem.ItemData.ItemSourceTypeEnum, deleteItem: false);
				foreach (KeyValuePair<ItemKey, int> item2 in exchangeItem.Inventory.Items)
				{
					item2.Deconstruct(out key, out value);
					ItemKey itemKey2 = key;
					int count2 = value;
					DomainManager.Organization.StoreItemInTreasury(context, exchange.AdvantageSummary.NpcOrganization.SettlementId, taiwuChar, itemKey2, count2, currentTreasuryLayer);
				}
			}
		}
	}

	public void ConfirmWarehouseExchange(DataContext context, Exchange exchange)
	{
		int num = exchange.CharId >> 16;
		if (1 == 0)
		{
		}
		ItemSourceType itemSourceType = num switch
		{
			0 => ItemSourceType.Inventory, 
			1 => ItemSourceType.Warehouse, 
			2 => ItemSourceType.Treasury, 
			3 => ItemSourceType.Stock, 
			_ => ItemSourceType.Trough, 
		};
		if (1 == 0)
		{
		}
		ItemSourceType self = itemSourceType;
		int num2 = exchange.CharId & 0xFFFF;
		if (1 == 0)
		{
		}
		itemSourceType = num2 switch
		{
			0 => ItemSourceType.Inventory, 
			1 => ItemSourceType.Warehouse, 
			2 => ItemSourceType.Treasury, 
			3 => ItemSourceType.Stock, 
			_ => ItemSourceType.Trough, 
		};
		if (1 == 0)
		{
		}
		ItemSourceType target = itemSourceType;
		foreach (ExchangeItem exchangeItem in exchange.ExchangeItemList)
		{
			if (ItemTemplateHelper.IsMiscResource(exchangeItem.Content.Key.ItemType, exchangeItem.Content.Key.TemplateId))
			{
				sbyte resourceType = ItemTemplateHelper.GetMiscResourceType(exchangeItem.Content.Key.ItemType, exchangeItem.Content.Key.TemplateId);
				TransferResource(context, (exchangeItem.Count > 0) ? target : self, (exchangeItem.Count > 0) ? self : target, resourceType, Math.Abs(exchangeItem.Count));
			}
			else
			{
				TransferItemInventory(context, (sbyte)((exchangeItem.Count > 0) ? target : self), (sbyte)((exchangeItem.Count > 0) ? self : target), exchangeItem.Inventory);
			}
		}
	}

	private void InitTaiwuLoad(Exchange exchange, GameData.Domains.Character.Character taiwuChar, GameData.Domains.Character.Character targetChar = null)
	{
		int taiwuCurLoad = taiwuChar.GetCurrInventoryLoad();
		int taiwuMaxLoad = taiwuChar.GetMaxInventoryLoad();
		int taiwuWarehouseCurLoad = GetWarehouseCurrLoad();
		int taiwuWarehouseMaxLoad = GetWarehouseMaxLoad();
		int targetCurLoad = targetChar?.GetCurrInventoryLoad() ?? 0;
		int targetMaxLoad = targetChar?.GetMaxInventoryLoad() ?? 0;
		exchange.InitLoad(taiwuCurLoad, taiwuMaxLoad, taiwuWarehouseCurLoad, taiwuWarehouseMaxLoad, targetCurLoad, targetMaxLoad);
	}

	private Exchange CreatePersonExchange(DataContext context, int charId)
	{
		GameData.Domains.Character.Character targetChar = DomainManager.Character.GetElement_Objects(charId);
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short areaId = (short)((targetChar.GetOrganizationInfo().SettlementId == -1) ? (-1) : DomainManager.Organization.GetSettlement(targetChar.GetOrganizationInfo().SettlementId).GetLocation().AreaId);
		OrganizationInfo organizationInfo = targetChar.GetOrganizationInfo();
		int favorabilityType = FavorabilityType.GetFavorabilityType(DomainManager.Character.GetRelation(charId, _taiwuCharId).Favorability);
		int level = CharacterAlertnessData.GetLevel(DomainManager.Character.GetAlertnessValue(charId));
		int id = targetChar.GetId();
		int behaviorType = targetChar.GetBehaviorType();
		int fameType = targetChar.GetFameType();
		sbyte behaviorType2 = taiwuChar.GetBehaviorType();
		sbyte fameType2 = taiwuChar.GetFameType();
		int debtMax = ((targetChar.GetOrganizationInfo().SettlementId != -1) ? Math.Min(DomainManager.Extra.GetAreaSpiritualDebt(areaId), 1000) : 0);
		Exchange exchange = new Exchange(EExchangeType.Person, charId, new ExchangeAdvantage(behaviorType2, fameType2, areaId, debtMax, id, organizationInfo, DomainManager.Character.GetRelatedCharacters(charId), favorabilityType, level, behaviorType, fameType, DomainManager.Character.GetCharacterLoveAndHateItemInfo(context, charId)));
		OrganizationInfo targetOrgInfo = targetChar.GetOrganizationInfo();
		OrganizationItem targetOrgConfig = Config.Organization.Instance[targetOrgInfo.OrgTemplateId];
		exchange.MartialArtistSkill0Useful = DomainManager.Extra.MartialArtistSkill0Useful(targetOrgConfig);
		exchange.CivilianSkill0Useful = DomainManager.Extra.CivilianSkill0Useful(targetOrgConfig);
		InitTaiwuLoad(exchange, taiwuChar, targetChar);
		return exchange;
	}

