	}

	[DomainMethod]
	public void GmCmd_GenerateCricketPolymorph(DataContext context, short templateId, sbyte gender)
	{
		if (_cricketPolymorphs.TryGetValue(templateId, out var polymorph) && polymorph.Alive)
		{
			return;
		}
		CricketPartsItem config = CricketParts.Instance[templateId];
		if (config == null)
		{
			return;
		}
		if (1 == 0)
		{
		}
		int num = gender switch
		{
			1 => config.CharacterMale, 
			0 => config.CharacterFemale, 
			_ => -1, 
		};
		if (1 == 0)
		{
		}
		int characterTemplateId = num;
		if (characterTemplateId >= 0)
		{
			if (polymorph != null && polymorph.ContainsState(ECricketPolymorphState.WaitForReturn))
			{
				polymorph.ChangeState(ECricketPolymorphState.Returned);
			}
			ItemKey cricket = DomainManager.Item.CreateCricket(context, templateId, 0);
			if (!CricketPolymorph(context, cricket, gender))
			{
				DomainManager.Item.RemoveItem(context, cricket);
				return;
			}
			polymorph = _cricketPolymorphs[templateId];
			JoinGroup(context, polymorph.CurrentCharacterId);
		}
	}

