	[DomainMethod]
	public void JoinGroup(DataContext context, int charId, bool showNotification = true)
	{
		DomainManager.Taiwu.ApplyGroupCharEquipmentPlan(context, charId);
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		if (character.GetLeaderId() >= 0)
		{
			DomainManager.Character.LeaveGroup(context, character);
		}
		DomainManager.Adventure.DynamicUnbindCharacterAndUnhideFromMap(context, character);
		if (character.GetCreatingType() == 2)
		{
			DomainManager.Character.ConvertRandomEnemy(context, character, character.GetLocation());
		}
		else if (DomainManager.Character.IsTemporaryIntelligentCharacter(charId))
		{
			DomainManager.Character.ConvertTemporaryIntelligentCharacter(context, character);
		}
		if (character.IsCreatedWithFixedTemplate() && charId != _taiwuCharId)
		{
			character.SetLeaderId(_taiwuCharId, context);
			DomainManager.Character.AddSpecialGroupCharacter(context, _taiwuCharId, charId);
			return;
		}
		if (character.GetLeaderId() == charId)
		{
			foreach (int prevGroupCharId in DomainManager.Character.GetGroup(charId).GetCollection())
			{
				if (prevGroupCharId != charId)
				{
					JoinGroup(context, prevGroupCharId);
				}
			}
		}
		_groupCharIds.Add(charId);
		SetGroupCharIds(_groupCharIds, context);
		character.SetLeaderId(_taiwuCharId, context);
		Events.RaiseCharacterLocationChanged(context, charId, character.GetLocation(), Location.Invalid);
		character.SetLocation(_taiwuChar.GetLocation(), context);
		OrganizationInfo orgInfo = character.GetOrganizationInfo();
		OrganizationInfo destOrgInfo = _taiwuChar.GetOrganizationInfo();
		if (orgInfo.OrgTemplateId != destOrgInfo.OrgTemplateId || orgInfo.SettlementId != destOrgInfo.SettlementId)
		{
			destOrgInfo.Grade = 0;
			destOrgInfo.Principal = true;
			DomainManager.Organization.ChangeOrganization(context, character, destOrgInfo);
		}
		else if (orgInfo.OrgTemplateId == 16)
		{
			DomainManager.Taiwu.TryRemoveTaiwuVillageResident(context, charId);
			DomainManager.Building.TryRemoveFeastCustomer(context, charId);
		}
		Tester.Assert(!character.IsActiveExternalRelationState(32uL));
		Tester.Assert(!character.IsActiveExternalRelationState(8uL));
		if (character.IsActiveExternalRelationState(188uL))
		{
			character.DeactivateExternalRelationState(context, 188uL);
		}
		foreach (int charInTeam in _groupCharIds.GetCollection())
		{
			if (charInTeam != charId)
			{
				DomainManager.Character.TryCreateRelation(context, charId, charInTeam);
			}
		}
		short currMusicId = DomainManager.Extra.GetSectXuannvPlayerMusicId();
		bool isEnabled = DomainManager.Extra.GetSectXuannvPlayerIsEnabled();
		if (currMusicId >= 0 && isEnabled)
		{
			short featureId = Music.Instance[currMusicId].TemporaryFeature;
			character.AddFeature(context, featureId, removeMutexFeature: true);
		}
		CharacterCombatSkillConfiguration skillConfiguration = DomainManager.Extra.TryGetCharacterCombatSkillConfiguration(charId);
		if (skillConfiguration != null)
		{
			if (skillConfiguration.IsCombatSkillLocked)
			{
				DomainManager.Character.ApplyCombatSkillPlan(context, character, skillConfiguration.CurrentEquipPlan);
				DomainManager.Extra.SetCharacterMasteredCombatSkills(context, charId, skillConfiguration.CurrentMasterPlan);
			}
			if (skillConfiguration.IsNeiliAllocationLocked)
			{
				DomainManager.Character.ApplyNeiliAllocation(context, character, skillConfiguration.NeiliAllocation);
			}
			if (skillConfiguration.IsCombatSkillAttainmentLocked)
			{
				DomainManager.Character.ApplyCombatSkillAttainmentPanels(context, character, skillConfiguration.CombatSkillAttainmentPanels);
			}
		}
		else
		{
			DomainManager.Character.AutoEquipCombatSkills(context, charId, -1);
		}
		if (showNotification)
		{
			InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
			instantNotifications.AddJoinGroup(charId);
		}
		if (!character.IsTaiwu())
		{
			if (!DomainManager.Character.IsCharacterCreating(_taiwuCharId))
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 231);
			}
			DomainManager.Global.InvokeGuidingTrigger(context, 294);
			switch (character.GetTemplateId())
			{
			case 519:
				AchievementManager.RequestSetStat(context, 175, 1);
				break;
			case 520:
				AchievementManager.RequestSetStat(context, 174, 1);
				break;
			case 521:
				AchievementManager.RequestSetStat(context, 173, 1);
				break;
			case 522:
				AchievementManager.RequestSetStat(context, 176, 1);
				break;
			}
		}
		DomainManager.TaiwuEvent.RecordTeammateStateChanged(isLosing: false, charId);
	}

	[DomainMethod]
	public void LeaveGroup(DataContext context, int charId, bool bringWards = true, bool showNotification = true, bool moveToRandomAdjacentBlock = true)
	{
		Logger.Info($"Character {charId} is leaving group at path {new StackTrace()}");
		for (int i = 0; i < _combatGroupCharIds.Length; i++)
		{
			if (_combatGroupCharIds[i] == charId)
			{
				SetElement_CombatGroupCharIds(i, -1, context);
			}
		}
		GameData.Domains.Character.Character character;
		bool characterExists = DomainManager.Character.TryGetElement_Objects(charId, out character);
		if (characterExists && character.IsCreatedWithFixedTemplate() && charId != _taiwuCharId)
		{
			character.SetLeaderId(-1, context);
			character.RemoveFeatureGroup(context, 262);
			DomainManager.Character.TryRemoveSpecialGroupCharacter(context, _taiwuCharId, charId);
			return;
		}
		if (!_groupCharIds.Remove(charId).Item2)
		{
			throw new Exception($"Character {charId} is not in the group");
		}
		SetGroupCharIds(_groupCharIds, context);
		RemoveManualChangeEquipGroupChar(context, charId, keepRecord: true);
		if (!characterExists)
		{
			return;
		}
		CharacterCombatSkillConfiguration skillConfiguration = DomainManager.Extra.TryGetCharacterCombatSkillConfiguration(charId);
		if (skillConfiguration != null)
		{
			if (skillConfiguration.IsCombatSkillLocked)
			{
				skillConfiguration.OfflineRecordCombatSkillPlan(character, skillConfiguration.CurrentPlanId);
			}
			if (skillConfiguration.IsNeiliAllocationLocked)
			{
				skillConfiguration.OfflineRecordNeiliAllocation(character);
			}
			if (skillConfiguration.IsCombatSkillAttainmentLocked)
			{
				skillConfiguration.OfflineRecordCombatSkillAttainmentPanels(character);
			}
			DomainManager.Extra.SetCharacterCombatSkillConfiguration(context, charId, skillConfiguration);
		}
		character.SetLeaderId(-1, context);
		Location location = _taiwuChar.GetLocation();
		if (!location.IsValid())
		{
			location = _taiwuChar.GetValidLocation();
		}
		if (moveToRandomAdjacentBlock)
		{
			short adjacentBlockId = DomainManager.Map.GetRandomAdjacentBlockId(context.Random, location.AreaId, location.BlockId);
			location.BlockId = adjacentBlockId;
		}
		Events.RaiseCharacterLocationChanged(context, charId, character.GetLocation(), location);
		character.SetLocation(location, context);
		character.RemoveFeatureGroup(context, 262);
		if (character.GetOrganizationInfo().OrgTemplateId == 16)
		{
			DomainManager.Taiwu.AddTaiwuVillageResident(context, charId);
		}
		if (bringWards)
		{
			HashSet<int> wards = ObjectPool<HashSet<int>>.Instance.Get();
			DomainManager.Character.GetWardsInGroup(character, _groupCharIds, wards);
			DomainManager.Character.ChangeGroup(context, wards, character);
		}
		if (showNotification)
		{
			InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
			instantNotifications.AddLeaveGroup(charId);
		}
		DomainManager.TaiwuEvent.RecordTeammateStateChanged(isLosing: true, charId);
	}

