	private void RegisterMonitorsForGuiding()
	{
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(new DataUid(9, 11, ulong.MaxValue), "RegisterMonitorsForGuiding", OnHomelessChanged);
