	private void OnHomelessChanged(DataContext context, DataUid uid)
	{
		if (_taiwuChar?.GetOrganizationInfo().OrgTemplateId == 16 && DomainManager.Building.GetHomeless().GetCount() > 0)
		{
			DomainManager.Global.InvokeGuidingTrigger(context, 332);
			GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(uid, "RegisterMonitorsForGuiding");
		}
	}

	private void UpdateMonitorsOnTaiwuForGuiding(int newTaiwuId, int oldTaiwuId = -1)
	{
		if (oldTaiwuId >= 0)
		{
			DataUid oldMonitorUid = new DataUid(4, 0, (ulong)oldTaiwuId, 44u);
			GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(oldMonitorUid, "OnTaiwuPoisonedChanged");
		}
		DataUid newMonitorUid = new DataUid(4, 0, (ulong)newTaiwuId, 44u);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(newMonitorUid, "OnTaiwuPoisonedChanged", OnTaiwuPoisonedChanged);
	}

	private void OnTaiwuPoisonedChanged(DataContext context, DataUid uid)
	{
		PoisonInts poisoned = _taiwuChar.GetPoisoned();
		if (!poisoned.IsNonZero())
		{
			return;
		}
		DomainManager.Global.InvokeGuidingTrigger(context, 271);
		int count = 0;
		for (sbyte poisonType = 0; poisonType < 6; poisonType++)
		{
			if (poisoned[poisonType] > 0)
			{
				count++;
			}
		}
		AchievementManager.RequestSetStat(context, 237, count);
	}

