	public bool TryItemAutoOperation(DataContext context, ItemKey itemKey, EItemAutoOperationSource source)
	{
		return false;
	}

	private bool TryItemAutoOperationDiscard(DataContext context, ItemKey itemKey, EItemAutoOperationSource source, bool needDisassemble)
	{
		if (!ItemTemplateHelper.IsTransferable(itemKey.ItemType, itemKey.TemplateId))
		{
			return false;
		}
		ItemAutoOperationSettingData setting = DomainManager.Taiwu.GetItemAutoOperationSettingData();
		if (!setting.DiscardGroup.SourceList.Contains(source))
		{
			return false;
		}
		sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
		EItemAutoOperationTargetType itemAutoOperationType = ItemAutoOperationSettingItem.GetItemAutoOperationType(itemKey);
		if (!setting.DiscardGroup.TypeDict.TryGetValue(itemAutoOperationType, out var settingItem))
		{
			return false;
		}
		if (grade > settingItem.Grade)
		{
			return false;
		}
		bool contains;
		if (itemKey.ItemType == 10)
		{
			bool isReadFinished = itemKey.ItemType == 10 && DomainManager.Taiwu.GetTotalReadingProgress(itemKey.Id) >= 100;
			bool isReading = DomainManager.Taiwu.GetCurReadingBook().Equals(itemKey);
			EItemAutoOperationBookSubtype readingType = ((!isReadFinished) ? (isReading ? EItemAutoOperationBookSubtype.Reading : EItemAutoOperationBookSubtype.NotReading) : EItemAutoOperationBookSubtype.ReadFinished);
			contains = settingItem.Contains(itemKey, readingType);
		}
		else
		{
			contains = settingItem.Contains(itemKey);
		}
		if (contains)
		{
			if (needDisassemble && TryItemAutoOperationDisassemble(context, itemKey, source, out var _))
			{
				return true;
			}
			DomainManager.Item.RemoveItem(context, itemKey);
			InstantNotificationCollection instantNotificationCollection = DomainManager.World.GetInstantNotificationCollection();
			instantNotificationCollection.AddAutoOperationDiscard(itemKey.ItemType, itemKey.TemplateId);
			return true;
		}
		return false;
	}

	private bool TryItemAutoOperationDisassemble(DataContext context, ItemKey itemKey, EItemAutoOperationSource source, out bool canDiscard)
	{
		canDiscard = false;
		if (!ItemTemplateHelper.GetCanDisassemble(itemKey.ItemType, itemKey.TemplateId))
		{
			return false;
		}
		ItemAutoOperationSettingData setting = DomainManager.Taiwu.GetItemAutoOperationSettingData();
		if (!setting.DisassembleGroup.SourceList.Contains(source))
		{
			return false;
		}
		EItemAutoOperationTargetType itemAutoOperationType = ItemAutoOperationSettingItem.GetItemAutoOperationType(itemKey);
		if (!setting.DisassembleGroup.TypeDict.TryGetValue(itemAutoOperationType, out var settingItem))
		{
			return false;
		}
		sbyte grade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
		if (grade > settingItem.Grade)
		{
			return false;
		}
		if (!settingItem.Contains(itemKey))
		{
			return false;
		}
		Inventory inventory = DomainManager.Taiwu.GetInventory(ItemSourceType.Inventory);
		short requiredAttainment = ItemTemplateHelper.GetDisassembleRequiredAttainment(itemKey.ItemType, itemKey.TemplateId);
		sbyte requiredLifeSkillType = ItemTemplateHelper.GetCraftRequiredLifeSkillType(itemKey.ItemType, itemKey.TemplateId);
		List<ItemKey> toolList = ObjectPool<List<ItemKey>>.Instance.Get();
		toolList.Clear();
		foreach (var (inventoryKey, _) in inventory.Items)
		{
			if (inventoryKey.ItemType == 6)
			{
				CraftToolItem toolConfig = Config.CraftTool.Instance[inventoryKey.TemplateId];
				if (toolConfig.RequiredLifeSkillTypes.Contains(requiredLifeSkillType) && toolConfig.Grade <= setting.DisassembleToolGrade)
				{
					toolList.Add(inventoryKey);
				}
			}
		}
		toolList.Sort(delegate(ItemKey a, ItemKey b)
		{
			short num2 = Config.CraftTool.Instance[a.TemplateId].DurabilityCost[grade];
			short value = Config.CraftTool.Instance[b.TemplateId].DurabilityCost[grade];
			return num2.CompareTo(value);
		});
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		ItemKey toolKey = toolList.FirstOrDefault((ItemKey t) => CheckToolForAutoDisassemble(t, requiredAttainment, requiredLifeSkillType, grade, 1), ItemKey.Invalid);
		ObjectPool<List<ItemKey>>.Instance.Return(toolList);
		if (toolKey.IsValid())
		{
			DomainManager.Item.DisassembleItemOptionalInternal(context, taiwuCharId, itemKey, toolKey, 1, 1);
			DomainManager.Item.RemoveItem(context, itemKey);
			InstantNotificationCollection instantNotificationCollection = DomainManager.World.GetInstantNotificationCollection();
			instantNotificationCollection.AddAutoOperationDisassemble(toolKey.ItemType, toolKey.TemplateId, itemKey.ItemType, itemKey.TemplateId);
			return true;
		}
		canDiscard = true;
		return false;
	}

	private bool CheckToolForAutoDisassemble(ItemKey inventoryKey, int requiredAttainment, sbyte requiredLifeSkillType, sbyte grade, int amount)
	{
		if (inventoryKey.ItemType != 6)
		{
			return false;
		}
		CraftToolItem toolConfig = Config.CraftTool.Instance[inventoryKey.TemplateId];
		if (!toolConfig.RequiredLifeSkillTypes.Contains(requiredLifeSkillType))
		{
			return false;
		}
		short oneCost = toolConfig.DurabilityCost[grade];
		int totalCost = oneCost * amount;
		if (!DomainManager.Building.CheckTool(inventoryKey, totalCost, oneCost, -1))
		{
			return false;
		}
		if (!DomainManager.Building.CheckLifeSkill(requiredLifeSkillType, requiredAttainment, inventoryKey))
		{
			return false;
		}
		return true;
	}

