	[DomainMethod]
	public void SelectLegacies(DataContext context, List<short> templateIds, List<short> noCostIds)
	{
		int sum = 0;
		if (templateIds != null)
		{
			foreach (short templateId in templateIds)
			{
				SelectLegacy(context, templateId);
				sum += Legacy.Instance[templateId].Cost;
			}
		}
		if (noCostIds != null)
		{
			foreach (short templateId2 in noCostIds)
			{
				SelectLegacy(context, templateId2);
			}
		}
		ChangeLegacyPointWhilePassingLegacy(context, -sum);
	}

