	public void AddLegacyPoint(DataContext context, short templateId, int percent = 100)
	{
		WorldCreationInfo info = DomainManager.World.GetWorldCreationInfo();
		LegacyPointItem configData = LegacyPoint.Instance[templateId];
		int addValue = configData.BasePoint * percent / 100;
		int settingsPercent = SharedMethods.GetLegacySettingsPercent(info, configData);
		addValue = addValue * settingsPercent / 100;
		short taiwuSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		int buildingBuff = DomainManager.Building.GetBuildingBlockEffect(taiwuSettlementId, EBuildingScaleEffect.LegacyPointBonusFactor);
		addValue = addValue * (100 + buildingBuff) / 100;
		DirectlyAddLegacyPoint(context, templateId, addValue);
	}

	private void DirectlyAddLegacyPoint(DataContext context, short templateId, int addValue)
	{
		LegacyPointItem legacyPointCfg = LegacyPoint.Instance[templateId];
		LegacyPointTypeItem legacyPointTypeCfg = LegacyPointType.Instance[legacyPointCfg.Type];
		int maxValue = GetLegacyMaxPoint(legacyPointCfg);
		if (!_legacyPointDict.TryGetValue(templateId, out var prevValue))
		{
			AddElement_LegacyPointDict(templateId, 0, context);
			prevValue = 0;
		}
		addValue = Math.Min(addValue, maxValue - prevValue);
		if (addValue > 0)
		{
			int newValue = prevValue + addValue;
			SetElement_LegacyPointDict(templateId, (short)newValue, context);
			SetLegacyPoint(_legacyPoint + addValue, context);
			IncreaseLegacyPointTimes(context, templateId);
			if (prevValue < maxValue / 2 && newValue >= maxValue / 2)
			{
				short legacyId = GetRandomAvailableLegacy(context.Random, legacyPointTypeCfg.Group);
				AddAvailableLegacy(context, legacyId);
			}
			if (prevValue < maxValue && newValue == maxValue)
			{
				short legacyId2 = GetRandomAvailableLegacy(context.Random, legacyPointTypeCfg.Group);
				AddAvailableLegacy(context, legacyId2);
			}
			if (addValue >= GuidingChapterTrigger.DefValue.Trigger329.Int1)
			{
				DomainManager.Global.InvokeGuidingTrigger(context, 324);
			}
		}
	}

	public int GetLegacyPointCountForLegacyType(sbyte legacyPointType)
	{
		int count = 0;
		foreach (KeyValuePair<short, short> kv in _legacyPointDict)
		{
			LegacyPointItem legacyPointConfig = LegacyPoint.Instance[kv.Key];
			if (legacyPointConfig.Type == legacyPointType)
			{
				count += kv.Value;
			}
		}
		return count;
	}

