	{
		return SharedMethods.GetLegacyMaxPoint(DomainManager.World.GetWorldCreationInfo(), configData);
	}

	public static int GetLegacySettingsPercent(LegacyPointItem configData)
	{
		return SharedMethods.GetLegacySettingsPercent(DomainManager.World.GetWorldCreationInfo(), configData);
