	public bool AddAvailableLegacy(DataContext context, short templateId)
	{
		LegacyItem config = Legacy.Instance[templateId];
		if (config.IsUnique && _availableLegacyList.Contains(templateId))
		{
			return false;
		}
		if (config.PermanentlyUnique && IsUniqueLegacySelected(templateId))
		{
			return false;
		}
		_availableLegacyList.Add(templateId);
		DomainManager.World.GetInstantNotifications().AddLegacy(templateId);
		SetAvailableLegacyList(_availableLegacyList, context);
		DomainManager.Global.InvokeGuidingTrigger(context, 325);
		return true;
	}

	public short GetRandomAvailableLegacy(IRandomSource random, sbyte groupId = -1)
	{
		if (groupId < 0)
		{
			groupId = (sbyte)random.Next(WorldCreationGroup.Instance.Count - 1);
		}
		sbyte level = GetWorldCreationGroupLevel(groupId);
		return RandomUtils.GetRandomResult(_categorizedNormalLegacyConfigs[groupId][level], random);
	}

	public static sbyte GetWorldCreationGroupLevel(sbyte groupId)
	{
		int legacyBonusSum = GetWorldCreationGroupLegacyBonusSum(groupId);
		for (sbyte i = (sbyte)(GlobalConfig.Instance.LegacyGroupLevelThresholds.Length - 1); i >= 0; i--)
		{
			if (legacyBonusSum >= GlobalConfig.Instance.LegacyGroupLevelThresholds[i])
			{
				return i;
			}
		}
		throw new Exception($"Invalid legacy bonus sum {legacyBonusSum} for group {groupId}.");
	}

	private static int GetWorldCreationGroupLegacyBonusSum(sbyte groupId)
	{
		int score = 0;
		WorldCreationGroupItem groupCfg = WorldCreationGroup.Instance[groupId];
		byte[] worldCreations = groupCfg.WorldCreations;
		foreach (byte worldCreationId in worldCreations)
		{
			WorldCreationItem worldCreationCfg = WorldCreation.Instance[worldCreationId];
			int value = DomainManager.World.GetWorldCreationSetting(worldCreationId);
			if (worldCreationCfg.LegacyPointBonus.CheckIndex(value))
			{
				score += worldCreationCfg.LegacyPointBonus[value];
			}
		}
		return score;
	}

	private static void InitializeNormalLegacies()
	{
		int levelCount = GlobalConfig.Instance.LegacyGroupLevelThresholds.Length;
		int groupCount = WorldCreationGroup.Instance.Count - 1;
		_categorizedNormalLegacyConfigs = new List<(short, short)>[groupCount][];
		for (int i = 0; i < groupCount; i++)
		{
			_categorizedNormalLegacyConfigs[i] = new List<(short, short)>[levelCount];
			for (int j = 0; j < levelCount; j++)
			{
				_categorizedNormalLegacyConfigs[i][j] = new List<(short, short)>();
			}
		}
		foreach (LegacyItem legacyCfg in (IEnumerable<LegacyItem>)Legacy.Instance)
		{
			if (legacyCfg.Weight != 0)
			{
				_categorizedNormalLegacyConfigs[legacyCfg.WorldCreationGroup][legacyCfg.Level].Add((legacyCfg.TemplateId, legacyCfg.Weight));
			}
		}
	}

	public void PushStateNewCharacterLegacyGrowingGrades(DataContext context, sbyte stateId, IEnumerable<sbyte> grades)
	{
		SByteList gradeList = _stateNewCharacterLegacyGrowingGrades[stateId];
		if (gradeList.Items == null)
		{
			gradeList = SByteList.Create();
		}
		gradeList.Items.AddRange(grades);
		SetElement_StateNewCharacterLegacyGrowingGrades(stateId, gradeList, context);
	}

	public sbyte PopStateNewCharacterLegacyGrowingGrade(DataContext context, sbyte stateId, sbyte minGrade = -1)
	{
		if (stateId < 0)
		{
			return minGrade;
		}
		SByteList gradeList = _stateNewCharacterLegacyGrowingGrades[stateId];
		if (gradeList.Items == null || gradeList.Items.Count == 0)
		{
			return minGrade;
		}
		sbyte growingGrade = gradeList.Items[0];
		if (growingGrade < minGrade)
		{
			return minGrade;
		}
		gradeList.Items.RemoveAt(0);
		SetElement_StateNewCharacterLegacyGrowingGrades(stateId, gradeList, context);
		return growingGrade;
	}

	public sbyte OfflinePopStateNewCharacterLegacyGrowingGrade(sbyte stateId)
	{
		if (stateId < 0)
		{
			return -1;
		}
		SByteList gradeList = _stateNewCharacterLegacyGrowingGrades[stateId];
		if (gradeList.Items == null || gradeList.Items.Count == 0)
		{
			return -1;
		}
		sbyte growingGrade = gradeList.Items[0];
		gradeList.Items.RemoveAt(0);
		return growingGrade;
	}

	[DomainMethod]
	public List<SuccessorCandidates> FindSuccessorCandidates(DataContext context, bool includeInvalid = false)
	{
		if (_successorCandidates.Count == 0)
		{
			CalculateSuccessorCandidates(context);
		}
		return (!includeInvalid) ? _successorCandidates.Where((SuccessorCandidates x) => GameData.Domains.Character.SharedMethods.CanBeTaiwu(x.TeammateData.CharacterTemplateId) && x.TeammateData.PhysiologicalAge >= 16).ToList() : _successorCandidates;
	}

	private void CalculateSuccessorCandidates(DataContext context)
	{
		Tester.Assert(_successorCandidates.Count == 0);
		switch (_legacyPassingState)
		{
		case 1:
			_successorCandidates.AddRange(from x in DomainManager.Character.GetCharacterDisplayDataForGeneralScrollListBatch(context, (from x in _groupCharIds.GetCollection()
					where x != _taiwuCharId
					select x).ToList())
				select new SuccessorCandidates
				{
					TeammateData = x
				});
			break;
		case 2:
		{
			Location location = _taiwuChar.GetLocation();
			if (!location.IsValid())
			{
				location = _taiwuChar.GetValidLocation();
			}
			List<Predicate<GameData.Domains.Character.Character>> predicates = ObjectPool<List<Predicate<GameData.Domains.Character.Character>>>.Instance.Get();
			List<GameData.Domains.Character.Character> charList = ObjectPool<List<GameData.Domains.Character.Character>>.Instance.Get();
			predicates.Clear();
			charList.Clear();
			GameData.Domains.Character.Filters.CharacterFilterRules.ToPredicates(13, predicates, Location.Invalid);
			MapCharacterFilter.Find(predicates, charList, location.AreaId);
			Logger.Info((predicates.Count > 0) ? "found male" : "created male");
			GameData.Domains.Character.Character maleChar = ((charList.Count > 0) ? charList.GetRandom(context.Random) : DomainManager.Character.CreateTemporaryIntelligentCharacter(context, 13, location));
			predicates.Clear();
			charList.Clear();
			GameData.Domains.Character.Filters.CharacterFilterRules.ToPredicates(14, predicates, Location.Invalid);
			MapCharacterFilter.Find(predicates, charList, location.AreaId);
			Logger.Info((predicates.Count > 0) ? "found female" : "created female");
			GameData.Domains.Character.Character femaleChar = ((charList.Count > 0) ? charList.GetRandom(context.Random) : DomainManager.Character.CreateTemporaryIntelligentCharacter(context, 14, location));
			ObjectPool<List<Predicate<GameData.Domains.Character.Character>>>.Instance.Return(predicates);
			ObjectPool<List<GameData.Domains.Character.Character>>.Instance.Return(charList);
			_successorCandidates.Add(GetSuccessor(maleChar));
			_successorCandidates.Add(GetSuccessor(femaleChar));
			break;
		}
		default:
			throw new Exception($"Trying to find successors in a invalid state {_legacyPassingState}.");
		}
		SetSuccessorCandidates(_successorCandidates, context);
		SuccessorCandidates GetSuccessor(GameData.Domains.Character.Character character)
		{
			return new SuccessorCandidates
			{
				TeammateData = DomainManager.Character.GetCharacterDisplayDataForGeneralScrollList(context, character),
				DisplayData = DomainManager.Character.GetCharacterMenuInfoDisplayData(context, character.GetId()),
				CombatSkillAttainments = character.GetCombatSkillAttainments(),
				LifeSkillAttainments = character.GetLifeSkillAttainments()
			};
		}
	}

	[DomainMethod]
	public void ConfirmChosenSuccessor(DataContext context, int newTaiwuId)
	{
		bool randomSuccessor = _legacyPassingState == 2;
		ConvertAndClearSuccessorsCandidates(context, newTaiwuId);
		SetLegacyPassingState(context, 4);
		GameData.Domains.Character.Character newTaiwuChar = DomainManager.Character.GetElement_Objects(newTaiwuId);
		(short, short) healthRatio = (newTaiwuChar.GetHealth(), newTaiwuChar.GetLeftMaxHealth());
		DomainManager.Character.RevertAllTemporaryModifications(context, _taiwuChar);
		_taiwuChar.RemoveFeatureGroup(context, 217);
		AchievementManager.RequestSetStat(context, 52, 1);
		if (!DomainManager.Character.TryGetRelation(_taiwuCharId, newTaiwuId, out var relation))
		{
			AchievementManager.RequestSetStat(context, 50, 1);
		}
		else if (RelationType.IsFamilyRelation(relation.RelationType))
		{
			AchievementManager.RequestSetStat(context, 49, 1);
		}
		if (_previousTaiwuIds.Contains(newTaiwuId))
		{
			AchievementManager.RequestSetStat(context, 53, 1);
		}
		if (_groupCharIds.GetCollection().Contains(newTaiwuId))
		{
			AchievementManager.RequestSetStat(context, 51, 1);
		}
		ArchiveCurrentTaiwuLifeSummaries(context, newTaiwuChar.GetId());
		TransferTaiwuData(context, newTaiwuChar, _taiwuChar, randomSuccessor);
		SetTaiwu(context, newTaiwuChar);
		CheckGuidingAfterTransferTaiwuData(context);
		UpdateConsummateLevelBrokenFeature(context);
		ApplyAndResetLegacy(context, newTaiwuChar, isClearLegaciesBuilding: false);
		short newTaiwuLeftMaxHealth = newTaiwuChar.GetLeftMaxHealth();
		short newTaiwuHealth = (short)Math.Clamp(newTaiwuChar.GetLeftMaxHealth() * healthRatio.Item1 / Math.Max(1, (int)healthRatio.Item2), 0, newTaiwuLeftMaxHealth);
		newTaiwuChar.SetHealth(newTaiwuHealth, context);
		Location newTaiwuLocation = newTaiwuChar.GetLocation();
		DomainManager.Map.SetBlockAndViewRangeVisible(context, newTaiwuLocation.AreaId, newTaiwuLocation.BlockId);
		_isTaiwuDying = false;
		DomainManager.TaiwuEvent.TriggerListener("PassingLegacyComplete", value: true);
	}

	public void ConvertAndClearSuccessorsCandidates(DataContext context, int newTaiwuId)
	{
		foreach (SuccessorCandidates charId in _successorCandidates)
		{
			if (DomainManager.Character.IsTemporaryIntelligentCharacter(charId.TeammateData.CharacterId))
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId.TeammateData.CharacterId);
				if (charId.TeammateData.CharacterId == newTaiwuId)
				{
					DomainManager.Character.ConvertTemporaryIntelligentCharacter(context, character);
				}
				else
				{
					DomainManager.Character.RemoveTemporaryIntelligentCharacter(context, character);
				}
			}
		}
		_successorCandidates.Clear();
	}

	public void CheckNotTaiwu(int charId)
	{
		Tester.Assert(charId != _taiwuCharId || _legacyPassingState != 0);
	}

	public void TransferTaiwuData(DataContext context, GameData.Domains.Character.Character newTaiwuChar, GameData.Domains.Character.Character oldTaiwuChar, bool randomSuccessor = false)
	{
		int newTaiwuCharId = newTaiwuChar.GetId();
		int oldTaiwuCharId = oldTaiwuChar.GetId();
		DomainManager.Character.PrepareTaiwuInheritor(context, newTaiwuChar, oldTaiwuChar);
		SetTaiwuGenerationsCount(_taiwuGenerationsCount + 1, context);
		DomainManager.Taiwu.TaiwuUnfollowNpc(context, newTaiwuCharId);
		List<short> learnedCombatSkills = newTaiwuChar.GetLearnedCombatSkills();
		List<GameData.Domains.CombatSkill.CombatSkill> combatSkills = ObjectPool<List<GameData.Domains.CombatSkill.CombatSkill>>.Instance.Get();
		combatSkills.Clear();
		foreach (short combatSkillId in oldTaiwuChar.GetLearnedCombatSkills())
		{
			GameData.Domains.CombatSkill.CombatSkill oldSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(oldTaiwuCharId, combatSkillId));
			GameData.Domains.CombatSkill.CombatSkill newSkill = GameData.Serializer.Serializer.CreateCopy(oldSkill);
			newSkill.OfflineSetCharId(newTaiwuCharId);
			combatSkills.Add(newSkill);
			learnedCombatSkills.Add(combatSkillId);
		}
		DomainManager.CombatSkill.RegisterCombatSkills(newTaiwuCharId, combatSkills);
		DomainManager.Character.AutoActivateReadCombatSkillNormalPages(context, combatSkills, newTaiwuCharId);
		ObjectPool<List<GameData.Domains.CombatSkill.CombatSkill>>.Instance.Return(combatSkills);
		newTaiwuChar.SetLearnedCombatSkills(learnedCombatSkills, context);
		newTaiwuChar.CopyCombatSkillEquipmentFrom(context, oldTaiwuChar);
		DomainManager.SpecialEffect.AddAllBrokenSkillEffects(context, newTaiwuChar);
		newTaiwuChar.SetLoopingNeigong(oldTaiwuChar.GetLoopingNeigong(), context);
		newTaiwuChar.SetCombatSkillAttainmentPanels(oldTaiwuChar.GetCombatSkillAttainmentPanels().ToArray(), context);
		List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = newTaiwuChar.GetLearnedLifeSkills();
		learnedLifeSkills.Clear();
		learnedLifeSkills.AddRange(oldTaiwuChar.GetLearnedLifeSkills());
		newTaiwuChar.SetLearnedLifeSkills(learnedLifeSkills, context);
		GameData.Utilities.ShortList masteredCombatSkills = DomainManager.Extra.GetCharacterMasteredCombatSkills(oldTaiwuCharId);
		DomainManager.Extra.ClearCharacterMasteredCombatSkills(context, oldTaiwuCharId);
		DomainManager.Extra.SetCharacterMasteredCombatSkills(context, newTaiwuCharId, masteredCombatSkills);
		DomainManager.Extra.TransferTaiwuProficiency(context, oldTaiwuCharId, newTaiwuCharId);
		ItemKey[] emptyEquipments = new ItemKey[17];
		for (int i = 0; i < 17; i++)
		{
			emptyEquipments[i] = ItemKey.Invalid;
		}
		ItemKey[] originalTaiwuEquipment = oldTaiwuChar.GetEquipment().ToArray();
		ItemKey clothingKey = originalTaiwuEquipment[4];
		ItemKey[] oldTaiwuEquipment = oldTaiwuChar.GetEquipment().ToArray();
		oldTaiwuEquipment[4] = newTaiwuChar.GetEquipment()[4];
		if (clothingKey.IsValid() && !(Config.Clothing.Instance[clothingKey.TemplateId]?.KeepOnPassing ?? false))
		{
			emptyEquipments[4] = clothingKey;
		}
		oldTaiwuChar.ChangeEquipment(context, emptyEquipments);
		List<sbyte> ownedBookTypes = DomainManager.LegendaryBook.GetCharOwnedBookTypes(oldTaiwuCharId);
		if (ownedBookTypes != null)
		{
			for (int index = ownedBookTypes.Count - 1; index >= 0; index--)
			{
				sbyte bookType = ownedBookTypes[index];
				ItemKey itemKey = DomainManager.LegendaryBook.GetLegendaryBookItem(bookType);
				oldTaiwuChar.RemoveInventoryItem(context, itemKey, 1, deleteItem: false);
				_taiwuCharId = newTaiwuCharId;
				newTaiwuChar.AddInventoryItem(context, itemKey, 1);
				_taiwuCharId = oldTaiwuCharId;
			}
		}
		ItemKey[] array = oldTaiwuEquipment;
		for (int j = 0; j < array.Length; j++)
		{
			ItemKey itemKey2 = array[j];
			if (itemKey2.IsValid())
			{
				DomainManager.Item.UpdateMysteryEffect(context, itemKey2.Id);
			}
		}
		Dictionary<ItemKey, int> inventoryItems = oldTaiwuChar.GetInventory().Items;
		foreach (KeyValuePair<ItemKey, int> item in inventoryItems)
		{
			DomainManager.Item.RemoveOwner(item.Key, ItemOwnerType.CharacterInventory, oldTaiwuCharId);
			newTaiwuChar.AddInventoryItem(context, item.Key, item.Value);
		}
		oldTaiwuChar.SetInventory(new Inventory(), context);
		newTaiwuChar.ChangeEquipment(context, oldTaiwuEquipment);
		ResourceInts oldTaiwuResources = oldTaiwuChar.GetResources();
		newTaiwuChar.ChangeResources(context, ref oldTaiwuResources);
		oldTaiwuResources.Initialize();
		oldTaiwuChar.SetResources(ref oldTaiwuResources, context);
		newTaiwuChar.ChangeExp(context, oldTaiwuChar.GetExp());
		oldTaiwuChar.SetExp(0, context);
		DomainManager.Information.TransferInformation(oldTaiwuCharId, newTaiwuCharId, context);
		if (randomSuccessor)
		{
			HashSet<int> groupCharSet = ObjectPool<HashSet<int>>.Instance.Get();
			groupCharSet.Clear();
			groupCharSet.UnionWith(_groupCharIds.GetCollection());
			_groupCharIds.Remove(oldTaiwuCharId);
			foreach (int charId in _groupCharIds.GetCollection())
			{
				if (DomainManager.Character.GetElement_Objects(charId).GetAgeGroup() != 0)
				{
					groupCharSet.Add(charId);
				}
			}
			foreach (int charId2 in groupCharSet)
			{
				if (charId2 != oldTaiwuCharId && _groupCharIds.Contains(charId2))
				{
					LeaveGroup(context, charId2, bringWards: true, showNotification: false);
				}
			}
			_groupCharIds.Add(oldTaiwuCharId);
			ObjectPool<HashSet<int>>.Instance.Get();
			foreach (int charId3 in _groupCharIds.GetCollection())
			{
				if (charId3 != oldTaiwuCharId)
				{
					LeaveGroup(context, charId3, bringWards: true, showNotification: false);
				}
			}
			JoinGroup(context, newTaiwuCharId, showNotification: false);
			oldTaiwuChar.SetLeaderId(newTaiwuCharId, context);
			newTaiwuChar.SetLeaderId(newTaiwuCharId, context);
		}
		else
		{
			foreach (int charId4 in _groupCharIds.GetCollection())
			{
				GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId4);
				character.SetLeaderId(newTaiwuCharId, context);
			}
			DomainManager.Character.TransferKidnappedCharactersToTaiwuSuccessor(context, newTaiwuChar, oldTaiwuChar);
		}
		DomainManager.Character.TransferSpecialGroup(context, oldTaiwuCharId, newTaiwuCharId, clearDestGroupFirst: true);
		if (randomSuccessor)
		{
			newTaiwuChar.SetHappiness(50, context);
			List<FameActionRecord> fameActionRecords = newTaiwuChar.GetFameActionRecords();
			fameActionRecords.Clear();
			newTaiwuChar.SetFameActionRecords(fameActionRecords, context);
		}
		sbyte oldTaiwuFame = oldTaiwuChar.GetFame();
		sbyte oldTaiwuFameType = FameType.GetFameType(oldTaiwuFame);
		if (oldTaiwuFameType >= 5)
		{
			newTaiwuChar.RecordFameAction(context, 54, -1, 1);
		}
		else if (oldTaiwuFameType <= 1)
		{
			newTaiwuChar.RecordFameAction(context, 55, -1, 1);
		}
		DomainManager.Organization.ResetSectExploreStatuses(context);
		DomainManager.World.GetMonthlyEventCollection().Clear();
		DomainManager.World.TransferXiangshuAvatarRelations(context, oldTaiwuCharId, newTaiwuCharId);
		DomainManager.Extra.TransferRanshanThreeCorpsesRelations(context, oldTaiwuCharId, newTaiwuCharId);
		DomainManager.Extra.TransferGearMateFavorability(context, oldTaiwuCharId, newTaiwuCharId);
		DomainManager.Character.TransferFixedCharacterFavorability(context, oldTaiwuCharId, newTaiwuCharId);
		DomainManager.Organization.ResetSectExploreStatuses(context);
		DomainManager.Adventure.RemoveLegacyPassingAdventures(context);
		DomainManager.Building.SetShrineBuyTimes(0, context);
		DomainManager.Extra.ResetInteractOfLoveData(context);
		ProfessionSkillHandle.OnTaiwuDeath(context);
		ClearPrenatalEducationBonus(context);
		DomainManager.Extra.TaiwuWantedResetAllSectInteracted(context);
		DomainManager.Extra.ClearAllTaiwuInteractionCooldowns(context);
		DomainManager.Extra.TransferTaiwuArtisanOrder(context, newTaiwuCharId, oldTaiwuCharId);
		newTaiwuChar.SetCurrNeili(oldTaiwuChar.GetCurrNeili(), context);
		newTaiwuChar.SetExtraNeili(oldTaiwuChar.GetExtraNeili(), context);
		newTaiwuChar.SetBaseNeiliAllocation(oldTaiwuChar.GetBaseNeiliAllocation(), context);
		newTaiwuChar.SetExtraNeiliAllocation(oldTaiwuChar.GetExtraNeiliAllocation(), context);
		newTaiwuChar.SetExtraNeiliAllocationProgressWithHooks(oldTaiwuChar.GetExtraNeiliAllocationProgress().ToArray(), context);
		newTaiwuChar.SetConsummateLevel(oldTaiwuChar.GetConsummateLevel(), context);
		byte oldTaiwuImmunities = DomainManager.Extra.GetPoisonImmunities(oldTaiwuCharId);
		if (oldTaiwuImmunities != 0)
		{
			ref PoisonInts newTaiwuPoisoned = ref newTaiwuChar.GetPoisoned();
			for (sbyte poisonType = 0; poisonType < 6; poisonType++)
			{
				if (BitOperation.GetBit(oldTaiwuImmunities, poisonType))
				{
					newTaiwuPoisoned[poisonType] = 0;
				}
			}
			newTaiwuChar.SetPoisoned(ref newTaiwuPoisoned, context);
			DomainManager.Extra.AddPoisonImmunities(context, newTaiwuCharId, oldTaiwuImmunities);
			DomainManager.Extra.RemovePoisonImmunities(context, oldTaiwuCharId);
		}
		List<short> oldTaiwuFeatureIds = oldTaiwuChar.GetFeatureIds();
		for (short templateId = 0; templateId < CharacterFeature.Instance.Count; templateId++)
		{
			CharacterFeatureItem config = CharacterFeature.Instance[templateId];
			if (config.InheritableTransferTaiwu && oldTaiwuFeatureIds.Contains(templateId))
			{
				newTaiwuChar.AddFeature(context, templateId);
				oldTaiwuChar.RemoveFeature(context, templateId);
			}
		}
		OrganizationInfo taiwuOrgInfo = oldTaiwuChar.GetOrganizationInfo();
		if (_isTaiwuDying)
		{
			LeaveGroup(context, oldTaiwuCharId, bringWards: false, showNotification: false);
			short deathType = (short)((oldTaiwuChar.GetLeftMaxHealth() <= 0) ? 1 : 2);
			DomainManager.Character.MakeCharacterDead(context, oldTaiwuChar, deathType);
		}
		else
		{
			LeaveGroup(context, oldTaiwuCharId, bringWards: false);
			Events.RaiseXiangshuInfectionFeatureChanged(context, oldTaiwuChar, 211);
		}
		DomainManager.Organization.ChangeGrade(context, newTaiwuChar, taiwuOrgInfo.Grade, taiwuOrgInfo.Principal);
		newTaiwuChar.RemoveFeatureGroup(context, 590);
		_villagerFeatureHolderSet.Remove(newTaiwuCharId);
		VillagerRoleRecords records = DomainManager.Extra.GetVillagerRoleRecordsData();
		if (records.History.RemoveAll((VillagerRoleRecordElement rc) => rc.CharacterId == newTaiwuCharId) > 0)
		{
			DomainManager.Extra.SetVillagerRoleRecordsData(context, records);
		}
		DomainManager.Character.ClearAndInitAlertness(context, newTaiwuChar);
		UpdateMonitorsOnTaiwuForGuiding(newTaiwuCharId, oldTaiwuCharId);
	}

	private void CheckGuidingAfterTransferTaiwuData(DataContext context)
	{
		DomainManager.Global.CheckPregnantGuidingTrigger(context);
		DomainManager.Global.CheckHasTwoWayAdoredGuidingTrigger(context);
	}

	public void ApplyAndResetLegacy(DataContext context, GameData.Domains.Character.Character taiwuChar, bool isClearLegaciesBuilding = true)
	{
		if (isClearLegaciesBuilding)
		{
			ClearLegaciesBuildingTemplateIdList(context);
		}
		foreach (short selectedLegacyId in _selectedLegacies)
		{
			ApplyLegacyAffect(context, taiwuChar, selectedLegacyId);
		}
		ResetLegacy(context);
	}

