	public void ApplyLegacyAffect(DataContext context, GameData.Domains.Character.Character newTaiwuChar, short legacyTemplateId)
	{
		LegacyItem legacyConfig = Legacy.Instance[legacyTemplateId];
		if (legacyConfig.AddFeature >= 0)
		{
			newTaiwuChar.AddFeature(context, legacyConfig.AddFeature, removeMutexFeature: true);
		}
		if (legacyConfig.ModifiedProperty >= 0)
		{
			DomainManager.Taiwu.AddTaiwuPropertyPermanentBonus(context, (ECharacterPropertyReferencedType)legacyConfig.ModifiedProperty, (EDataModifyType)legacyConfig.PropertyBonusType, legacyConfig.PropertyDelta);
		}
		if (legacyConfig.TargetBehaviorType >= 0)
		{
			(short, short) moralityRange = GameData.Domains.Character.BehaviorType.Ranges[legacyConfig.TargetBehaviorType];
			int morality = context.Random.Next(moralityRange.Item1, moralityRange.Item2 + 1);
			newTaiwuChar.SetBaseMorality((short)morality, context);
		}
		if (legacyConfig.AddBuildingBlock >= 0)
		{
			BuildingBlockItem config = BuildingBlock.Instance[legacyConfig.AddBuildingBlock];
			if (BuildingBlockData.IsUsefulResource(config.Type))
			{
				List<short> list = DomainManager.Extra.GetLegaciesBuildingTemplateIdList();
				list.Add(legacyConfig.AddBuildingBlock);
				DomainManager.Extra.SetLegaciesBuildingTemplateIdList(list, context);
			}
			else
			{
				Location taiwuVillageLocation = GetTaiwuVillageLocation();
				DomainManager.Building.PlaceBuildingAtBlock(context, taiwuVillageLocation.AreaId, taiwuVillageLocation.BlockId, legacyConfig.AddBuildingBlock, forcePlace: false, isRandom: true);
			}
		}
		if (legacyConfig.AddBuildingCoreItem >= 0)
		{
			ItemKey itemKey = DomainManager.Item.CreateItem(context, 12, legacyConfig.AddBuildingCoreItem);
			DomainManager.Taiwu.WarehouseAdd(context, itemKey, 1);
		}
		if (legacyConfig.SpiritualDebtDelta != 0)
		{
			List<short> areaList = ObjectPool<List<short>>.Instance.Get();
			areaList.Clear();
			sbyte stateId = (sbyte)(legacyConfig.AffectingState - 1);
			DomainManager.Map.GetAllAreaInState(stateId, areaList);
			int spiritualDebt = 10 * legacyConfig.SpiritualDebtDelta;
			foreach (short areaId in areaList)
			{
				DomainManager.Extra.ChangeAreaSpiritualDebt(context, areaId, spiritualDebt);
			}
		}
		sbyte[] stateNewbornChildrenGrowingGrade = legacyConfig.StateNewbornChildrenGrowingGrade;
		if (stateNewbornChildrenGrowingGrade != null && stateNewbornChildrenGrowingGrade.Length != 0)
		{
			sbyte stateId2 = (sbyte)(legacyConfig.AffectingState - 1);
			PushStateNewCharacterLegacyGrowingGrades(context, stateId2, legacyConfig.StateNewbornChildrenGrowingGrade);
		}
		if (legacyConfig.AffectingOrganization >= 0)
		{
			sbyte[] supportingSectCharacterGrades = legacyConfig.SupportingSectCharacterGrades;
			foreach (sbyte grade in supportingSectCharacterGrades)
			{
				DomainManager.Organization.SelectRandomSectCharacterToApproveTaiwu(context, legacyConfig.AffectingOrganization, grade);
			}
		}
		if (legacyConfig.TargetNeiliProportionOfFiveElements.SumCheck() == 100)
		{
			newTaiwuChar.SetBaseNeiliProportionOfFiveElements(legacyConfig.TargetNeiliProportionOfFiveElements, context);
			DomainManager.Global.CheckFiveElementConflictGuidingTrigger(context, newTaiwuChar.GetNeiliType());
		}
		if (legacyConfig.PoisonImmunityCount > 0)
		{
			Span<sbyte> immuneTypes = stackalloc sbyte[6];
			for (sbyte i2 = 0; i2 < 6; i2++)
			{
				immuneTypes[i2] = i2;
			}
			CollectionUtils.Shuffle(context.Random, immuneTypes, 6);
			ref PoisonInts poisoned = ref newTaiwuChar.GetPoisoned();
			byte poisonImmunities = 0;
			for (int j = 0; j < legacyConfig.PoisonImmunityCount; j++)
			{
				sbyte type = immuneTypes[j];
				poisonImmunities = BitOperation.SetBit(poisonImmunities, type, bit: true);
				poisoned[j] = 0;
			}
			newTaiwuChar.SetPoisoned(ref poisoned, context);
			DomainManager.Extra.AddPoisonImmunities(context, newTaiwuChar.GetId(), poisonImmunities);
		}
		if (legacyConfig.TargetQualificationGrowthTypeLifeSkill >= 0)
		{
			newTaiwuChar.SetLifeSkillQualificationGrowthType(legacyConfig.TargetQualificationGrowthTypeLifeSkill, context);
		}
		if (legacyConfig.TargetQualificationGrowthTypeCombatSkill >= 0)
		{
			newTaiwuChar.SetCombatSkillQualificationGrowthType(legacyConfig.TargetQualificationGrowthTypeCombatSkill, context);
		}
	}

	public int CalcStarFortune(int rawPoint, int percent = 100)
	{
		LegacyPointItem configData = LegacyPoint.Instance[(short)46];
		int addValue = rawPoint * percent / 100;
		int settingsPercent = GetLegacySettingsPercent(configData);
		addValue = addValue * settingsPercent / 100;
		short taiwuSettlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		int buildingBuff = DomainManager.Building.GetBuildingBlockEffect(taiwuSettlementId, EBuildingScaleEffect.LegacyPointBonusFactor);
		return addValue * (100 + buildingBuff) / 100;
	}

	public CharacterPropertyBonus GetTaiwuPropertyPermanentBonus(ECharacterPropertyReferencedType propertyType)
	{
		CharacterPropertyBonus value = _taiwuPropertyPermanentBonuses.GetValueOrDefault((short)propertyType);
		if (value.IsZero)
		{
			return value;
		}
		if (propertyType == ECharacterPropertyReferencedType.MaxNeili)
		{
			return value;
		}
		if (!DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(43))
		{
			return value;
		}
		CValuePercentBonus bonus = 50;
		if (value.AddValue > 0)
		{
			value.AddValue *= bonus;
		}
		if (value.AddPercent > 0)
		{
			value.AddPercent *= bonus;
		}
		return value;
	}

	public void AddTaiwuPropertyPermanentBonus(DataContext context, ECharacterPropertyReferencedType propertyType, EDataModifyType bonusType, int bonusVal)
	{
		short propertyTypeShort = (short)propertyType;
		if (_taiwuPropertyPermanentBonuses.TryGetValue(propertyTypeShort, out var currBonus))
		{
			currBonus.AddBonus(bonusType, bonusVal);
			SetElement_TaiwuPropertyPermanentBonuses(propertyTypeShort, currBonus, context);
		}
		else
		{
			currBonus = default(CharacterPropertyBonus);
			currBonus.AddBonus(bonusType, bonusVal);
			AddElement_TaiwuPropertyPermanentBonuses(propertyTypeShort, currBonus, context);
		}
	}

