	[DomainMethod]
	public List<CharacterPropertyBonus> GetAllCharacterPropertyBonusData()
	{
		List<CharacterPropertyBonus> data = new List<CharacterPropertyBonus>();
		GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
		List<short> featureIds = taiwu.GetFeatureIds();
		for (ECharacterPropertyReferencedType propertyType = ECharacterPropertyReferencedType.Strength; propertyType < ECharacterPropertyReferencedType.Count; propertyType++)
		{
			CharacterPropertyBonus bonus = _taiwuPropertyPermanentBonuses.GetOrDefault((short)propertyType);
			foreach (short featureId in featureIds)
			{
				CharacterFeatureItem featureCfg = CharacterFeature.Instance[featureId];
				if (featureCfg.InheritableTransferTaiwu && featureCfg.CanCrossArchive)
				{
					bonus.AddValue += featureCfg.GetCharacterPropertyBonusInt(propertyType);
				}
			}
			data.Add(bonus);
		}
		return data;
	}

