	public void CalcSingleVillagerSkillLegacy(DataContext context, int charId)
	{
		if (!DomainManager.Character.TryGetElement_Objects(charId, out var character) || !DomainManager.Taiwu.HasInheritedTaiwuVillage())
		{
			return;
		}
		for (sbyte combatSkillType = 0; combatSkillType < 14; combatSkillType++)
		{
			short attainment = character.GetCombatSkillAttainment(combatSkillType);
			if (attainment >= GlobalConfig.Instance.VillagerSkillLegacyAttainmentRequirement && !GetVillagerCombatSkillLegacy(charId, combatSkillType))
			{
				SetVillagerCombatSkillLegacy(context, charId, combatSkillType);
				DomainManager.Taiwu.AddLegacyPoint(context, 25);
			}
		}
		for (sbyte lifeSkillType = 0; lifeSkillType < 16; lifeSkillType++)
		{
			short attainment2 = character.GetLifeSkillAttainment(lifeSkillType);
			if (attainment2 >= GlobalConfig.Instance.VillagerSkillLegacyAttainmentRequirement && !GetVillagerLifeSkillLegacy(charId, lifeSkillType))
			{
				SetVillagerLifeSkillLegacy(context, charId, lifeSkillType);
				DomainManager.Taiwu.AddLegacyPoint(context, 19);
			}
		}
	}

	public void CalcSingleVillagerSkillLegacy(DataContext context, DataUid uid)
	{
		if (uid.DomainId == 4 && uid.DataId == 0)
		{
			CalcSingleVillagerSkillLegacy(context, (int)uid.SubId0);
		}
	}

	private bool GetVillagerCombatSkillLegacy(int charId, sbyte combatSkillType)
	{
		return GetVillagerSkillLegacy(charId, combatSkillType);
	}

	private bool GetVillagerLifeSkillLegacy(int charId, sbyte lifeSkillType)
	{
		return GetVillagerSkillLegacy(charId, 14 + lifeSkillType);
	}

	private bool GetVillagerSkillLegacy(int charId, int index)
	{
		if (_villagerSkillLegacyPointDict.TryGetValue(charId, out var value))
		{
			return (value & (1 << index)) != 0;
		}
		return false;
	}

	private void SetVillagerCombatSkillLegacy(DataContext context, int charId, sbyte combatSkillType)
	{
		SetVillageSkillLegacy(context, charId, combatSkillType);
	}

	private void SetVillagerLifeSkillLegacy(DataContext context, int charId, sbyte lifeSkillType)
	{
		SetVillageSkillLegacy(context, charId, 14 + lifeSkillType);
	}

	private void SetVillageSkillLegacy(DataContext context, int charId, int index)
	{
		Tester.Assert(index >= 0 && index < 30);
		if (_villagerSkillLegacyPointDict.TryGetValue(charId, out var value))
		{
			value |= 1 << index;
			SetElement_VillagerSkillLegacyPointDict(charId, value, context);
		}
		else
		{
			value |= 1 << index;
			AddElement_VillagerSkillLegacyPointDict(charId, value, context);
		}
	}

	public void RemoveVillageSkillLegacy(DataContext context, int charId)
	{
		if (_villagerSkillLegacyPointDict.ContainsKey(charId))
		{
			RemoveElement_VillagerSkillLegacyPointDict(charId, context);
			UnRegisterVillagerSkillLegacyPoint(charId);
		}
	}

	public void RegisterVillagerSkillLegacyPoint()
	{
		short settlementId = DomainManager.Taiwu.GetTaiwuVillageSettlementId();
		Settlement settlement = DomainManager.Organization.GetSettlement(settlementId);
		List<int> charList = ObjectPool<List<int>>.Instance.Get();
		settlement.GetMembers().GetAllMembers(charList);
		charList.Remove(DomainManager.Taiwu.GetTaiwuCharId());
		foreach (int charId in charList)
		{
			UnRegisterVillagerSkillLegacyPoint(charId);
			RegisterVillagerSkillLegacyPoint(charId);
		}
		ObjectPool<List<int>>.Instance.Return(charList);
	}

	public void RegisterVillagerSkillLegacyPoint(int charId)
	{
		DataUid lifeSkillAttainments = new DataUid(4, 0, (ulong)charId, 97u);
		DataUid combatSkillAttainments = new DataUid(4, 0, (ulong)charId, 99u);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(lifeSkillAttainments, "CalcSingleVillagerSkillLegacy", CalcSingleVillagerSkillLegacy);
		GameData.GameDataBridge.GameDataBridge.AddPostDataModificationHandler(combatSkillAttainments, "CalcSingleVillagerSkillLegacy", CalcSingleVillagerSkillLegacy);
	}

	public void UnRegisterVillagerSkillLegacyPoint(int charId)
	{
		DataUid lifeSkillAttainments = new DataUid(4, 0, (ulong)charId, 97u);
		DataUid combatSkillAttainments = new DataUid(4, 0, (ulong)charId, 99u);
		GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(lifeSkillAttainments, "CalcSingleVillagerSkillLegacy");
		GameData.GameDataBridge.GameDataBridge.RemovePostDataModificationHandler(combatSkillAttainments, "CalcSingleVillagerSkillLegacy");
	}

