	[DomainMethod]
	public void RecordLifeSummary(DataContext context, int templateId, int delta = 1)
	{
		if (DomainManager.Global.GetCurrGameWorldType() != 1 || DomainManager.Combat.GetIsPuppetCombat() || !DomainManager.Combat.NotInCombatOrTaiwuInCombat)
		{
			return;
		}
		if (!TaiwuLifeSummaryType.Instance[templateId].IsDate)
		{
			_currTaiwuLifeSummary.Record(templateId, delta);
		}
		else
		{
			if (_currTaiwuLifeSummary.Contains(templateId))
			{
				return;
			}
			_currTaiwuLifeSummary.Set(templateId, DomainManager.World.GetCurrDate());
		}
		SetCurrTaiwuLifeSummary(_currTaiwuLifeSummary, context);
	}

	private void ArchiveCurrentTaiwuLifeSummaries(DataContext context, int newTaiwuCharId)
	{
		TaiwuLifeSummary currTaiwuLifeSummary = _currTaiwuLifeSummary;
		if (currTaiwuLifeSummary != null && currTaiwuLifeSummary.IsValid)
		{
			AbridgedCharacter abridgedChar = DomainManager.Character.GetAbridgeCharacter(_currTaiwuLifeSummary.TaiwuCharId);
			_currTaiwuLifeSummary.Archive(abridgedChar);
			_prevTaiwuLifeSummaries.Add(_currTaiwuLifeSummary);
			SetPrevTaiwuLifeSummaries(_prevTaiwuLifeSummaries, context);
		}
		_currTaiwuLifeSummary = new TaiwuLifeSummary(newTaiwuCharId);
		SetCurrTaiwuLifeSummary(_currTaiwuLifeSummary, context);
	}

