	public TaiwuLifeSummaryDisplayData GetTaiwuLifeSummaryDisplayData()
	{
		TaiwuLifeSummaryDisplayData taiwuLifeSummaryDisplayData = new TaiwuLifeSummaryDisplayData();
		taiwuLifeSummaryDisplayData.TotalTaiwuLifeSummaries = _prevTaiwuLifeSummaries.Concat(new TaiwuLifeSummary[1] { _currTaiwuLifeSummary }).ToList();
		taiwuLifeSummaryDisplayData.TotalTaiwuDisplayDatas = DomainManager.Character.GetCharacterDisplayDataList(GetPreviousTaiwuIds().Concat(new int[1] { GetTaiwu().GetId() }).ToList());
		return taiwuLifeSummaryDisplayData;
	}

	[DomainMethod]
	public TotalTaiwuLifeSummaryInfo GetTotalTaiwuLifeSummaryInfo()
	{
		List<int> taiwuIds = GetPreviousTaiwuIds().Concat(new int[1] { GetTaiwu().GetId() }).ToList();
		List<string> totalTaiwuSurnames = taiwuIds.Select(delegate(int x)
		{
			DomainManager.Character.TryGetElement_Objects(x, out var element);
			NameRelatedData data = new NameRelatedData();
			if (element != null)
			{
				CharacterDomain.GetNameRelatedData(element, ref data);
				return data.GetDisplayNameDetailed(isTaiwu: true, ignoreNickName: true).surname;
			}
			if (DomainManager.Character.TryGetDeadCharacter(x, out var character))
			{
				CharacterDomain.GetNameRelatedData(x, character, ref data);
				return data.GetDisplayNameDetailed(isTaiwu: true, ignoreNickName: true).surname;
			}
			return string.Empty;
		}).ToList();
		List<string> totalTaiwuGivenNames = taiwuIds.Select(delegate(int x)
		{
			DomainManager.Character.TryGetElement_Objects(x, out var element);
			NameRelatedData data = new NameRelatedData();
			if (element != null)
			{
				CharacterDomain.GetNameRelatedData(element, ref data);
				return data.GetDisplayNameDetailed(isTaiwu: true, ignoreNickName: true).givenName;
			}
			if (DomainManager.Character.TryGetDeadCharacter(x, out var character))
			{
				CharacterDomain.GetNameRelatedData(x, character, ref data);
				return data.GetDisplayNameDetailed(isTaiwu: true, ignoreNickName: true).givenName;
			}
			return string.Empty;
		}).ToList();
		List<short> temp = new List<short>();
		List<short> totalTaiwuTitleIds = ((IEnumerable<int>)taiwuIds).Select((Func<int, short>)delegate(int x)
		{
			DomainManager.Character.TryGetElement_Objects(x, out var element);
			if (element == null)
			{
				return -1;
			}
			element.GetTitles(temp);
			return (short)((temp.Count > 0) ? temp[0] : (-1));
		}).ToList();
		TotalTaiwuLifeSummaryInfo totalTaiwuLifeSummaryInfo = new TotalTaiwuLifeSummaryInfo();
		totalTaiwuLifeSummaryInfo.TotalTaiwuLifeSummaries = _prevTaiwuLifeSummaries.Concat(new TaiwuLifeSummary[1] { _currTaiwuLifeSummary }).ToList();
		totalTaiwuLifeSummaryInfo.TotalTaiwuAvatarRelatedDatas = DomainManager.Character.GetAvatarRelatedDataListIncludeDead(taiwuIds);
		totalTaiwuLifeSummaryInfo.TotalTaiwuSurnames = totalTaiwuSurnames;
		totalTaiwuLifeSummaryInfo.TotalTaiwuGivenNames = totalTaiwuGivenNames;
		totalTaiwuLifeSummaryInfo.TotalTaiwuTitleIds = totalTaiwuTitleIds;
		return totalTaiwuLifeSummaryInfo;
	}

	[DomainMethod]
	public void SetReferenceCombatSkillAt(DataContext context, int index, short combatSkillTemplateId)
	{
		if (!IsReferenceSkillSlotUnlocked(index))
		{
			throw new InvalidOperationException("Reference skill slot is locked.");
		}
		List<short> referenceSkillList1 = DomainManager.Extra.GetReferenceSkillList() ?? new List<short>();
		while (referenceSkillList1.Count < 3)
		{
			referenceSkillList1.Add(-1);
		}
		List<short> referenceSkillList2 = referenceSkillList1;
		referenceSkillList2[index] = combatSkillTemplateId;
		DomainManager.Extra.SetReferenceSkillList(referenceSkillList2, context);
		short loopingNeigong = _taiwuChar.GetLoopingNeigong();
		TryRemoveLoopingEvent(context, loopingNeigong);
	}

	[DomainMethod]
	public void SetTaiwuLoopingNeigong(DataContext context, short combatSkillTemplateId)
	{
		short loopingNeigong = _taiwuChar.GetLoopingNeigong();
		if (combatSkillTemplateId != loopingNeigong)
		{
			TryRemoveLoopingEvent(context, loopingNeigong);
			_taiwuChar.SetLoopingNeigong(combatSkillTemplateId, context);
		}
	}

	private void TryRemoveLoopingEvent(DataContext context, short loopingNeigong)
	{
		List<short> hasEventSkillIdList = DomainManager.Extra.GetLoopingEventSkillIdList();
		if (hasEventSkillIdList.Contains(loopingNeigong))
		{
			hasEventSkillIdList.Remove(loopingNeigong);
			DomainManager.Extra.SetLoopingEventSkillIdList(hasEventSkillIdList, context);
		}
	}

	public bool IsReferenceSkillSlotUnlocked(int slotIndex)
	{
