	public void SetAutoAllocateNeiliToMax(bool value)
	{
		_autoAllocateNeiliToMax = value;
	}

	public void UpdateTaiwuNeiliAllocation(DataContext context, bool isInCombat = false)
	{
		if (_autoAllocateNeiliToMax)
		{
			NeiliAllocation taiwuMaxNeiliAllocation = DomainManager.Extra.GetTaiwuMaxNeiliAllocation();
			UpdateTaiwuNeiliAllocation(context, taiwuMaxNeiliAllocation, isInCombat);
		}
	}

	public void UpdateTaiwuNeiliAllocation(DataContext context, NeiliAllocation targetAllocation, bool isInCombat = false)
	{
		if (_autoAllocateNeiliToMax)
		{
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			NeiliAllocation currNeiliAllocation = taiwu.GetBaseNeiliAllocation();
			int currNeili = taiwu.GetCurrNeili();
			int maxNeili = taiwu.GetMaxNeili();
			short maxTotalAllocation = CombatHelper.GetMaxTotalNeiliAllocationConsideringFeature(taiwu.GetConsummateLevel(), taiwu.GetFeatureIds(), DomainManager.World.GetChallengeModeData());
			if (isInCombat)
			{
				short disorderOfQi = taiwu.GetDisorderOfQi();
				sbyte disorderLevel = DisorderLevelOfQi.GetDisorderLevelOfQi(disorderOfQi);
				sbyte neiliCostPercentage = QiDisorderEffect.Instance[disorderLevel].NeiliCostInCombat;
				CombatHelper.TryAllocateToTargetAllocation(targetAllocation, ref currNeiliAllocation, maxNeili, ref currNeili, maxTotalAllocation, neiliCostPercentage);
			}
			else
			{
				CombatHelper.TryAllocateToTargetAllocation(targetAllocation, ref currNeiliAllocation, maxNeili, ref currNeili, maxTotalAllocation);
			}
			taiwu.SetBaseNeiliAllocation(currNeiliAllocation, context);
			taiwu.SpecifyCurrNeili(context, currNeili);
		}
	}

	[DomainMethod]
	public unsafe void ActiveNeigongLoopingOnce(DataContext context)
	{
		int dayCost = GlobalConfig.Instance.ActiveNeigongLoopingTimeCost;
		MainAttributes mainAttributes = _taiwuChar.GetCurrMainAttributes();
		short concentrationCost = GlobalConfig.Instance.ActiveNeigongLoopingAttributeCost;
		short curInt = mainAttributes.Items[2];
		if (DomainManager.World.GetLeftDaysInCurrMonth() < dayCost)
		{
			Logger.Warn("You don't have enough days in this month");
			return;
		}
		if (concentrationCost > curInt)
		{
			Logger.Warn($"You don't have enough intelligence: {concentrationCost} needed, current int is {curInt}");
			return;
		}
		AdventureTaiwu adventureTaiwu = DomainManager.Adventure.GetAdventureTaiwu();
		if (!adventureTaiwu.InAdventure)
		{
			DomainManager.World.AdvanceDaysInMonth(context, dayCost);
		}
		else if (!DomainManager.Adventure.ConsumeActionPointInAdventure(context, dayCost * 10))
		{
			return;
		}
		if (concentrationCost > 0)
		{
			_taiwuChar.ChangeCurrMainAttribute(context, 2, -concentrationCost);
		}
		short maxProgress = GlobalConfig.Instance.MaxActiveNeigongLoopingProgress;
		short oldProgress = DomainManager.Extra.GetActiveLoopingProgress();
		int newProgress = oldProgress + 1;
		if (newProgress <= maxProgress)
		{
			DomainManager.Extra.SetActiveLoopingProgress((short)newProgress, context);
			bool isTen = newProgress % 10 == 0;
			int efficiency = GlobalConfig.Instance.ActiveLoopProgressAffectedEfficiency[oldProgress / 10];
			if (isTen)
			{
				ApplyNeigongLoopingImprovementOnce(context, efficiency);
			}
		}
	}

	public void ApplyNeigongLoopingImprovementOnce(DataContext context, int efficiency = 100)
	{
		if (_taiwuChar.GenerateNeigongLoopingImprovementForTaiwu(context, out var neili, out var qiDisorder, out var extraNeiliAllocationProgress))
		{
			neili = (short)(neili * efficiency / 100);
			qiDisorder = (short)(qiDisorder * efficiency / 100);
			for (int i = 0; i < extraNeiliAllocationProgress.Length; i++)
			{
				extraNeiliAllocationProgress[i] = extraNeiliAllocationProgress[i] * efficiency / 100;
			}
			DomainManager.CombatSkill.ApplyNeigongLoopingEffect(context, _taiwuChar, _taiwuChar.GetLoopingNeigong(), neili, extraNeiliAllocationProgress);
			if (qiDisorder != 0)
			{
				_taiwuChar.ChangeDisorderOfQiRandomRecovery(context, qiDisorder);
			}
			DomainManager.Story.UpdateBaihuaLifeLinkNeiliType(context);
		}
	}

	[DomainMethod]
	public void GmCmd_TaiwuActiveLoopingApply(DataContext context)
	{
		ApplyNeigongLoopingImprovementOnce(context);
	}

	public void ClearActiveNeigongLoopingProgressOnMonthChange(DataContext context)
	{
		short nowProgress = DomainManager.Extra.GetActiveLoopingProgress();
		int newProgress = nowProgress % 10;
		DomainManager.Extra.SetActiveLoopingProgress((short)newProgress, context);
	}

	[DomainMethod]
	public ProfessionTipDisplayData GetProfessionTipDisplayData(int professionId)
	{
		var (workingSkillType, attainmentBonus) = GetWorkingSkillTypeAndBonus();
		return new ProfessionTipDisplayData
		{
			ProfessionId = professionId,
			WorkingSkillType = workingSkillType,
			AttainmentBonus = attainmentBonus,
			ProfessionUpgrade = DomainManager.World.GetProfessionUpgrade(),
			ProfessionUpgradeBonus = ExtraDomain.GetWorldProfessionUpgradePercent(),
			IsWearingBonusClothing = IsWearingBonusClothing()
		};
		(sbyte, int) GetWorkingSkillTypeAndBonus()
		{
			ProfessionItem config = Config.Profession.Instance[professionId];
			GameData.Domains.Character.Character taiwu = DomainManager.Taiwu.GetTaiwu();
			int factor = 100;
			sbyte workingSkillType2 = -1;
			if (config.BonusLifeSkills != null)
			{
				short bestAttainment = 0;
				foreach (sbyte lifeSkillType in config.BonusLifeSkills)
				{
					short attainment = taiwu.GetLifeSkillAttainment(lifeSkillType);
					if (attainment > bestAttainment)
					{
						bestAttainment = attainment;
						workingSkillType2 = lifeSkillType;
					}
				}
				factor += bestAttainment / 3;
			}
			if (config.BonusCombatSkills != null)
			{
				short bestAttainment2 = 0;
				foreach (sbyte combatSkillType in config.BonusCombatSkills)
				{
					short attainment2 = taiwu.GetCombatSkillAttainment(combatSkillType);
					if (attainment2 > bestAttainment2)
					{
						bestAttainment2 = attainment2;
						workingSkillType2 = combatSkillType;
					}
				}
				factor += bestAttainment2 / 3;
			}
			return (workingSkillType2, factor);
		}
		bool IsWearingBonusClothing()
		{
			ItemKey clothingKey = _taiwuChar.GetEquipment()[4];
			if (!clothingKey.IsValid() || DomainManager.Item.GetBaseItem(clothingKey).IsDurabilityRunningOut())
			{
				return false;
			}
			ProfessionItem professionConfig = Config.Profession.Instance[professionId];
			return professionConfig.BonusClothing == clothingKey.TemplateId;
		}
	}

	[DomainMethod]
	public ChangeWeaponTrickDisplayData GetChangeWeaponTrickDisplayData(DataContext context)
	{
		ChangeWeaponTrickDisplayData data = new ChangeWeaponTrickDisplayData
		{
			InventoryItemList = DomainManager.Taiwu.GetAllItems(ItemSourceType.Inventory).list,
			WarehouseItemList = DomainManager.Taiwu.GetAllItems(ItemSourceType.Warehouse).list,
			TreasuryItemList = DomainManager.Taiwu.GetAllItems(ItemSourceType.Treasury).list,
			StockItemList = DomainManager.Taiwu.GetAllItems(ItemSourceType.Stock).list,
			CanTransferItemToWarehouse = DomainManager.Taiwu.CanTransferItemToWarehouse(context),
			AllMaterialInventory = new Inventory(),
			LifeSkillAttainments = DomainManager.Taiwu.GetTaiwu().GetLifeSkillAttainments(),
			EmptyToolKey = DomainManager.Item.GetEmptyToolKey(context)
		};
		data.InventoryItemList.AddRange(DomainManager.Taiwu.GetAllItems(ItemSourceType.Equipment).list);
		AddMaterial(data.InventoryItemList);
		if (data.CanTransferItemToWarehouse)
		{
			AddMaterial(data.WarehouseItemList);
			AddMaterial(data.TreasuryItemList);
			AddMaterial(data.StockItemList);
		}
		return data;
		void AddMaterial(List<ItemDisplayData> list)
		{
			foreach (ItemDisplayData itemData in list)
			{
				if (itemData.RealKey.ItemType == 5)
				{
					MaterialItem config = Config.Material.Instance[itemData.RealKey.TemplateId];
					if (config.CraftableItemTypes.Count > 0)
					{
						data.AllMaterialInventory.OfflineAdd(itemData.RealKey, itemData.Amount);
					}
				}
			}
		}
	}

	[DomainMethod]
	public int GetWineTasterBonusPercentage()
	{
		if (!DomainManager.Extra.IsProfessionalSkillUnlockedAndEquipped(30))
		{
			return 0;
		}
		HashSet<short> wine = new HashSet<short>();
		EatingItems eatingItems = DomainManager.Taiwu.GetTaiwu().GetEatingItems();
		for (int i = 0; i < 9; i++)
		{
			ItemKey itemKey = eatingItems.Get(i);
			if (itemKey.IsValid() && ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId) == 901)
			{
				wine.Add(itemKey.TemplateId);
			}
		}
		return wine.Count * DomainManager.Extra.GetProfessionData(7).GetSeniorityPercent() / GlobalConfig.Instance.WineTasterSkill2Factor;
	}

	public bool IsProfessionSkillRequiresExpEnabled()
	{
		return DomainManager.World.IsChallengeModeEnabled(EChallengeModeImplement.ProfessionSkillRequiresExp);
	}

	public int CalcProfessionSkillLearnExpCost()
	{
		if (!IsProfessionSkillRequiresExpEnabled())
		{
			return 0;
		}
		int[] scores = GlobalConfig.Instance.ChallengeProfessionSkillLearnScores;
		int multiplier = GlobalConfig.Instance.ChallengeProfessionSkillLearnExpMultiplier;
		int totalScore = 0;
		foreach (ProfessionItem professionCfg in (IEnumerable<ProfessionItem>)Config.Profession.Instance)
		{
			ProfessionData professionData = DomainManager.Extra.GetProfessionData(professionCfg.TemplateId);
			if (professionData == null)
			{
				continue;
			}
			int skillCount = professionData.GetSkillCount();
			for (int i = 0; i < skillCount && i < scores.Length; i++)
			{
				if (professionData.IsSkillLearned(i))
				{
					totalScore += scores[i];
				}
			}
		}
		return totalScore * multiplier;
	}

	public bool IsProfessionalSkillPendingLearn(int professionId, int skillIndex)
	{
		if (!IsProfessionSkillRequiresExpEnabled())
		{
			return false;
		}
		ProfessionData professionData = DomainManager.Extra.GetProfessionData(professionId);
		if (professionData == null)
		{
			return false;
		}
		return professionData.IsSkillUnlocked(skillIndex) && !professionData.IsSkillLearned(skillIndex);
	}

	[DomainMethod]
	public bool LearnProfessionSkill(DataContext context, int professionId, int skillIndex)
	{
		if (!IsProfessionSkillRequiresExpEnabled())
		{
			return false;
		}
		ProfessionData professionData = DomainManager.Extra.GetProfessionData(professionId);
		if (professionData == null)
		{
			return false;
		}
		if (!professionData.IsSkillUnlocked(skillIndex))
		{
			return false;
		}
		if (professionData.IsSkillLearned(skillIndex))
		{
			return false;
		}
		int expCost = CalcProfessionSkillLearnExpCost();
		GameData.Domains.Character.Character taiwu = GetTaiwu();
		if (taiwu.GetExp() < expCost)
		{
			return false;
		}
		taiwu.ChangeExp(context, -expCost);
		professionData.SetSkillLearned(skillIndex);
		DomainManager.Extra.SetProfessionData(context, professionData);
		int skillTemplateId = GameData.Domains.Taiwu.Profession.SharedMethods.GetSkillId(professionId, skillIndex);
		GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.OpenProfessionSkillUnlocked, skillTemplateId, DomainManager.World.GetAdvancingMonthState() == 0);
		return true;
	}

	[DomainMethod]
	public void SetQiArtStrategy(DataContext context, int index, sbyte templateId)
	{
		if (index >= GlobalConfig.Instance.MaxQiArtStrategyCount)
		{
			throw new ArgumentOutOfRangeException("index", index, "index should be less than MaxQiArtStrategyCount");
		}
		if (templateId < 0)
		{
			throw new ArgumentOutOfRangeException("templateId", templateId, "templateId should be greater than or equal to 0");
		}
		QiArtStrategyItem config = QiArtStrategy.Instance[templateId];
		if (!TryCost(context, config))
		{
			throw new ArgumentException("Concentration or Neili not enough", "templateId");
		}
		short loopingNeigong = _taiwuChar.GetLoopingNeigong();
		if (loopingNeigong < 0)
		{
			throw new Exception("should have looping neigong");
		}
		SByteList qiArtStrategyList = DomainManager.Extra.GetOrInitQiArtStrategies(context, loopingNeigong);
		while (index >= qiArtStrategyList.Items.Count)
		{
			qiArtStrategyList.Items.Add(-1);
		}
		IntList expireList = DomainManager.Extra.GetOrInitQiArtStrategyExpireTimeList(context, loopingNeigong);
		while (index >= expireList.Items.Count)
		{
			expireList.Items.Add(-1);
		}
		PreProcessInstantQiArtStrategy(context, config, qiArtStrategyList);
		qiArtStrategyList.Items[index] = templateId;
		expireList.Items[index] = config.Duration + DomainManager.World.GetCurrDate();
		RemoveOtherEffectInSameGroup(qiArtStrategyList.Items, expireList.Items, index);
		RemoveOtherEffectByConfig(qiArtStrategyList.Items, expireList.Items, index);
		ProcessInstantQiArtStrategy(context, config);
		DomainManager.Extra.SetQiArtStrategies(context, loopingNeigong, qiArtStrategyList);
		DomainManager.Extra.SetQiArtStrategyExpireTimeList(context, loopingNeigong, expireList);
		DomainManager.Taiwu.RecordLifeSummary(context, 53);
		short concentrationCost = config.ConcentrationCost;
		_currentLoopingEventCostedConcentration += concentrationCost;
	}

