				return 0;
			}
			int bonus = 0;
			foreach (sbyte id in qiArtStrategyList.Items)
			{
				if (id != -1)
				{
					QiArtStrategyItem config = QiArtStrategy.Instance[id];
					bonus += GetRandomBetween(random, config.MinExtraNeiliAllocation, config.MaxExtraNeiliAllocation);
				}
			}
			return bonus;
		}
		return 0;
	}

	public (int min, int max) GetQiArtStrategyExtraNeiliAllocationBonusRange()
	{
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short loopingNeigongTemplateId = taiwuChar.GetLoopingNeigong();
		if (DomainManager.Extra.TryGetElement_QiArtStrategyMap(loopingNeigongTemplateId, out var qiArtStrategyList))
		{
			if (qiArtStrategyList.Items.Count == 0)
			{
				return (min: 0, max: 0);
			}
			int min = 0;
			int max = 0;
			foreach (sbyte id in qiArtStrategyList.Items)
			{
				if (id != -1)
				{
					QiArtStrategyItem config = QiArtStrategy.Instance[id];
					min += config.MinExtraNeiliAllocation;
					max += config.MaxExtraNeiliAllocation;
				}
			}
			return (min: min, max: max);
		}
		return (min: 0, max: 0);
	}

	public void ClearExpiredQiArtStrategies(DataContext context)
	{
		foreach (KeyValuePair<short, SByteList> item in DomainManager.Extra.GetQiArtStrategyMapEnumerable())
		{
			item.Deconstruct(out var key, out var value);
			short combatSkillTid = key;
			SByteList qiArtStrategyList = value;
			IntList expireList = DomainManager.Extra.GetElement_QiArtStrategyExpireTimeMap(combatSkillTid);
			int currentDate = DomainManager.World.GetCurrDate();
			for (int i = 0; i < expireList.Items.Count; i++)
			{
				sbyte id = qiArtStrategyList.Items[i];
				if (id != -1 && currentDate >= expireList.Items[i])
				{
					qiArtStrategyList.Items[i] = -1;
					expireList.Items[i] = -1;
				}
			}
			DomainManager.Extra.SetQiArtStrategyExpireTimeList(context, combatSkillTid, expireList);
			DomainManager.Extra.SetQiArtStrategies(context, combatSkillTid, qiArtStrategyList);
		}
	}

	public bool TryAddLoopingEvent(DataContext context, int basePercentProb)
	{
		int finalProb = basePercentProb;
		List<short> referenceSkills = DomainManager.Extra.GetReferenceSkillList();
		int possibleQiArtStrategyCount = 0;
		if (referenceSkills != null && referenceSkills.Count > 0)
		{
			foreach (short referenceSkillId in referenceSkills)
			{
				if (referenceSkillId != -1)
				{
					CombatSkillItem config = Config.CombatSkill.Instance[referenceSkillId];
					finalProb += config.QiArtStrategyGenerateProbability;
					possibleQiArtStrategyCount += config.PossibleQiArtStrategyList.Count;
				}
			}
		}
		if (possibleQiArtStrategyCount <= 0)
		{
			return false;
		}
		if (!context.Random.CheckPercentProb(finalProb))
		{
			return false;
		}
		return AddLoopingEvent(context);
	}

	public bool AddLoopingEvent(DataContext context)
	{
		_currentLoopingEventCostedConcentration = 0;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short loopingNeigongTemplateId = taiwuChar.GetLoopingNeigong();
		if (loopingNeigongTemplateId < 0)
		{
			return false;
		}
		List<short> qiArtStrategySkillIdList = DomainManager.Extra.GetLoopingEventSkillIdList();
		if (qiArtStrategySkillIdList.Contains(loopingNeigongTemplateId))
		{
			return false;
		}
		qiArtStrategySkillIdList.Add(loopingNeigongTemplateId);
		DomainManager.Extra.SetLoopingEventSkillIdList(qiArtStrategySkillIdList, context);
		GenerateAvailableQiArtStrategies(context, loopingNeigongTemplateId);
		return true;
	}

	private void GenerateAvailableQiArtStrategies(DataContext context, short loopingNeigongTemplateId)
	{
		QiArtStrategy qiArtConfig = QiArtStrategy.Instance;
		List<List<sbyte>> groupedResult = new List<List<sbyte>>();
		for (int i = 0; i < 2; i++)
		{
			groupedResult.Add(new List<sbyte>());
		}
		sbyte loopingNeigongProvidedStrategy = DrawOneByNeigong(loopingNeigongTemplateId, context.Random);
		if (loopingNeigongProvidedStrategy != -1)
		{
			groupedResult[qiArtConfig[loopingNeigongProvidedStrategy].ExtractGroup - 1].Add(loopingNeigongProvidedStrategy);
		}
		List<short> referenceSkillList = DomainManager.Extra.GetReferenceSkillList();
		if (referenceSkillList != null && referenceSkillList.Count > 0)
		{
			foreach (short refSkill in referenceSkillList)
			{
				if (refSkill == -1)
				{
					continue;
				}
				sbyte refSkillProvidedStrategy = DrawOneByNeigong(refSkill, context.Random);
				if (refSkillProvidedStrategy != -1)
				{
					List<sbyte> targetResultGroup = groupedResult[qiArtConfig[refSkillProvidedStrategy].ExtractGroup - 1];
					if (targetResultGroup.Count < 3)
					{
						targetResultGroup.Add(refSkillProvidedStrategy);
					}
				}
			}
		}
		List<sbyte> validConfigGroup = new List<sbyte>();
		List<short> weightList = new List<short>();
		for (int j = 0; j < 2; j++)
		{
			validConfigGroup.Clear();
			weightList.Clear();
			foreach (QiArtStrategyItem config in (IEnumerable<QiArtStrategyItem>)qiArtConfig)
			{
				sbyte id = config.TemplateId;
				if (config.ExtractGroup - 1 == j && CanDrawStrategy(id, -1))
				{
					validConfigGroup.Add(id);
					weightList.Add(config.ExtractWeight);
				}
			}
			while (groupedResult[j].Count < 3)
			{
				int randIndex = RandomUtils.GetRandomIndex(weightList, context.Random);
				sbyte drawnConfigIndex = validConfigGroup[randIndex];
				groupedResult[j].Add(drawnConfigIndex);
			}
		}
		List<sbyte> result = new List<sbyte>();
		foreach (List<sbyte> group in groupedResult)
		{
			result.AddRange(group);
		}
		if (DomainManager.Extra.IsProfessionalSkillUnlocked(3, 1))
		{
			int seniority = DomainManager.Extra.GetProfessionData(3).Seniority;
			int extraCount = ProfessionData.SeniorityToExtraReadingLoopingStrategyCount(seniority);
			for (int k = 0; k < extraCount; k++)
			{
				int strategyTid = context.Random.Next(QiArtStrategy.Instance.Count);
				result.Add((sbyte)strategyTid);
			}
		}
		DomainManager.Extra.SetAvailableQiArtStrategiesForNeigong(context, loopingNeigongTemplateId, new SByteList(result));
	}

	private sbyte DrawOneByNeigong(short sourceNeigongTemplateId, IRandomSource randomSource)
	{
		CombatSkillItem skillConfig = Config.CombatSkill.Instance[sourceNeigongTemplateId];
		List<sbyte> configPossibleStrategies = skillConfig.PossibleQiArtStrategyList;
		List<sbyte> possibleStrategies = new List<sbyte>();
		List<short> weights = new List<short>();
		foreach (sbyte s in configPossibleStrategies)
		{
			if (CanDrawStrategy(s, sourceNeigongTemplateId))
			{
				possibleStrategies.Add(s);
				weights.Add(QiArtStrategy.Instance[s].ExtractWeight);
			}
		}
		if (weights.Count == 0)
		{
			return -1;
		}
		int index = RandomUtils.GetRandomIndex(weights, randomSource);
		return possibleStrategies[index];
	}

	private bool CanDrawStrategy(sbyte qiArtStrategyTemplateId, short sourceNeigongTemplateId)
	{
		QiArtStrategyItem config = QiArtStrategy.Instance[qiArtStrategyTemplateId];
		if (Enumerable.Contains(UseDrawConditionCanObtainNeiliIdList, qiArtStrategyTemplateId))
		{
			return DrawConditionCanObtainNeili();
		}
		if (Enumerable.Contains(UseDrawConditionNeiliAllocationLessThanIdList, qiArtStrategyTemplateId))
		{
			return DrawConditionCanObtainNeiliAllocation();
		}
		if (qiArtStrategyTemplateId >= 18 && qiArtStrategyTemplateId <= 23)
		{
			return DrawConditionIsReferenceSkill(sourceNeigongTemplateId);
		}
		if (qiArtStrategyTemplateId >= 24 && qiArtStrategyTemplateId <= 38)
		{
			return DrawConditionIsDifferenceFiveElementTransfer(config);
		}
		return true;
	}

	private bool DrawConditionIsDifferenceFiveElementTransfer(QiArtStrategyItem config)
	{
		sbyte transferTo = config.TransferToFiveElements;
		sbyte transferType = config.FiveElementsTransferType;
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short loopingNeigongTemplateId = taiwuChar.GetLoopingNeigong();
		CombatSkillItem skillConfig = Config.CombatSkill.Instance[loopingNeigongTemplateId];
		sbyte skillTransferTo = skillConfig.DestTypeWhileLooping;
		sbyte skillTransferType = skillConfig.TransferTypeWhileLooping;
		return skillTransferTo != transferTo || transferType != skillTransferType;
	}

	private bool DrawConditionIsReferenceSkill(short sourceNeigongTemplateId)
	{
		List<short> referenceSkillList = DomainManager.Extra.GetReferenceSkillList();
		if (referenceSkillList == null)
		{
			return false;
		}
		if (referenceSkillList.Count == 0)
		{
			return false;
		}
		return referenceSkillList.Contains(sourceNeigongTemplateId);
	}

	private bool DrawConditionCanObtainNeiliAllocation()
	{
		int maxProgress = GameData.Domains.Character.Character.GetNeiliAllocationMaxProgress();
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		int[] currentProgress = taiwuChar.GetExtraNeiliAllocationProgress();
		for (int i = 0; i < 4; i++)
		{
			if (currentProgress[i] < maxProgress)
			{
				return true;
			}
		}
		return false;
	}

	private bool DrawConditionCanObtainNeili()
	{
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short loopingNeigongTemplateId = taiwuChar.GetLoopingNeigong();
		CombatSkillKey skillKey = new CombatSkillKey(taiwuChar.GetId(), loopingNeigongTemplateId);
		GameData.Domains.CombatSkill.CombatSkill skill = DomainManager.CombatSkill.GetElement_CombatSkills(skillKey);
		short totalNeili = skill.GetTotalObtainableNeili();
		short currentNeili = skill.GetObtainedNeili();
		return currentNeili < totalNeili;
	}

	[DomainMethod]
	public void ClearCurrentLoopingNeigongEvent(DataContext context)
	{
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		short loopingNeigongTemplateId = taiwuChar.GetLoopingNeigong();
		if (_currentLoopingEventCostedConcentration > 0)
		{
			sbyte grade = Config.CombatSkill.Instance[loopingNeigongTemplateId].Grade;
			int addSeniority = ProfessionFormulaImpl.Calculate(28, _currentLoopingEventCostedConcentration, grade);
			DomainManager.Extra.ChangeProfessionSeniority(context, 3, addSeniority);
		}
		_currentLoopingEventCostedConcentration = 0;
		List<short> qiArtStrategySkillIdList = DomainManager.Extra.GetLoopingEventSkillIdList();
		if (qiArtStrategySkillIdList.Contains(loopingNeigongTemplateId))
		{
			qiArtStrategySkillIdList.Remove(loopingNeigongTemplateId);
			DomainManager.Extra.SetLoopingEventSkillIdList(qiArtStrategySkillIdList, context);
			DomainManager.Taiwu.AddLegacyPoint(context, 48);
		}
	}

	private static int GetRandomBetween(IRandomSource random, int a, int b)
	{
		if (a.Equals(b))
		{
			return a;
		}
		return random.Next(a, b);
	}

	[DomainMethod]
	public LoopingViewDisplayData GetLoopingViewDisplayData(DataContext context)
	{
		LoopingViewDisplayData result = new LoopingViewDisplayData();
		GameData.Domains.Character.Character taiwuChar = DomainManager.Taiwu.GetTaiwu();
		result.CurConcentration = taiwuChar.GetCurrMainAttributes()[2];
		result.MaxConcentration = taiwuChar.GetMaxMainAttributes()[2];
		result.CurrNeili = taiwuChar.GetCurrNeili();
		result.LoopingNeigong = taiwuChar.GetLoopingNeigong();
		result.LearnedSkillList = taiwuChar.GetLearnedCombatSkills();
		foreach (CombatSkillDisplayDataCharacterMenuListItem item in DomainManager.CombatSkill.GetCharacterMenuCombatSkillListItemDisplayData(context, taiwuChar.GetId()))
		{
			if (Config.CombatSkill.Instance[item.TemplateId].Type == 0)
			{
				result.CombatSkillDisplayDataList.Add(item);
			}
		}
		result.ReferenceSkillList = DomainManager.Extra.GetReferenceSkillList() ?? new List<short>();
		while (result.ReferenceSkillList.Count < 3)
		{
			result.ReferenceSkillList.Add(-1);
		}
		result.ReferenceSkillSlotUnlockStates = GetReferenceSkillSlotUnlockStates();
		ref List<int> items = ref result.TaiwuExtraNeiliAllocationProgress.Items;
		if (items == null)
		{
			items = new List<int>();
		}
		result.TaiwuExtraNeiliAllocationProgress.Items.AddRange(taiwuChar.GetExtraNeiliAllocationProgress());
		(int minNeili, int maxNeili) tuple = DomainManager.CombatSkill.CalcTaiwuExtraDeltaNeiliPerLoop(context);
		int extraMin = tuple.minNeili;
		int extraMax = tuple.maxNeili;
		result.ExtraNeiliPerLoopMin = extraMin;
		result.ExtraNeiliPerLoopMax = extraMax;
		result.ExtraNeiliAllocationPerLoop = DomainManager.CombatSkill.CalcTaiwuExtraDeltaNeiliAllocationPerLoop(context);
		if (result.LoopingNeigong >= 0)
		{
			SByteList qiArtStrategyList = DomainManager.Extra.GetOrInitQiArtStrategies(context, result.LoopingNeigong);
			IntList qiArtExpireList = DomainManager.Extra.GetOrInitQiArtStrategyExpireTimeList(context, result.LoopingNeigong);
			for (int i = 0; i < qiArtExpireList.Items.Count; i++)
			{
				result.TaiwuQiArtStrategyList.Add(new QiArtStrategyDisplayData
				{
					TemplateId = qiArtStrategyList.Items[i],
					ExpireTime = qiArtExpireList.Items[i]
				});
			}
			result.AvailableStrategies = SByteList.Create();
			if (DomainManager.Extra.TryGetElement_AvailableQiArtStrategyMap(result.LoopingNeigong, out var strategyList))
			{
				result.AvailableStrategies.Items.AddRange(strategyList.Items);
			}
		}
		result.LoopingEventSkillIdList = DomainManager.Extra.GetLoopingEventSkillIdList();
		result.LoopInLifeSkillCombatCount = DomainManager.Extra.GetLoopInLifeSkillCombatCount();
		result.LoopInCombatCount = DomainManager.Extra.GetLoopInCombatCount();
		return result;
	}

	[DomainMethod]
	public void SetReferenceBook(DataContext context, sbyte index, ItemKey bookItemKey)
	{
		if (bookItemKey.IsValid())
		{
			if (!IsReferenceBookSlotUnlocked(index))
			{
				throw new Exception($"Reference book slot {index} is locked");
			}
			if (_curReadingBook.Id == bookItemKey.Id)
			{
				throw new Exception($"Book with Id {bookItemKey.Id} is already being read.");
			}
			for (int i = 0; i < _referenceBooks.Length; i++)
			{
				if (i != index && bookItemKey.Id == _referenceBooks[i].Id)
				{
					throw new Exception($"Book with templateId {bookItemKey.Id} is already being referenced at slot {i}");
				}
			}
		}
		_referenceBooks[index] = bookItemKey;
		SetReferenceBooks(_referenceBooks, context);
	}

	[DomainMethod]
	public void SetReadingBook(DataContext context, ItemKey bookItemKey)
	{
		if (bookItemKey.IsValid())
		{
			for (int i = 0; i < _referenceBooks.Length; i++)
			{
				if (bookItemKey.Id == _referenceBooks[i].Id)
				{
					throw new Exception($"Book with templateId {bookItemKey.TemplateId} is already being referenced at slot {i}");
				}
			}
			if (!_readingBooks.ContainsKey(bookItemKey))
			{
				ReadingBookStrategies readingBookStrats = default(ReadingBookStrategies);
				readingBookStrats.Initialize();
				AddElement_ReadingBooks(bookItemKey, ref readingBookStrats, context);
			}
		}
		SetCurReadingBook(bookItemKey, context);
	}

	[DomainMethod]
	public ReadingBookStrategies GetCurReadingStrategies()
	{
		if (!_readingBooks.TryGetValue(_curReadingBook, out var strategies))
		{
			strategies.Initialize();
		}
		return strategies;
	}

	public ReadingBookStrategies GetTaiwuReadingStrategies(ItemKey book)
	{
		if (!_readingBooks.TryGetValue(book, out var strategies))
		{
			strategies.Initialize();
		}
		return strategies;
	}

	[DomainMethod]
	public unsafe void SetReadingStrategy(DataContext context, byte pageIndex, int strategyIndex, sbyte strategyId)
	{
		if (!_curReadingBook.IsValid())
		{
			throw new Exception($"CurrentReadingBook is invalid {_curReadingBook}");
		}
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		short bookSubType = ItemTemplateHelper.GetItemSubType(_curReadingBook.ItemType, _curReadingBook.TemplateId);
		int pageCount = ((bookSubType == 1001) ? 6 : 5);
		if (pageIndex >= pageCount)
		{
			throw new Exception($"the given page index {pageIndex} is illegal.");
		}
		if (strategyIndex < 0 || strategyIndex >= 3)
		{
			throw new Exception($"The given strategy slot index {strategyIndex} is illegal.");
		}
		ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategyId];
		if (!_readingBooks.TryGetValue(_curReadingBook, out var strategies))
		{
			strategies.Initialize();
			AddElement_ReadingBooks(_curReadingBook, ref strategies, context);
		}
		MainAttributes mainAttributes = _taiwuChar.GetCurrMainAttributes();
		int buildingEffectFactor = DomainManager.Building.GetSutraReadingRoomBuffValue();
		int intCost = strategyCfg.IntelligenceCost * buildingEffectFactor / 100 + strategies.GetPageIntCostChange(pageIndex);
		short curInt = mainAttributes.Items[5];
		if (intCost > curInt)
		{
			throw new Exception($"You don't have enough intelligence: {intCost} needed, current int is {curInt}");
		}
		if (intCost > 0)
		{
			_taiwuChar.ChangeCurrMainAttribute(context, 5, -intCost);
		}
		if (strategyCfg.DurabilityCost > 0)
		{
			book.SetCurrDurability((short)(book.GetCurrDurability() - strategyCfg.DurabilityCost), context);
		}
		if (book.IsCombatSkillBook())
		{
			ApplyImmediateReadingStrategyEffectForCombatSkill(context, book, pageIndex, ref strategies, strategyId);
		}
		else
		{
			ApplyImmediateReadingStrategyEffectForLifeSkill(context, book, pageIndex, ref strategies, strategyId);
		}
		if (strategyCfg.ClearPageStrategies)
		{
			strategies.ClearPageStrategies(pageIndex);
			DomainManager.Extra.ClearReadingStrategiesExpireTimeForPage(context, _curReadingBook, pageIndex);
		}
		sbyte efficiencyBonus = (sbyte)((strategyCfg.MaxCurrPageEfficiencyChange > strategyCfg.MinCurrPageEfficiencyChange) ? context.Random.Next(strategyCfg.MinCurrPageEfficiencyChange, strategyCfg.MaxCurrPageEfficiencyChange + 1) : strategyCfg.MaxCurrPageEfficiencyChange);
		strategies.SetPageStrategy(pageIndex, strategyIndex, strategyId, efficiencyBonus);
		SetElement_ReadingBooks(_curReadingBook, ref strategies, context);
		DomainManager.Extra.SetReadingStrategiesExpireTime(context, _curReadingBook, pageIndex, strategyIndex, strategyId);
		if (book.GetCurrDurability() <= 0)
		{
			_taiwuChar.RemoveInventoryItem(context, _curReadingBook, 1, deleteItem: true);
			SetReadingBook(context, ItemKey.Invalid);
		}
		_currentReadingEventCostedIntelligence += intCost;
		RecordLifeSummary(context, 45);
	}

	private sbyte GetStrategyProgressAddValue(IRandomSource random, ReadingStrategyItem strategyCfg)
	{
		return (sbyte)((strategyCfg.MaxProgressAddValue > strategyCfg.MinProgressAddValue) ? random.Next(strategyCfg.MinProgressAddValue, strategyCfg.MaxProgressAddValue + 1) : strategyCfg.MaxProgressAddValue);
	}

	private void ApplyImmediateReadingStrategyEffectForCombatSkill(DataContext context, GameData.Domains.Item.SkillBook book, byte pageIndex, ref ReadingBookStrategies strategies, sbyte strategyId)
	{
		short skillTemplateId = book.GetCombatSkillTemplateId();
		TaiwuCombatSkill taiwuCombatSkill = GetTaiwuCombatSkill(skillTemplateId);
		byte pageTypes = book.GetPageTypes();
		sbyte outlinePageType = SkillBookStateHelper.GetOutlinePageType(pageTypes);
		byte pageInternalIndex = CombatSkillStateHelper.GetPageInternalIndex(outlinePageType, SkillBookStateHelper.GetNormalPageType(pageTypes, pageIndex), pageIndex);
		ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategyId];
		ushort incompleteState = book.GetPageIncompleteState();
		if (strategyCfg.MaxProgressAddValue != 0)
		{
			sbyte currPageAddValue = GetStrategyProgressAddValue(context.Random, strategyCfg);
			bool readingFinished = OfflineAddReadingProgress(taiwuCombatSkill, pageInternalIndex, currPageAddValue);
			SetTaiwuCombatSkill(context, skillTemplateId, taiwuCombatSkill);
			if (readingFinished)
			{
				SetCombatSkillPageComplete(context, book, pageInternalIndex);
			}
		}
		ApplyNextPageProgressAddValueEffectForCombatSkill(context, book, pageIndex, strategyCfg, taiwuCombatSkill, pageInternalIndex);
		if (strategyId == 4)
		{
			ApplyDoubleCurrentPageStrategyAddValues(context, book, taiwuCombatSkill, ref strategies, pageIndex, pageInternalIndex);
		}
		if (strategyId == 5)
		{
			ApplyDoubleCurrentPageStrategyEfficiencyChange(context, book.GetItemKey(), ref strategies, pageIndex);
		}
		if (strategyId == 14)
		{
			ApplyIntGainAccordingToStrategies(context, strategies, pageIndex);
		}
	}

	private void ApplyNextPageProgressAddValueEffectForCombatSkill(DataContext context, GameData.Domains.Item.SkillBook book, byte pageIndex, ReadingStrategyItem strategyCfg, TaiwuCombatSkill taiwuCombatSkill, byte pageInternalIndex)
	{
		byte pageTypes = book.GetPageTypes();
		ushort incompleteState = book.GetPageIncompleteState();
		short skillTemplateId = book.GetCombatSkillTemplateId();
		if (strategyCfg.NextPageProgressAddValue == 0 || taiwuCombatSkill.GetBookPageReadingProgress(pageInternalIndex) != 100)
		{
			return;
		}
		for (byte index = (byte)(pageIndex + 1); index < 6; index++)
		{
			sbyte normalPageType = SkillBookStateHelper.GetNormalPageType(pageTypes, index);
			byte internalIndex = CombatSkillStateHelper.GetNormalPageInternalIndex(normalPageType, index);
			int state = DomainManager.Item.GetPageIncompleteState(incompleteState, index, _referenceBooks, _curReadingBook);
			if (taiwuCombatSkill.GetBookPageReadingProgress(internalIndex) < 100 && state != 2)
			{
				bool readingFinished = OfflineAddReadingProgress(taiwuCombatSkill, internalIndex, strategyCfg.NextPageProgressAddValue);
				SetTaiwuCombatSkill(context, skillTemplateId, taiwuCombatSkill);
				if (readingFinished)
				{
					SetCombatSkillPageComplete(context, book, internalIndex);
				}
				break;
			}
		}
	}

	private void ApplyImmediateReadingStrategyEffectForLifeSkill(DataContext context, GameData.Domains.Item.SkillBook book, byte pageIndex, ref ReadingBookStrategies strategies, sbyte strategyId)
	{
		short skillTemplateId = book.GetLifeSkillTemplateId();
		TaiwuLifeSkill taiwuLifeSkill = GetTaiwuLifeSkill(skillTemplateId);
		ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategyId];
		ushort incompleteState = book.GetPageIncompleteState();
		if (strategyCfg.MaxProgressAddValue != 0)
		{
			sbyte currPageAddValue = (sbyte)((strategyCfg.MaxProgressAddValue > strategyCfg.MinProgressAddValue) ? context.Random.Next(strategyCfg.MinProgressAddValue, strategyCfg.MaxProgressAddValue + 1) : strategyCfg.MaxProgressAddValue);
			bool readingFinished = OfflineAddReadingProgress(taiwuLifeSkill, pageIndex, currPageAddValue);
			SetTaiwuLifeSkill(context, skillTemplateId, taiwuLifeSkill);
			if (readingFinished)
			{
				SetLifeSkillPageComplete(context, book, pageIndex);
			}
		}
		ApplyNextPageProgressAddValueEffectForLifeSkill(context, book, pageIndex, strategyCfg, taiwuLifeSkill);
		if (strategyId == 4)
		{
			ApplyDoubleCurrentPageStrategyAddValues(context, book, taiwuLifeSkill, ref strategies, pageIndex);
		}
		if (strategyId == 5)
		{
			ApplyDoubleCurrentPageStrategyEfficiencyChange(context, book.GetItemKey(), ref strategies, pageIndex);
		}
		if (strategyId == 14)
		{
			ApplyIntGainAccordingToStrategies(context, strategies, pageIndex);
		}
	}

	private void ApplyNextPageProgressAddValueEffectForLifeSkill(DataContext context, GameData.Domains.Item.SkillBook book, byte startPageIndex, ReadingStrategyItem strategyCfg, TaiwuLifeSkill taiwuLifeSkill)
	{
		if (strategyCfg.NextPageProgressAddValue == 0 || taiwuLifeSkill.GetBookPageReadingProgress(startPageIndex) != 100)
		{
			return;
		}
		ushort incompleteState = book.GetPageIncompleteState();
		short skillTemplateId = book.GetLifeSkillTemplateId();
		for (byte index = (byte)(startPageIndex + 1); index < 5; index++)
		{
			int state = DomainManager.Item.GetPageIncompleteState(incompleteState, index, _referenceBooks, _curReadingBook);
			if (taiwuLifeSkill.GetBookPageReadingProgress(index) < 100 && state != 2)
			{
				bool readingFinished = OfflineAddReadingProgress(taiwuLifeSkill, index, strategyCfg.NextPageProgressAddValue);
				SetTaiwuLifeSkill(context, skillTemplateId, taiwuLifeSkill);
				if (readingFinished)
				{
					SetLifeSkillPageComplete(context, book, index);
				}
				break;
			}
		}
	}

	private void ApplyDoubleCurrentPageStrategyAddValues(DataContext context, GameData.Domains.Item.SkillBook book, TaiwuCombatSkill taiwuCombatSkill, ref ReadingBookStrategies strategies, byte pageIndex, byte pageInternalIndex)
	{
		bool readingFinished = false;
		for (int i = 0; i < 3; i++)
		{
			if (readingFinished)
			{
				break;
			}
			sbyte currStrategyId = strategies.GetPageStrategy(pageIndex, i);
			if (currStrategyId >= 0)
			{
				ReadingStrategyItem currStrategyCfg = ReadingStrategy.Instance[currStrategyId];
				if (currStrategyCfg.MaxProgressAddValue != 0)
				{
					sbyte currPageAddValue = GetStrategyProgressAddValue(context.Random, currStrategyCfg);
					readingFinished = OfflineAddReadingProgress(taiwuCombatSkill, pageInternalIndex, currPageAddValue);
				}
				if (currStrategyCfg.NextPageProgressAddValue != 0)
				{
					ApplyNextPageProgressAddValueEffectForCombatSkill(context, book, pageIndex, currStrategyCfg, taiwuCombatSkill, pageInternalIndex);
				}
			}
		}
		SetTaiwuCombatSkill(context, book.GetCombatSkillTemplateId(), taiwuCombatSkill);
		if (readingFinished)
		{
			SetCombatSkillPageComplete(context, book, pageInternalIndex);
		}
	}

	private void ApplyDoubleCurrentPageStrategyAddValues(DataContext context, GameData.Domains.Item.SkillBook book, TaiwuLifeSkill taiwuLifeSkill, ref ReadingBookStrategies strategies, byte pageIndex)
	{
		bool readingFinished = false;
		for (int i = 0; i < 3; i++)
		{
			if (readingFinished)
			{
				break;
			}
			sbyte currStrategyId = strategies.GetPageStrategy(pageIndex, i);
			if (currStrategyId >= 0)
			{
				ReadingStrategyItem currStrategyCfg = ReadingStrategy.Instance[currStrategyId];
				if (currStrategyCfg.MaxProgressAddValue != 0)
				{
					sbyte currPageAddValue = GetStrategyProgressAddValue(context.Random, currStrategyCfg);
					readingFinished = OfflineAddReadingProgress(taiwuLifeSkill, pageIndex, currPageAddValue);
				}
				if (currStrategyCfg.NextPageProgressAddValue != 0)
				{
					ApplyNextPageProgressAddValueEffectForLifeSkill(context, book, pageIndex, currStrategyCfg, taiwuLifeSkill);
				}
			}
		}
		SetTaiwuLifeSkill(context, book.GetLifeSkillTemplateId(), taiwuLifeSkill);
		if (readingFinished)
		{
			SetLifeSkillPageComplete(context, book, pageIndex);
		}
	}

	private unsafe void ApplyDoubleCurrentPageStrategyEfficiencyChange(DataContext context, ItemKey bookItemKey, ref ReadingBookStrategies strategies, byte pageIndex)
	{
		for (int i = 0; i < 3; i++)
		{
			int value = strategies.Bonus[pageIndex * 3 + i] * 2;
			strategies.Bonus[pageIndex * 3 + i] = (sbyte)Math.Clamp(value, 0, 100);
		}
		SetElement_ReadingBooks(bookItemKey, ref strategies, context);
	}

	private void ApplyIntGainAccordingToStrategies(DataContext context, ReadingBookStrategies strategies, byte pageIndex)
	{
		int intGain = 0;
		for (int i = 0; i < 3; i++)
		{
			sbyte currStrategyId = strategies.GetPageStrategy(pageIndex, i);
			if (currStrategyId >= 0)
			{
				ReadingStrategyItem currStrategyCfg = ReadingStrategy.Instance[currStrategyId];
				if (currStrategyCfg.IntelligenceCost > 0)
				{
					intGain += currStrategyCfg.IntelligenceCost / 2;
				}
			}
		}
		_taiwuChar.ChangeCurrMainAttribute(context, 5, intGain);
	}

	[DomainMethod]
	public void ClearPageStrategy(DataContext context, byte pageIndex)
	{
		if (!_curReadingBook.IsValid())
		{
			throw new Exception($"CurrentReadingBook is invalid {_curReadingBook}");
		}
		short bookSubType = ItemTemplateHelper.GetItemSubType(_curReadingBook.ItemType, _curReadingBook.TemplateId);
		int pageCount = ((bookSubType == 1001) ? 6 : 5);
		if (pageIndex < 0 || pageIndex >= pageCount)
		{
			throw new Exception($"the given page index {pageIndex} is illegal.");
		}
		ReadingBookStrategies strategies = _readingBooks[_curReadingBook];
		strategies.ClearPageStrategies(pageIndex);
		SetElement_ReadingBooks(_curReadingBook, ref strategies, context);
		DomainManager.Extra.ClearReadingStrategiesExpireTimeForPage(context, _curReadingBook, pageIndex);
	}

