	public sbyte GetBaseReadingSpeed(ItemKey bookKey, byte curReadingPage)
	{
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(bookKey.Id);
		int incompleteState = DomainManager.Item.GetPageIncompleteState(book.GetPageIncompleteState(), curReadingPage, _referenceBooks, bookKey);
		return SkillBookPageIncompleteState.BaseReadingSpeed[incompleteState];
