	public int GetReadingSpeedBonus(byte curReadingPage, bool isInBattle = false, int tempPageReadStatus = 0, short skillAttainment = 0)
	{
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		if (!_readingBooks.TryGetValue(_curReadingBook, out var strategies))
		{
			strategies.Initialize();
		}
		int notReadPrePageCount = 0;
		int permanentBonus = 0;
		int sectApprovalFactor = 0;
		int strategyBonus = 0;
		int buildingBonusSpeed = 0;
		if (SkillGroup.FromItemSubType(book.GetItemSubType()) == 0)
		{
			short skillTemplateId = book.GetLifeSkillTemplateId();
			sbyte lifeSkillType = book.GetLifeSkillType();
			List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = _taiwuChar.GetLearnedLifeSkills();
			int learnedIndex = _taiwuChar.FindLearnedLifeSkillIndex(skillTemplateId);
			if (learnedIndex >= 0)
			{
				GameData.Domains.Character.LifeSkillItem skillItem = learnedLifeSkills[learnedIndex];
				for (byte i = 0; i < curReadingPage; i++)
				{
					if (!skillItem.IsPageRead(i) && (tempPageReadStatus & (1 << (int)i)) == 0)
					{
						notReadPrePageCount++;
					}
				}
			}
			else
			{
				for (byte i2 = 0; i2 < curReadingPage; i2++)
				{
					if ((tempPageReadStatus & (1 << (int)i2)) == 0)
					{
						notReadPrePageCount++;
					}
				}
			}
			if (skillAttainment <= 0)
			{
				skillAttainment = _taiwuChar.GetLifeSkillAttainment(lifeSkillType);
			}
			permanentBonus = GetTaiwuPropertyPermanentBonus(ECharacterPropertyReferencedType.LifeSkillBookReadEfficiency).AddPercent;
			strategyBonus = strategies.GetPageReadingEfficiencyBonus(curReadingPage);
			Location location = _taiwuChar.GetLocation();
			buildingBonusSpeed += DomainManager.Building.GetBuildingBlockEffect(location, EBuildingScaleEffect.LifeSkillReadingSpeedBonusFactor, lifeSkillType);
		}
		else
		{
			short skillTemplateId2 = book.GetCombatSkillTemplateId();
			CombatSkillItem skillConfig = Config.CombatSkill.Instance[skillTemplateId2];
			byte pageTypes = book.GetPageTypes();
			sbyte behaviorType = SkillBookStateHelper.GetOutlinePageType(pageTypes);
			sbyte direction = SkillBookStateHelper.GetNormalPageType(pageTypes, curReadingPage);
			byte readingInternalIndex = CombatSkillStateHelper.GetPageInternalIndex(behaviorType, direction, curReadingPage);
			if (_taiwuChar.GetLearnedCombatSkills().Contains(skillTemplateId2))
			{
				GameData.Domains.CombatSkill.CombatSkill skillItem2 = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillTemplateId2));
				ushort readingState = skillItem2.GetReadingState();
				for (byte i3 = 0; i3 < curReadingPage; i3++)
				{
					byte internalIndex = CombatSkillStateHelper.GetPageInternalIndex(behaviorType, SkillBookStateHelper.GetNormalPageType(pageTypes, i3), i3);
					if (!CombatSkillStateHelper.IsPageRead(readingState, internalIndex) && (tempPageReadStatus & (1 << (int)i3)) == 0)
					{
						notReadPrePageCount++;
					}
				}
			}
			else
			{
				for (byte i4 = 0; i4 < curReadingPage; i4++)
				{
					if ((tempPageReadStatus & (1 << (int)i4)) == 0)
					{
						notReadPrePageCount++;
					}
				}
			}
			skillAttainment = _taiwuChar.GetCombatSkillAttainment(book.GetCombatSkillType());
			short requiredAttainment = SkillGradeData.Instance[book.GetGrade()].ReadingAttainmentRequirement;
			skillAttainment = GetAttainmentWithSectApprovalBonus(skillConfig.SectId, skillAttainment, requiredAttainment);
			permanentBonus = GetTaiwuPropertyPermanentBonus(ECharacterPropertyReferencedType.CombatSkillBookReadEfficiency).AddPercent;
			strategyBonus = strategies.GetPageReadingEfficiencyBonus(curReadingPage);
			sbyte sectId = Config.CombatSkill.Instance[book.GetCombatSkillTemplateId()].SectId;
			sectApprovalFactor = CalcReadingSpeedSectApprovalFactor(sectId, (curReadingPage == 0) ? SkillBookStateHelper.GetOutlinePageType(pageTypes) : direction, (sbyte)curReadingPage, isInBattle);
			Location location2 = _taiwuChar.GetLocation();
			buildingBonusSpeed += DomainManager.Building.GetBuildingBlockEffect(location2, EBuildingScaleEffect.CombatSkillReadingSpeedBonusFactor, skillConfig.Type);
		}
		int readingSpeedAttainmentFactor = CalcReadingSpeedAttainmentFactor(skillAttainment, book.GetGrade());
		int refBookBonusSpeed = CalcReferenceBooksBonusSpeedPercent();
		byte difficulty = DomainManager.World.GetReadingDifficulty();
		short difficultyBonus = WorldCreation.Instance[(byte)2].InfluenceFactors[difficulty];
		int professionBonus = 0;
		if (DomainManager.Extra.IsProfessionalSkillUnlocked(4, 1))
		{
			int seniority = DomainManager.Extra.GetProfessionData(4).Seniority;
			int maxSeniority = 3000000;
			professionBonus = 30 + 30 * seniority / maxSeniority;
		}
		int speedMultiplier = 100 + permanentBonus + buildingBonusSpeed + refBookBonusSpeed + strategyBonus + professionBonus;
		speedMultiplier = speedMultiplier * (100 + readingSpeedAttainmentFactor) / 100;
		speedMultiplier = speedMultiplier * (100 + sectApprovalFactor) / 100;
		speedMultiplier = speedMultiplier * difficultyBonus / 100;
		for (int j = 0; j < notReadPrePageCount; j++)
		{
			speedMultiplier /= 2;
		}
		return Math.Max(speedMultiplier, 0);
	}

