	public static int CalcReadingSpeedAttainmentFactor(short attainment, sbyte grade)
	{
		return Math.Clamp(100 * attainment / SkillGradeData.Instance[grade].ReadingAttainmentRequirement, 10, 1000);
	}

	private int CalcReferenceBooksBonusSpeedPercent()
	{
		int refBonusSpeed = 0;
		ItemKey[] referenceBooks = _referenceBooks;
		for (int i = 0; i < referenceBooks.Length; i++)
		{
			ItemKey refBookKey = referenceBooks[i];
			if (refBookKey.IsValid())
			{
				refBonusSpeed += GetRefBonusSpeed(refBookKey);
			}
		}
		return Math.Max(0, refBonusSpeed);
	}

	[DomainMethod]
	public int GetRefBonusSpeed(ItemKey refBookKey)
	{
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		sbyte bookSkillType = ((book.GetItemSubType() == 1000) ? book.GetLifeSkillType() : book.GetCombatSkillType());
		GameData.Domains.Item.SkillBook refBook = DomainManager.Item.GetElement_SkillBooks(refBookKey.Id);
		sbyte refBookGrade = refBook.GetGrade();
		int factor = 15;
		if (CheckRefBonusSpeedIsSpecial(refBookKey))
		{
			factor = 30;
		}
		sbyte refBookSkillType = ((refBook.GetItemSubType() == 1000) ? refBook.GetLifeSkillType() : refBook.GetCombatSkillType());
		if (refBook.GetItemSubType() == book.GetItemSubType() && refBookSkillType == bookSkillType)
		{
			factor = 30;
		}
		return GlobalConfig.Instance.BaseRefBonusSpeed + (refBookGrade + 1) * factor;
	}

	private bool CheckRefBonusSpeedIsSpecial(ItemKey refBookKey)
	{
		if (!_curReadingBook.IsValid())
		{
			return false;
		}
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		return book.GetReferenceBooksWithBonus()?.Contains(refBookKey.TemplateId) ?? false;
	}

	[DomainMethod]
	public void CheckNotInInventoryBooks(DataContext context)
	{
		Inventory inventory = _taiwuChar.GetInventory();
		for (sbyte i = 0; i < _referenceBooks.Length; i++)
		{
			if (_referenceBooks[i].IsValid() && !inventory.Items.ContainsKey(_referenceBooks[i]))
			{
				SetReferenceBook(context, i, ItemKey.Invalid);
			}
			else if (!IsReferenceBookSlotUnlocked(i))
			{
				SetReferenceBook(context, i, ItemKey.Invalid);
			}
		}
		if (_curReadingBook.IsValid() && !inventory.Items.ContainsKey(_curReadingBook))
		{
			SetReadingBook(context, ItemKey.Invalid);
		}
	}

	public bool IsReferenceBookSlotUnlocked(int index)
	{
		byte unlockState = GetReferenceBookSlotUnlockStates();
		return ((unlockState >> index) & 1) == 1;
	}

	public bool UpdateReadingProgressOnce(DataContext context, bool isInCombat, bool addInstantNotification = true)
	{
		CheckNotInInventoryBooks(context);
		if (!_curReadingBook.IsValid())
		{
			return false;
		}
		ReadingBookStrategies strategies = GetCurReadingStrategies();
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		ItemKey bookKey = book.GetItemKey();
		InstantNotificationCollection collection = DomainManager.World.GetInstantNotificationCollection();
		if (isInCombat)
		{
			Events.RegisterHandler_CombatEnd(OnCombatEndTryAttachPoisonByReadInCombat);
		}
		else
		{
			ApplyAttachedPoisonForReading(context);
		}
		if (SkillGroup.FromItemSubType(book.GetItemSubType()) == 0)
		{
			int progress = UpdateLifeSkillBookReadingProgress(context, book, strategies, isInCombat);
			sbyte count = DomainManager.Extra.GetReadInLifeSkillCombatCount();
			if (addInstantNotification)
			{
				if (count <= 0)
				{
					collection.AddReadInLifeSkillCombatNoChance(bookKey.ItemType, bookKey.TemplateId, progress);
				}
				else
				{
					collection.AddReadInLifeSkillCombat(bookKey.ItemType, bookKey.TemplateId, progress, count);
				}
			}
		}
		else
		{
			int progress2 = UpdateCombatSkillBookReadingProgress(context, book, strategies, isInCombat);
			sbyte count2 = DomainManager.Taiwu.GetReadInCombatCount();
			if (addInstantNotification)
			{
				if (count2 <= 0)
				{
					collection.AddReadInCombatNoChance(bookKey.ItemType, bookKey.TemplateId, progress2);
				}
				else
				{
					collection.AddReadInCombat(bookKey.ItemType, bookKey.TemplateId, progress2, count2);
				}
			}
		}
		int readingEventTotalRate = 20;
		for (int i = 0; i < _referenceBooks.Length; i++)
		{
			if (_referenceBooks[i].IsValid())
			{
				GameData.Domains.Item.SkillBook referenceBook = DomainManager.Item.GetElement_SkillBooks(_referenceBooks[i].Id);
				if (SkillGroup.FromItemSubType(referenceBook.GetItemSubType()) == 0)
				{
					readingEventTotalRate += LifeSkill.Instance[referenceBook.GetLifeSkillTemplateId()].ReadingEventBonusRate;
				}
			}
		}
		if (_curReadingBook.IsValid() && (readingEventTotalRate >= 100 || context.Random.CheckProb(readingEventTotalRate, 100)))
		{
			return true;
		}
		return false;
	}

