	private void ApplyAttachedPoisonForReading(DataContext context)
	{
		if (_curReadingBook.IsValid())
		{
			GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
			_taiwuChar.TryApplyAttachedPoison(context, book.GetItemKey());
		}
	}

	public void UpdateReadingProgressOnMonthChange(DataContext context)
	{
		SetReadInCombatCount(1, context);
		DomainManager.Extra.SetReadInLifeSkillCombatCount(1, context);
		short readingEventTotalRate = GetCurrReadingEventBonusRate();
		MakeReadingProgressActuallyWork(context);
		if (_curReadingBook.IsValid() && (readingEventTotalRate >= 100 || context.Random.CheckProb(readingEventTotalRate, 100)) && DomainManager.Extra.AddReadingEventBookId(context, _curReadingBook.Id))
		{
			DomainManager.World.GetMonthlyNotificationCollection().AddReadingEvent((ulong)_curReadingBook);
		}
	}

	public void MakeReadingProgressActuallyWork(DataContext context, int activeReadProgressAffectedEfficiency = 100)
	{
		CheckNotInInventoryBooks(context);
		if (!_curReadingBook.IsValid() || !DomainManager.SpecialEffect.ModifyData(_taiwuCharId, -1, 259, dataValue: true))
		{
			return;
		}
		ReadingBookStrategies strategies = GetCurReadingStrategies();
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		_taiwuChar.TryApplyAttachedPoison(context, book.GetItemKey());
		if (SkillGroup.FromItemSubType(book.GetItemSubType()) == 0)
		{
			UpdateLifeSkillBookReadingProgress(context, book, strategies, isInBattle: false, activeReadProgressAffectedEfficiency);
		}
		else
		{
			UpdateCombatSkillBookReadingProgress(context, book, strategies, isInBattle: false, activeReadProgressAffectedEfficiency);
		}
		for (int i = 0; i < _referenceBooks.Length; i++)
		{
			if (_referenceBooks[i].IsValid())
			{
				GameData.Domains.Item.SkillBook referenceBook = DomainManager.Item.GetElement_SkillBooks(_referenceBooks[i].Id);
				_taiwuChar.TryApplyAttachedPoison(context, referenceBook.GetItemKey());
				referenceBook.SetCurrDurability((short)(referenceBook.GetCurrDurability() - 1), context);
				if (referenceBook.GetCurrDurability() <= 0)
				{
					_taiwuChar.RemoveInventoryItem(context, _referenceBooks[i], 1, deleteItem: true);
					_referenceBooks[i] = ItemKey.Invalid;
				}
			}
		}
		SetReferenceBooks(_referenceBooks, context);
		book.SetCurrDurability((short)(book.GetCurrDurability() - 1), context);
		if (book.GetCurrDurability() <= 0)
		{
			_taiwuChar.RemoveInventoryItem(context, _curReadingBook, 1, deleteItem: true);
			SetReadingBook(context, ItemKey.Invalid);
		}
	}

	public void TaiwuReadingBook(DataContext context, ItemKey itemKey)
	{
		if (!itemKey.IsValid() || !DomainManager.Item.TryGetElement_SkillBooks(itemKey.Id, out var book))
		{
			return;
		}
		ReadingBookStrategies strategies = GetTaiwuReadingStrategies(itemKey);
		bool isCurReadingBook = itemKey.Equals(_curReadingBook);
		_taiwuChar.TryApplyAttachedPoison(context, book.GetItemKey());
		if (SkillGroup.FromItemSubType(book.GetItemSubType()) == 0)
		{
			UpdateLifeSkillBookReadingProgress(context, book, strategies);
		}
		else
		{
			UpdateCombatSkillBookReadingProgress(context, book, strategies);
		}
		if (isCurReadingBook)
		{
			for (int i = 0; i < _referenceBooks.Length; i++)
			{
				if (_referenceBooks[i].IsValid())
				{
					GameData.Domains.Item.SkillBook referenceBook = DomainManager.Item.GetElement_SkillBooks(_referenceBooks[i].Id);
					_taiwuChar.TryApplyAttachedPoison(context, referenceBook.GetItemKey());
					referenceBook.SetCurrDurability((short)(referenceBook.GetCurrDurability() - 1), context);
					if (referenceBook.GetCurrDurability() <= 0)
					{
						_taiwuChar.RemoveInventoryItem(context, _referenceBooks[i], 1, deleteItem: true);
						_referenceBooks[i] = ItemKey.Invalid;
					}
				}
			}
			SetReferenceBooks(_referenceBooks, context);
		}
		book.SetCurrDurability((short)(book.GetCurrDurability() - 1), context);
		if (book.GetCurrDurability() <= 0)
		{
			DomainManager.Taiwu.RemoveTaiwuItemFromTaiwuStorage(context, itemKey, 1, deleteItem: true);
			if (isCurReadingBook)
			{
				SetReadingBook(context, ItemKey.Invalid);
			}
		}
	}

	public void ClearReadingStrategy(DataContext context, ItemKey book, byte pageIndex, int strategyIndex)
	{
		if (_readingBooks.TryGetValue(book, out var strategies))
		{
			strategies.SetPageStrategy(pageIndex, strategyIndex, -1, 0);
			SetElement_ReadingBooks(book, ref strategies, context);
		}
	}

	private TaiwuLifeSkill GetTaiwuLifeSkill(short skillTemplateId)
	{
		if (TryGetElement_LifeSkills(skillTemplateId, out var lifeSkill))
		{
			return lifeSkill;
		}
		if (TryGetElement_NotLearnLifeSkillReadingProgress(skillTemplateId, out lifeSkill))
		{
			return lifeSkill;
		}
		return new TaiwuLifeSkill();
	}

	private void SetTaiwuLifeSkill(DataContext context, short skillTemplateId, TaiwuLifeSkill taiwuLifeSkill)
	{
		if (_lifeSkills.ContainsKey(skillTemplateId))
		{
			SetElement_LifeSkills(skillTemplateId, taiwuLifeSkill, context);
		}
		else if (_notLearnLifeSkillReadingProgress.ContainsKey(skillTemplateId))
		{
			SetElement_NotLearnLifeSkillReadingProgress(skillTemplateId, taiwuLifeSkill, context);
