	private int UpdateLifeSkillBookReadingProgress(DataContext context, GameData.Domains.Item.SkillBook book, ReadingBookStrategies strategies, bool isInBattle = false, int activeReadProgressAffectedEfficiency = 100)
	{
		short skillTemplateId = book.GetLifeSkillTemplateId();
		TaiwuLifeSkill lifeSkill = GetTaiwuLifeSkill(skillTemplateId);
		byte readingPage = GetCurrentReadingPage(book, strategies, lifeSkill);
		int totalAddProgress = 0;
		int remainingSpeedPercent = 100;
		SkillBookItem skillBookItem = Config.SkillBook.Instance[skillTemplateId];
		sbyte lifeSkillType = skillBookItem.LifeSkillType;
		sbyte bookGrade = skillBookItem.Grade;
		while (remainingSpeedPercent > 0 && readingPage < 5)
		{
			if (IsLifeSkillBookPageRead(book, readingPage) || strategies.GetSkipPage(readingPage))
			{
				readingPage++;
				continue;
			}
			int combatBonus = (isInBattle ? DomainManager.Taiwu.CalcReadingBonusRateFactorInCombat(DomainManager.Taiwu.GetCurReadingBook()) : 100);
			int readingSpeed = GetBaseReadingSpeed(readingPage) * GetReadingSpeedBonus(readingPage, isInBattle, 0, 0) / 100;
			readingSpeed = readingSpeed * activeReadProgressAffectedEfficiency / 100;
			readingSpeed = readingSpeed * combatBonus / 100;
			if (readingSpeed == 0)
			{
				break;
			}
			(bool, int) tuple = ReadSkillBookPage(context, book, readingPage, readingSpeed, isCombatSkill: false, ref remainingSpeedPercent, ref readingPage);
			bool readingFinished = tuple.Item1;
			int addedProgress = tuple.Item2;
			totalAddProgress += addedProgress;
			if (readingFinished)
			{
				switch (lifeSkillType)
				{
				case 13:
				{
					int addSeniority2 = ProfessionFormulaImpl.Calculate(43, bookGrade);
					DomainManager.Extra.ChangeProfessionSeniority(context, 6, addSeniority2);
					break;
				}
				case 12:
				{
					int addSeniority = ProfessionFormulaImpl.Calculate(37, bookGrade);
					DomainManager.Extra.ChangeProfessionSeniority(context, 5, addSeniority);
					break;
				}
				}
			}
			if (readingFinished)
			{
				continue;
			}
			break;
		}
		if (readingPage == 5)
		{
			int pageCount = GetReadPageCountByRereading(isInBattle, remainingSpeedPercent, null, 0, 0);
			_taiwuChar.ChangeExp(context, GetExpByRereading(bookGrade, pageCount));
			switch (lifeSkillType)
			{
			case 13:
			{
				int addSeniority4 = ProfessionFormulaImpl.Calculate(44, bookGrade) * pageCount;
				DomainManager.Extra.ChangeProfessionSeniority(context, 6, addSeniority4);
				break;
			}
			case 12:
			{
				int addSeniority3 = ProfessionFormulaImpl.Calculate(38, bookGrade) * pageCount;
				DomainManager.Extra.ChangeProfessionSeniority(context, 5, addSeniority3);
				break;
			}
			}
		}
		Events.RaiseTaiwuReadBook(context, book);
		return totalAddProgress;
	}

	private int UpdateCombatSkillBookReadingProgress(DataContext context, GameData.Domains.Item.SkillBook book, ReadingBookStrategies strategies, bool isInBattle = false, int activeReadProgressAffectedEfficiency = 100)
	{
		short skillTemplateId = book.GetCombatSkillTemplateId();
		byte pageTypes = book.GetPageTypes();
		TaiwuCombatSkill combatSkill = GetTaiwuCombatSkill(skillTemplateId);
		byte readingPage = GetCurrentReadingPage(book, strategies, combatSkill);
		int totalAddProgress = 0;
		int remainingSpeedPercent = 100;
		while (remainingSpeedPercent > 0 && readingPage < 6)
		{
			if (IsCombatSkillBookPageRead(book, readingPage) || strategies.GetSkipPage(readingPage))
			{
				readingPage++;
				continue;
			}
			int combatBonus = (isInBattle ? DomainManager.Taiwu.CalcReadingBonusRateFactorInCombat(DomainManager.Taiwu.GetCurReadingBook()) : 100);
			int readingSpeed = GetBaseReadingSpeed(readingPage) * GetReadingSpeedBonus(readingPage, isInBattle, 0, 0) / 100;
			readingSpeed = readingSpeed * activeReadProgressAffectedEfficiency / 100;
			readingSpeed = readingSpeed * combatBonus / 100;
			if (readingSpeed == 0)
			{
				break;
			}
			byte pageInternalIndex = CombatSkillStateHelper.GetPageInternalIndex(SkillBookStateHelper.GetOutlinePageType(pageTypes), SkillBookStateHelper.GetNormalPageType(pageTypes, readingPage), readingPage);
			(bool, int) tuple = ReadSkillBookPage(context, book, pageInternalIndex, readingSpeed, isCombatSkill: true, ref remainingSpeedPercent, ref readingPage);
			bool readingFinished = tuple.Item1;
			int addedProgress = tuple.Item2;
			totalAddProgress += addedProgress;
			if (readingFinished)
			{
				continue;
			}
			break;
		}
		if (readingPage == 6)
		{
			_taiwuChar.ChangeExp(context, GetExpByRereading(isInBattle, remainingSpeedPercent));
		}
		Events.RaiseTaiwuReadBook(context, book);
		return totalAddProgress;
	}

	[DomainMethod]
	public int GetExpByRereading(bool isInBattle, int remainingSpeedPercent)
	{
		return _curReadingBook.IsValid() ? GetExpByRereading(DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id).GetGrade(), GetReadPageCountByRereading(isInBattle, remainingSpeedPercent, null, 0, 0)) : 0;
	}

	public int GetExpByRereading(sbyte grade, int pageCount)
	{
		return SkillGradeData.Instance[grade].ReadingExpGainPerPage * GlobalConfig.Instance.ReadingFinishedBookExpGainPercent * (grade + 1) / 100 * pageCount;
	}

	private int GetReadPageCountByRereading(bool isInBattle, int remainingSpeedPercent, int[] progress = null, int tempPageReadStatus = 0, short skillAttainment = 0)
	{
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		byte limit = book.GetPageCount();
		ReadingBookStrategies strategies = GetCurReadingStrategies();
		int readPageCount = 0;
		for (byte readingPage = 0; readingPage < limit; readingPage++)
		{
			if (!strategies.GetSkipPage(readingPage))
			{
				int combatBonus = (isInBattle ? DomainManager.Taiwu.CalcReadingBonusRateFactorInCombat(book.GetItemKey()) : 100);
				int readingSpeed = SkillBookPageIncompleteState.BaseReadingSpeed[0] * GetReadingSpeedBonus(readingPage, isInBattle, tempPageReadStatus, skillAttainment) * combatBonus / 10000;
				int addingProgress = readingSpeed * remainingSpeedPercent / 100;
				if (progress != null)
				{
					progress[readingPage] += Math.Min(addingProgress, 100);
				}
				if (addingProgress < 100)
				{
					break;
				}
				readPageCount++;
				remainingSpeedPercent -= 10000 / readingSpeed;
			}
		}
		return readPageCount;
	}

	[DomainMethod]
	public int[] GetReadingResult()
	{
		int[] progress = new int[6];
		if (!_curReadingBook.IsValid() || GetCurrReadingBanByWug())
		{
			return progress;
		}
		int readPageCount = 0;
		int tempPageReadStatus = 0;
		int remainingSpeedPercent = 100;
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		byte limit = book.GetPageCount();
		ReadingBookStrategies strategies = GetCurReadingStrategies();
		bool isCombatSkill = book.IsCombatSkillBook();
		byte pageTypes = book.GetPageTypes();
		short skillAttainment = 0;
		byte readingPage;
		ITaiwuSkill skill;
		if (isCombatSkill)
		{
			short skillTemplateId = book.GetCombatSkillTemplateId();
			TaiwuCombatSkill combatSkill = GetTaiwuCombatSkill(skillTemplateId);
			readingPage = GetCurrentReadingPage(book, strategies, combatSkill);
			skill = combatSkill;
		}
		else
		{
			short skillTemplateId2 = book.GetLifeSkillTemplateId();
			TaiwuLifeSkill lifeSkill = GetTaiwuLifeSkill(skillTemplateId2);
			readingPage = GetCurrentReadingPage(book, strategies, lifeSkill);
			skill = lifeSkill;
		}
		while (readingPage < limit)
		{
			sbyte readingProgress = (isCombatSkill ? skill.GetBookPageReadingProgress(CombatSkillStateHelper.GetPageInternalIndex(SkillBookStateHelper.GetOutlinePageType(pageTypes), SkillBookStateHelper.GetNormalPageType(pageTypes, readingPage), readingPage)) : skill.GetBookPageReadingProgress(readingPage));
			if (readingProgress == 100)
			{
				tempPageReadStatus |= 1 << (int)readingPage;
				readPageCount++;
			}
			else if (!strategies.GetSkipPage(readingPage))
			{
				if (!isCombatSkill)
				{
					skillAttainment = _taiwuChar.GetPredictLifeSkillAttainment(book.GetLifeSkillType(), book.GetLifeSkillTemplateId(), readPageCount);
				}
				int readingSpeed = GetBaseReadingSpeed(readingPage) * GetReadingSpeedBonus(readingPage, isInBattle: false, tempPageReadStatus, skillAttainment) / 100;
				int addingProgress = readingSpeed * remainingSpeedPercent / 100;
				int addedProgress = Math.Min(100, addingProgress + readingProgress) - readingProgress;
				if (readingSpeed == 0)
				{
					break;
				}
				remainingSpeedPercent -= addedProgress * 100 / readingSpeed;
				progress[readingPage] = (sbyte)addedProgress;
				if (addingProgress + readingProgress < 100)
				{
					break;
				}
				tempPageReadStatus |= 1 << (int)readingPage;
				readPageCount++;
			}
			readingPage++;
		}
		if (readingPage == limit)
		{
			skillAttainment = (short)((!isCombatSkill) ? _taiwuChar.GetPredictLifeSkillAttainment(book.GetLifeSkillType(), book.GetLifeSkillTemplateId(), readPageCount) : 0);
			GetReadPageCountByRereading(isInBattle: false, remainingSpeedPercent, progress, tempPageReadStatus, skillAttainment);
		}
		return progress;
	}

	[DomainMethod]
	public unsafe int GetPreviewReadingEfficiency(byte pageIndex, int strategyIndex, sbyte strategyId)
	{
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		ReadingStrategyItem strategyCfg = ReadingStrategy.Instance[strategyId];
		ReadingBookStrategies originalStrategies = GetCurReadingStrategies();
		ReadingBookStrategies previewStrategies = originalStrategies;
		if (strategyCfg.ClearPageStrategies)
		{
			previewStrategies.ClearPageStrategies(pageIndex);
		}
		if (strategyId == 5)
		{
			for (int i = 0; i < 3; i++)
			{
				int value = previewStrategies.Bonus[pageIndex * 3 + i] * 2;
				previewStrategies.Bonus[pageIndex * 3 + i] = (sbyte)Math.Clamp(value, 0, 100);
			}
		}
		sbyte efficiencyBonus = Math.Min(strategyCfg.MinCurrPageEfficiencyChange, strategyCfg.MaxCurrPageEfficiencyChange);
		previewStrategies.SetPageStrategy(pageIndex, strategyIndex, strategyId, efficiencyBonus);
		ReadingBookStrategies oldStrategies;
		bool hadOldEntry = _readingBooks.TryGetValue(_curReadingBook, out oldStrategies);
		_readingBooks[_curReadingBook] = previewStrategies;
		try
		{
			int[] readingResult = GetReadingResult();
			GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
			sbyte totalProgress = GetTotalReadingProgress(_curReadingBook.Id);
			SkillBookPageDisplayData pageDisplayData = DomainManager.Item.GetSkillBookPagesInfo(_curReadingBook);
			int efficiency = 0;
			if (totalProgress < 100)
			{
				for (int j = 0; j < pageDisplayData.ReadingProgress.Length; j++)
				{
					if (pageDisplayData.ReadingProgress[j] < 100)
					{
						efficiency += Math.Min(readingResult[j], 100 - pageDisplayData.ReadingProgress[j]);
					}
				}
			}
			else
			{
				int[] array = readingResult;
				foreach (int t in array)
				{
					efficiency += t;
				}
			}
			return efficiency;
		}
		finally
		{
			if (hadOldEntry)
			{
				_readingBooks[_curReadingBook] = oldStrategies;
			}
			else
			{
				_readingBooks.Remove(_curReadingBook);
			}
		}
	}

