				int addingProgress = readingSpeed * remainingSpeedPercent / 100;
				int addedProgress = Math.Min(100, addingProgress + readingProgress) - readingProgress;
				if (readingSpeed == 0)
				{
					break;
				}
				remainingSpeedPercent -= addedProgress * 100 / readingSpeed;
