	public void ReadSkillBookPageAndSetComplete(DataContext context, GameData.Domains.Item.SkillBook book, byte readingPage)
	{
		if (book.IsCombatSkillBook())
		{
			short skillTemplateId = book.GetCombatSkillTemplateId();
			TaiwuCombatSkill taiwuCombatSkill = GetTaiwuCombatSkill(skillTemplateId);
			byte pageTypes = book.GetPageTypes();
			sbyte behaviorType = SkillBookStateHelper.GetOutlinePageType(pageTypes);
			sbyte direction = SkillBookStateHelper.GetNormalPageType(pageTypes, readingPage);
			byte internalIndex = CombatSkillStateHelper.GetPageInternalIndex(behaviorType, direction, readingPage);
			taiwuCombatSkill.SetBookPageReadingProgress(internalIndex, 100);
			SetTaiwuCombatSkill(context, skillTemplateId, taiwuCombatSkill);
			SetCombatSkillPageComplete(context, book, internalIndex);
		}
		else
		{
			short skillTemplateId2 = book.GetLifeSkillTemplateId();
			TaiwuLifeSkill taiwuLifeSkill = GetTaiwuLifeSkill(skillTemplateId2);
			taiwuLifeSkill.SetBookPageReadingProgress(readingPage, 100);
			SetTaiwuLifeSkill(context, skillTemplateId2, taiwuLifeSkill);
			SetLifeSkillPageComplete(context, book, readingPage);
		}
	}

	private void SetLifeSkillPageComplete(DataContext context, GameData.Domains.Item.SkillBook book, byte readingPage)
	{
		if (!_readingBooks.TryGetValue(book.GetItemKey(), out var strategies) || !strategies.PageContainsStrategy(readingPage, 12))
		{
			short expGain = SkillGradeData.Instance[book.GetGrade()].ReadingExpGainPerPage;
			_taiwuChar.ChangeExp(context, expGain);
		}
		short skillTemplateId = book.GetLifeSkillTemplateId();
		if (_notLearnLifeSkillReadingProgress.ContainsKey(skillTemplateId))
		{
			TaiwuLearnLifeSkill(context, skillTemplateId, (byte)(1 << (int)readingPage));
			List<GameData.Domains.Character.LifeSkillItem> learnedLifeSkills = _taiwuChar.GetLearnedLifeSkills();
			GameData.Domains.Character.LifeSkillItem learnedLifeSkill = learnedLifeSkills[learnedLifeSkills.Count - 1];
			Tester.Assert(learnedLifeSkill.SkillTemplateId == skillTemplateId);
			Events.RaiseTaiwuLifeSkillBookPageFinished(context, learnedLifeSkill, book, readingPage);
			return;
		}
		int index = _taiwuChar.FindLearnedLifeSkillIndex(skillTemplateId);
		GameData.Domains.Character.LifeSkillItem oldLearnedLifeSkill = _taiwuChar.GetLearnedLifeSkills()[index];
		_taiwuChar.CheckLearnedBookHasUnlockedDebateStrategy(oldLearnedLifeSkill, out var strategyTemplateId, out var _);
		DebateStrategyItem strategyConfig = DebateStrategy.Instance[strategyTemplateId];
		Dictionary<sbyte, int> oldDict = _taiwuChar.GetHasUnlockedDebateStrategyLearnedBookCountDict(strategyConfig.Level);
		if (_taiwuChar.GetLearnedLifeSkills()[index].IsPageRead(readingPage))
		{
			return;
		}
		_taiwuChar.ReadLifeSkillPage(context, index, readingPage);
		GameData.Domains.Character.LifeSkillItem learnedLifeSkill2 = _taiwuChar.GetLearnedLifeSkills()[index];
		if (SkillBookStateHelper.GetPageIncompleteState(book.GetPageIncompleteState(), readingPage) == 0)
		{
			DomainManager.Taiwu.AddLegacyPoint(context, 15);
		}
		else
		{
			DomainManager.Taiwu.AddLegacyPoint(context, 16);
		}
		if (learnedLifeSkill2.IsAllPagesRead())
		{
			DomainManager.Taiwu.AddLegacyPoint(context, 17);
			short unlockedDebateStrategy = _taiwuChar.GetUnlockedDebateStrategy(learnedLifeSkill2, oldDict);
			if (unlockedDebateStrategy >= 0)
			{
				List<short> unlockedDebateStrategyList = DomainManager.Taiwu.GetUnlockedDebateStrategyList();
				if (!unlockedDebateStrategyList.Contains(unlockedDebateStrategy))
				{
					unlockedDebateStrategyList.Add(unlockedDebateStrategy);
					DomainManager.Taiwu.SetUnlockedDebateStrategyList(unlockedDebateStrategyList, context);
					GameData.GameDataBridge.GameDataBridge.AddDisplayEvent(DisplayEventType.UnlockLifeSkillCombatStrategy);
				}
			}
		}
		Events.RaiseTaiwuLifeSkillBookPageFinished(context, learnedLifeSkill2, book, readingPage);
	}

	private void SetCombatSkillPageComplete(DataContext context, GameData.Domains.Item.SkillBook book, byte internalIndex)
	{
		byte readingPage = CombatSkillStateHelper.GetPageId(internalIndex);
		if (!_readingBooks.TryGetValue(book.GetItemKey(), out var strategies) || !strategies.PageContainsStrategy(readingPage, 12))
		{
			short expGain = SkillGradeData.Instance[book.GetGrade()].ReadingExpGainPerPage;
			_taiwuChar.ChangeExp(context, expGain);
		}
		short skillTemplateId = book.GetCombatSkillTemplateId();
		if (_notLearnCombatSkillReadingProgress.ContainsKey(skillTemplateId))
		{
			ushort readingState = CombatSkillStateHelper.SetPageRead(0, internalIndex);
			TaiwuLearnCombatSkill(context, skillTemplateId, readingState);
			DomainManager.Global.InvokeGuidingTrigger(context, 236);
		}
		else
		{
			GameData.Domains.CombatSkill.CombatSkill skillItem = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillTemplateId));
			if (CombatSkillStateHelper.IsPageRead(skillItem.GetReadingState(), internalIndex))
			{
				return;
			}
			DomainManager.CombatSkill.SetCombatSkillReadingState(context, skillItem, CombatSkillStateHelper.SetPageRead(skillItem.GetReadingState(), internalIndex));
			if (SkillBookStateHelper.GetPageIncompleteState(book.GetPageIncompleteState(), readingPage) == 0)
			{
				DomainManager.Taiwu.AddLegacyPoint(context, 21);
			}
			else
			{
				DomainManager.Taiwu.AddLegacyPoint(context, 22);
			}
		}
		DomainManager.CombatSkill.TryActivateCombatSkillBookPageWhenSetReadingState(context, _taiwuCharId, skillTemplateId, internalIndex);
		GameData.Domains.CombatSkill.CombatSkill combatSkill = DomainManager.CombatSkill.GetElement_CombatSkills(new CombatSkillKey(_taiwuCharId, skillTemplateId));
		Events.RaiseTaiwuCombatSkillBookPageFinished(context, combatSkill, book, internalIndex);
	}

	private bool OfflineAddReadingProgress(ITaiwuSkill skill, byte readingPage, int delta)
	{
		sbyte progress = skill.GetBookPageReadingProgress(readingPage);
		progress = (sbyte)Math.Min(100, progress + delta);
		skill.SetBookPageReadingProgress(readingPage, progress);
		return progress == 100;
	}

	public byte GetCurrentReadingPage(GameData.Domains.Item.SkillBook book, ReadingBookStrategies strategies, TaiwuCombatSkill combatSkill)
	{
		sbyte[] readingProgress = combatSkill.GetAllBookPageReadingProgress();
		byte bookPageTypes = book.GetPageTypes();
		sbyte pageType = SkillBookStateHelper.GetOutlinePageType(bookPageTypes);
		byte pageInternalIndex = CombatSkillStateHelper.GetOutlinePageInternalIndex(pageType);
		if (readingProgress[pageInternalIndex] < 100 && !strategies.GetSkipPage(0))
		{
			return 0;
		}
		for (byte page = 1; page < 6; page++)
		{
			pageType = SkillBookStateHelper.GetNormalPageType(bookPageTypes, page);
			pageInternalIndex = CombatSkillStateHelper.GetNormalPageInternalIndex(pageType, page);
			if (readingProgress[pageInternalIndex] < 100 && !strategies.GetSkipPage(page))
			{
				return page;
			}
		}
		return 6;
	}

