	[DomainMethod]
	public sbyte GetTotalReadingProgress(int bookItemId)
	{
		if (!DomainManager.Item.TryGetElement_SkillBooks(bookItemId, out var book))
		{
			return 0;
		}
		sbyte[] pageProgress;
		if (SkillGroup.FromItemSubType(book.GetItemSubType()) == 0)
		{
			short skillTemplateId = book.GetLifeSkillTemplateId();
			pageProgress = (DomainManager.Taiwu.TryGetElement_LifeSkills(skillTemplateId, out var lifeSkill) ? lifeSkill.GetAllBookPageReadingProgress() : ((!DomainManager.Taiwu.TryGetElement_NotLearnLifeSkillReadingProgress(skillTemplateId, out var notLearnLifeSkill)) ? new sbyte[5] : notLearnLifeSkill.GetAllBookPageReadingProgress()));
		}
		else
		{
			byte pageTypes = book.GetPageTypes();
			sbyte behaviorType = SkillBookStateHelper.GetOutlinePageType(pageTypes);
			short skillTemplateId = book.GetCombatSkillTemplateId();
			sbyte[] readingProgress = null;
			TaiwuCombatSkill notLearnCombatSkill;
			if (DomainManager.Taiwu.TryGetElement_CombatSkills(skillTemplateId, out var combatSkill))
			{
				readingProgress = combatSkill.GetAllBookPageReadingProgress();
			}
			else if (DomainManager.Taiwu.TryGetElement_NotLearnCombatSkillReadingProgress(skillTemplateId, out notLearnCombatSkill))
			{
				readingProgress = notLearnCombatSkill.GetAllBookPageReadingProgress();
			}
			pageProgress = new sbyte[6];
			if (readingProgress != null)
			{
				for (byte i = 0; i < 6; i++)
				{
					sbyte direction = SkillBookStateHelper.GetNormalPageType(pageTypes, i);
					pageProgress[i] = readingProgress[CombatSkillStateHelper.GetPageInternalIndex(behaviorType, direction, i)];
				}
			}
		}
		return (sbyte)(pageProgress.Sum() / pageProgress.Length);
	}

	[DomainMethod]
	public List<sbyte> GetTotalReadingProgressList(List<int> bookItemIdList)
	{
		if (bookItemIdList == null || bookItemIdList.Count == 0)
		{
			return new List<sbyte>();
		}
		List<sbyte> readingProgressList = new List<sbyte>();
		foreach (int id in bookItemIdList)
		{
			readingProgressList.Add(GetTotalReadingProgress(id));
		}
		return readingProgressList;
	}

