	[DomainMethod]
	public short GetCurrReadingEventBonusRate()
	{
		if (GetCurrReadingBanByWug())
		{
			return 0;
		}
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		int readingEventTotalRate;
		if (DomainManager.TutorialChapter.InGuiding && DomainManager.TutorialChapter.GetTutorialChapter() == 5 && _curReadingBook.TemplateId == 878)
		{
			readingEventTotalRate = ((GetTotalReadingProgress(_curReadingBook.Id) < 100) ? 100 : 0);
			return (short)readingEventTotalRate;
		}
		readingEventTotalRate = 20;
		for (int i = 0; i < _referenceBooks.Length; i++)
		{
			if (_referenceBooks[i].IsValid())
			{
				GameData.Domains.Item.SkillBook referenceBook = DomainManager.Item.GetElement_SkillBooks(_referenceBooks[i].Id);
				if (SkillGroup.FromItemSubType(referenceBook.GetItemSubType()) == 0)
				{
					readingEventTotalRate += LifeSkill.Instance[referenceBook.GetLifeSkillTemplateId()].ReadingEventBonusRate;
				}
			}
		}
		return (short)MathF.Min(100f, readingEventTotalRate);
	}

	[DomainMethod]
	public short GetCurrReadingEfficiency(DataContext context)
	{
		if (GetCurrReadingBanByWug())
		{
			return 0;
		}
		if (!_curReadingBook.IsValid())
		{
			return 0;
		}
		if (!_readingBooks.ContainsKey(_curReadingBook))
		{
			ReadingBookStrategies readingBookStrats = default(ReadingBookStrategies);
			readingBookStrats.Initialize();
			AddElement_ReadingBooks(_curReadingBook, ref readingBookStrats, context);
		}
		ReadingBookStrategies strategies = _readingBooks[_curReadingBook];
		GameData.Domains.Item.SkillBook book = DomainManager.Item.GetElement_SkillBooks(_curReadingBook.Id);
		short skillTemplateId = -1;
		byte readingPage = 0;
		if (book.IsCombatSkillBook())
		{
			skillTemplateId = book.GetCombatSkillTemplateId();
			TaiwuCombatSkill combatSkill = GetTaiwuCombatSkill(skillTemplateId);
			readingPage = GetCurrentReadingPage(book, strategies, combatSkill);
			if (readingPage >= 6)
			{
				readingPage = 0;
			}
		}
		else
		{
			skillTemplateId = book.GetLifeSkillTemplateId();
			TaiwuLifeSkill lifeSkill = GetTaiwuLifeSkill(skillTemplateId);
			readingPage = GetCurrentReadingPage(book, strategies, lifeSkill);
			if (readingPage >= 5)
			{
				readingPage = 0;
			}
		}
		int readingSpeed = GetBaseReadingSpeed(readingPage) * GetReadingSpeedBonus(readingPage, isInBattle: false, 0, 0) / 100;
		return (short)readingSpeed;
	}

	[DomainMethod]
	public unsafe void ActiveReadOnce(DataContext context)
	{
		int dayCost = GlobalConfig.Instance.ActiveReadingTimeCost;
		MainAttributes mainAttributes = _taiwuChar.GetCurrMainAttributes();
		short intelligenceCost = GlobalConfig.Instance.ActiveReadingAttributeCost;
		short curInt = mainAttributes.Items[5];
		if (DomainManager.World.GetLeftDaysInCurrMonth() < dayCost)
		{
			Logger.Warn("You don't have enough days in this month");
			return;
		}
		if (intelligenceCost > curInt)
		{
			Logger.Warn($"You don't have enough intelligence: {intelligenceCost} needed, current int is {curInt}");
			return;
		}
		AdventureTaiwu adventureTaiwu = DomainManager.Adventure.GetAdventureTaiwu();
		if (!adventureTaiwu.InAdventure)
		{
			DomainManager.World.AdvanceDaysInMonth(context, dayCost);
		}
		else if (!DomainManager.Adventure.ConsumeActionPointInAdventure(context, dayCost * 10))
		{
			return;
		}
		if (intelligenceCost > 0)
		{
			_taiwuChar.ChangeCurrMainAttribute(context, 5, -intelligenceCost);
		}
		short maxProgress = GlobalConfig.Instance.MaxActiveReadingProgress;
		short oldProgress = DomainManager.Extra.GetActiveReadingProgress();
		int newProgress = oldProgress + 1;
		if (newProgress <= maxProgress)
		{
			DomainManager.Extra.SetActiveReadingProgress((short)newProgress, context);
			int efficiency = GlobalConfig.Instance.ActiveReadProgressAffectedEfficiency[oldProgress / 10];
			if (newProgress % 10 == 0)
			{
				MakeReadingProgressActuallyWork(context, efficiency);
			}
		}
	}

	public void ClearActiveReadingProgressOnMonthChange(DataContext context)
	{
		short nowProgress = DomainManager.Extra.GetActiveReadingProgress();
		int newProgress = nowProgress % 10;
		DomainManager.Extra.SetActiveReadingProgress((short)newProgress, context);
	}

	public void GenerateAvailableReadingStrategies(DataContext context)
	{
		if (!_curReadingBook.IsValid())
		{
			return;
		}
		SByteList result = SByteList.Create();
		if (DomainManager.TutorialChapter.InGuiding && DomainManager.TutorialChapter.GetTutorialChapter() == 5 && _curReadingBook.TemplateId == 878)
		{
			for (int i = 0; i < 9; i++)
			{
				result.Items.Add(18);
			}
			DomainManager.Extra.SetAvailableReadingStrategies(context, _curReadingBook.Id, result);
			return;
		}
		List<List<sbyte>> groupedResult = new List<List<sbyte>>();
		for (int j = 0; j < 3; j++)
		{
			groupedResult.Add(new List<sbyte>());
		}
		ItemKey[] referenceBooks = _referenceBooks;
		if (referenceBooks != null && referenceBooks.Length != 0)
		{
			ItemKey[] array = referenceBooks;
			for (int k = 0; k < array.Length; k++)
			{
				ItemKey referenceBookItemKey = array[k];
				if (!referenceBookItemKey.IsValid())
				{
					continue;
				}
				short lifeSkillTid = Config.SkillBook.Instance[referenceBookItemKey.TemplateId].LifeSkillTemplateId;
				if (lifeSkillTid >= 0)
				{
					sbyte strategyTid = DrawOneStrategyByBook(context.Random, lifeSkillTid);
					if (strategyTid != -1)
					{
						groupedResult[ReadingStrategy.Instance[strategyTid].ExtractGroup - 1].Add(strategyTid);
					}
				}
			}
		}
		List<sbyte> configGroup = new List<sbyte>();
		List<short> weightList = new List<short>();
		for (int l = 0; l < 3; l++)
		{
			configGroup.Clear();
			weightList.Clear();
			foreach (ReadingStrategyItem config in (IEnumerable<ReadingStrategyItem>)ReadingStrategy.Instance)
			{
				sbyte id = config.TemplateId;
				if (config.ExtractGroup - 1 == l)
				{
					configGroup.Add(id);
					weightList.Add(config.ExtractWeight);
				}
			}
			while (groupedResult[l].Count < 3)
			{
				int randIndex = RandomUtils.GetRandomIndex(weightList, context.Random);
				sbyte drawnConfigIndex = configGroup[randIndex];
				groupedResult[l].Add(drawnConfigIndex);
			}
		}
		foreach (List<sbyte> group in groupedResult)
		{
			result.Items.AddRange(group);
		}
		if (DomainManager.Extra.IsProfessionalSkillUnlocked(4, 1))
		{
			int seniority = DomainManager.Extra.GetProfessionData(4).Seniority;
			int extraCount = ProfessionData.SeniorityToExtraReadingLoopingStrategyCount(seniority);
			for (int m = 0; m < extraCount; m++)
			{
				int strategyTid2 = context.Random.Next(ReadingStrategy.Instance.Count - 1);
				result.Items.Add((sbyte)strategyTid2);
			}
		}
		DomainManager.Extra.SetAvailableReadingStrategies(context, _curReadingBook.Id, result);
	}

	private sbyte DrawOneStrategyByBook(IRandomSource randomSource, short lifeSkillTid)
	{
		Config.LifeSkillItem config = LifeSkill.Instance[lifeSkillTid];
		List<byte> configPossibleStrategies = config.ProvidedReadingStrategies;
		if (configPossibleStrategies == null || configPossibleStrategies.Count == 0)
		{
			return -1;
		}
		List<short> weights = new List<short>();
		foreach (byte strategyTid in configPossibleStrategies)
		{
			weights.Add(ReadingStrategy.Instance[strategyTid].ExtractWeight);
		}
		int index = RandomUtils.GetRandomIndex(weights, randomSource);
		return (sbyte)configPossibleStrategies[index];
	}

