	public (bool, int) ReadSkillBookPage(DataContext context, GameData.Domains.Item.SkillBook book, byte combatSkillBookInternalIndex, int speed, bool isCombatSkill, ref int remainingSpeedPercent, ref byte readingPage)
	{
		short skillTemplateId = (isCombatSkill ? book.GetCombatSkillTemplateId() : book.GetLifeSkillTemplateId());
		TaiwuCombatSkill combatSkill = GetTaiwuCombatSkill(skillTemplateId);
		TaiwuLifeSkill lifeSkill = GetTaiwuLifeSkill(skillTemplateId);
		ITaiwuSkill taiwuSkill2;
		if (!isCombatSkill)
		{
			ITaiwuSkill taiwuSkill = lifeSkill;
			taiwuSkill2 = taiwuSkill;
		}
		else
		{
			ITaiwuSkill taiwuSkill = combatSkill;
			taiwuSkill2 = taiwuSkill;
		}
		ITaiwuSkill skill = taiwuSkill2;
		sbyte readingProgress = skill.GetBookPageReadingProgress(combatSkillBookInternalIndex);
		int addingProgress = speed * remainingSpeedPercent / 100;
		bool pageComplete = OfflineAddReadingProgress(skill, combatSkillBookInternalIndex, addingProgress);
		int addedProgress = skill.GetBookPageReadingProgress(combatSkillBookInternalIndex) - readingProgress;
		if (isCombatSkill)
		{
			SetTaiwuCombatSkill(context, skillTemplateId, combatSkill);
			if (pageComplete)
			{
				SetCombatSkillPageComplete(context, book, combatSkillBookInternalIndex);
			}
		}
		else
		{
			SetTaiwuLifeSkill(context, skillTemplateId, lifeSkill);
			if (pageComplete)
			{
				SetLifeSkillPageComplete(context, book, combatSkillBookInternalIndex);
			}
		}
		remainingSpeedPercent -= addedProgress * 100 / speed;
		readingPage++;
		return (pageComplete, addedProgress);
	}

	[DomainMethod]
	public ReadAndLoopDisplayData RequestReadingAndLooping()
	{
		GameData.Domains.CombatSkill.CombatSkill skill;
		bool hasSkill = DomainManager.CombatSkill.TryGetElement_CombatSkills(new CombatSkillKey(_taiwuChar.GetId(), _taiwuChar.GetLoopingNeigong()), out skill);
		return new ReadAndLoopDisplayData
		{
			BookKey = _curReadingBook,
			BookReadProgress = (sbyte)(_curReadingBook.IsValid() ? GetTotalReadingProgress(_curReadingBook.Id) : (-1)),
			LoopingId = _taiwuChar.GetLoopingNeigong(),
			HasEventFlag = (sbyte)((DomainManager.Extra.GetReadingEventBookIdList().Contains(_curReadingBook.Id) ? 1 : 0) | (DomainManager.Extra.GetLoopingEventSkillIdList().Contains(_taiwuChar.GetLoopingNeigong()) ? 2 : 0)),
			LoopingObtainedNeili = (short)(hasSkill ? skill.GetObtainedNeili() : 0),
			LoopingTotalObtainableNeili = (short)((!hasSkill) ? 1 : skill.GetTotalObtainableNeili()),
			ReferenceBook = GetReferenceBooks(),
			Durabilities = GetReferenceBooks().Prepend(_curReadingBook).Select(delegate(ItemKey x)
			{
				int result;
				if (x.IsValid())
				{
					ItemBase itemBase = DomainManager.Item.TryGetBaseItem(x.ItemType, x.Id);
					if (itemBase != null)
					{
						result = itemBase.GetCurrDurability();
						goto IL_002c;
					}
				}
				result = 0;
				goto IL_002c;
				IL_002c:
				return result;
			}).ToList(),
			ActiveLoopingProgress = DomainManager.Extra.GetActiveLoopingProgress(),
			ActiveReadingProgress = DomainManager.Extra.GetActiveReadingProgress(),
			MainAttributes = _taiwuChar.GetCurrMainAttributes()
		};
	}

