	public bool TryAddVisitedSettlement(short settlementId, DataContext context)
	{
		if (_visitedSettlements.Contains(settlementId))
		{
			return false;
		}
		_visitedSettlements.Add(settlementId);
		SetVisitedSettlements(_visitedSettlements, context);
		Location settlementLocation = DomainManager.Organization.GetSettlement(settlementId).GetLocation();
		EMapBlockType settlementType = DomainManager.Map.GetBlock(settlementLocation).GetConfig().Type;
		bool flag = (uint)settlementType <= 1u;
		int formulaId = (flag ? 75 : 76);
		int addSeniority = ProfessionFormula.Instance[formulaId].Calculate();
		DomainManager.Extra.ChangeProfessionSeniority(context, 11, addSeniority);
		return true;
	}

	public void RecordTrace(DataContext context, int srcId, int dstId, bool isSwapSoulThusWillSetIsMergeLater = false)
	{
		if (_taiwuCharIdForJixi == srcId)
		{
			SetTaiwuCharIdForJixi(dstId, context);
			if (!isSwapSoulThusWillSetIsMergeLater)
			{
				SetTaiwuCharIdForJixiIsMerge(value: false, context);
			}
		}
		if (_taiwuCharIdForCloseFriend == srcId)
		{
			SetTaiwuCharIdForCloseFriend(dstId, context);
		}
	}

	public void RecordMergingTrace(DataContext context, int soulId, int bodyId)
	{
		if (_taiwuCharIdForJixi == soulId)
		{
			SetTaiwuCharIdForJixiIsMerge(value: true, context);
		}
		RecordTrace(context, bodyId, -1, isSwapSoulThusWillSetIsMergeLater: true);
		RecordTrace(context, soulId, bodyId, isSwapSoulThusWillSetIsMergeLater: true);
	}

	public void RecordMergingTrace(DataContext context, List<int> soulIds, int bodyId)
	{
		if (soulIds.Contains(_taiwuCharIdForJixi))
		{
			SetTaiwuCharIdForJixiIsMerge(value: true, context);
		}
		RecordTrace(context, bodyId, -1, isSwapSoulThusWillSetIsMergeLater: true);
		foreach (int soul in soulIds)
		{
			RecordTrace(context, soul, bodyId, isSwapSoulThusWillSetIsMergeLater: true);
		}
	}

