	public int CalcItemContribution(ItemKey itemKey, int amount)
	{
		short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
		int value = DomainManager.Item.GetValue(itemKey);
		SettlementTreasury treasury = GetTaiwuTreasury();
		return treasury.CalcAdjustedWorth(itemSubType, value) * amount * GlobalConfig.Instance.ItemContributionPercent / 100;
	}

	public void UpdateTaiwuTreasury(DataContext context)
	{
		int currDate = DomainManager.World.GetCurrDate();
		ClearTaiwuVillageStoragesRecordCollection(context);
		TaiwuVillageStoragesRecordCollection collection = GetTaiwuVillageStoragesRecordCollection();
		for (sbyte i = 0; i < 5; i++)
		{
			collection.AddClearRecord(currDate, (TaiwuVillageStorageType)i);
		}
		collection.AddClearRecord(currDate, TaiwuVillageStorageType.Warehouse);
		CommitTaiwuVillageStoragesRecordCollection(context);
	}

	[DomainMethod]
	public TaiwuVillageStoragesRecordCollection GetTaiwuVillageStoragesRecordCollection(DataContext context)
	{
		return GetTaiwuVillageStoragesRecordCollection();
	}

	[DomainMethod]
	public TransferableRecordDataBase GetReversedTaiwuVillageStoragesRecordCollection(DataContext context)
	{
		TaiwuVillageStoragesRecordCollection collection = GetTaiwuVillageStoragesRecordCollection();
		TransferableRecordDataBase data = new TransferableRecordDataBase();
		collection.ReadTaiwuVillageDataWithNormalOrder(data, GetParameters);
		LifeRecordDomain.PostProcess(data);
		return data;
		static string[] GetParameters(int recordType)
		{
			TaiwuVillageStoragesRecordItem config = TaiwuVillageStoragesRecord.Instance[recordType];
			if (config != null)
			{
				return config.Parameters ?? Array.Empty<string>();
			}
			AdaptableLog.Warning($"Unable to render TaiwuVillageStoragesRecord with template id {recordType}");
			return null;
		}
	}

	public void CommitTaiwuVillageStoragesRecordCollection(DataContext context)
	{
		int deltaSize = _taiwuVillageStoragesRecordCollection.Size - _taiwuVillageStoragesRecordCommittedOffset;
		if (deltaSize > 0)
		{
			CommitInsert_TaiwuVillageStoragesRecordCollection(context, _taiwuVillageStoragesRecordCommittedOffset, deltaSize);
			CommitSetMetadata_TaiwuVillageStoragesRecordCollection(context);
			_taiwuVillageStoragesRecordCommittedOffset = _taiwuVillageStoragesRecordCollection.Size;
		}
	}

	public void ClearTaiwuVillageStoragesRecordCollection(DataContext context)
	{
		CommitTaiwuVillageStoragesRecordCollection(context);
		_taiwuVillageStoragesRecordCommittedOffset = 0;
		int size = _taiwuVillageStoragesRecordCollection.Size;
		_taiwuVillageStoragesRecordCollection.Clear();
		CommitRemove_TaiwuVillageStoragesRecordCollection(context, 0, size);
		CommitSetMetadata_TaiwuVillageStoragesRecordCollection(context);
	}

