	internal void CommitTaiwuVillageStorages(DataContext context)
	{
		if (_warehouse.NeedCommit)
		{
			SetWarehouse(_warehouse, context);
			_warehouse.NeedCommit = false;
		}
		if (_stock.NeedCommit)
		{
			SetStock(_stock, context);
			_stock.NeedCommit = false;
		}
		if (_trough.NeedCommit)
		{
			SetTrough(_trough, context);
			_trough.NeedCommit = false;
		}
		CommitTaiwuSettlementTreasury(context);
	}

