	[DomainMethod]
	public bool SetFarmerMigrateWork(DataContext context, int charId, short areaId, sbyte resourceType)
	{
		short blockId = DomainManager.Map.GetAreaByAreaId(areaId).StationBlockId;
		RemoveVillagerWork(context, charId, removeUnlockedState: false);
		VillagerWorkData workData = new VillagerWorkData(charId, 14, areaId, blockId);
		workData.ResourceType = resourceType;
		VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(charId);
		if (villagerRole == null)
		{
			Logger.Warn($"character {charId} is not assigned as any villager role.");
			return false;
		}
		villagerRole.ArrangementTemplateId = 2;
		DomainManager.Extra.SetVillagerRole(context, charId);
		SetVillagerWork(context, charId, workData);
		return true;
	}

