	[DomainMethod]
	public bool StopVillagerWorkOptional(DataContext context, short areaId, short blockId, sbyte workType, bool removeUnlockedState)
	{
		foreach (KeyValuePair<int, VillagerWorkData> work in _villagerWork)
		{
			if ((work.Value.WorkType == workType || workType == -1) && work.Value.AreaId == areaId && work.Value.BlockId == blockId)
			{
				RemoveVillagerWork(context, work.Key, removeUnlockedState);
				return true;
			}
		}
		return false;
	}

