	public void VillagerLeaveTaiwuVillage(DataContext context, GameData.Domains.Character.Character character)
	{
		if (character.GetAgeGroup() == 0)
		{
			throw new ArgumentException($"You cannot expel a baby {character.GetId()}.");
		}
		if (IsInGroup(character.GetId()))
		{
			LeaveGroup(context, character.GetId());
		}
		DomainManager.Organization.JoinNearbyVillageTownAsBeggar(context, character, -1);
		Location characterLocation = character.GetLocation();
		if (characterLocation.IsValid())
		{
			MapBlockData blockData = DomainManager.Map.GetBlock(characterLocation);
			DomainManager.Map.SetBlockData(context, blockData);
		}
	}

	[DomainMethod]
	public void ExpelVillager(DataContext context, int charId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		VillagerLeaveTaiwuVillage(context, character);
		LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
		int currDate = DomainManager.World.GetCurrDate();
		lifeRecordCollection.AddExpelVillager(_taiwuCharId, currDate, charId, _taiwuChar.GetLocation());
		sbyte behaviorType = character.GetBehaviorType();
		if ((behaviorType == 0 || (uint)(behaviorType - 3) <= 1u) ? true : false)
		{
			GameData.Domains.Character.Character.ApplyAddRelation_Enemy(context, character, _taiwuChar, selfIsTaiwuPeople: true, 0);
		}
		InstantNotificationCollection instantNotifications = DomainManager.World.GetInstantNotificationCollection();
		instantNotifications.AddLeaveTaiwuVillage(charId);
		EventHelper.ChangeFavorabilityOptional(character, _taiwuChar, GlobalConfig.Instance.FavorabilityChangeOnExpel[behaviorType], 4);
	}

	[DomainMethod]
	public void ExpelVillagers(DataContext context, List<int> charIds)
	{
		HashSet<int> team = DomainManager.Taiwu.GetGroupCharIds().GetCollection().ToHashSet();
		foreach (int charId in charIds.Where(team.Contains).Concat(charIds.Where((int id) => !team.Contains(id))))
		{
			ExpelVillager(context, charId);
		}
	}

