	public void MakeVillagerWorkSettlementsVisited(DataContext context)
	{
		MapDomain mapDomain = DomainManager.Map;
		CharacterDomain characterDomain = DomainManager.Character;
		foreach (KeyValuePair<int, VillagerWorkData> workPair in _villagerWork)
		{
			if (!characterDomain.TryGetElement_Objects(workPair.Key, out var workCharacter))
			{
				continue;
			}
			Location characterLocation = workCharacter.GetLocation();
			if (characterLocation.AreaId != workPair.Value.AreaId || characterLocation.BlockId != workPair.Value.BlockId)
			{
				continue;
			}
			MapBlockData currentRootBlock = mapDomain.GetBlock(characterLocation).GetRootBlock();
			MapAreaData areaData = mapDomain.GetElement_Areas(characterLocation.AreaId);
			SettlementInfo[] settlementInfos = areaData.SettlementInfos;
			for (int i = 0; i < settlementInfos.Length; i++)
			{
				SettlementInfo settlementInfo = settlementInfos[i];
				if (settlementInfo.BlockId == currentRootBlock.BlockId)
				{
					TryAddVisitedSettlement(settlementInfo.SettlementId, context);
				}
			}
		}
	}

	public void SetVillagerWork(DataContext context, int charId, VillagerWorkData workData, bool allowChild = false)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		bool isTutorial = DomainManager.TutorialChapter.InGuiding && DomainManager.TutorialChapter.GetTutorialChapter() == 1;
		if (!allowChild && character.GetPhysiologicalAge() < 16 && !isTutorial)
		{
			throw new Exception($"Cannot send a child to work: {character}");
		}
		if (_villagerWork.TryGetValue(charId, out var prevWork))
		{
			if (prevWork.GetVillagerRole() != null && workData.GetVillagerRole() == null)
			{
				prevWork.GetVillagerRole().ArrangementTemplateId = -1;
				prevWork.GetVillagerRole().WorkData = null;
				DomainManager.Extra.SetVillagerRole(context, charId);
			}
			RemoveVillagerWork(context, charId);
		}
		AddElement_VillagerWork(charId, workData, context);
		VillagerRoleBase role = DomainManager.Extra.GetVillagerRole(charId);
		if (role != null)
		{
			role.WorkData = workData;
		}
		switch (workData.WorkType)
		{
		case 0:
			DomainManager.Building.SetBuildingOperator(context, new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), workData.WorkerIndex, charId);
			break;
		case 1:
			DomainManager.Building.SetShopBuildingManager(context, new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), workData.WorkerIndex, charId);
			break;
		case 2:
			if (workData.GetVillagerRole() == null || workData.GetVillagerRole().ArrangementTemplateId < 0)
			{
				throw new Exception($"Need a role to work a job: {character}");
			}
			break;
		default:
			AddVillagerWorkLocations(context, new Location(workData.AreaId, workData.BlockId));
			break;
		}
		if (VillagerWorkType.IsWorkOnMapAndNeedMark(workData.WorkType))
		{
			DomainManager.Building.AddLocationMark(context, new Location(workData.AreaId, workData.BlockId));
		}
		character.ActiveExternalRelationState(context, 1uL);
		if (VillagerWorkType.IsWorkOnMap(workData.WorkType) && DomainManager.World.IsExtraTaskInProgress(24))
		{
			DomainManager.World.FinishTriggeredExtraTask(context, 13, 24);
		}
	}

	public void RemoveVillagerWork(DataContext context, int charId, bool removeUnlockedState = true)
	{
		if (!_villagerWork.TryGetValue(charId, out var oldWorkData))
		{
			return;
		}
		if (oldWorkData.GetVillagerRole() != null)
		{
			oldWorkData.GetVillagerRole().WorkData = null;
			if (oldWorkData.GetVillagerRole().ArrangementTemplateId >= 0)
			{
				oldWorkData.GetVillagerRole().ArrangementTemplateId = -1;
				DomainManager.Extra.SetVillagerRole(context, charId);
			}
		}
		switch (oldWorkData.WorkType)
		{
		case 0:
			DomainManager.Building.SetBuildingOperator(context, new BuildingBlockKey(oldWorkData.AreaId, oldWorkData.BlockId, oldWorkData.BuildingBlockIndex), oldWorkData.WorkerIndex, -1);
			break;
		case 1:
			DomainManager.Building.SetShopBuildingManager(context, new BuildingBlockKey(oldWorkData.AreaId, oldWorkData.BlockId, oldWorkData.BuildingBlockIndex), oldWorkData.WorkerIndex, -1);
			break;
		case 14:
		{
			VillagerRoleBase villagerRole = DomainManager.Extra.GetVillagerRole(charId);
			if (villagerRole is VillagerRoleFarmer farmer)
			{
				farmer.ResetFailureAccumulation();
				DomainManager.Extra.SetVillagerRole(context, charId);
			}
			break;
		}
		default:
			RemoveVillagerWorkLocations(context, new Location(oldWorkData.AreaId, oldWorkData.BlockId));
			break;
		case 2:
			break;
		}
		if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
		{
			character.DeactivateExternalRelationState(context, 1uL);
		}
		RemoveElement_VillagerWork(charId, context);
		if (removeUnlockedState)
		{
			DomainManager.Building.TryRemoveUnlockedWorkingVillager(context, charId);
		}
	}

	public void AddVillagerWorkLocations(DataContext context, Location location)
	{
		if (_villagerWorkLocationCount.TryGetValue(location, out var count))
		{
			_villagerWorkLocationCount[location] = count + 1;
			return;
		}
		if (context != null)
		{
			AddElement_VillagerWorkLocations(location, default(VoidValue), context);
		}
		else
		{
			_villagerWorkLocations.Add(location, default(VoidValue));
		}
		_villagerWorkLocationCount[location] = 1;
	}

	public void RemoveVillagerWorkLocations(DataContext context, Location location)
	{
		if (!_villagerWorkLocationCount.TryGetValue(location, out var count))
		{
			AdaptableLog.Warning($"location {location} has no villager");
			CalcVillagerWorkLocations(context);
		}
		else if (count == 1)
		{
			_villagerWorkLocationCount.Remove(location);
			RemoveElement_VillagerWorkLocations(location, context);
		}
		else
		{
			_villagerWorkLocationCount[location] = count - 1;
		}
	}

	public void CalcVillagerWorkLocations(DataContext context = null)
	{
		foreach (VillagerWorkData workData in _villagerWork.Values)
		{
			if (VillagerWorkType.IsWorkOnMap(workData.WorkType))
			{
				AddVillagerWorkLocations(context, new Location(workData.AreaId, workData.BlockId));
			}
		}
	}

