	[DomainMethod]
	public List<int> GetAllVillagersAvailableForWork(bool actuallyNotOccupiedOnly = false)
	{
		List<int> memberList = new List<int>();
		if (DomainManager.TaiwuEvent.GetGlobalEventArgumentBox().Get("MainStoryLine_SpiritualWanderPlace_TaiwuVillagersCenter", out Location _))
		{
			return memberList;
		}
		DomainManager.Organization.GetElement_CivilianSettlements(_taiwuVillageSettlementId).GetMembers().GetAllMembers(memberList);
		for (int i = memberList.Count - 1; i >= 0; i--)
		{
			if (!IsVillagerAvailableForWork(memberList[i], actuallyNotOccupiedOnly))
			{
				memberList.RemoveAt(i);
			}
		}
		return memberList;
	}

	[DomainMethod]
	public List<int> GetAllChildAvailableForWork(bool actuallyNotOccupiedOnly = false)
	{
		List<int> memberList = new List<int>();
		DomainManager.Organization.GetElement_CivilianSettlements(_taiwuVillageSettlementId).GetMembers().GetAllMembers(memberList);
		for (int i = memberList.Count - 1; i >= 0; i--)
		{
			if (!IsVillagerChildAvailableForWork(memberList[i], actuallyNotOccupiedOnly))
			{
				memberList.RemoveAt(i);
			}
		}
		return memberList;
	}

