	public void MoveVillagersToWorkLocation(DataContext context)
	{
		MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
		_moveToWorkLocationCharList.Clear();
		foreach (KeyValuePair<int, VillagerWorkData> item in _villagerWork)
		{
			VillagerWorkData workData = item.Value;
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(workData.CharacterId);
			Location srcLocation = character.GetLocation();
			Location location = new Location(workData.AreaId, workData.BlockId);
			if (!location.IsValid() || workData.WorkType == 2)
			{
				continue;
			}
			sbyte workType = workData.WorkType;
			if ((uint)workType <= 1u)
			{
				if (!DomainManager.Map.IsLocationInSettlementInfluenceRange(srcLocation, _taiwuVillageSettlementId))
				{
					List<short> blocks = new List<short>();
					DomainManager.Map.GetSettlementBlocksAndAffiliatedBlocks(location.AreaId, location.BlockId, blocks);
					int randomDestIndex = context.Random.Next(blocks.Count);
					Location destLocation = new Location(location.AreaId, blocks[randomDestIndex]);
					DomainManager.Character.LeaveGroup(context, character);
					DomainManager.Character.GroupMove(context, character, destLocation);
					_moveToWorkLocationCharList.Add(workData.CharacterId);
				}
				else
				{
					Location destLocation2 = srcLocation;
					DomainManager.Character.LeaveGroup(context, character);
					DomainManager.Character.GroupMove(context, character, destLocation2);
				}
			}
			else if (srcLocation.AreaId != workData.AreaId || srcLocation.BlockId != workData.BlockId)
			{
				Location destLocation3 = location;
				DomainManager.Character.LeaveGroup(context, character);
				DomainManager.Character.GroupMove(context, character, destLocation3);
				_moveToWorkLocationCharList.Add(workData.CharacterId);
			}
		}
	}

	public void CalcVillagerWorkLocation(DataContext context)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(10))
		{
			return;
		}
		List<MapBlockData> blockLocationList = new List<MapBlockData>();
		List<VillagerWorkData> workDataList = new List<VillagerWorkData>();
		List<VillagerWorkData> collectResourceList = new List<VillagerWorkData>();
		Dictionary<short, sbyte> blockDict = new Dictionary<short, sbyte>();
		foreach (IGrouping<short, VillagerWorkData> ids in from x in _villagerWork.Values.Where(delegate(VillagerWorkData x)
			{
				sbyte workType = x.WorkType;
				bool flag = ((workType == 10 || workType == 14) ? true : false);
				return flag && x.ResourceType != -1 && CanWork(x.CharacterId);
			})
			group x by x.AreaId)
		{
			DomainManager.Map.GetPassableBlocksInArea(ids.Key, blockLocationList);
			collectResourceList.AddRange(ids);
			workDataList.AddRange(collectResourceList.Where((VillagerWorkData x) => x.WorkType == 14));
			collectResourceList.RemoveAll((VillagerWorkData x) => x.WorkType == 14);
			ProcessFarmerMigration(context, blockLocationList, workDataList);
			foreach (VillagerWorkData workData in workDataList)
			{
				blockDict[workData.BlockId] = workData.ResourceType;
			}
			workDataList.Clear();
			foreach (IGrouping<sbyte, VillagerWorkData> types in from x in collectResourceList
				group x by x.ResourceType)
			{
				blockLocationList.Sort((MapBlockData x, MapBlockData y) => x.CurrResources[types.Key].CompareTo(y.CurrResources[types.Key]));
				workDataList.AddRange(types);
				workDataList.Sort(delegate(VillagerWorkData x, VillagerWorkData y)
				{
					int num = x.WorkType.CompareTo(y.WorkType);
					return (num != 0) ? num : ((x.GetVillagerRole() as VillagerRoleFarmer)?.CollectResourceActionCount ?? 0).CompareTo((y.GetVillagerRole() as VillagerRoleFarmer)?.CollectResourceActionCount ?? 0);
				});
				int counter = blockLocationList.Count - 1;
				while (workDataList.Count != 0 && counter >= 0)
				{
					VillagerWorkData workData2 = workDataList[workDataList.Count - 1];
					if (blockDict.TryGetValue(blockLocationList[counter].BlockId, out var type) && type == types.Key)
					{
						counter--;
						continue;
					}
					short blockId = blockLocationList[counter--].BlockId;
					RemoveVillagerWorkLocations(context, new Location(workData2.AreaId, workData2.BlockId));
					AddVillagerWorkLocations(context, new Location(workData2.AreaId, blockId));
					workDataList.RemoveAt(workDataList.Count - 1);
					workData2.BlockId = blockId;
				}
				foreach (VillagerWorkData work in workDataList)
				{
					RemoveVillagerWork(context, work.CharacterId);
					DomainManager.Extra.SetVillagerRole(context, work.CharacterId);
				}
				workDataList.Clear();
			}
			blockDict.Clear();
			collectResourceList.Clear();
		}
	}

	private void ProcessFarmerMigration(DataContext context, List<MapBlockData> blockLocationList, List<VillagerWorkData> workDataList)
	{
		int minResource = GlobalConfig.Instance.VillagerRoleFarmerMigrateMinResource;
		List<VillagerWorkData> pending = workDataList.Where(delegate(VillagerWorkData villagerWorkData)
		{
			MapBlockData blockData = DomainManager.Map.GetBlockData(villagerWorkData.AreaId, villagerWorkData.BlockId);
			return ((blockData != null) ? blockData.CurrResources[villagerWorkData.ResourceType] : 0) < minResource;
		}).ToList();
		List<MapBlockData> sortedBlocks = blockLocationList.OrderByDescending((MapBlockData item) => item.CurrResources.GetSum()).ToList();
		foreach (MapBlockData block in sortedBlocks)
		{
			VillagerWorkData matched = pending.FirstOrDefault((VillagerWorkData x) => block.CurrResources[x.ResourceType] >= minResource);
			if (matched != null)
			{
				RemoveVillagerWorkLocations(context, new Location(matched.AreaId, matched.BlockId));
				AddVillagerWorkLocations(context, new Location(matched.AreaId, block.BlockId));
				matched.BlockId = block.BlockId;
				pending.Remove(matched);
			}
		}
		foreach (VillagerWorkData workData in pending)
		{
			RemoveVillagerWork(context, workData.CharacterId);
			DomainManager.Extra.SetVillagerRole(context, workData.CharacterId);
		}
	}

	public void CalcVillagerWorkOnMap(DataContext context)
	{
		if (!DomainManager.World.GetWorldFunctionsStatus(10))
		{
			return;
		}
		foreach (KeyValuePair<int, VillagerWorkData> item in _villagerWork)
		{
			VillagerWorkData workData = item.Value;
			if (CanWork(workData.CharacterId))
			{
				switch (workData.WorkType)
				{
				case 10:
					VillagerWorkCollectResource(context, workData);
					break;
				case 14:
					VillagerWorkMigrateResource(context, workData);
					break;
				}
			}
		}
	}

