	public unsafe (int[] qualifications, int[] attianments) GetVillagerAverageLifeSkillInfo()
	{
		List<int> memberList = new List<int>();
		Settlement settlement = DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId);
		settlement.GetMembers().GetAllMembers(memberList);
		memberList.Remove(_taiwuCharId);
		int[] qualifications = new int[16];
		int[] attainments = new int[16];
		foreach (int charId in memberList)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				LifeSkillShorts skillQualifications = character.GetLifeSkillQualifications();
				LifeSkillShorts skillAttainments = character.GetLifeSkillAttainments();
				for (int i = 0; i < 16; i++)
				{
					qualifications[i] += skillQualifications.Items[i];
					attainments[i] += skillAttainments.Items[i];
				}
			}
		}
		if (memberList.Count > 0)
		{
			for (int j = 0; j < 16; j++)
			{
				qualifications[j] = Convert.ToInt32((float)qualifications[j] / (float)memberList.Count);
				attainments[j] = Convert.ToInt32((float)attainments[j] / (float)memberList.Count);
			}
		}
		return (qualifications: qualifications, attianments: attainments);
	}

