	public void UpdateVillagerTreasuryNeed(DataContext context)
	{
		CalcVillagerClasses();
		List<int> memberList = GetTaiwuVillagerMemberList();
		Settlement settlement = DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId);
		RemoveAllInvalidVillagerNeed(context, memberList, settlement);
		foreach (int charId in memberList)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			if (IsMeetWorkStatus(character, settlement))
			{
				character.VillagerReturnNotReadableBooks(context);
				character.ReturnVillagerRoleClothing(context);
			}
		}
		List<int>[] villagerListClassArray = _villagerListClassArray;
		foreach (List<int> charList in villagerListClassArray)
		{
			if (charList == null || charList.Count <= 0)
			{
				continue;
			}
			_timeMeetTreasuryNeedDict.Clear();
			foreach (int charId2 in charList)
			{
				UpdateVillagerTreasuryNeed(charId2);
			}
			if (_timeMeetTreasuryNeedDict.Count <= 0)
			{
				continue;
			}
			List<int> keyList = _timeMeetTreasuryNeedDict.Keys.ToList();
			CollectionUtils.Shuffle(context.Random, keyList);
			foreach (int charId3 in keyList)
			{
				List<GameData.Domains.Character.Ai.PersonalNeed> needs = _timeMeetTreasuryNeedDict[charId3];
				foreach (GameData.Domains.Character.Ai.PersonalNeed need in needs)
				{
					HandleVillagerTreasuryNeed(context, charId3, settlement, need.ItemType, need.ItemTemplateId);
				}
			}
		}
		RemoveAllInvalidVillagerNeed(context, memberList, settlement);
		DomainManager.Extra.ClearVillagerLastInfluencePowerGrades(context);
		for (int j = 0; j < _villagerListClassArray.Length; j++)
		{
			List<int> list = _villagerListClassArray[j];
			if (list == null || list.Count <= 0)
			{
				continue;
			}
			foreach (int charId4 in list)
			{
				GameData.Domains.Character.Character character2 = DomainManager.Character.GetElement_Objects(charId4);
				if (character2.GetAgeGroup() != 0 && IsMeetWorkStatus(character2, settlement))
				{
					HandleVillagerPersonalNeed(context, character2, settlement);
					HandleVillagerNoNeed(context, character2, settlement);
				}
			}
			sbyte charClass = Convert.ToSByte(8 - j);
			foreach (int charId5 in list)
			{
				DomainManager.Extra.SetVillagerLastInfluencePowerGrade(context, charId5, charClass);
			}
		}
		_treasuryNeededItemDict.Clear();
		foreach (int charId6 in memberList)
		{
			GameData.Domains.Character.Character character3 = DomainManager.Character.GetElement_Objects(charId6);
			character3.SetActionPlanningModified(context);
			if (!DomainManager.Extra.TryGetVillagerTreasuryNeed(charId6, out var villagerTreasuryNeed))
			{
				continue;
			}
			DomainManager.Extra.SetVillagerTreasuryNeed(context, charId6, villagerTreasuryNeed);
			foreach (GameData.Domains.Character.Ai.PersonalNeed personal in villagerTreasuryNeed.PersonalNeeds)
			{
				AddNeededItem(personal, charId6);
			}
		}
		foreach (int charId7 in memberList)
		{
			GameData.Domains.Character.Character character4 = DomainManager.Character.GetElement_Objects(charId7);
			if (IsMeetWorkStatus(character4, settlement))
			{
				character4.ReturnVillagerRoleClothing(context);
			}
		}
	}

	private void RemoveAllInvalidVillagerNeed(DataContext context, List<int> memberList, Settlement settlement)
	{
		foreach (int charId in memberList)
		{
			GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
			RemoveInvalidVillagerTreasuryNeed(character, GetTaiwuTreasury());
			RemoveInvalidVillagerPersonalNeed(context, character);
		}
	}

	private void UpdateVillagerTreasuryNeed(int charId)
	{
		if (!DomainManager.Extra.TryGetVillagerTreasuryNeed(charId, out var villagerTreasuryNeed))
		{
			return;
		}
		List<GameData.Domains.Character.Ai.PersonalNeed> personalNeeds = villagerTreasuryNeed.PersonalNeeds;
		if (personalNeeds == null || personalNeeds.Count <= 0 || !_villagerClassDict.TryGetValue(charId, out var charClass))
		{
			return;
		}
		for (int index = 0; index < villagerTreasuryNeed.PersonalNeeds.Count; index++)
		{
			GameData.Domains.Character.Ai.PersonalNeed personalNeed = villagerTreasuryNeed.PersonalNeeds[index];
			if (personalNeed.RemainingMonths > 0)
			{
				personalNeed.RemainingMonths--;
				if (DomainManager.Extra.TryGetVillagerLastInfluencePowerGrade(charId, out var lastCharClass))
				{
					sbyte itemGrade = ItemTemplateHelper.GetGrade(personalNeed.ItemType, personalNeed.ItemTemplateId);
					sbyte lastTime = CalcVillagerTreasuryNeedWaitTime(lastCharClass, itemGrade);
					sbyte curTime = CalcVillagerTreasuryNeedWaitTime(charClass, itemGrade);
					personalNeed.RemainingMonths += Convert.ToSByte(curTime - lastTime);
				}
				villagerTreasuryNeed.PersonalNeeds[index] = personalNeed;
			}
			if (personalNeed.RemainingMonths <= 0)
			{
				if (!_timeMeetTreasuryNeedDict.TryGetValue(charId, out var personalNeeds2))
				{
					personalNeeds2 = new List<GameData.Domains.Character.Ai.PersonalNeed>();
					_timeMeetTreasuryNeedDict[charId] = personalNeeds2;
				}
				personalNeeds2.Add(personalNeed);
			}
		}
	}

	private static sbyte CalcVillagerTreasuryNeedWaitTime(sbyte charClass, sbyte itemGrade)
	{
		return (sbyte)Math.Max(0, itemGrade - charClass);
	}

	private void HandleVillagerTreasuryNeed(DataContext context, int charId, Settlement settlement, sbyte itemType, short templateId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		List<ItemKey> selectionList = ObjectPool<List<ItemKey>>.Instance.Get();
		GetTaiwuTreasury().Inventory.GetInventoryItemKeyList(itemType, templateId, selectionList);
		if (selectionList.Count == 0)
		{
			ObjectPool<List<ItemKey>>.Instance.Return(selectionList);
			return;
		}
		selectionList.RemoveAll((ItemKey k) => !IsMeetInventoryLoad(character, k) || !ShouldTakeEquipment(character, k, checkEquipmentLoad: true));
		if (selectionList.Count == 0)
		{
			ObjectPool<List<ItemKey>>.Instance.Return(selectionList);
			return;
		}
		ItemKey targetItemKey = selectionList.GetRandom(context.Random);
		VillagerTakeItemFromTreasury(context, character, targetItemKey, 1);
		character.AddInventoryItem(context, targetItemKey, 1);
		HandleVillagerGainTreasuryItem(context, targetItemKey, character);
		ObjectPool<List<ItemKey>>.Instance.Return(selectionList);
	}

	private void RemoveInvalidVillagerTreasuryNeed(GameData.Domains.Character.Character selfChar, SettlementTreasury settlementTreasury)
	{
		if (!DomainManager.Extra.TryGetVillagerTreasuryNeed(selfChar.GetId(), out var villagerTreasuryNeed))
		{
			return;
		}
		List<GameData.Domains.Character.Ai.PersonalNeed> personalNeeds = villagerTreasuryNeed.PersonalNeeds;
		if (personalNeeds == null || personalNeeds.Count <= 0)
		{
			return;
		}
		villagerTreasuryNeed.PersonalNeeds?.RemoveAll(delegate(GameData.Domains.Character.Ai.PersonalNeed personalNeed)
		{
			List<ItemKey> list = ObjectPool<List<ItemKey>>.Instance.Get();
			settlementTreasury.Inventory.GetInventoryItemKeyList(personalNeed.ItemType, personalNeed.ItemTemplateId, list);
			if (list.Count == 0)
			{
				ObjectPool<List<ItemKey>>.Instance.Return(list);
				return true;
			}
			list.RemoveAll((ItemKey k) => !ShouldTakeEquipment(selfChar, k, checkEquipmentLoad: false));
			if (list.Count == 0)
			{
				ObjectPool<List<ItemKey>>.Instance.Return(list);
				return true;
			}
			ObjectPool<List<ItemKey>>.Instance.Return(list);
			if (selfChar.GetInventory().GetInventoryItemKey(personalNeed.ItemType, personalNeed.ItemTemplateId).IsValid())
			{
				return true;
			}
			return selfChar.GetEquipment().Exist((ItemKey k) => k.ItemType == personalNeed.ItemType && k.TemplateId == personalNeed.ItemTemplateId) ? true : false;
		});
	}

	private void HandleVillagerPersonalNeed(DataContext context, GameData.Domains.Character.Character character, Settlement settlement)
	{
		_villagerGainedItemTypeSet.Clear();
		_villagerItems.Clear();
		ItemKey key;
		int value;
		foreach (KeyValuePair<ItemKey, int> item in character.GetInventory().Items)
		{
			item.Deconstruct(out key, out value);
			ItemKey itemKey = key;
			int amount = value;
			_villagerItems[itemKey] = amount;
		}
		foreach (KeyValuePair<ItemKey, int> item2 in GetTaiwuTreasury().Inventory.Items)
		{
			item2.Deconstruct(out key, out value);
			ItemKey itemKey2 = key;
			int amount2 = value;
			_villagerItems.TryGetValue(itemKey2, out var oldAmount);
			_villagerItems[itemKey2] = oldAmount + amount2;
		}
		CategorizedRegenItems(_villagerItems);
		IReadOnlyList<CharacterGoalData> goals = character.GetGoals();
		for (int index = 0; index < goals.Count; index++)
		{
			CharacterGoalData goal = goals[index];
			switch (goal.GoalTemplateId)
			{
			case 228:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(4, goal.Args.InjuryType, goal.Args.Amount);
				HandleVillagerPersonalNeedForHealingAndDetox(context, character, settlement, personalNeed);
				break;
			}
			case 229:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(5, goal.Args.PoisonType, goal.Args.Amount);
				HandleVillagerPersonalNeedForHealingAndDetox(context, character, settlement, personalNeed);
				break;
			}
			case 230:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(2, goal.Args.Amount);
				HandleVillagerPersonalNeedForHealingAndDetox(context, character, settlement, personalNeed);
				break;
			}
			case 227:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(1, goal.Args.Amount);
				HandleVillagerPersonalNeedForHeath(context, character, settlement, personalNeed);
				break;
			}
			case 233:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(3, goal.Args.Amount);
				HandleVillagerPersonalNeedForNeili(context, character, settlement, personalNeed);
				break;
			}
			case 231:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(7, goal.Args.WugType);
				HandleVillagerPersonalNeedForWug(context, character, settlement, personalNeed);
				break;
			}
			case 234:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(6, goal.Args.MainAttributeType, goal.Args.Amount);
				HandleVillagerPersonalNeedForMainAttributes(context, character, settlement, personalNeed);
				break;
			}
			case 232:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(0, goal.Args.Amount);
				HandleVillagerPersonalNeedForHappiness(context, character, settlement, personalNeed);
				break;
			}
			case 236:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(8, goal.Args.ResourceType, goal.Args.Amount);
				HandleVillagerPersonalNeedForGainResource(context, character, settlement, personalNeed, index);
				break;
			}
			case 238:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(10, goal.Args.ItemType, goal.Args.ItemTemplateId);
				HandleVillagerPersonalNeedForGainItem(context, character, settlement, personalNeed);
				break;
			}
			case 241:
			{
				GameData.Domains.Character.Ai.PersonalNeed personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(12, goal.Args.PoisonType);
				HandleVillagerPersonalNeedForAddPoisonToItem(context, character, settlement, personalNeed);
				break;
			}
			}
		}
	}

	private void HandleVillagerNoNeed(DataContext context, GameData.Domains.Character.Character character, Settlement settlement)
	{
		short roleTemplateId = DomainManager.Extra.GetVillagerRoleTemplateId(character.GetId());
		VillagerRoleItem roleCfg = ((roleTemplateId >= 0) ? Config.VillagerRole.Instance[roleTemplateId] : null);
		sbyte charClass = _villagerClassDict[character.GetId()];
		HashSet<sbyte> lifeSkillTypeSet = VillagerRoleNeedLifeSkillBooks[roleTemplateId];
		bool canChangeEquipment = !_villagerGainedItemTypeSet.Any(ItemType.IsEquipmentItemType) && !DomainManager.Taiwu.GetManualChangeEquipGroupCharIds().Contains(character.GetId());
		bool canGainBook = !_villagerGainedItemTypeSet.Contains(10) && !character.HasReadableBook() && roleCfg != null;
		bool canGainTool = !_villagerGainedItemTypeSet.Contains(6) && lifeSkillTypeSet != null && lifeSkillTypeSet.Count > 0;
		if (canGainTool && character.GetInventory().Items.Keys.Any((ItemKey k) => k.ItemType == 6 && Config.CraftTool.Instance[k.TemplateId].RequiredLifeSkillTypes.Any((sbyte t) => lifeSkillTypeSet.Contains(t))))
		{
			canGainTool = false;
		}
		bool canGainMisc = !_villagerGainedItemTypeSet.Contains(12) && context.Random.NextFloat() >= _gainItemActionRate;
		bool canGainMaterial = !_villagerGainedItemTypeSet.Contains(5) && context.Random.NextFloat() >= _gainItemActionRate;
		if (!(canChangeEquipment || canGainBook || canGainTool || canGainMisc || canGainMaterial))
		{
			return;
		}
		HashSet<sbyte> resourceTypeSet = _villagerRoleNeedMaterials[roleTemplateId];
		ItemKey[] equipments = character.GetEquipment();
		SettlementTreasury treasury = GetTaiwuTreasury();
		foreach (KeyValuePair<ItemKey, int> item in treasury.Inventory.Items)
		{
			item.Deconstruct(out var key, out var _);
			ItemKey itemKey = key;
			bool addToList = false;
			if (!_villagerSelectableItemKeys.TryGetValue(itemKey.ItemType, out List<(ItemKey, int)> selectableItemList))
			{
				selectableItemList = ObjectPool<List<(ItemKey, int)>>.Instance.Get();
				_villagerSelectableItemKeys[itemKey.ItemType] = selectableItemList;
			}
			if (ItemType.IsEquipmentItemType(itemKey.ItemType))
			{
				if (!canChangeEquipment)
				{
					continue;
				}
				short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
				for (sbyte slot = 0; slot < equipments.Length; slot++)
				{
					ItemKey equipment = equipments[slot];
					if (itemKey.ItemType == EquipmentSlotHelper.GetSlotItemType(slot) && (itemKey.ItemType != 3 || (!Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == itemKey.TemplateId) && character.GetAgeGroup() == 2)))
					{
						if (equipment.IsValid())
						{
							if ((itemKey.ItemType != 1 || itemSubType == ItemTemplateHelper.GetItemSubType(equipment.ItemType, equipment.TemplateId)) && CompareVillagerSelectableEquipments(equipment, itemKey, character))
							{
								addToList = true;
							}
						}
						else
						{
							addToList = true;
						}
					}
				}
			}
			else if (itemKey.ItemType == 12)
			{
				if (!canGainMisc)
				{
					continue;
				}
				addToList = true;
			}
			else if (itemKey.ItemType == 5)
			{
				if (!canGainMaterial)
				{
					continue;
				}
				sbyte resourceType = ItemTemplateHelper.GetResourceType(itemKey.ItemType, itemKey.TemplateId);
				if (resourceTypeSet == null || resourceTypeSet.Contains(resourceType))
				{
					addToList = true;
				}
			}
			else if (itemKey.ItemType == 10)
			{
				if (!canGainBook || !character.BookIsReadable(itemKey))
				{
					continue;
				}
				SkillBookItem skillBookItem = Config.SkillBook.Instance[itemKey.TemplateId];
				if (skillBookItem.ItemSubType == 1001)
				{
					if (!Enumerable.Contains(roleCfg.LearnableCombatSkillTypes, skillBookItem.CombatSkillType))
					{
						continue;
					}
					CombatSkillKey combatSkillKey = new CombatSkillKey(character.GetId(), skillBookItem.CombatSkillTemplateId);
					if (DomainManager.CombatSkill.TryGetElement_CombatSkills(combatSkillKey, out var combatSkill))
					{
						if (!CombatSkillStateHelper.IsBrokenOut(combatSkill.GetActivationState()) && !combatSkill.CanBreakout())
						{
							addToList = true;
						}
					}
					else
					{
						addToList = true;
					}
				}
				else
				{
					if (!Enumerable.Contains(roleCfg.LearnableLifeSkillTypes, skillBookItem.LifeSkillType))
					{
						continue;
					}
					addToList = true;
				}
			}
			else if (itemKey.ItemType == 6)
			{
				if (!canGainTool)
				{
					continue;
				}
				if (lifeSkillTypeSet != null)
				{
					CraftToolItem toolItem = Config.CraftTool.Instance[itemKey.TemplateId];
					if (toolItem.RequiredLifeSkillTypes.Any((sbyte t) => lifeSkillTypeSet.Contains(t)))
					{
						addToList = true;
					}
				}
			}
			if (addToList)
			{
				selectableItemList.Add((itemKey, 0));
			}
		}
		short key2;
		List<(ItemKey, int)> value2;
		foreach (KeyValuePair<short, List<(ItemKey, int)>> villagerSelectableItemKey in _villagerSelectableItemKeys)
		{
			villagerSelectableItemKey.Deconstruct(out key2, out value2);
			List<(ItemKey, int)> list = value2;
			SortVillagerSelectableItemsByGrade(list);
		}
		if (canChangeEquipment)
		{
			for (sbyte slot2 = 0; slot2 < equipments.Length; slot2++)
			{
				sbyte itemType = EquipmentSlotHelper.GetSlotItemType(slot2);
				if (_villagerSelectableItemKeys.TryGetValue(itemType, out List<(ItemKey, int)> items) && items.Count > 0)
				{
					SortVillagerSelectableEquipments(items, character);
					TakeHighestScoreVillagerSelectableItem(context, character, settlement, charClass, itemType, slot2);
				}
			}
		}
		if (canGainBook && _villagerSelectableItemKeys.TryGetValue(10, out List<(ItemKey, int)> items2))
		{
			SortVillagerSelectableBooks(items2, character);
			TakeHighestScoreVillagerSelectableItem(context, character, settlement, charClass, 10, -1);
		}
		if (canGainTool)
		{
			TakeHighestScoreVillagerSelectableItem(context, character, settlement, charClass, 6, -1);
		}
		if (canGainMisc)
		{
			TakeHighestScoreVillagerSelectableItem(context, character, settlement, charClass, 12, -1);
		}
		if (canGainMaterial)
		{
			TakeHighestScoreVillagerSelectableItem(context, character, settlement, charClass, 5, -1);
		}
		foreach (KeyValuePair<short, List<(ItemKey, int)>> villagerSelectableItemKey2 in _villagerSelectableItemKeys)
		{
			villagerSelectableItemKey2.Deconstruct(out key2, out value2);
			List<(ItemKey, int)> list2 = value2;
			List<ItemKey> tempList = ObjectPool<List<ItemKey>>.Instance.Get();
			foreach (var (itemKey2, score) in list2)
			{
				tempList.Add(itemKey2);
			}
			UpdateVillagerTreasuryNeed(context, character, settlement, tempList, listIsFromTreasuryOnly: true);
			ObjectPool<List<(ItemKey, int)>>.Instance.Return(list2);
			ObjectPool<List<ItemKey>>.Instance.Return(tempList);
		}
		_villagerSelectableItemKeys.Clear();
	}

	private void TakeHighestScoreVillagerSelectableItem(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, sbyte charClass, sbyte itemType, sbyte slot = -1)
	{
		if (!_villagerSelectableItemKeys.TryGetValue(itemType, out List<(ItemKey, int)> list) || list == null || list.Count <= 0)
		{
			return;
		}
		ItemKey equippedItem = ((slot >= 0) ? character.GetEquipment()[slot] : ItemKey.Invalid);
		short idealClothingTemplateId = character.GetIdealClothingTemplateId();
		VillagerWorkData workData = DomainManager.Extra.GetVillagerRole(character.GetId())?.WorkData;
		BuildingBlockData blockData = null;
		if (itemType == 10 && workData?.WorkType == 1)
		{
			DomainManager.Building.TryGetElement_BuildingBlocks(new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), out blockData);
		}
		bool waitingForBook = false;
		bool takeBook = false;
		for (int i = list.Count - 1; i >= 0; i--)
		{
			(ItemKey, int) tuple = list[i];
			sbyte itemGrade = ItemTemplateHelper.GetGrade(tuple.Item1.ItemType, tuple.Item1.TemplateId);
			bool notCheckClass = itemType == 3 && idealClothingTemplateId == tuple.Item1.TemplateId;
			if (itemType == 10)
			{
				if (DomainManager.Extra.GetVillagerRoleTemplateId(character.GetId()) == 5)
				{
					if (takeBook = blockData?.ConfigData.RequireCombatSkillType >= 0 && Config.SkillBook.Instance[tuple.Item1.TemplateId].CombatSkillType == blockData?.ConfigData.RequireCombatSkillType)
					{
						waitingForBook = true;
					}
				}
				else if (takeBook = blockData?.ConfigData.RequireLifeSkillType >= 0 && Config.SkillBook.Instance[tuple.Item1.TemplateId].LifeSkillType == blockData?.ConfigData.RequireLifeSkillType)
				{
					waitingForBook = true;
				}
			}
			if ((notCheckClass || charClass >= itemGrade) && IsMeetInventoryLoad(character, tuple.Item1) && (!ItemType.IsEquipmentItemType(tuple.Item1.ItemType) || (EquipmentSlotHelper.IsItemMeetSlot(slot, tuple.Item1) && ShouldTakeEquipment(character, equippedItem, tuple.Item1, checkEquipmentLoad: true))) && (!(itemType == 10 && waitingForBook) || takeBook))
			{
				VillagerTakeItemFromTreasury(context, character, tuple.Item1, 1);
				character.AddInventoryItem(context, tuple.Item1, 1);
				HandleVillagerGainTreasuryItem(context, tuple.Item1, character);
				list.RemoveAt(i);
				break;
			}
		}
	}

	private void RemoveInvalidVillagerPersonalNeed(DataContext context, GameData.Domains.Character.Character selfChar)
	{
		List<CharacterGoalData> personalNeeds = selfChar.ActionPlanningData.Goals;
		if (personalNeeds == null || personalNeeds.Count <= 0)
		{
			return;
		}
		for (int i = personalNeeds.Count - 1; i >= 0; i--)
		{
			CharacterGoalData need = personalNeeds[i];
			if (!need.IsValid(selfChar) || selfChar.CheckGoalComplete(context, need))
			{
				CollectionUtils.SwapAndRemove(personalNeeds, i);
			}
		}
	}

	private void HandleVillagerGainTreasuryItem(DataContext context, ItemKey itemKey, GameData.Domains.Character.Character character)
	{
		sbyte itemType = itemKey.ItemType;
		sbyte b = itemType;
		if ((uint)b <= 4u)
		{
			HandleVillagerGainTreasuryEquipment(context, itemKey, character);
		}
	}

	private void HandleVillagerGainTreasuryEquipment(DataContext context, ItemKey itemKey, GameData.Domains.Character.Character character)
	{
		Settlement settlement = DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId);
		ItemKey[] equipment = character.GetEquipment();
		short idealClothingTemplateId = character.GetIdealClothingTemplateId();
		IReadOnlyDictionary<ItemKey, int> taiwuGiftItems = (DomainManager.Taiwu.IsInGroup(character.GetId()) ? DomainManager.Extra.GetTaiwuGiftItems(character.GetId()) : Inventory.Empty);
		for (sbyte slot = 0; slot < equipment.Length; slot++)
		{
			if (EquipmentSlotHelper.IsItemMeetSlot(slot, itemKey))
			{
				ItemKey equippedItem = equipment[slot];
				if (!equippedItem.IsValid() && IsMeetEquipmentLoad(character, equippedItem, itemKey))
				{
					character.ChangeEquipment(context, -1, slot, itemKey);
					return;
				}
			}
		}
		for (sbyte slot2 = 0; slot2 < equipment.Length; slot2++)
		{
			if (EquipmentSlotHelper.IsItemMeetSlot(slot2, itemKey))
			{
				ItemKey equippedItem2 = equipment[slot2];
				if (IsMeetEquipmentLoad(character, equippedItem2, itemKey) && equippedItem2.IsValid() && CompareEquipmentScore(equippedItem2, itemKey, character))
				{
					character.ChangeEquipment(context, slot2, -1, equippedItem2);
					character.ChangeEquipment(context, -1, slot2, itemKey);
					bool shouldNotStore = itemKey.ItemType == 3 && itemKey.TemplateId == idealClothingTemplateId && equippedItem2.TemplateId != idealClothingTemplateId;
					if (taiwuGiftItems.ContainsKey(itemKey))
					{
						shouldNotStore = true;
					}
					if (!shouldNotStore)
					{
						character.RemoveInventoryItem(context, equippedItem2, 1, deleteItem: false);
						DomainManager.Taiwu.VillagerStoreItemInTreasury(context, character, equippedItem2, 1);
					}
					break;
				}
			}
		}
	}

	private ItemKey RemovePersonalNeedSelectedItem<T>(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, List<(T item, int amount)> items, List<ItemKey> selections) where T : ItemBase
	{
		ItemKey itemKey = InternalRemovePersonalNeedSelectedItem(context, character, settlement, selections);
		if (itemKey.IsValid())
		{
			int finalSelectedIndex = items.FindIndex(((T item, int amount) i) => i.item.GetItemKey() == itemKey);
			if (finalSelectedIndex >= 0)
			{
				var (item, amount) = items[finalSelectedIndex];
				if (amount > 1)
				{
					items[finalSelectedIndex] = (item, amount - 1);
				}
				else
				{
					items.RemoveAt(finalSelectedIndex);
				}
			}
		}
		return itemKey;
	}

	private ItemKey InternalRemovePersonalNeedSelectedItem(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, List<ItemKey> itemKeyList)
	{
		sbyte charClass = _villagerClassDict[character.GetId()];
		SettlementTreasury treasury = GetTaiwuTreasury();
		for (int index = itemKeyList.Count - 1; index >= 0; index--)
		{
			ItemKey itemKey = itemKeyList[index];
			sbyte itemGrade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
			int treasuryAmount = treasury.Inventory.GetInventoryItemCount(itemKey);
			if (treasuryAmount > 0 && charClass >= itemGrade)
			{
				VillagerTakeItemFromTreasury(context, character, itemKey, 1);
				itemKeyList.RemoveAt(index);
				return itemKey;
			}
			int inventoryAmount = character.GetInventory().GetInventoryItemCount(itemKey);
			if (inventoryAmount > 0)
			{
				character.RemoveInventoryItem(context, itemKey, 1, deleteItem: true);
				itemKeyList.RemoveAt(index);
				return itemKey;
			}
		}
		return ItemKey.Invalid;
	}

	private void UpdateVillagerTreasuryNeed(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, List<ItemKey> itemKeyList, bool listIsFromTreasuryOnly)
	{
		sbyte charClass = _villagerClassDict[character.GetId()];
		SettlementTreasury treasury = GetTaiwuTreasury();
		ItemKey targetItemKey = ItemKey.Invalid;
		for (int i = itemKeyList.Count - 1; i >= 0; i--)
		{
			ItemKey itemKey = itemKeyList[i];
			if (!listIsFromTreasuryOnly)
			{
				int treasuryAmount = treasury.Inventory.GetInventoryItemCount(itemKey);
				if (treasuryAmount <= 0)
				{
					continue;
				}
			}
			if (!CanNeedTreasuryItem(character, settlement, itemKey, charClass))
			{
				continue;
			}
			targetItemKey = itemKey;
			break;
		}
		if (!targetItemKey.IsValid())
		{
			return;
		}
		if (!DomainManager.Extra.TryGetVillagerTreasuryNeed(character.GetId(), out var villagerTreasuryNeed))
		{
			villagerTreasuryNeed = new VillagerTreasuryNeed();
			villagerTreasuryNeed.PersonalNeeds = new List<GameData.Domains.Character.Ai.PersonalNeed>();
		}
		int findIndex = villagerTreasuryNeed.PersonalNeeds.FindIndex((GameData.Domains.Character.Ai.PersonalNeed n) => n.ItemType == targetItemKey.ItemType);
		GameData.Domains.Character.Ai.PersonalNeed personalNeed;
		if (findIndex >= 0)
		{
			personalNeed = villagerTreasuryNeed.PersonalNeeds[findIndex];
			ItemKey oldKey = new ItemKey(personalNeed.ItemType, 0, personalNeed.ItemTemplateId, -1);
			targetItemKey.Id = -1;
			if (!CompareVillagerSelectableItems(oldKey, targetItemKey, character))
			{
				return;
			}
			sbyte itemGrade = ItemTemplateHelper.GetGrade(targetItemKey.ItemType, targetItemKey.TemplateId);
			sbyte waitTime = CalcVillagerTreasuryNeedWaitTime(charClass, itemGrade);
			personalNeed.RemainingMonths = waitTime;
			personalNeed.ItemTemplateId = targetItemKey.TemplateId;
			villagerTreasuryNeed.PersonalNeeds[findIndex] = personalNeed;
		}
		else
		{
			sbyte itemGrade2 = ItemTemplateHelper.GetGrade(targetItemKey.ItemType, targetItemKey.TemplateId);
			sbyte waitTime2 = CalcVillagerTreasuryNeedWaitTime(charClass, itemGrade2);
			personalNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(10, targetItemKey.ItemType, targetItemKey.TemplateId);
			personalNeed.RemainingMonths = waitTime2;
			villagerTreasuryNeed.PersonalNeeds.Add(personalNeed);
			DomainManager.Extra.SetVillagerTreasuryNeed(context, character.GetId(), villagerTreasuryNeed);
		}
		AddNeededItem(personalNeed, character.GetId());
	}

	private bool CanNeedTreasuryItem(GameData.Domains.Character.Character character, Settlement settlement, ItemKey itemKey, int charClass)
	{
		SettlementCharacter settlementCharacter = DomainManager.Organization.GetSettlementCharacter(character.GetId());
		short curInfluencePower = settlementCharacter.GetInfluencePower();
		sbyte itemGrade = ItemTemplateHelper.GetGrade(itemKey.ItemType, itemKey.TemplateId);
		if (itemGrade <= charClass)
		{
			return false;
		}
		ItemKey tempKey = ItemKey.Invalid;
		tempKey.ItemType = itemKey.ItemType;
		tempKey.TemplateId = itemKey.TemplateId;
		if (!_treasuryNeededItemDict.TryGetValue(tempKey, out var dict))
		{
			return true;
		}
		int itemCount = GetTaiwuTreasury().Inventory.GetInventoryItemCount(tempKey.ItemType, tempKey.TemplateId);
		if (itemCount > dict.Count)
		{
			return true;
		}
		return dict.Keys.All(delegate(int charId)
		{
			if (DomainManager.Organization.TryGetSettlementCharacter(charId, out settlementCharacter))
			{
				short influencePower = settlementCharacter.GetInfluencePower();
				return curInfluencePower > influencePower;
			}
			return true;
		});
	}

	public bool IsMeetWorkStatus(GameData.Domains.Character.Character character, Settlement settlement)
	{
		byte workStatus = GetVillagerWorkStatus(character);
		bool isNotWorking = workStatus != 2;
		sbyte memberGrade = character.GetOrganizationInfo().Grade;
		bool hasNoneRole = memberGrade == 0;
		if (isNotWorking && hasNoneRole)
		{
			if (settlement.GetLocation().AreaId != character.GetLocation().AreaId)
			{
				return false;
			}
			if (!DomainManager.Map.IsLocationInSettlementInfluenceRange(character.GetLocation(), _taiwuVillageSettlementId))
			{
				return false;
			}
		}
		return true;
	}

	private bool IsMeetInventoryLoad(GameData.Domains.Character.Character character, ItemKey itemKey)
	{
		int weight = DomainManager.Item.GetBaseItem(itemKey).GetWeight();
		if (weight == 0)
		{
			return true;
		}
		int curLoad = character.GetCurrInventoryLoad();
		int maxLoad = character.GetMaxInventoryLoad();
		return curLoad + weight <= maxLoad;
	}

	private bool IsMeetEquipmentLoad(GameData.Domains.Character.Character character, ItemKey oldItemKey, ItemKey newItemKey)
	{
		int newWeight = (oldItemKey.IsValid() ? DomainManager.Item.GetBaseItem(newItemKey).GetWeight() : 0);
		if (newWeight == 0)
		{
			return true;
		}
		int oldWeight = (oldItemKey.IsValid() ? DomainManager.Item.GetBaseItem(oldItemKey).GetWeight() : 0);
		int curLoad = character.GetCurrEquipmentLoad();
		int maxLoad = character.GetMaxEquipmentLoad();
		return curLoad - oldWeight + newWeight <= maxLoad;
	}

	private bool ShouldTakeEquipment(GameData.Domains.Character.Character character, ItemKey equippedItem, ItemKey itemKey, bool checkEquipmentLoad)
	{
		if (checkEquipmentLoad && !IsMeetEquipmentLoad(character, equippedItem, itemKey))
		{
			return false;
		}
		if (itemKey.ItemType == 0)
		{
			short itemSubType = ItemTemplateHelper.GetItemSubType(itemKey.ItemType, itemKey.TemplateId);
			if (character.GetEquipment().Exist((ItemKey e) => e.IsValid() && itemSubType == ItemTemplateHelper.GetItemSubType(e.ItemType, e.TemplateId)))
			{
				return false;
			}
		}
		if (equippedItem.IsValid())
		{
			return CompareEquipmentScore(equippedItem, itemKey, character);
		}
		return true;
	}

	private bool ShouldTakeEquipment(GameData.Domains.Character.Character character, ItemKey targetItemKey, bool checkEquipmentLoad)
	{
		if (!ItemType.IsEquipmentItemType(targetItemKey.ItemType))
		{
			return true;
		}
		ItemKey[] equipment = character.GetEquipment();
		for (sbyte slot = 0; slot < equipment.Length; slot++)
		{
			if (EquipmentSlotHelper.IsItemMeetSlot(slot, targetItemKey))
			{
				ItemKey equippedItem = equipment[slot];
				if (ShouldTakeEquipment(character, equippedItem, targetItemKey, checkEquipmentLoad))
				{
					return true;
				}
			}
		}
		return false;
	}

	private bool CompareEquipmentScore(ItemKey selfKey, ItemKey targetKey, GameData.Domains.Character.Character character)
	{
		if (!ItemType.IsEquipmentItemType(selfKey.ItemType))
		{
			return false;
		}
		if (selfKey.ItemType == 0)
		{
			_availableWeapons.Clear();
			_suitableWeapons.Clear();
			_availableWeapons.Add((selfKey, 0));
			_availableWeapons.Add((targetKey, 0));
			Equipping.GetWeaponScores(character, _availableWeapons, _suitableWeapons, _fixedBestWeapons);
			return _availableWeapons[1].score > _availableWeapons[0].score;
		}
		if (selfKey.ItemType == 3)
		{
			short idealClothingTemplateId = character.GetIdealClothingTemplateId();
			if (selfKey.TemplateId == idealClothingTemplateId)
			{
				return false;
			}
			if (targetKey.TemplateId == idealClothingTemplateId)
			{
				return true;
			}
			bool selfIsRoleClothing = Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == selfKey.TemplateId);
			bool targetIsRoleClothing = Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == targetKey.TemplateId);
			if (selfIsRoleClothing != targetIsRoleClothing)
			{
				return !targetIsRoleClothing;
			}
			(int, bool) selfScore = Equipping.CalcEquipmentScore(selfKey, -1);
			return Equipping.CalcEquipmentScore(targetKey, -1).score > selfScore.Item1;
		}
		(int, bool) selfScore2 = Equipping.CalcEquipmentScore(selfKey, -1);
		return Equipping.CalcEquipmentScore(targetKey, -1).score > selfScore2.Item1;
	}

	private unsafe void CategorizedRegenItems(IReadOnlyDictionary<ItemKey, int> inventoryItems)
	{
		List<(GameData.Domains.Item.Medicine, int)>[] categorizedMedicines = _categorizedMedicines;
		foreach (List<(GameData.Domains.Item.Medicine, int)> list in categorizedMedicines)
		{
			list.Clear();
		}
		List<(GameData.Domains.Item.Food, int)>[] foodsForMainAttributes = _foodsForMainAttributes;
		foreach (List<(GameData.Domains.Item.Food, int)> list2 in foodsForMainAttributes)
		{
			list2.Clear();
		}
		_teaWinesForHappiness.Clear();
		_itemsForNeili.Clear();
		foreach (var (itemKey2, amount) in inventoryItems)
		{
			switch (itemKey2.ItemType)
			{
			case 7:
			{
				FoodItem config3 = Config.Food.Instance[itemKey2.TemplateId];
				for (sbyte attrType = 0; attrType < 6; attrType++)
				{
					if (config3.MainAttributesRegen.Items[attrType] > 0)
					{
						GameData.Domains.Item.Food item4 = DomainManager.Item.GetElement_Foods(itemKey2.Id);
						_foodsForMainAttributes[attrType].Add((item4, amount));
						break;
					}
				}
				break;
			}
			case 8:
			{
				MedicineItem config2 = Config.Medicine.Instance[itemKey2.TemplateId];
				if (config2.EffectType != EMedicineEffectType.Invalid)
				{
					GameData.Domains.Item.Medicine item2 = DomainManager.Item.GetElement_Medicines(itemKey2.Id);
					_categorizedMedicines[(int)config2.EffectType].Add((item2, amount));
				}
				break;
			}
			case 9:
				if (DomainManager.Item.GetBaseItem(itemKey2).GetHappinessChange() > 0)
				{
					GameData.Domains.Item.TeaWine item3 = DomainManager.Item.GetElement_TeaWines(itemKey2.Id);
					_teaWinesForHappiness.Add((item3, amount));
				}
				break;
			case 12:
			{
				MiscItem config = Config.Misc.Instance[itemKey2.TemplateId];
				GameData.Domains.Item.Misc item = DomainManager.Item.GetElement_Misc(itemKey2.Id);
				if (config.Neili > 0)
				{
					_itemsForNeili.Add((item, amount));
				}
				break;
			}
			}
		}
	}

	private void AddNeededItem(GameData.Domains.Character.Ai.PersonalNeed personalNeed, int charId)
	{
		ItemKey tempKey = ItemKey.Invalid;
		tempKey.ItemType = personalNeed.ItemType;
		tempKey.TemplateId = personalNeed.ItemTemplateId;
		if (!_treasuryNeededItemDict.TryGetValue(tempKey, out var charDict))
		{
			charDict = new Dictionary<int, sbyte>();
			_treasuryNeededItemDict[tempKey] = charDict;
		}
		charDict[charId] = personalNeed.RemainingMonths;
	}

	private unsafe void HandleVillagerPersonalNeedForHealingAndDetox(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		sbyte currMaxEatingSlotsCount = character.GetCurrMaxEatingSlotsCount();
		int availableEatingSlotsCount = character.GetEatingItems().GetAvailableEatingSlotsCount(currMaxEatingSlotsCount);
		PoisonInts poisonResists = character.GetPoisonResists();
		MainAttributes currMainAttributes = character.GetCurrMainAttributes();
		Injuries injuries = character.GetInjuries();
		PoisonInts poisoned = character.GetPoisoned();
		short disorderOfQi = character.GetDisorderOfQi();
		List<(GameData.Domains.Item.Medicine, int)>[] categorizedMedicines = _categorizedMedicines;
		List<(GameData.Domains.Item.Medicine, int)> outerMedicines = categorizedMedicines[0];
		List<(GameData.Domains.Item.Medicine, int)> innerMedicines = categorizedMedicines[1];
		outerMedicines.Sort(EatingItemComparer.MedicineInjury);
		innerMedicines.Sort(EatingItemComparer.MedicineInjury);
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
		{
			var (outer, inner) = injuries.Get(bodyPart);
			if (outer > 2 && outerMedicines.Count > 0)
			{
				int selectedIndex = character.SelectTopicalMedicineIndex(outerMedicines, outer, ref currMainAttributes, selections);
				if (selectedIndex >= 0)
				{
					ItemKey itemKey = RemovePersonalNeedSelectedItem(context, character, settlement, outerMedicines, selections);
					if (itemKey.IsValid())
					{
						DomainManager.Item.RemoveItem(context, itemKey);
						character.ApplyTopicalMedicine(context, itemKey);
						if (personalNeed.CheckValid(character))
						{
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
						}
					}
					else
					{
						UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					}
				}
			}
			if (inner > 2 && innerMedicines.Count > 0)
			{
				int selectedIndex2 = character.SelectTopicalMedicineIndex(innerMedicines, inner, ref currMainAttributes, selections);
				if (selectedIndex2 >= 0)
				{
					ItemKey itemKey2 = RemovePersonalNeedSelectedItem(context, character, settlement, innerMedicines, selections);
					if (itemKey2.IsValid())
					{
						DomainManager.Item.RemoveItem(context, itemKey2);
						character.ApplyTopicalMedicine(context, itemKey2);
						if (personalNeed.CheckValid(character))
						{
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
						}
					}
				}
				else
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				}
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
		categorizedMedicines[3].Sort(EatingItemComparer.MedicineQiDisorder);
		int* healthChanges = stackalloc int[3];
		while (availableEatingSlotsCount > 1)
		{
			*healthChanges = GameData.Domains.Character.Character.GetHealthChangeDueToInjuries(ref injuries) << 8;
			healthChanges[1] = (GameData.Domains.Character.Character.GetHealthChangeDueToPoisons(ref poisoned, ref poisonResists) << 8) + 1;
			healthChanges[2] = (character.GetHealthChangeDueToDisorderOfQi(disorderOfQi) << 8) + 2;
			CollectionUtils.Sort(healthChanges, 3);
			if (*healthChanges >> 8 >= 0 || !HandleVillagerPersonalNeedForHealingAndDetoxHelper(context, healthChanges, character, settlement, personalNeed))
			{
				break;
			}
			availableEatingSlotsCount--;
		}
	}

	private unsafe bool HandleVillagerPersonalNeedForHealingAndDetoxHelper(DataContext context, int* healthChanges, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		PoisonInts poisonResists = character.GetPoisonResists();
		Injuries injuries = character.GetInjuries();
		PoisonInts poisoned = character.GetPoisoned();
		short disorderOfQi = character.GetDisorderOfQi();
		List<(GameData.Domains.Item.Medicine, int)>[] categorizedMedicines = _categorizedMedicines;
		int* poisonLevels = stackalloc int[6];
		for (int i = 0; i < 3; i++)
		{
			int type = healthChanges[i] & 0xFF;
			int deltaHealth = healthChanges[i] >> 8;
			if (deltaHealth >= 0)
			{
				break;
			}
			switch (type)
			{
			case 0:
			{
				List<(GameData.Domains.Item.Medicine, int)> outerMedicines = categorizedMedicines[0];
				List<(GameData.Domains.Item.Medicine, int)> innerMedicines = categorizedMedicines[1];
				sbyte innerInjuryMinLevel = sbyte.MaxValue;
				sbyte outerInjuryMinLevel = sbyte.MaxValue;
				sbyte outerInjuryTotalLevel = 0;
				sbyte innerInjuryTotalLevel = 0;
				for (sbyte bodyPart = 0; bodyPart < 7; bodyPart++)
				{
					(sbyte outer, sbyte inner) tuple = injuries.Get(bodyPart);
					sbyte outer = tuple.outer;
					sbyte inner = tuple.inner;
					outerInjuryTotalLevel += outer;
					innerInjuryTotalLevel += inner;
					if (outer > 0 && outer < outerInjuryMinLevel)
					{
						outerInjuryMinLevel = outer;
					}
					if (inner > 0 && inner < innerInjuryMinLevel)
					{
						innerInjuryMinLevel = inner;
					}
				}
				int medicineIndex = -1;
				if (outerMedicines.Count > 0 && outerInjuryMinLevel > innerInjuryMinLevel && outerInjuryMinLevel <= 6)
				{
					medicineIndex = character.SelectMedicineIndexForInjury(outerMedicines, outerInjuryMinLevel, outerInjuryTotalLevel, selections);
					if (medicineIndex >= 0)
					{
						ItemKey itemKey2 = RemovePersonalNeedSelectedItem(context, character, settlement, outerMedicines, selections);
						if (itemKey2.IsValid())
						{
							character.AddEatingItem(context, itemKey2);
							if (personalNeed.CheckValid(character))
							{
								UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
							}
							return true;
						}
						UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					}
				}
				if (innerMedicines.Count <= 0 || innerInjuryMinLevel > 6)
				{
					break;
				}
				medicineIndex = character.SelectMedicineIndexForInjury(innerMedicines, innerInjuryMinLevel, innerInjuryTotalLevel, selections);
				if (medicineIndex < 0)
				{
					break;
				}
				ItemKey itemKey3 = RemovePersonalNeedSelectedItem(context, character, settlement, innerMedicines, selections);
				if (itemKey3.IsValid())
				{
					character.AddEatingItem(context, itemKey3);
					if (personalNeed.CheckValid(character))
					{
						UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					}
					return true;
				}
				UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				break;
			}
			case 1:
			{
				List<(GameData.Domains.Item.Medicine, int)> detoxMedicines = _categorizedMedicines[4];
				if (detoxMedicines.Count <= 0)
				{
					break;
				}
				detoxMedicines.Sort(character.CompareDetoxPoisonMedicines);
				for (sbyte poisonType = 0; poisonType < 6; poisonType++)
				{
					int level = ((poisonResists.Items[poisonType] < 1000) ? PoisonsAndLevels.CalcPoisonedLevel(poisoned.Items[poisonType]) : 0);
					poisonLevels[poisonType] = (level << 8) + poisonType;
				}
				CollectionUtils.Sort(poisonLevels, 6);
				for (sbyte index = 5; index >= 0; index--)
				{
					sbyte poisonType2 = (sbyte)(poisonLevels[index] & 0xFF);
					sbyte level2 = (sbyte)(poisonLevels[index] >> 8);
					if (level2 <= 0)
					{
						break;
					}
					int medicineIndex2 = character.SelectMedicineIndexForDetoxPoison(detoxMedicines, poisonType2, level2, poisoned.Items[poisonType2], selections);
					if (medicineIndex2 >= 0)
					{
						ItemKey itemKey4 = RemovePersonalNeedSelectedItem(context, character, settlement, detoxMedicines, selections);
						if (itemKey4.IsValid())
						{
							character.AddEatingItem(context, itemKey4);
							if (personalNeed.CheckValid(character))
							{
								UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
							}
							return true;
						}
						UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					}
				}
				break;
			}
			case 2:
			{
				List<(GameData.Domains.Item.Medicine, int)> qiMedicines = _categorizedMedicines[3];
				int selectedIndex = character.SelectMedicineIndexForQiDisorder(qiMedicines, disorderOfQi, selections);
				if (selectedIndex < 0)
				{
					break;
				}
				ItemKey itemKey = RemovePersonalNeedSelectedItem(context, character, settlement, qiMedicines, selections);
				if (itemKey.IsValid())
				{
					character.AddEatingItem(context, itemKey);
					if (personalNeed.CheckValid(character))
					{
						UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					}
					return true;
				}
				UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				break;
			}
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
		return false;
	}

	private void HandleVillagerPersonalNeedForHeath(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		short health = character.GetHealth();
		short leftMaxHealth = character.GetLeftMaxHealth();
		sbyte currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
		sbyte eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
		List<(GameData.Domains.Item.Medicine, int)> medicines = _categorizedMedicines[2];
		if (eatingSlot >= 0 && medicines.Count > 0)
		{
			medicines.Sort(EatingItemComparer.MedicineEffect);
			while (eatingSlot >= 0 && health < leftMaxHealth)
			{
				int selectedIndex = character.SelectMedicineIndexForHealth(medicines, health, leftMaxHealth, selections);
				if (selectedIndex < 0)
				{
					break;
				}
				ItemKey itemKey = RemovePersonalNeedSelectedItem(context, character, settlement, medicines, selections);
				if (!itemKey.IsValid())
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					break;
				}
				character.AddEatingItem(context, itemKey);
				if (personalNeed.CheckValid(character))
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				}
				health = character.GetHealth();
				leftMaxHealth = character.GetLeftMaxHealth();
				currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
				eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
	}

	private unsafe void HandleVillagerPersonalNeedForWug(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		EatingItems eatingItems = character.GetEatingItems();
		sbyte currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
		sbyte eatingSlot = eatingItems.GetAvailableEatingSlot(currMaxEatingSlotCount);
		List<(GameData.Domains.Item.Medicine, int)> medicines = _categorizedMedicines[5];
		List<(GameData.Domains.Item.Medicine, int)> poisons = _categorizedMedicines[6];
		if (eatingSlot >= 0 && (medicines.Count > 0 || poisons.Count > 0))
		{
			medicines.Sort(EatingItemComparer.MedicineGrade);
			poisons.Sort(EatingItemComparer.MedicineGrade);
			for (sbyte currSlot = 0; currSlot < 9; currSlot++)
			{
				ItemKey itemKey = (ItemKey)eatingItems.ItemKeys[currSlot];
				if (EatingItems.IsWug(itemKey) && !itemKey.IsValid())
				{
					MedicineItem wugConfig = Config.Medicine.Instance[itemKey.TemplateId];
					while (eatingSlot >= 0 && EatingItems.IsWug(eatingItems.Get(currSlot)) && !eatingItems.Get(currSlot).IsValid())
					{
						int selectedIndex = character.SelectMedicineIndexForWug(medicines, wugConfig.WugType, eatingItems.Durations[currSlot], selections);
						if (selectedIndex >= 0)
						{
							ItemKey usedItemKey = RemovePersonalNeedSelectedItem(context, character, settlement, medicines, selections);
							if (itemKey.IsValid())
							{
								character.AddEatingItem(context, usedItemKey);
								if (personalNeed.CheckValid(character))
								{
									UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
								}
								currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
								eatingItems = character.GetEatingItems();
								eatingSlot = eatingItems.GetAvailableEatingSlot(currMaxEatingSlotCount);
								continue;
							}
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
						}
						selectedIndex = GameData.Domains.Character.Character.SelectPoisonIndexForWug(poisons, wugConfig.WugType, eatingItems.Durations[currSlot], selections);
						if (selectedIndex >= 0)
						{
							ItemKey usedItemKey2 = RemovePersonalNeedSelectedItem(context, character, settlement, poisons, selections);
							if (usedItemKey2.IsValid())
							{
								character.AddEatingItem(context, usedItemKey2);
								if (personalNeed.CheckValid(character))
								{
									UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
								}
								currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
								eatingItems = character.GetEatingItems();
								eatingSlot = eatingItems.GetAvailableEatingSlot(currMaxEatingSlotCount);
								continue;
							}
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
							break;
						}
						break;
					}
				}
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
	}

	private void HandleVillagerPersonalNeedForNeili(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		int currNeili = character.GetCurrNeili();
		int maxNeili = character.GetMaxNeili();
		List<(GameData.Domains.Item.Misc, int)> itemsForNeili = _itemsForNeili;
		if (itemsForNeili.Count > 0)
		{
			itemsForNeili.Sort(EatingItemComparer.MiscNeili);
			while (currNeili < maxNeili)
			{
				int selectedIndex = character.SelectItemIndexForNeili(itemsForNeili, currNeili, maxNeili, selections);
				if (selectedIndex < 0)
				{
					break;
				}
				ItemKey usedItemKey = RemovePersonalNeedSelectedItem(context, character, settlement, itemsForNeili, selections);
				if (!usedItemKey.IsValid())
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					break;
				}
				character.AddEatingItem(context, usedItemKey);
				if (personalNeed.CheckValid(character))
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				}
				currNeili = character.GetCurrNeili();
				maxNeili = character.GetMaxNeili();
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
	}

	private unsafe void HandleVillagerPersonalNeedForMainAttributes(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		MainAttributes currMainAttributes = character.GetCurrMainAttributes();
		MainAttributes maxMainAttributes = character.GetMaxMainAttributes();
		sbyte currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
		sbyte eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
		for (sbyte attrType = 0; attrType < 6; attrType++)
		{
			short maxMainAttr = maxMainAttributes.Items[attrType];
			if (currMainAttributes.Items[attrType] * 2 < maxMainAttr)
			{
				List<(GameData.Domains.Item.Food, int)> foods = _foodsForMainAttributes[attrType];
				if (eatingSlot >= 0 && foods.Count > 0)
				{
					sbyte behaviorType = character.GetBehaviorType();
					sbyte eatForbiddenFoodChance = AiHelper.UpdateStatusConstants.EatForbiddenFoodChance[behaviorType];
					bool isMeatForbidden = character.IsForbiddenToEatMeat();
					short rateAdjust = DomainManager.Character.GetAiActionRateAdjust(character.GetId(), 6, -1);
					bool allowMeat = !isMeatForbidden || context.Random.CheckPercentProb(eatForbiddenFoodChance + rateAdjust);
					foods.Sort(EatingItemComparer.FoodMainAttributes[attrType]);
					while (eatingSlot >= 0 && currMainAttributes.Items[attrType] < maxMainAttr)
					{
						int selectedIndex = character.SelectFoodIndexForMainAttributes(foods, attrType, currMainAttributes.Items[attrType], maxMainAttr, allowMeat, selections);
						if (selectedIndex < 0)
						{
							break;
						}
						ItemKey usedItemKey = RemovePersonalNeedSelectedItem(context, character, settlement, foods, selections);
						if (!usedItemKey.IsValid())
						{
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
							break;
						}
						character.AddEatingItem(context, usedItemKey);
						if (personalNeed.CheckValid(character))
						{
							UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
						}
						currMainAttributes = character.GetCurrMainAttributes();
						maxMainAttributes = character.GetMaxMainAttributes();
						currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
						eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
					}
				}
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
	}

	private void HandleVillagerPersonalNeedForHappiness(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		List<ItemKey> selections = ObjectPool<List<ItemKey>>.Instance.Get();
		sbyte happinessThreshold = HappinessType.Ranges[3].min;
		sbyte happiness = character.GetHappiness();
		sbyte currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
		sbyte eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
		List<(GameData.Domains.Item.TeaWine, int)> teaWines = _teaWinesForHappiness;
		if (eatingSlot >= 0 && teaWines.Count > 0)
		{
			sbyte behaviorType = character.GetBehaviorType();
			short rateAdjust = DomainManager.Character.GetAiActionRateAdjust(character.GetId(), 6, -1);
			sbyte eatForbiddenFoodChance = AiHelper.UpdateStatusConstants.EatForbiddenFoodChance[behaviorType];
			bool isWineForbidden = character.IsForbiddenToDrinkingWines();
			bool allowWines = !isWineForbidden || context.Random.CheckPercentProb(eatForbiddenFoodChance + rateAdjust);
			teaWines.Sort(EatingItemComparer.TeaWineHappiness);
			while (eatingSlot >= 0 && happiness < happinessThreshold)
			{
				int selectedIndex = character.SelectTeaWineForHappiness(teaWines, happiness, happinessThreshold, allowWines, selections);
				if (selectedIndex < 0)
				{
					break;
				}
				ItemKey usedItemKey = RemovePersonalNeedSelectedItem(context, character, settlement, teaWines, selections);
				if (!usedItemKey.IsValid())
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
					break;
				}
				character.AddEatingItem(context, usedItemKey);
				TeaWineItem config = Config.TeaWine.Instance[usedItemKey.TemplateId];
				happiness = (sbyte)Math.Clamp(happiness + config.EatHappinessChange, -119, 119);
				if (isWineForbidden && config.ItemSubType == 901)
				{
					sbyte happinessChange = AiHelper.UpdateStatusConstants.EatForbiddenFoodHappinessChange[behaviorType];
					happiness = (sbyte)Math.Clamp(happiness + happinessChange, -119, 119);
				}
				character.SetHappiness(happiness, context);
				if (personalNeed.CheckValid(character))
				{
					UpdateVillagerTreasuryNeed(context, character, settlement, selections, listIsFromTreasuryOnly: false);
				}
				currMaxEatingSlotCount = character.GetCurrMaxEatingSlotsCount();
				eatingSlot = character.GetEatingItems().GetAvailableEatingSlot(currMaxEatingSlotCount);
			}
		}
		ObjectPool<List<ItemKey>>.Instance.Return(selections);
	}

	private void HandleVillagerPersonalNeedForGainItem(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		if (!IsMeetWorkStatus(character, settlement))
		{
			return;
		}
		SettlementTreasury treasury = GetTaiwuTreasury();
		bool isRoleClothing = personalNeed.ItemType == 3 && Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == personalNeed.ItemTemplateId);
		int offset = ((!isRoleClothing) ? (-2) : 0);
		ItemKey targetItemKey = treasury.Inventory.GetItemInSameGroup(personalNeed.ItemType, personalNeed.ItemTemplateId, offset);
		if (!targetItemKey.IsValid())
		{
			return;
		}
		sbyte targetItemGrade = ItemTemplateHelper.GetGrade(targetItemKey.ItemType, targetItemKey.TemplateId);
		if (!isRoleClothing)
		{
			short curGroupId = ItemTemplateHelper.GetGroupId(personalNeed.ItemType, personalNeed.ItemTemplateId);
			List<ItemKey> keyList = ObjectPool<List<ItemKey>>.Instance.Get();
			foreach (var (key, _) in treasury.Inventory.Items)
			{
				if (key.ItemType != personalNeed.ItemType)
				{
					continue;
				}
				short itemGroupId = ItemTemplateHelper.GetGroupId(key.ItemType, key.TemplateId);
				if (curGroupId != itemGroupId)
				{
					continue;
				}
				sbyte itemGrade = ItemTemplateHelper.GetGrade(key.ItemType, key.TemplateId);
				if (itemGrade < targetItemGrade)
				{
					continue;
				}
				if (targetItemKey.ItemType == 11)
				{
					ItemBase cricket = DomainManager.Item.GetBaseItem(targetItemKey);
					if (cricket.GetCurrDurability() <= 0)
					{
						continue;
					}
				}
				keyList.Add(key);
			}
			if (personalNeed.ItemType == 10)
			{
				sbyte bookType = -1;
				short roleTemplateId = DomainManager.Extra.GetVillagerRoleTemplateId(character.GetId());
				if (roleTemplateId < 0)
				{
					SortVillagerSelectableItemsByGrade(keyList);
				}
				else
				{
					VillagerWorkData workData = DomainManager.Extra.GetVillagerRole(character.GetId())?.WorkData;
					HashSet<sbyte> lifeSkillTypeSet = VillagerRoleNeedLifeSkillBooks[roleTemplateId];
					if (roleTemplateId == 5)
					{
						if (workData?.WorkType == 1 && DomainManager.Building.TryGetElement_BuildingBlocks(new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), out var blockData))
						{
							bookType = blockData.ConfigData.RequireCombatSkillType;
						}
						keyList.Sort((ItemKey a, ItemKey b) => CompareCombatSkillBook(a, b, bookType));
					}
					else if (lifeSkillTypeSet != null && lifeSkillTypeSet.Count > 0)
					{
						if (workData?.WorkType == 1 && DomainManager.Building.TryGetElement_BuildingBlocks(new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), out var blockData2))
						{
							bookType = blockData2.ConfigData.RequireLifeSkillType;
						}
						keyList.Sort((ItemKey a, ItemKey b) => CompareLifeSkillBook(a, b, lifeSkillTypeSet, bookType));
					}
				}
			}
			else
			{
				SortVillagerSelectableItemsByGrade(keyList);
			}
			UpdateVillagerTreasuryNeed(context, character, settlement, keyList, listIsFromTreasuryOnly: true);
			ObjectPool<List<ItemKey>>.Instance.Return(keyList);
		}
		if (targetItemKey.ItemType != 3)
		{
			sbyte charClass = _villagerClassDict[character.GetId()];
			if (charClass < targetItemGrade)
			{
				return;
			}
		}
		if (targetItemKey.ItemType == 11)
		{
			ItemBase cricket2 = DomainManager.Item.GetBaseItem(targetItemKey);
			if (cricket2.GetCurrDurability() <= 0)
			{
				return;
			}
		}
		if (IsMeetInventoryLoad(character, targetItemKey))
		{
			VillagerTakeItemFromTreasury(context, character, targetItemKey, 1);
			character.AddInventoryItem(context, targetItemKey, 1);
			HandleVillagerGainTreasuryItem(context, targetItemKey, character);
			_villagerGainedItemTypeSet.Add(targetItemKey.ItemType);
		}
	}

	private void HandleVillagerPersonalNeedForGainResource(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed, int needIndex)
	{
		if (IsMeetWorkStatus(character, settlement))
		{
			SettlementTreasury treasury = GetTaiwuTreasury();
			int meetAmount = (treasury.Resources.CheckIsMeet(personalNeed.ResourceType, personalNeed.Amount) ? personalNeed.Amount : treasury.Resources.Get(personalNeed.ResourceType));
			if (meetAmount > 0)
			{
				VillagerTakeResourceFromTreasury(context, character, personalNeed.ResourceType, meetAmount);
				character.ChangeResource(context, personalNeed.ResourceType, meetAmount);
				personalNeed.Amount -= meetAmount;
				IReadOnlyList<CharacterGoalData> goals = character.GetGoals();
				CharacterGoalData goal = goals[needIndex];
				((IContextArgGroup)goal).SetArgOfType(EPlanningParameterType.Integer, (PlanningContextArg)personalNeed.Amount);
			}
		}
	}

	private bool HandleVillagerPersonalNeedForAddPoisonToItem(DataContext context, GameData.Domains.Character.Character character, Settlement settlement, GameData.Domains.Character.Ai.PersonalNeed personalNeed)
	{
		if (!IsMeetWorkStatus(character, settlement))
		{
			return false;
		}
		SettlementTreasury treasury = GetTaiwuTreasury();
		short toxicologyAttainment = character.GetLifeSkillAttainment(9);
		sbyte poisonType = personalNeed.PoisonType;
		ItemKey targetItemKey = ItemKey.Invalid;
		foreach (var (itemKey2, _) in treasury.Inventory.Items)
		{
			if (itemKey2.ItemType == 8)
			{
				MedicineItem config = Config.Medicine.Instance[itemKey2.TemplateId];
				short attainmentRequired = GlobalConfig.Instance.PoisonAttainments[config.Grade];
				if (toxicologyAttainment >= attainmentRequired && config.ApplyPoisonType == poisonType)
				{
					targetItemKey = itemKey2;
					break;
				}
			}
		}
		if (!targetItemKey.IsValid())
		{
			return false;
		}
		GameData.Domains.Character.Ai.PersonalNeed newNeed = GameData.Domains.Character.Ai.PersonalNeed.CreatePersonalNeed(10, targetItemKey.ItemType, targetItemKey.TemplateId);
		HandleVillagerPersonalNeedForGainItem(context, character, settlement, newNeed);
		return true;
	}

	private static void SortVillagerSelectableItemsByGrade(List<(ItemKey itemKey, int score)> items)
	{
		items.Sort(delegate((ItemKey itemKey, int score) a, (ItemKey itemKey, int score) b)
		{
			sbyte grade = ItemTemplateHelper.GetGrade(a.itemKey.ItemType, a.itemKey.TemplateId);
			sbyte grade2 = ItemTemplateHelper.GetGrade(b.itemKey.ItemType, b.itemKey.TemplateId);
			return grade.CompareTo(grade2);
		});
	}

	private static void SortVillagerSelectableItemsByGrade(List<ItemKey> items)
	{
		items.Sort(delegate(ItemKey a, ItemKey b)
		{
			sbyte grade = ItemTemplateHelper.GetGrade(a.ItemType, a.TemplateId);
			sbyte grade2 = ItemTemplateHelper.GetGrade(b.ItemType, b.TemplateId);
			return grade.CompareTo(grade2);
		});
	}

	private void SortVillagerSelectableBooks(List<(ItemKey itemKey, int score)> items, GameData.Domains.Character.Character character)
	{
		short roleTemplateId = DomainManager.Extra.GetVillagerRoleTemplateId(character.GetId());
		HashSet<sbyte> lifeSkillTypeSet = VillagerRoleNeedLifeSkillBooks[roleTemplateId];
		Equipping.SortBooksByScore(items, character);
		sbyte bookType = -1;
		VillagerWorkData workData = DomainManager.Extra.GetVillagerRole(character.GetId())?.WorkData;
		if (roleTemplateId == 5)
		{
			if (workData?.WorkType == 1 && DomainManager.Building.TryGetElement_BuildingBlocks(new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), out var blockData))
			{
				bookType = blockData.ConfigData.RequireCombatSkillType;
			}
			items.Sort(((ItemKey itemKey, int score) a, (ItemKey itemKey, int score) b) => CompareCombatSkillBook(a.itemKey, b.itemKey, bookType));
		}
		else if (lifeSkillTypeSet != null && lifeSkillTypeSet.Count > 0)
		{
			if (workData?.WorkType == 1 && DomainManager.Building.TryGetElement_BuildingBlocks(new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex), out var blockData2))
			{
				bookType = blockData2.ConfigData.RequireLifeSkillType;
			}
			items.Sort(((ItemKey itemKey, int score) a, (ItemKey itemKey, int score) b) => CompareLifeSkillBook(a.itemKey, b.itemKey, lifeSkillTypeSet, bookType));
		}
	}

	private static int CompareCombatSkillBook(ItemKey a, ItemKey b, sbyte bookType)
	{
		SkillBookItem skillBookItemA = Config.SkillBook.Instance[a.TemplateId];
		SkillBookItem skillBookItemB = Config.SkillBook.Instance[b.TemplateId];
		bool aIsBetter = skillBookItemA.ItemSubType == 1001 && skillBookItemB.CombatSkillType != bookType;
		bool bIsBetter = skillBookItemB.ItemSubType == 1001 && skillBookItemA.CombatSkillType != bookType;
		return aIsBetter.CompareTo(bIsBetter);
	}

	private static int CompareLifeSkillBook(ItemKey a, ItemKey b, HashSet<sbyte> lifeSkillTypeSet, sbyte bookType)
	{
		SkillBookItem skillBookItemA = Config.SkillBook.Instance[a.TemplateId];
		SkillBookItem skillBookItemB = Config.SkillBook.Instance[b.TemplateId];
		bool aIsBetter = lifeSkillTypeSet.Contains(skillBookItemA.LifeSkillType) && skillBookItemB.LifeSkillType != bookType;
		bool bIsBetter = lifeSkillTypeSet.Contains(skillBookItemB.LifeSkillType) && skillBookItemA.LifeSkillType != bookType;
		return aIsBetter.CompareTo(bIsBetter);
	}

	private void SortVillagerSelectableEquipments(List<(ItemKey itemKey, int score)> items, GameData.Domains.Character.Character character)
	{
		if (items == null || items.Count <= 0)
		{
			return;
		}
		short idealClothingTemplateId = character.GetIdealClothingTemplateId();
		items.Sort(delegate((ItemKey itemKey, int score) a, (ItemKey itemKey, int score) b)
		{
			switch (items.First().itemKey.ItemType)
			{
			case 0:
				_availableWeapons.Clear();
				_suitableWeapons.Clear();
				_availableWeapons.Add((a.itemKey, 0));
				_availableWeapons.Add((b.itemKey, 0));
				Equipping.GetWeaponScores(character, _availableWeapons, _suitableWeapons, _fixedBestWeapons);
				if (_availableWeapons[0].weapon.Equals(a.itemKey))
				{
					a.score = _availableWeapons[0].score;
					b.score = _availableWeapons[1].score;
				}
				else
				{
					a.score = _availableWeapons[1].score;
					b.score = _availableWeapons[0].score;
				}
				return a.score.CompareTo(b.score);
			case 3:
			{
				if (a.itemKey.TemplateId == idealClothingTemplateId)
				{
					return 1;
				}
				if (b.itemKey.TemplateId == idealClothingTemplateId)
				{
					return -1;
				}
				bool flag = Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == a.itemKey.TemplateId);
				bool flag2 = Config.VillagerRole.Instance.Any((VillagerRoleItem r) => r.Clothing == b.itemKey.TemplateId);
				if (flag != flag2)
				{
					return flag2.CompareTo(flag);
				}
				(int, bool) tuple5 = Equipping.CalcEquipmentScore(a.itemKey, -1);
				(int, bool) tuple6 = Equipping.CalcEquipmentScore(b.itemKey, -1);
				(a.score, _) = tuple5;
				(b.score, _) = tuple6;
				return a.score.CompareTo(b.score);
			}
			default:
			{
				(int, bool) tuple = Equipping.CalcEquipmentScore(a.itemKey, -1);
				(int, bool) tuple2 = Equipping.CalcEquipmentScore(b.itemKey, -1);
				(a.score, _) = tuple;
				(b.score, _) = tuple2;
				return a.score.CompareTo(b.score);
			}
			}
		});
	}

	private bool CompareVillagerSelectableItems(ItemKey selfItemKey, ItemKey targetItemKey, GameData.Domains.Character.Character character)
	{
		List<(ItemKey, int)> items = ObjectPool<List<(ItemKey, int)>>.Instance.Get();
		items.Add((targetItemKey, 0));
		items.Add((selfItemKey, 0));
		if (ItemType.IsEquipmentItemType(selfItemKey.ItemType))
		{
			SortVillagerSelectableEquipments(items, character);
		}
		else if (selfItemKey.ItemType == 10)
		{
			SortVillagerSelectableBooks(items, character);
		}
		else
		{
			SortVillagerSelectableItemsByGrade(items);
		}
		int selfIndex = items.FindIndex(((ItemKey itemKey, int score) t) => t.itemKey.Equals(selfItemKey));
		int targetIndex = items.FindIndex(((ItemKey itemKey, int score) t) => t.itemKey.Equals(targetItemKey));
		bool result = targetIndex > selfIndex;
		ObjectPool<List<(ItemKey, int)>>.Instance.Return(items);
		return result;
	}

	private bool CompareVillagerSelectableBooks(ItemKey selfItemKey, ItemKey targetItemKey, GameData.Domains.Character.Character character)
	{
		List<(ItemKey, int)> items = ObjectPool<List<(ItemKey, int)>>.Instance.Get();
		items.Add((targetItemKey, 0));
		items.Add((selfItemKey, 0));
		SortVillagerSelectableBooks(items, character);
		int selfIndex = items.FindIndex(((ItemKey itemKey, int score) t) => t.itemKey.Equals(selfItemKey));
		int targetIndex = items.FindIndex(((ItemKey itemKey, int score) t) => t.itemKey.Equals(targetItemKey));
		bool result = targetIndex > selfIndex;
		ObjectPool<List<(ItemKey, int)>>.Instance.Return(items);
		return result;
	}

