	public void InitVillagerTreasuryTempData()
	{
		_villagerClassDict.Clear();
		List<int>[] villagerListClassArray = _villagerListClassArray;
		for (int i = 0; i < villagerListClassArray.Length; i++)
		{
			villagerListClassArray[i]?.Clear();
		}
		foreach (var (charId, grade) in DomainManager.Extra.VillagerLastInfluencePowerGrade)
		{
			if (DomainManager.Character.TryGetElement_Objects(charId, out var character) && character.GetOrganizationInfo().SettlementId == _taiwuVillageSettlementId)
			{
				_villagerClassDict[charId] = grade;
				int index = 8 - grade;
				List<int> list = _villagerListClassArray[index];
				if (list == null)
				{
					list = new List<int>();
				}
				list.Add(charId);
				_villagerListClassArray[index] = list;
			}
		}
		RefreshTreasuryNeededItem();
	}

	private void CalcVillagerClasses()
	{
		List<int> memberList = GetTaiwuVillagerMemberList();
		int configLength = GlobalConfig.Instance.VillagerInfluencePowerRankingRatio.Length;
		Span<short> villagerCountClassArray = stackalloc short[configLength];
		int curMemberCount = 0;
		for (int i = 0; i < configLength; i++)
		{
			if (i == configLength - 1)
			{
				villagerCountClassArray[i] = (short)(memberList.Count - curMemberCount);
				break;
			}
			float value = GlobalConfig.Instance.VillagerInfluencePowerRankingRatio[i];
			short count = (short)Math.Max(1.0, Math.Round(value * (float)memberList.Count / 100f));
			villagerCountClassArray[i] = count;
			curMemberCount += count;
		}
		int classIndex = 0;
		int classMemberCount = 0;
		_villagerClassDict.Clear();
		List<int>[] villagerListClassArray = _villagerListClassArray;
		for (int j = 0; j < villagerListClassArray.Length; j++)
		{
			villagerListClassArray[j]?.Clear();
		}
		foreach (int charId in memberList)
		{
			short classMemberMaxCount = villagerCountClassArray[classIndex];
			List<int>[] villagerListClassArray2 = _villagerListClassArray;
			int num = classIndex;
			if (villagerListClassArray2[num] == null)
			{
				villagerListClassArray2[num] = new List<int>(classMemberMaxCount);
			}
			_villagerListClassArray[classIndex].Add(charId);
			sbyte charClass = Convert.ToSByte(8 - classIndex);
			_villagerClassDict[charId] = charClass;
			classMemberCount++;
			if (classMemberCount >= classMemberMaxCount)
			{
				classIndex++;
				classMemberCount = 0;
			}
		}
	}

