	[DomainMethod]
	public List<ItemNeedDisplayData> GetTreasuryNeededItemDataList()
	{
		List<ItemNeedDisplayData> result = new List<ItemNeedDisplayData>();
		Dictionary<TemplateKey, Dictionary<int, sbyte>> itemIndex = new Dictionary<TemplateKey, Dictionary<int, sbyte>>();
		foreach (KeyValuePair<ItemKey, Dictionary<int, sbyte>> item in GetTreasuryNeededItemDict())
		{
			if (!(item.Key == ItemKey.Invalid))
			{
				itemIndex[item.Key.TemplateKey] = item.Value;
			}
		}
		foreach (ItemDisplayData item2 in DomainManager.Taiwu.GetAllItems(ItemSourceType.Treasury).list)
		{
			if (!itemIndex.Keys.Contains(item2.Key.TemplateKey))
			{
				continue;
			}
			ItemNeedDisplayData displayData = new ItemNeedDisplayData
			{
				ItemDisplayData = item2
			};
			displayData.CharacterDisplayDataList = new List<ItemNeedCharacterDisplayData>();
			foreach (KeyValuePair<int, sbyte> charInfoPair in itemIndex[item2.Key.TemplateKey])
			{
				int villagerId = charInfoPair.Key;
				sbyte remainMonth = charInfoPair.Value;
				if (DomainManager.Character.TryGetElement_Objects(villagerId, out var character))
				{
					(ushort, ushort) relationBetweenCharacters = DomainManager.Character.GetRelationBetweenCharacters(villagerId, _taiwuCharId);
					ushort relationToTaiwu = relationBetweenCharacters.Item1;
					ushort relationFromTaiwu = relationBetweenCharacters.Item2;
					ItemNeedCharacterDisplayData characterData = new ItemNeedCharacterDisplayData
					{
						TakeAmount = 1,
						TakeTime = remainMonth,
						CharacterId = villagerId,
						CreatingType = character.GetCreatingType(),
						FullName = character.GetFullName(),
						AvatarRelatedData = character.GenerateAvatarRelatedData(),
						CharacterTemplateId = character.GetTemplateId(),
						FavorabilityToTaiwu = DomainManager.Character.GetFavorability(villagerId, _taiwuCharId),
						IsInteractedWithTaiwu = DomainManager.Character.IsInteractedWithTaiwu(villagerId),
						RoleTemplateId = DomainManager.Extra.GetVillagerRoleTemplateId(character.GetId()),
						RelationFromTaiwu = relationFromTaiwu,
						RelationToTaiwu = relationToTaiwu,
						NameData = DomainManager.Character.GetNameRelatedData(villagerId),
						Health = character.GetHealth(),
						IsCompanion = DomainManager.Taiwu.IsInGroup(villagerId),
						GeneralScrollListData = DomainManager.Character.GetCharacterDisplayDataForGeneralScrollListForItemNeed(character)
					};
					DomainManager.Extra.TryGetVillagerLastInfluencePowerGrade(villagerId, out var powerLevel);
					characterData.PowerLevel = powerLevel;
					displayData.CharacterDisplayDataList.Add(characterData);
				}
			}
			result.Add(displayData);
		}
		return result;
	}

	private void RefreshTreasuryNeededItem()
	{
		_treasuryNeededItemDict.Clear();
		List<int> memberList = new List<int>();
		Settlement settlement = DomainManager.Organization.GetSettlement(_taiwuVillageSettlementId);
		settlement.GetMembers().GetAllMembers(memberList);
		memberList.Remove(_taiwuCharId);
		foreach (int charId in memberList)
		{
			if (!DomainManager.Extra.TryGetVillagerTreasuryNeed(charId, out var villagerTreasuryNeed))
			{
				continue;
			}
			foreach (GameData.Domains.Character.Ai.PersonalNeed personal in villagerTreasuryNeed.PersonalNeeds)
			{
				AddNeededItem(personal, charId);
			}
		}
	}

