	public sbyte GetVillagerNeedWaitTime(int charId, CharacterSortFilter characterSortFilter)
	{
		if (characterSortFilter == null)
		{
			return 0;
		}
		if (characterSortFilter.Settings.FilterType != 4)
		{
			return 0;
		}
		Dictionary<int, sbyte> charDict = _treasuryNeededItemDict[characterSortFilter.Settings.VillagerNeededItem];
		sbyte waitTime = charDict.GetValueOrDefault<int, sbyte>(charId, 0);
		return Math.Max(1, waitTime);
	}

