	[DomainMethod]
	public bool SetVillagerRole(DataContext context, int charId, short roleTemplateId)
	{
		GameData.Domains.Character.Character character = DomainManager.Character.GetElement_Objects(charId);
		VillagerRoleItem roleCfg = Config.VillagerRole.Instance.GetItem(roleTemplateId);
		int roleCount = ((roleCfg != null) ? _villagerFeatureHolderSet.Count((int cId) => DomainManager.Character.TryGetElement_Objects(cId, out var element) && element.GetFeatureIds().Contains(roleCfg.FeatureId)) : 0);
		foreach (short featureId in CalcVillagerRoleFeatureTemplateIds())
		{
			character.RemoveFeature(context, featureId);
		}
		_villagerFeatureHolderSet.Remove(charId);
		ExtraDomain extraDomain = DomainManager.Extra;
		VillagerRoleRecords records = extraDomain.GetVillagerRoleRecordsData();
		short currentRoleId = DomainManager.Extra.GetVillagerRoleTemplateId(charId);
		bool shouldFixRecord = currentRoleId >= 0 && !records.History.Any((VillagerRoleRecordElement element) => element.CharacterId == charId && element.RoleTemplateId == currentRoleId);
		if (shouldFixRecord)
		{
			VillagerRoleRecordElement record = new VillagerRoleRecordElement();
			FillVillagerRoleRecordElement(character, record);
			records.History.Add(record);
		}
		if (roleCfg == null)
		{
			DomainManager.Character.ChangeFavorabilityOptional(context, character, DomainManager.Taiwu.GetTaiwu(), -VillagerRoleFormula.DefValue.BaseFavorCostLostRole.Calculate(character.GetOrganizationInfo().Grade), 3);
			DomainManager.Organization.ChangeGrade(context, character, 0, destPrincipal: true);
			if (shouldFixRecord)
			{
				extraDomain.SetVillagerRoleRecordsData(context, records);
			}
			return true;
		}
		AchievementManager.RequestSetStat(context, 10, 1);
		OrganizationMemberItem memberCfg = OrganizationMember.Instance[roleCfg.OrganizationMember];
		VillagerRoleFormulaItem formula = ((memberCfg.Grade > character.GetOrganizationInfo().Grade) ? VillagerRoleFormula.DefValue.BaseFavorAddGainRole : VillagerRoleFormula.DefValue.BaseFavorCostLostRole);
		int factorBase = formula.Calculate(character.GetOrganizationInfo().Grade);
		DomainManager.Organization.ChangeGrade(context, character, memberCfg.Grade, destPrincipal: true);
		DomainManager.Character.ChangeFavorabilityOptional(context, character, DomainManager.Taiwu.GetTaiwu(), formula.Calculate(memberCfg.Grade) - factorBase, 3);
		int cost = GameData.Domains.Taiwu.VillagerRole.SharedMethods.CalcSetVillagerRoleAuthorityCost(roleCount, roleTemplateId);
		GetTaiwu().ChangeResource(context, 7, -cost);
		character.AddFeature(context, roleCfg.FeatureId, removeMutexFeature: true);
		_villagerFeatureHolderSet.Add(charId);
		records.History.RemoveAll((VillagerRoleRecordElement element) => element.CharacterId == charId && element.RoleTemplateId == roleTemplateId);
		VillagerRoleRecordElement record2 = new VillagerRoleRecordElement();
		FillVillagerRoleRecordElement(character, record2);
		records.History.Add(record2);
		extraDomain.SetVillagerRoleRecordsData(context, records);
		if (DomainManager.Taiwu.TryGetElement_VillagerWork(charId, out var workData) && workData.WorkType == 1)
		{
			Location taiwuVillageLocation = DomainManager.Taiwu.GetTaiwuVillageLocation();
			BuildingBlockKey blockKey = new BuildingBlockKey(taiwuVillageLocation.AreaId, taiwuVillageLocation.BlockId, workData.BuildingBlockIndex);
			if (DomainManager.Building.TryGetElement_ShopManagerDict(blockKey, out var managerList))
			{
				DomainManager.Building.SetElementShopManagerDict(blockKey, managerList, context);
			}
		}
		return true;
	}

	public void OnTaiwuVillagerGradeChanged(DataContext context, GameData.Domains.Character.Character character, sbyte targetGrade)
	{
		Tester.Assert(character.GetOrganizationInfo().OrgTemplateId == 16);
		int charId = character.GetId();
		VillagerRoleBase prevRole = DomainManager.Extra.GetVillagerRole(charId);
		if (prevRole != null)
		{
			DomainManager.Extra.UnregisterVillagerRole(context, charId);
			VillagerWorkData prevWork;
			if (prevRole.ArrangementTemplateId >= 0)
			{
				RemoveVillagerWork(context, charId);
			}
			else if (_villagerWork.TryGetValue(charId, out prevWork) && VillagerWorkType.IsVillagerRoleSpecificType(prevWork.WorkType))
			{
				RemoveVillagerWork(context, charId);
				SetVillagerIdleWork(context, charId, prevWork.AreaId, prevWork.BlockId);
			}
		}
		short roleTemplateId = GetGradeVillagerRole(targetGrade);
		if (roleTemplateId >= 0)
		{
			DomainManager.Extra.RegisterVillagerRole(context, charId, roleTemplateId);
			DomainManager.Taiwu.RecordLifeSummary(context, 67);
		}
		DomainManager.Merchant.RemoveMerchantData(context, charId);
		if (roleTemplateId == 3)
		{
			SetMerchantType(context, charId, 7);
		}
	}

