	private void VillagerWorkCollectResource(DataContext context, VillagerWorkData workData)
	{
		if (workData.ResourceType >= 0)
		{
			if (workData.GetVillagerRole() is VillagerRoleFarmer farmer)
			{
				Location blockKey = new Location(workData.AreaId, workData.BlockId);
				MapBlockData block = DomainManager.Map.GetBlock(blockKey);
				farmer.CollectResource(context, block, workData.ResourceType);
			}
			else
			{
				Logger.AppendWarning($"Non-farmer character {workData.CharacterId} trying to collect resource for taiwu village.");
			}
		}
	}

	private void VillagerWorkMigrateResource(DataContext context, VillagerWorkData workData)
	{
		Location location = workData.Location;
		short settlementId = DomainManager.Character.GetElement_Objects(workData.CharacterId).GetOrganizationInfo().SettlementId;
		MapBlockData block = DomainManager.Map.GetBlock(location);
		if (workData.ResourceType < 0 || !(workData.GetVillagerRole() is VillagerRoleFarmer farmer))
		{
			return;
		}
		farmer.RefreshFailureAccumulation(workData.ResourceType);
		int successRate = farmer.MigrateResourceBaseSuccessRate;
		int buildingBonus = DomainManager.Building.GetBuildingBlockEffect(settlementId, EBuildingScaleEffect.MigrateSpeedBonusFactor);
		successRate *= (CValuePercentBonus)buildingBonus;
		successRate += farmer.MigrateResourceSuccessRateBonus;
		if (context.Random.CheckPercentProb(successRate))
		{
			ResourceTypeItem resourceTypeCfg = Config.ResourceType.Instance[workData.ResourceType];
			List<(short, short)> weightTable = context.AdvanceMonthRelatedData.WeightTable.Occupy();
			short[] possibleItems = resourceTypeCfg.PossibleBuildingCoreItem;
			if (farmer.HasChickenUpgradeEffect && context.Random.CheckPercentProb(farmer.UpgradeBuildingCoreRate))
			{
				short[] possibleUpgradedBuildingCoreItem = resourceTypeCfg.PossibleUpgradedBuildingCoreItem;
				if (possibleUpgradedBuildingCoreItem != null && possibleUpgradedBuildingCoreItem.Length > 0)
				{
					possibleItems = resourceTypeCfg.PossibleUpgradedBuildingCoreItem;
				}
			}
			short[] array = possibleItems;
			foreach (short coreItem in array)
			{
				weightTable.Add((coreItem, 0));
			}
			foreach (BuildingBlockItem buildingBlock in (IEnumerable<BuildingBlockItem>)BuildingBlock.Instance)
			{
				if (buildingBlock.BuildingCoreItem < 0)
				{
					continue;
				}
				int index = resourceTypeCfg.PossibleBuildingCoreItem.IndexOf(buildingBlock.BuildingCoreItem);
				if (index < 0)
				{
					continue;
				}
				sbyte[] collectResourcePercent = buildingBlock.CollectResourcePercent;
				if (collectResourcePercent != null && collectResourcePercent.Length > 0)
				{
					short weight = (short)(weightTable[index].Item2 + buildingBlock.CollectResourcePercent[workData.ResourceType]);
					if (workData.ResourceType == 5)
					{
						weight += buildingBlock.CollectResourcePercent[workData.ResourceType + 1];
					}
					weightTable[index] = (buildingBlock.BuildingCoreItem, weight);
				}
			}
			short miscTemplateId = RandomUtils.GetRandomResult(weightTable, context.Random);
			ItemKey itemKey = DomainManager.Item.CreateMisc(context, miscTemplateId);
			DomainManager.Taiwu.WarehouseAdd(context, itemKey, 1);
			context.AdvanceMonthRelatedData.WeightTable.Release(ref weightTable);
			int currDate = DomainManager.World.GetCurrDate();
			LifeRecordCollection lifeRecordCollection = DomainManager.LifeRecord.GetLifeRecordCollection();
			MonthlyNotificationCollection monthlyNotifications = DomainManager.World.GetMonthlyNotificationCollection();
			TaiwuVillageStoragesRecordCollection storageRecordCollection = DomainManager.Taiwu.GetTaiwuVillageStoragesRecordCollection();
			lifeRecordCollection.AddVillagerMigrateResources(workData.CharacterId, currDate, location, itemKey.ItemType, itemKey.TemplateId);
			monthlyNotifications.AddResourceMigration(workData.CharacterId, location, itemKey.ItemType, itemKey.TemplateId);
			storageRecordCollection.AddMigrateResources(currDate, TaiwuVillageStorageType.Warehouse, workData.CharacterId, itemKey.ItemType, itemKey.TemplateId);
			RemoveVillagerWork(context, workData.CharacterId);
			if (block.RootBlockId >= 0 || block.GroupBlockList != null)
			{
				return;
			}
			DomainManager.Map.MakeBlockDestroyedInAdvanceMonth(context, block);
			DomainManager.Extra.AddMapBlockRecoveryLock(context, location, 120);
		}
		else
		{
			farmer.AccumulateMigrateFailure();
		}
		DomainManager.Extra.SetVillagerRole(context, farmer.Character.GetId());
	}

	private static bool GetVillagerSelectCharacterBoolValue(VillagerWorkData workData, VillagerRoleBase role, BuildingBlockData buildingBlockData)
	{
		bool boolValue = role is VillagerRoleMerchant villagerRoleMerchant && villagerRoleMerchant.ItemTemplateKey.ItemType >= 0;
		if (workData.WorkType == 0 && buildingBlockData.OperationType == 0)
		{
			boolValue = true;
		}
		if (workData.WorkType == 1 && BuildingBlock.Instance[buildingBlockData.TemplateId].ArtisanOrderAvailable)
		{
			boolValue = true;
		}
		return boolValue;
	}

	[DomainMethod]
	public List<VillagerSelectCharacterDisplayData> GetVillagersAvailableForWorkDisplayData(DataContext context, bool actuallyNotOccupiedOnly = false)
	{
		List<int> charIds = GetAllVillagersAvailableForWork(actuallyNotOccupiedOnly);
		List<VillagerSelectCharacterDisplayData> result = new List<VillagerSelectCharacterDisplayData>(charIds.Count);
		List<CharacterDisplayDataForGeneralScrollList> mainDataList = DomainManager.Character.GetCharacterDisplayDataForGeneralScrollListBatch(context, charIds);
		int taiwuCharId = DomainManager.Taiwu.GetTaiwuCharId();
		for (int i = 0; i < charIds.Count; i++)
		{
			int charId = charIds[i];
			CharacterDisplayDataForGeneralScrollList mainData = mainDataList[i];
			if (!DomainManager.Character.TryGetElement_Objects(charId, out var character))
			{
				continue;
			}
			VillagerSelectCharacterDisplayData data = new VillagerSelectCharacterDisplayData
			{
				MainData = mainData,
				OrgInfo = character.GetOrganizationInfo()
			};
			if (_villagerWork.TryGetValue(charId, out var workData))
			{
				VillagerRoleBase role = workData.GetVillagerRole();
				data.RoleTemplateId = role?.RoleTemplateId ?? (-1);
				data.WorkType = workData.WorkType;
				data.WorkStatus = 2;
				data.ArrangementTemplateId = role?.ArrangementTemplateId ?? (-1);
				data.BuildingBlockTemplateId = -1;
				data.IsBuyOperation = false;
				sbyte workType = workData.WorkType;
				bool flag = (uint)workType <= 1u;
				if (flag && workData.BuildingBlockIndex >= 0)
				{
					BuildingBlockKey buildingBlockKey = new BuildingBlockKey(workData.AreaId, workData.BlockId, workData.BuildingBlockIndex);
					if (DomainManager.Building.TryGetElement_BuildingBlocks(buildingBlockKey, out var buildingBlockData))
					{
						data.BuildingBlockTemplateId = buildingBlockData.TemplateId;
						data.IsBuyOperation = GetVillagerSelectCharacterBoolValue(workData, role, buildingBlockData);
					}
					else
					{
						Logger.Warn($"GetVillagersAvailableForWorkDisplayData: character {charId} has invalid BuildingBlockKey: areaId={workData.AreaId}, blockId={workData.BlockId}, blockIndex={workData.BuildingBlockIndex}, workType={workData.WorkType}");
					}
				}
				data.IsWorkLeader = workData.WorkerIndex == 0;
				data.GraveId = workData.GraveId;
				data.SwordTombId = -1;
				if (role is VillagerRoleSwordTombKeeper swordTombKeeper)
				{
					data.SwordTombId = swordTombKeeper.XiangshuAvatarId;
				}
			}
			else
			{
				data.RoleTemplateId = DomainManager.Extra.GetVillagerRole(charId)?.RoleTemplateId ?? (-1);
				data.WorkType = -1;
				data.WorkStatus = 0;
				data.ArrangementTemplateId = -1;
				data.BuildingBlockTemplateId = -1;
				data.IsBuyOperation = false;
				data.IsWorkLeader = false;
				data.GraveId = -1;
				data.SwordTombId = -1;
			}
			Location location = character.GetLocation();
			data.LocationData = new CharacterTableLocationData
			{
				AreaId = location.AreaId,
				BlockId = location.BlockId,
				BlockIndex = -1,
				AreaTemplateId = (short)(location.IsValid() ? DomainManager.Map.GetElement_Areas(location.AreaId).GetTemplateId() : (-1))
			};
			(ushort, ushort) relationBetweenCharacters = DomainManager.Character.GetRelationBetweenCharacters(charId, taiwuCharId);
			ushort relationTo = relationBetweenCharacters.Item1;
			ushort relationFrom = relationBetweenCharacters.Item2;
			data.RelationToTaiwu = relationTo;
			data.RelationFromTaiwu = relationFrom;
			data.LeftPotentialCount = GetTaiwuVillagerLeftPotentialCount(charId);
			data.LifeSkillAttainments = character.GetLifeSkillAttainments();
			data.CombatSkillAttainments = character.GetCombatSkillAttainments();
			result.Add(data);
		}
		return result;
	}

