	public int GetWarehouseMaxLoad()
	{
		Thread.MemoryBarrier();
		if (BaseGameDataDomain.IsCached(DataStates, 7))
		{
			return _warehouseMaxLoad;
		}
		int value = CalcWarehouseMaxLoad();
		bool lockTaken = false;
		try
		{
			_spinLockWarehouseMaxLoad.Enter(ref lockTaken);
			_warehouseMaxLoad = value;
			BaseGameDataDomain.SetCached(DataStates, 7);
		}
		finally
		{
			if (lockTaken)
			{
				_spinLockWarehouseMaxLoad.Exit(useMemoryBarrier: false);
			}
		}
		Thread.MemoryBarrier();
		return _warehouseMaxLoad;
	}

