	private void RunTestings(DataContext context)
	{
		Test_QuickFillCombatSkillAttainmentPanel(context);
		Test_SaveCombatSkillAttainmentPanelPlan(context);
	}

	private void Test_FindSectLeaderLocation()
	{
		Location location = _taiwuChar.GetLocation();
		Span<MapBlockData> areaBlocks = DomainManager.Map.GetAreaBlocks(location.AreaId);
		for (int i = 0; i < 10; i++)
		{
			Logger.Info("-----------");
			Stopwatch stopwatch = Stopwatch.StartNew();
			GameData.Domains.Character.Character foundChar = null;
			Span<MapBlockData> span = areaBlocks;
			for (int j = 0; j < span.Length; j++)
			{
				MapBlockData block = span[j];
				if (foundChar == null)
				{
					foundChar = EventHelper.FindLeaderOfTargetOrganizationAtLocation(block.GetLocation(), 3, includeAllRelatedLocations: true);
				}
			}
			stopwatch.Stop();
			Logger.Info($"Found {foundChar} in {stopwatch.ElapsedTicks} ticks with {"FindLeaderOfTargetOrganizationAtLocation"}");
			Stopwatch stopwatch2 = Stopwatch.StartNew();
			GameData.Domains.Character.Character foundChar2 = null;
			Span<MapBlockData> span2 = areaBlocks;
			for (int k = 0; k < span2.Length; k++)
			{
				MapBlockData block2 = span2[k];
				if (foundChar2 == null)
				{
					foundChar2 = EventHelper.TryGetSectLeaderAtLocation(block2.GetLocation(), 3, includeAllBlocksInGroup: true);
				}
			}
			stopwatch2.Stop();
			Logger.Info($"Found {foundChar2} in {stopwatch2.ElapsedTicks} ticks with {"TryGetSectLeaderAtLocation"}");
			Logger.Info("-----------");
		}
	}

	private void Test_QuickFillCombatSkillAttainmentPanel(DataContext context)
	{
		short[] panels = _taiwuChar.GetCombatSkillAttainmentPanels();
		for (sbyte skillType = 0; skillType < 14; skillType += 2)
		{
			QuickFillCombatSkillAttainmentPanel(context, skillType);
		}
		sbyte skillType2;
		for (skillType2 = 0; skillType2 < 14; skillType2 += 2)
		{
			Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> learnedCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(_taiwuCharId);
			List<KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill>> viableSkills = learnedCombatSkills.Where((KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> pair) => Config.CombatSkill.Instance[pair.Key].Type == skillType2 && !pair.Value.GetRevoked() && CombatSkillStateHelper.IsBrokenOut(pair.Value.GetActivationState())).ToList();
			sbyte grade;
			for (grade = 0; grade < 9; grade++)
			{
				short skillId = CombatSkillAttainmentPanelsHelper.Get(panels, skillType2, grade);
				if (skillId < 0)
				{
					Tester.Assert(!viableSkills.Exists((KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> pair) => Config.CombatSkill.Instance[pair.Key].Grade == grade));
				}
				else
				{
					Tester.Assert(Config.CombatSkill.Instance[skillId].Grade == grade);
					Tester.Assert(Config.CombatSkill.Instance[skillId].Type == skillType2);
				}
			}
		}
	}

	private void Test_SaveCombatSkillAttainmentPanelPlan(DataContext context)
	{
		short[] panels = _taiwuChar.GetCombatSkillAttainmentPanels();
		for (sbyte skillType = 0; skillType < 14; skillType += 2)
		{
			SaveCombatSkillAttainmentPanelPlan(context, skillType, (sbyte)(skillType % 4 + 1));
		}
		sbyte skillType2;
		for (skillType2 = 0; skillType2 < 14; skillType2++)
		{
			Dictionary<short, GameData.Domains.CombatSkill.CombatSkill> learnedCombatSkills = DomainManager.CombatSkill.GetCharCombatSkills(_taiwuCharId);
			List<KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill>> viableSkills = learnedCombatSkills.Where((KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> pair) => Config.CombatSkill.Instance[pair.Key].Type == skillType2 && !pair.Value.GetRevoked() && CombatSkillStateHelper.IsBrokenOut(pair.Value.GetActivationState())).ToList();
			for (sbyte planId = 0; planId < 5; planId++)
			{
				SelectCombatSkillAttainmentPanelPlan(context, skillType2, planId);
				Logger.Info("CombatSkillAttainmentPanelPlan ========================================");
				Logger.Info($"skill type {skillType2}\t planId {planId}");
				sbyte grade;
				for (grade = 0; grade < 9; grade++)
				{
					short skillId = CombatSkillAttainmentPanelsHelper.Get(panels, skillType2, grade);
					if (skillId < 0)
					{
						Tester.Assert(!viableSkills.Exists((KeyValuePair<short, GameData.Domains.CombatSkill.CombatSkill> pair) => Config.CombatSkill.Instance[pair.Key].Grade == grade));
						Logger.Warn($"Can't find viable CombatSkill with type {skillType2} and grade {grade}");
					}
					else
					{
						Logger.Info($"Can't find viable CombatSkill with type {skillType2} and grade {grade}");
						Tester.Assert(Config.CombatSkill.Instance[skillId].Grade == grade);
						Tester.Assert(Config.CombatSkill.Instance[skillId].Type == skillType2);
					}
				}
			}
		}
	}
